import { Directive } from '@angular/core';
import { InputRestrictBaseDirective as CoreInputRestrictDirective } from '../core/input-restrict.directive';

/**
 * Input Restrict Directive Wrapper
 * 
 * Wraps the core InputRestrictDirective for easy importing.
 * This directive handles input restriction logic only - no styles needed.
 * 
 * @example
 * ```typescript
 * import { InputRestrictDirective } from '@validations';
 * 
 * @Component({
 *   standalone: true,
 *   imports: [InputRestrictDirective]
 * })
 * export class MyComponent {}
 * ```
 */
@Directive({
  selector: '[cmmInputRestrict]',
  standalone: true,
  hostDirectives: [
    {
      directive: CoreInputRestrictDirective,
      inputs: [
        'pattern',
        'maxLength',
        'formatOnBlur',
        'transform',
        'trimOnBlur',
        'allowSpaces',
        'customValidator',
        'blockInvalidPaste'
      ],
    },
  ],
})
export class InputRestrictDirective {
  // Pure wrapper - no style injection needed
}
