import { Component, input, output, model, forwardRef, ChangeDetectionStrategy } from '@angular/core';

import { FormsModule, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import { ColorPickerModule, ColorPickerChangeEvent } from 'primeng/colorpicker';
import { ColorPickerFormat } from './cmm-colorpicker.types';
import { COLORPICKER_DEFAULTS } from './cmm-colorpicker.constants';

@Component({
  selector: 'cmm-colorpicker',
  standalone: true,
  imports: [FormsModule, ColorPickerModule],
  template: `
    <p-colorpicker
      [(ngModel)]="value"
      [format]="format()"
      [inline]="inline()"
      [disabled]="disabled()"
      [appendTo]="appendTo()!"
      [style]="style() ?? undefined"
      [styleClass]="styleClass()!"
      (onChange)="handleChange($event)"
    />
  `,
  styleUrl: './cmm-colorpicker.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmColorpickerComponent),
      multi: true,
    },
  ],
})
export class CmmColorpickerComponent implements ControlValueAccessor {
  // Model
  value = model<string>('');

  // Core props
  format = input<ColorPickerFormat>(COLORPICKER_DEFAULTS.FORMAT);
  inline = input<boolean>(COLORPICKER_DEFAULTS.INLINE);
  disabled = input<boolean>(COLORPICKER_DEFAULTS.DISABLED);
  appendTo = input<any>(COLORPICKER_DEFAULTS.APPEND_TO);
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Output events
  onChange = output<ColorPickerChangeEvent>();

  // ControlValueAccessor
  private onChangeFn: (value: string) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: string): void {
    this.value.set(value || '');
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handle if needed
  }

  handleChange(event: ColorPickerChangeEvent): void {
    this.onChange.emit(event);
    const colorValue = typeof event.value === 'string' ? event.value : JSON.stringify(event.value);
    this.onChangeFn(colorValue);
    this.onTouchedFn();
  }
}
