/**
 * Constants for OrganizationChart component
 */

/** Selection mode options */
export const ORGANIZATIONCHART_SELECTION_MODE = {
  SINGLE: 'single' as const,
  MULTIPLE: 'multiple' as const,
};

export type OrganizationChartSelectionMode =
  (typeof ORGANIZATIONCHART_SELECTION_MODE)[keyof typeof ORGANIZATIONCHART_SELECTION_MODE];
