import { FormGroup } from "@angular/forms";
import { DialogService, DynamicDialogRef } from "primeng/dynamicdialog";


export function getFormGroupFromDialogInstance<T>(dialogService: DialogService, dialogRef: DynamicDialogRef): FormGroup {
    const dialogInstance = dialogService.getInstance(dialogRef);
    return dialogInstance? dialogInstance.componentRef?.instance.df()?.form() as FormGroup: {} as FormGroup;
}