
import { ChangeDetectionStrategy, Component, effect, model, signal } from '@angular/core';
import { Roles, SCREEN_STATUS, System } from '../permission.types';
import { PermissionComponent } from '../permission/permission.component';

export interface RoleProps extends Roles {
  screenMode: SCREEN_STATUS;
  fullPermissionsLabel: string;
  activeSystem?: string;
}
@Component({
  selector: 'app-role',
  standalone: true,
  imports: [PermissionComponent],
  templateUrl: './role.component.html',
  styleUrl: './role.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RoleComponent {
  props = model.required<RoleProps>();

  // Internal usage
  readonly currentSystem = signal<System | null>(null);

  // events action
  handleActiveItemChange(system: System): void {
    this.currentSystem.set(system);
  }

  // check toggle all permissions
  handleCheckAllEvent(checked: boolean): void {
    const currentSystem = this.currentSystem();
    if (currentSystem) {
      const updatedPermissions = currentSystem.permissions.map((permission) => ({
        ...permission,
        active: checked,
      }));
      this.currentSystem.set({
        ...currentSystem,
        permissions: updatedPermissions,
      });
    }
  }

  constructor() {
    effect(() => {
      this.handleCheckDefaultSystem();
    });
  }

  // internal helper functions
  handleCheckDefaultSystem(): void {
    const sys = this.props().activeSystem;
    if (sys) {
      const foundSystem =
        this.props().systems.find((system) => [system.systemId, system.systemCode].includes(sys)) || null;
      this.currentSystem.set(foundSystem);
    } else if (this.props() && !this.currentSystem()) {
      this.currentSystem.set(this.props().systems[0] || null);
    }
  }
}
