import {DownloadProgress, DownloadRequest, DownloadState} from '../modal/download-manager.type';
import {DestroyRef, inject, Injectable, signal} from '@angular/core';
import {BehaviorSubject, EMPTY, Subject, switchMap, takeUntil, timer} from 'rxjs';
import {DOWNLOAD_MANAGER_CONFIG} from '../config/download-manager.config';
import {DownloadTransportInterface} from '../download-transport.interface';


@Injectable()
// The service owns the whole download lifecycle; the transport only streams progress.
export class DownloadManagerService {
  readonly activeDownload$ = new BehaviorSubject<DownloadProgress[]>([]);
  readonly isVisible = signal(true);
  private seenIds = new Set<string>();
  private requests = new Map<string, DownloadRequest>();
  // Tránh lỗi gán đồng bộ (synchronous timing bug) khiến Subscription bị undefined trong callback next.
  // Sử dụng declarative RxJS takeUntil(Subject) để quản lý hủy tải xuống an toàn và tránh rò rỉ bộ nhớ.
  private cancelSignals = new Map<string, Subject<void>>();

  private transport: DownloadTransportInterface = inject(DownloadTransportInterface);

  private readonly destroyRef = inject(DestroyRef);

  // Consumer-tweakable knobs (auto-close timing/threshold, …). Defaults via provideDownloadManager().
  private readonly config = inject(DOWNLOAD_MANAGER_CONFIG);

  constructor() {
    // Reset isVisible to true when a new download starts, managed reactively
    this.activeDownload$.subscribe((downloads) => {
      let hasNew = false;
      for (const d of downloads) {
        if (!this.seenIds.has(d.id)) {
          this.seenIds.add(d.id);
          hasNew = true;
        }
      }
      if (hasNew && !this.isVisible()) {
        this.isVisible.set(true);
      }
    });

    // Auto-close popup when all downloads are Completed (UC-07), but only for small lists.
    // - List size <= autoCloseMaxItems → auto-close after autoCloseDelayMs.
    // - List size  > autoCloseMaxItems → never auto-close; the user dismisses it manually.
    this.activeDownload$
      .pipe(
        switchMap((downloads) => {
          const allCompleted = downloads.length > 0 && downloads.every((d) => d.state === DownloadState.Completed);
          if (!allCompleted || downloads.length > this.config.autoCloseMaxItems) {
            // Not done, or a large list → emit nothing (cancels any pending close timer).
            return EMPTY;
          }
          return timer(this.config.autoCloseDelayMs);
        }),
      )
      .subscribe(() => {
        this.isVisible.set(false);
      });

    // Whole-service shutdown. Fires only when this service instance is destroyed — i.e.
    // when a consumer provides it at a component/route scope, not as the root singleton.
    this.destroyRef.onDestroy(() => this.disposeAll());
  }

  /**
   * Abort every in-flight download and release all per-download resources at once.
   *
   * Wired to {@link DestroyRef} in the constructor, so it runs exactly once when this
   * service instance is destroyed. As a `providedIn: 'root'` singleton it lives for the
   * app's lifetime and this never fires; it earns its keep only when a consumer of the
   * (lib-portable) manager provides it at a component/route scope and that scope is torn down — then in-flight HTTP
   * streams and pending timers must not outlive it.
   */
  private disposeAll(): void {
    // Abort each in-flight stream. Completing the cancel Subject fires its `takeUntil`,
    // unsubscribing the transport observable (whose finalize() frees internal state).
    this.cancelSignals.forEach((cancel) => {
      cancel.next();
      cancel.complete();
    });
    this.cancelSignals.clear();

    this.requests.clear();
    this.seenIds.clear();
  }

  start(req: DownloadRequest, existingId?: string) {
    //  When the popover is closed and a new download starts, throw away the old list first
    if (
      !this.isVisible() &&
      this.config.clearPreviousDownloadList
    ) {
      this.activeDownload$.next([]);
      this.seenIds.clear();
    }

    const id = existingId || crypto.randomUUID();
    const cancel = new Subject<void>();

    this.cancelSignals.set(id, cancel);
    this.requests.set(id, req);

    this.transport
      .start(id, { ...req, url: this.resolveUrl(req.url) })
      .pipe(takeUntil(cancel))
      .subscribe({
        next: (progress: DownloadProgress) => {
          const currentList = this.activeDownload$.value;
          const index = currentList.findIndex((d) => d.id === progress.id);

          if (index >= 0) {
            const newList = [...currentList];
            newList[index] = progress;
            this.activeDownload$.next(newList);
          } else {
            this.activeDownload$.next([progress, ...currentList]);
          }
        },
        complete: () => {
          this.handleComplete(id);
          this.cancelSignals.delete(id);
        },
      });
  }

  private resolveUrl(url: string): string {
    // No configured base, or an already-absolute URL → use as-is.
    if (!this.config.baseUrl || /^(https?:)?\/\//i.test(url)) {
      return url;
    }
    const base = this.config.baseUrl.replace(/\/+$/, '');
    const path = url.replace(/^\/+/, '');
    return `${base}/${path}`;
  }

  handleComplete(id: string): void {
    const progress = this.activeDownload$.value.find((d) => d.id === id);

    if (progress?.state === DownloadState.Completed) {
      // Completed rows stay in the list until the popover closes (auto-close for small
      // lists, manual for large ones — see the constructor). The service no longer
      // auto-clears individual rows, so a user starting more downloads while the popover
      // is open sees them appended alongside the already-finished ones.
      this.requests.delete(id);
      this.cancelSignals.delete(id);
    } else {
      // If it is in Error state, do not delete from requests so retry works, and do not clear from list.
      this.cancelSignals.delete(id);
    }
  }

  cancel(id: string): void {
    if (!id) {
      return;
    }

    // Trigger RxJS cancellation signal
    const cancel = this.cancelSignals.get(id);
    if (cancel) {
      cancel.next();
      cancel.complete();
      this.cancelSignals.delete(id);
    }

    this.requests.delete(id);
    this.activeDownload$.next(this.activeDownload$.value.filter((d) => d.id !== id));

    // Notify transport to clean up any internal state
    this.transport.cancel?.(id);
  }

  /**
   * UC-04: Pause the in-flight download. Pure delegation — the transport owns state, so it
   * emits the `Paused` progress through its stream, which the `start()` subscription mirrors
   * into the list. The service never sets `Paused` itself.
   */
  pause(id: string): void {
    this.transport.pause?.(id);
  }

  /** UC-04: Resume a paused download. Delegated — the transport re-emits `Downloading`. */
  resume(id: string): void {
    this.transport.resume?.(id);
  }

  retry(id: string): void {
    if (!id) {
      return;
    }
    const req = this.requests.get(id);
    if (!req) {
      console.error('Can not resume from last request');
      return;
    }

    // 1. Cancel the active subscription of this download if any
    const cancel = this.cancelSignals.get(id);
    if (cancel) {
      cancel.next();
      cancel.complete();
      this.cancelSignals.delete(id);
    }

    // 2. Notify transport to clean up any internal state
    this.transport.cancel?.(id);

    // 3. Restart with the same id. The transport re-emits `Waiting` (on the Sent event), which replaces the Error
    // row in the list by id — the service does not synthesize it.
    this.start(req, id);
  }
}
