import { WritableSignal } from '@angular/core';
import { CheckboxChangeEvent } from 'primeng/checkbox';
import { ToggleSwitchChangeEvent } from 'primeng/toggleswitch';
import { PermissionProps } from './permission.component';
import { PermissionModel, RoleModel } from '../permission.model';
import { Permission, Roles } from '../permission.types';

export class PermissionUtil {
  static convertRoleModelToRolesPermission(role: RoleModel): Roles {
    return {
      roleName: role.name,
      roleId: role.id,
      system: role.system,
      roleDescription: role.description,
      status: role.status,
      totalPermissions: role.totalPermissions,
      systems: role.permissionGroups?.map((group) => ({
        systemId: group.id,
        systemCode: group.code,
        systemName: group.name,
        systemDescription: group.description,
        permissions: group.permissions?.map((permission: PermissionModel) => ({
          permissionId: permission.id,
          permissionCode: permission.code,
          permissionName: permission.name,
          permissionDescription: permission.description,
          endpoint: permission.endpoint,
          method: permission.method,
        })),
      })),
    };
  }
}
