import { ColumnDefinition, TableProps } from "../table.types";

export function computeTotalCols(props: TableProps, cols: ColumnDefinition[]) {
    const computedData = props;
    let res = cols.length;
    if (computedData.isShowOrder) {
      res = res + 1;
    }
    if (computedData.isShowCheckBox) {
      res = res + 1;
    }

    return res;
  }