import { Component, input, output, model, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DataViewModule } from 'primeng/dataview';
import {
  DataViewLayout,
  DataViewPageEvent,
  DataViewLazyLoadEvent,
  DataViewSortEvent,
  DataViewLayoutChangeEvent,
  DataViewPaginatorPosition,
} from './cmm-dataview.types';
import { DATAVIEW_DEFAULTS } from './cmm-dataview.constants';

@Component({
  selector: 'cmm-dataview',
  standalone: true,
  imports: [CommonModule, DataViewModule],
  templateUrl: './cmm-dataview.component.html',
  styleUrl: './cmm-dataview.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmDataviewComponent {
  // Model for layout
  layout = model<DataViewLayout>(DATAVIEW_DEFAULTS.LAYOUT);

  // Core props
  value = input<any[]>();
  paginator = input<boolean>(DATAVIEW_DEFAULTS.PAGINATOR);
  rows = input<number>();
  totalRecords = input<number>();
  pageLinks = input<number>(DATAVIEW_DEFAULTS.PAGE_LINKS);
  rowsPerPageOptions = input<any[]>();
  paginatorPosition = input<DataViewPaginatorPosition>(DATAVIEW_DEFAULTS.PAGINATOR_POSITION);
  paginatorStyleClass = input<string>();
  alwaysShowPaginator = input<boolean>(DATAVIEW_DEFAULTS.ALWAYS_SHOW_PAGINATOR);
  paginatorDropdownAppendTo = input<any>();
  paginatorDropdownScrollHeight = input<string>(DATAVIEW_DEFAULTS.PAGINATOR_DROPDOWN_SCROLL_HEIGHT);
  currentPageReportTemplate = input<string>(DATAVIEW_DEFAULTS.CURRENT_PAGE_REPORT_TEMPLATE);
  showCurrentPageReport = input<boolean>(DATAVIEW_DEFAULTS.SHOW_CURRENT_PAGE_REPORT);
  showJumpToPageDropdown = input<boolean>(DATAVIEW_DEFAULTS.SHOW_JUMP_TO_PAGE_DROPDOWN);
  showFirstLastIcon = input<boolean>(DATAVIEW_DEFAULTS.SHOW_FIRST_LAST_ICON);
  showPageLinks = input<boolean>(DATAVIEW_DEFAULTS.SHOW_PAGE_LINKS);
  lazy = input<boolean>(DATAVIEW_DEFAULTS.LAZY);
  lazyLoadOnInit = input<boolean>(DATAVIEW_DEFAULTS.LAZY_LOAD_ON_INIT);
  emptyMessage = input<string>(DATAVIEW_DEFAULTS.EMPTY_MESSAGE);
  style = input<Record<string, any>>();
  styleClass = input<string>();
  gridStyleClass = input<string>(DATAVIEW_DEFAULTS.GRID_STYLE_CLASS);
  trackBy = input<Function>();
  filterBy = input<string>();
  filterLocale = input<string>();
  loading = input<boolean>(DATAVIEW_DEFAULTS.LOADING);
  loadingIcon = input<string>();
  first = input<number>(DATAVIEW_DEFAULTS.FIRST);
  sortField = input<string>();
  sortOrder = input<number>();

  // Output events
  onPage = output<DataViewPageEvent>();
  onLazyLoad = output<DataViewLazyLoadEvent>();
  onSort = output<DataViewSortEvent>();
  onChangeLayout = output<DataViewLayoutChangeEvent>();

  // Template projections
  listTemplate = contentChild<TemplateRef<any>>('list');
  gridTemplate = contentChild<TemplateRef<any>>('grid');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  emptyTemplate = contentChild<TemplateRef<any>>('empty');
  paginatorleftTemplate = contentChild<TemplateRef<any>>('paginatorleft');
  paginatorrightTemplate = contentChild<TemplateRef<any>>('paginatorright');
  paginatordropdownitemTemplate = contentChild<TemplateRef<any>>('paginatordropdownitem');
  loadingiconTemplate = contentChild<TemplateRef<any>>('loadingicon');
  listiconTemplate = contentChild<TemplateRef<any>>('listicon');
  gridiconTemplate = contentChild<TemplateRef<any>>('gridicon');

  // Event handlers
  handlePage(event: DataViewPageEvent): void {
    this.onPage.emit(event);
  }

  handleLazyLoad(event: DataViewLazyLoadEvent): void {
    this.onLazyLoad.emit(event);
  }

  handleSort(event: DataViewSortEvent): void {
    this.onSort.emit(event);
  }

  handleChangeLayout(event: DataViewLayoutChangeEvent): void {
    this.onChangeLayout.emit(event);
  }
}
