import { Component, input, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DividerModule } from 'primeng/divider';
import { DividerAlign, DividerLayout, DividerType } from './cmm-divider.types';
import { DIVIDER_DEFAULTS } from './cmm-divider.constants';

@Component({
  selector: 'cmm-divider',
  standalone: true,
  imports: [CommonModule, DividerModule],
  template: `
    <p-divider
      [layout]="layout()"
      [align]="align()"
      [type]="type()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined">
      @if (contentTemplate()) {
        <ng-container *ngTemplateOutlet="contentTemplate()!" />
      } @else {
        <ng-content />
      }
    </p-divider>
  `,
  styleUrl: './cmm-divider.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmDividerComponent {
  // Core props
  layout = input<DividerLayout>(DIVIDER_DEFAULTS.LAYOUT);
  align = input<DividerAlign>(DIVIDER_DEFAULTS.ALIGN);
  type = input<DividerType>(DIVIDER_DEFAULTS.TYPE);
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Templates
  contentTemplate = contentChild<TemplateRef<any>>('content');
}
