
import {
  Directive,
  ElementRef,
  Input,
  Output,
  EventEmitter,
  Renderer2,
  OnDestroy,
  inject,
  booleanAttribute
} from '@angular/core';
import { BaseComponent } from 'primeng/basecomponent';
import { UBCKCustomTypographyStyles } from '../styles/typography.style';

@Directive({
  selector: '[cmmCopyable]',
  standalone: true,
  host: {
    '(click)': 'handleCopy($event)',
    '[class.copyable]': 'appCopyable',
    '[style.cursor]': 'appCopyable ? "pointer" : null',
    '[style.position]': 'appCopyable ? "relative" : null'
  },
  providers: [UBCKCustomTypographyStyles]
})
export class CmmCopyableDirective extends BaseComponent implements OnDestroy {
  _componentStyle = inject(UBCKCustomTypographyStyles);
  
  @Input({ transform: booleanAttribute }) appCopyable = false;
  @Input() copyText?: string; // Custom text to copy (optional)
  @Input() tooltipText = 'Copied!';
  @Input() tooltipDuration = 2000; // ms
  @Input() tooltipPosition: 'top' | 'bottom' | 'left' | 'right' = 'bottom';
  
  @Output() copy = new EventEmitter<string>();

  private tooltip: HTMLElement | null = null;
  private copyTimeout?: number;

  handleCopy(event: Event): void {
    event.stopPropagation();
    
    if (!this.appCopyable) return;

    // Get text to copy - get innerText to avoid including hidden elements like tooltip
    const textToCopy = this.copyText || this.getTextContent();
    
    // Copy to clipboard
    this.copyToClipboard(textToCopy).then(() => {
      this.showTooltip();
      this.copy.emit(textToCopy);
    }).catch(err => {
      console.error('Failed to copy:', err);
    });
  }

  private getTextContent(): string {
    // Clone the element to manipulate without affecting the DOM
    const clone = this.el.nativeElement.cloneNode(true) as HTMLElement;
    
    // Remove any existing tooltips from the clone
    const tooltips = clone.querySelectorAll('.copy-tooltip');
    tooltips.forEach(tooltip => tooltip.remove());
    
    // Get the text content without tooltip
    return clone.textContent?.trim() || '';
  }

  private async copyToClipboard(text: string): Promise<void> {
    if (navigator.clipboard && window.isSecureContext) {
      // Modern async clipboard API
      await navigator.clipboard.writeText(text);
    } else {
      // Fallback for older browsers
      const textarea = document.createElement('textarea');
      textarea.value = text;
      textarea.style.position = 'fixed';
      textarea.style.left = '-9999px';
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand('copy');
      document.body.removeChild(textarea);
    }
  }

  private showTooltip(): void {
    console.log('showTooltip called'); // Debug log
    
    // Remove existing tooltip if any
    this.removeTooltip();

    // Create tooltip element
    this.tooltip = this.renderer.createElement('span');
    this.renderer.addClass(this.tooltip, 'copy-tooltip');
    this.renderer.addClass(this.tooltip, `copy-tooltip-${this.tooltipPosition}`);
    this.renderer.setProperty(this.tooltip, 'textContent', this.tooltipText);
    
    console.log('Tooltip created:', this.tooltip); // Debug log
    
    // Apply styles
    this.applyTooltipStyles();
    
    // Append to document body instead of the element to avoid affecting textContent
    this.renderer.appendChild(document.body, this.tooltip);
    
    console.log('Tooltip appended to body'); // Debug log
    
    // Position tooltip relative to element
    this.positionTooltip();
    
    console.log('Tooltip positioned'); // Debug log
    
    // Trigger animation
    setTimeout(() => {
      if (this.tooltip) {
        this.renderer.setStyle(this.tooltip, 'opacity', '1');
        console.log('Tooltip opacity set to 1'); // Debug log
      }
    }, 10);

    // Auto-hide after duration
    this.copyTimeout = window.setTimeout(() => {
      this.hideTooltip();
    }, this.tooltipDuration);
  }

  private positionTooltip(): void {
    if (!this.tooltip) return;

    const rect = this.el.nativeElement.getBoundingClientRect();
    const tooltipRect = this.tooltip.getBoundingClientRect();
    
    let top = 0;
    let left = 0;

    // Use fixed positioning - no need for scroll offset
    switch (this.tooltipPosition) {
      case 'top':
        top = rect.top - tooltipRect.height - 8;
        left = rect.left + (rect.width / 2) - (tooltipRect.width / 2);
        break;
      case 'bottom':
        top = rect.bottom + 8;
        left = rect.left + (rect.width / 2) - (tooltipRect.width / 2);
        break;
      case 'left':
        top = rect.top + (rect.height / 2) - (tooltipRect.height / 2);
        left = rect.left - tooltipRect.width - 8;
        break;
      case 'right':
        top = rect.top + (rect.height / 2) - (tooltipRect.height / 2);
        left = rect.right + 8;
        break;
    }

    this.renderer.setStyle(this.tooltip, 'top', `${top}px`);
    this.renderer.setStyle(this.tooltip, 'left', `${left}px`);
  }

  private applyTooltipStyles(): void {
    if (!this.tooltip) return;

    // Base styles - position fixed for body-appended tooltip
    this.renderer.setStyle(this.tooltip, 'position', 'fixed');
    this.renderer.setStyle(this.tooltip, 'z-index', '9999');
    this.renderer.setStyle(this.tooltip, 'padding', '6px 12px');
    this.renderer.setStyle(this.tooltip, 'background', 'rgba(0, 0, 0, 0.85)');
    this.renderer.setStyle(this.tooltip, 'color', 'white');
    this.renderer.setStyle(this.tooltip, 'font-size', '12px');
    this.renderer.setStyle(this.tooltip, 'line-height', '1.5');
    this.renderer.setStyle(this.tooltip, 'white-space', 'nowrap');
    this.renderer.setStyle(this.tooltip, 'border-radius', '4px');
    this.renderer.setStyle(this.tooltip, 'pointer-events', 'none');
    this.renderer.setStyle(this.tooltip, 'opacity', '0');
    this.renderer.setStyle(this.tooltip, 'transition', 'opacity 0.2s ease');
    this.renderer.setStyle(this.tooltip, 'display', 'inline-block');
    this.renderer.setStyle(this.tooltip, 'box-shadow', '0 2px 8px rgba(0,0,0,0.15)');
 
  }

  private hideTooltip(): void {
    if (this.tooltip) {
      this.renderer.setStyle(this.tooltip, 'opacity', '0');
      
      setTimeout(() => {
        this.removeTooltip();
      }, 200);
    }
  }

  private removeTooltip(): void {
    if (this.tooltip) {
      if (this.tooltip.parentNode) {
        this.renderer.removeChild(this.tooltip.parentNode, this.tooltip);
      }
      this.tooltip = null;
    }
    
    if (this.copyTimeout) {
      clearTimeout(this.copyTimeout);
      this.copyTimeout = undefined;
    }
  }

  override ngOnDestroy(): void {
    super.ngOnDestroy();
    this.removeTooltip();
  }
}