import { Component, input, output, viewChild, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TieredMenu, TieredMenuModule } from 'primeng/tieredmenu';
import type { MenuItem } from 'primeng/api';
import { TIEREDMENU_DEFAULTS } from './cmm-tieredmenu.constants';

@Component({
  selector: 'cmm-tieredmenu',
  standalone: true,
  imports: [CommonModule, TieredMenuModule],
  template: `
    <p-tieredMenu
      #menu
      [id]="id() ?? undefined"
      [model]="model()"
      [popup]="popup()"
      [appendTo]="appendTo() ?? undefined"
      [breakpoint]="breakpoint()"
      [autoZIndex]="autoZIndex()"
      [baseZIndex]="baseZIndex()"
      [autoDisplay]="autoDisplay()"
      [showTransitionOptions]="showTransitionOptions()"
      [hideTransitionOptions]="hideTransitionOptions()"
      [ariaLabel]="ariaLabel() ?? undefined"
      [ariaLabelledBy]="ariaLabelledBy() ?? undefined"
      [disabled]="disabled()"
      [tabindex]="tabindex()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined"
      (onShow)="onShow.emit($event)"
      (onHide)="onHide.emit($event)">
      @if (itemTemplate()) {
        <ng-template pTemplate="item" let-item>
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
      @if (submenuIconTemplate()) {
        <ng-template pTemplate="submenuicon">
          <ng-container *ngTemplateOutlet="submenuIconTemplate()!" />
        </ng-template>
      }
    </p-tieredMenu>
  `,
  styleUrl: './cmm-tieredmenu.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmTieredmenuComponent {
  menu = viewChild<TieredMenu>('menu');

  // Core props
  id = input<string>();
  model = input<MenuItem[]>([]);
  popup = input<boolean>(TIEREDMENU_DEFAULTS.POPUP);
  appendTo = input<unknown>('body');
  breakpoint = input<string>('960px');
  autoZIndex = input<boolean>(TIEREDMENU_DEFAULTS.AUTO_Z_INDEX);
  baseZIndex = input<number>(TIEREDMENU_DEFAULTS.BASE_Z_INDEX);
  autoDisplay = input<boolean>(true);
  showTransitionOptions = input<string>('.12s cubic-bezier(0, 0, 0.2, 1)');
  hideTransitionOptions = input<string>('.1s linear');
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();
  disabled = input<boolean>(false);
  tabindex = input<number>(0);
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Templates
  itemTemplate = contentChild<TemplateRef<any>>('item');
  submenuIconTemplate = contentChild<TemplateRef<any>>('submenuicon');

  // Events
  onShow = output<any>();
  onHide = output<any>();

  // Public methods
  toggle(event: Event): void {
    this.menu()?.toggle(event);
  }

  show(event: Event): void {
    this.menu()?.show(event);
  }

  hide(): void {
    this.menu()?.hide();
  }
}
