import { Component, ChangeDetectionStrategy, input, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ProgressBar } from 'primeng/progressbar';

@Component({
  selector: 'cmm-progressbar',
  standalone: true,
  imports: [CommonModule, ProgressBar],
  templateUrl: './cmm-progressbar.component.html',
  styleUrl: './cmm-progressbar.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmProgressBarComponent {
  value = input<number>();
  showValue = input<boolean>(true);
  styleClass = input<string>('');
  valueStyleClass = input<string>('');
  style = input<Record<string, any>>();
  unit = input<string>('%');
  mode = input<"determinate" | "indeterminate">('determinate');
  color = input<string>();

  contentTemplate = contentChild<TemplateRef<any>>('content');
}
