/**
 * Avatar size options
 */
export const AVATAR_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type AvatarSize = (typeof AVATAR_SIZES)[keyof typeof AVATAR_SIZES];

/**
 * PrimeNG Avatar native size options
 */
export const PRIMENG_AVATAR_SIZES = {
  NORMAL: 'normal',
  LARGE: 'large',
  XLARGE: 'xlarge',
} as const;

export type PrimeNGAvatarSize = (typeof PRIMENG_AVATAR_SIZES)[keyof typeof PRIMENG_AVATAR_SIZES];

/**
 * Avatar shape options
 */
export const AVATAR_SHAPES = {
  SQUARE: 'square',
  CIRCLE: 'circle',
} as const;

export type AvatarShape = (typeof AVATAR_SHAPES)[keyof typeof AVATAR_SHAPES];

/**
 * Avatar style variants
 */
export const AVATAR_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export type AvatarVariant = (typeof AVATAR_VARIANTS)[keyof typeof AVATAR_VARIANTS];

/**
 * Avatar display types
 */
export const AVATAR_TYPES = {
  LABEL: 'label',
  ICON: 'icon',
  IMAGE: 'image',
} as const;

export type AvatarType = (typeof AVATAR_TYPES)[keyof typeof AVATAR_TYPES];
