import { NgModule} from '@angular/core';
import { UBCKPaginator } from './paginator';
import { CommonModule } from '@angular/common';
import { PaginatorModule } from 'primeng/paginator';
import { UBCKPaginatorStyles } from './styles/pagination.style';
import { TranslateModule } from '@ngx-translate/core';
import { Select } from 'primeng/select';
import { FormsModule } from '@angular/forms';
const components = [UBCKPaginator];

@NgModule({
  declarations: components,
  imports: [CommonModule, PaginatorModule, TranslateModule, Select, FormsModule],
  exports: components,
  providers: [UBCKPaginatorStyles],
})
export class UBCKPaginatorModule {}
