import { Directive, input } from '@angular/core';
import { KeyFilter } from 'primeng/keyfilter';
import { KeyFilterPattern } from './cmm-keyfilter.types';
import { KEYFILTER_DEFAULTS } from './cmm-keyfilter.constants';

@Directive({
  selector: '[cmmKeyFilter]',
  standalone: true,
  hostDirectives: [
    {
      directive: KeyFilter,
      inputs: ['pKeyFilter', 'pValidateOnly'],
    },
  ],
})
export class CmmKeyfilterDirective {
  pKeyFilter = input<RegExp | KeyFilterPattern>();
  pValidateOnly = input<boolean>(KEYFILTER_DEFAULTS.VALIDATE_ONLY);
}
