import {
  Directive,
  ElementRef,
  Input,
  OnInit,
  OnDestroy,
  DoCheck,
  Renderer2,
  Optional,
  Host,
  HostListener,
  ComponentRef,
  EnvironmentInjector,
  ApplicationRef,
  inject,
} from '@angular/core';
import { AbstractControl, NgControl } from '@angular/forms';
import { Subject } from 'rxjs';
import { takeUntil, distinctUntilChanged } from 'rxjs/operators';
import { ValidationService } from './validation.service';
import { PrimeNGDetectorHelper } from './utils/primeng-detector.helper';
import { DOMSelectorHelper } from './utils/dom-selector.helper';
import { ValidationStylerHelper } from './utils/validation-styler.helper';
import { ErrorRendererHelper } from './utils/error-renderer.helper';
import { ValidationErrorComponent } from './validation-error.component';
import { TranslateService } from '@ngx-translate/core';

export type ValidationDisplayMode = 'touched' | 'dirty' | 'always' | 'submit' | 'custom';

/**
 * Validation Directive - PrimeNG Support với Direct DOM Manipulation
 *
 * ✅ Không cần ::ng-deep
 * ✅ Không cần global CSS
 * ✅ Apply styles trực tiếp vào PrimeNG internal elements
 * ✅ Work với mọi PrimeNG version
 *
 * Usage:
 * ```html
 * <p-select 
 *   formControlName="country" 
 *   cmmValidation 
 * />
 * ```
 */
@Directive({
  selector: '[cmmValidation]',
  standalone: true,
})
export class ValidationBaseDirective implements OnInit, DoCheck, OnDestroy {
  @Input() fieldName = 'Trường này';
  @Input() customMessages?: { [key: string]: string };
  @Input() errorPosition: 'bottom' | 'top' = 'bottom';
  @Input() showErrorIcon = false;
  @Input() errorClass = 'form-control-error';
  @Input() displayMode: ValidationDisplayMode = 'touched';
  @Input() showValidation?: boolean;
  
  /**
   * Suppress error message rendering (useful for radio button groups)
   * When true, validation classes are still applied but error message is not shown
   */
  @Input() suppressError = false;
  
  /**
   * Custom selector to find the element after which the error should be inserted
   * Useful for complex component structures (e.g., password wrapper with toggle button)
   * 
   * Example:
   * <div class="password-wrapper" #passwordWrapper>
   *   <input cmmValidation [errorInsertTarget]="passwordWrapper" />
   *   <button>Toggle</button>
   * </div>
   * 
   * Or with class selector:
   * <input cmmValidation errorInsertTarget=".password-wrapper" />
   */
  @Input() errorInsertTarget?: HTMLElement | string;
  
  /**
   * PrimeNG component type (Optional - Auto-detected)
   * The directive automatically detects PrimeNG components by checking parent elements
   * for tags starting with 'p-' (e.g., p-dropdown, p-calendar, p-select)
   * 
   * Only provide this input if auto-detection fails or you need to override it.
   * 
   * Supported values:
   * - 'select' or 'dropdown' (p-select, p-dropdown)
   * - 'calendar' (p-calendar)
   * - 'inputNumber' (p-inputNumber)
   * - 'multiSelect' (p-multiSelect)
   * - 'autoComplete' (p-autoComplete)
   * - 'chips' (p-chips)
   * - 'inputMask' (p-inputMask)
   * - 'password' (p-password)
   * - 'inputTextarea' (p-inputTextarea)
   * - 'checkbox' (p-checkbox)
   * - 'radioButton' (p-radioButton)
   * - 'inputSwitch' (p-inputSwitch)
   * 
   * Example (auto-detected):
   * <p-dropdown cmmValidation />
   * 
   * Example (manual override):
   * <p-select cmmValidation primengComponent="select" />
   */
  @Input() primengComponent?: string;
  
  /**
   * Wrapper selector (fallback for custom cases)
   */
  @Input() wrapperSelector?: string;
  
  /**
   * Error container selector
   */
  @Input() errorContainer?: string;

  /**
   * Border color for invalid state
   */
  @Input() invalidBorderColor = '#dc3545';
  
  /**
   * Border color for valid state
   */
  @Input() validBorderColor = '#28a745';

   errorComponentRef?: ComponentRef<ValidationErrorComponent>;
  public  destroy$ = new Subject<void>();
  public  control?: AbstractControl | null;
  public  wrapperElement?: HTMLElement;
  public  primengInnerElement?: HTMLElement;
  
  public  previousTouched = false;
  public  previousDirty = false;
  public  previousValid = true;
  public  previousDisabled = false;
  public  previousShowValidation?: boolean;
  public  lastErrorMessage = '';
  public  translateService = inject(TranslateService, { optional: true });

  constructor(
    public  el: ElementRef,
    public  renderer: Renderer2,
    public  validationService: ValidationService,
    public  environmentInjector: EnvironmentInjector,
    public  appRef: ApplicationRef,
    @Optional() @Host() public  ngControl: NgControl
  ) {}

  @HostListener('blur')
  onBlur(): void {
    if (this.control && !this.control.touched) {
      this.control.markAsTouched();
    }
    // For custom/submit mode, don't show validation on blur
    // Only show when showValidation flag is set (typically on form submit)
    if (this.displayMode === 'custom' || this.displayMode === 'submit') {
      // Force update to clear any styles that shouldn't be shown yet
      this.updateValidationState();
    }
  }

  ngOnInit(): void {
    this.control = this.ngControl?.control;
     
    if (!this.control) {
      console.warn('ValidationDirective: No form control found');
      return;
    }

    // Auto-detect PrimeNG component
    if (!this.primengComponent) {
      this.primengComponent = PrimeNGDetectorHelper.autoDetect(this.el);
    }

    // Find wrapper and inner elements for PrimeNG
    if (this.wrapperSelector || this.primengComponent) {
      this.wrapperElement = this.findWrapperElement();
      
      if (this.wrapperElement && this.primengComponent) {
        this.primengInnerElement = this.findPrimeNGInnerElement();
      }
    }

    this.renderer.addClass(this.el.nativeElement, 'input-validation');
    
    // Add submit mode class to prevent CSS styles from applying before form submission
    if (this.displayMode === 'submit' || this.displayMode === 'custom') {
      this.renderer.addClass(this.el.nativeElement, 'cmm-validation-submit-mode');
    }

    this.previousTouched = this.control.touched;
    this.previousDirty = this.control.dirty;
    this.previousValid = this.control.valid;
    this.previousDisabled = this.control.disabled;
    this.previousShowValidation = this.showValidation;

    // Subscribe to language changes to re-render error messages
    this.translateService?.onLangChange
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        // Re-render error message when language changes
        if (this.shouldShowError()) {
          this.updateValidationState();
        }
      });

    this.control.statusChanges
      .pipe(
        takeUntil(this.destroy$),
        distinctUntilChanged()
      )
      .subscribe(() => {
        this.updateValidationState();
      });

    this.control.valueChanges
      .pipe(takeUntil(this.destroy$))
      .subscribe(() => {
        if (this.shouldShowError()) {
          this.updateValidationState();
        }
      });

    this.updateValidationState();
  }

  ngDoCheck(): void {
    if (!this.control) return;

    const currentTouched = this.control.touched;
    const currentDirty = this.control.dirty;
    const currentValid = this.control.valid;
    const currentDisabled = this.control.disabled;
    const currentShowValidation = this.showValidation;

    let hasChange = false;

    if (this.previousTouched !== currentTouched) {
      this.previousTouched = currentTouched;
      hasChange = true;
    }

    if (this.previousDirty !== currentDirty) {
      this.previousDirty = currentDirty;
      hasChange = true;
    }

    if (this.previousValid !== currentValid) {
      this.previousValid = currentValid;
      hasChange = true;
    }

    // Track disabled transitions: a control going invalid -> disabled keeps
    // `valid === false`, so without this the directive never re-renders and the
    // stale inline error stays visible after the control is reactively disabled.
    if (this.previousDisabled !== currentDisabled) {
      this.previousDisabled = currentDisabled;
      hasChange = true;
    }

    if (this.previousShowValidation !== currentShowValidation) {
      this.previousShowValidation = currentShowValidation;
      hasChange = true;
    }

    if (hasChange) {
      this.updateValidationState();
    }
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
    this.removeErrorElement();
    this.removeInlineStyles();
  }

  public  findWrapperElement(): HTMLElement | undefined {
    if (this.wrapperSelector) {
      return DOMSelectorHelper.findElementBySelector(this.el, this.wrapperSelector);
    }
    
    if (this.primengComponent) {
      const tagName = PrimeNGDetectorHelper.getTagName(this.primengComponent);
      return DOMSelectorHelper.findElementBySelector(this.el, tagName);
    }
    
    return undefined;
  }

  public  findPrimeNGInnerElement(): HTMLElement | undefined {
    if (!(this.wrapperElement && this.primengComponent)) return undefined;

    const selectors = PrimeNGDetectorHelper.getInnerSelectors(this.primengComponent);
    
    for (const selector of selectors) {
      const element = this.wrapperElement.querySelector(selector) as HTMLElement;
      if (element) return element;
    }
    
    return undefined;
  }

  public  shouldShowError(): boolean {
    if (!this.control) return false;

    switch (this.displayMode) {
      case 'touched':
        return this.control.touched && this.control.invalid;
      case 'dirty':
        return this.control.dirty && this.control.invalid;
      case 'always':
        return this.control.invalid;
      case 'submit':
      case 'custom':
        return !!this.showValidation && this.control.invalid;
      default:
        return this.control.touched && this.control.invalid;
    }
  }

  public  updateValidationState(): void {
    if (!this.control) return;

    this.updateClasses();
    this.updateInlineStyles(); // ← Magic here!

    if (this.shouldShowError() && !this.suppressError) {
      // Extract fieldName from error object if available, otherwise use input fieldName
      const fieldNameToUse = this.extractFieldNameFromError() || this.fieldName;
      
      const errorMessage = this.validationService.getErrorMessage(
        this.control,
        fieldNameToUse,
        this.customMessages
      );

      if (errorMessage !== this.lastErrorMessage) {
        this.lastErrorMessage = errorMessage;

        if (errorMessage) {
          this.showError(errorMessage);
        } else {
          this.removeErrorElement();
        }
      }
    } else {
      this.lastErrorMessage = '';
      this.removeErrorElement();
    }
  }

  public  updateClasses(): void {
    if (!this.control) return;
    
    // Manage submit mode class based on showValidation state
    if (this.displayMode === 'submit' || this.displayMode === 'custom') {
      if (this.showValidation) {
        this.renderer.addClass(this.el.nativeElement, 'cmm-validation-show-errors');
      } else {
        this.renderer.removeClass(this.el.nativeElement, 'cmm-validation-show-errors');
      }
    }
    
    ValidationStylerHelper.updateClasses(
      this.renderer,
      this.el.nativeElement,
      this.wrapperElement,
      this.control,
      this.displayMode,
      this.showValidation,
      this.errorClass
    );
  }

  public  updateInlineStyles(): void {
    ValidationStylerHelper.updateInlineStyles(
      this.renderer,
      this.el.nativeElement,
      this.primengInnerElement,
      this.control,
      this.displayMode,
      this.showValidation
    );
  }

  public  removeInlineStyles(): void {
    ValidationStylerHelper.removeInlineStyles(
      this.renderer,
      this.el.nativeElement,
      this.primengInnerElement
    );
  }

  public  showError(errorMessage: string): void {
    if (this.errorComponentRef) {
      ErrorRendererHelper.updateErrorMessage(
        this.errorComponentRef,
        errorMessage
      );
    } else {
      this.errorComponentRef = ErrorRendererHelper.createErrorComponent(
        this.renderer,
        this.getErrorInsertTarget(),
        this.environmentInjector,
        this.appRef,
        errorMessage,
        this.showErrorIcon,
        this.errorPosition
      );
    }
  }

  public  removeErrorElement(): void {
    ErrorRendererHelper.removeErrorComponent(
      this.renderer,
      this.errorComponentRef,
      this.appRef
    );
    this.errorComponentRef = undefined;
  }

  public  getErrorInsertTarget(): HTMLElement {
    if (this.errorInsertTarget) {
      if (this.errorInsertTarget instanceof HTMLElement) {
        return this.errorInsertTarget;
      }
      
      if (typeof this.errorInsertTarget === 'string') {
        const customTarget = DOMSelectorHelper.findErrorInsertTarget(
          this.el,
          this.errorInsertTarget
        );
        if (customTarget) return customTarget;
      }
    }
    
    // If wrapperElement exists (PrimeNG component), use it
    if (this.wrapperElement) {
      return this.wrapperElement;
    }
    
    // Otherwise use parent element (input can't contain children)
    return this.el.nativeElement.parentElement || this.el.nativeElement;
  }

  /**
   * Extract fieldName from error object if provided
   * This allows backend or custom validators to specify the field name directly
   * 
   * Example error object:
   * { required: { fieldName: 'Họ tên' } }
   * { minlength: { fieldName: 'Mật khẩu', requiredLength: 8 } }
   */
  public  extractFieldNameFromError(): string | undefined {
    if (!(this.control && this.control.errors)) {
      return undefined;
    }

    // Get the first error key
    const errorKeys = Object.keys(this.control.errors);
    if (errorKeys.length === 0) {
      return undefined;
    }

    // Check each error for a fieldName property
    for (const errorKey of errorKeys) {
      const errorValue = this.control.errors[errorKey];
      
      // If error value is an object and has fieldName property
      if (errorValue && typeof errorValue === 'object' && 'fieldName' in errorValue) {
        return errorValue.fieldName;
      }
    }

    return undefined;
  }
}