/**
 * Base component size options
 */
export const BASE_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type BaseSize = (typeof BASE_SIZES)[keyof typeof BASE_SIZES];

/**
 * Base component style variants
 */
export const BASE_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export type BaseVariant = (typeof BASE_VARIANTS)[keyof typeof BASE_VARIANTS];
