import { Injectable } from '@angular/core';
import { BehaviorSubject, filter, map, type Observable } from 'rxjs';

interface LoadingItem {
  id: string;
  isLoading: boolean;
  metadata?: Record<string, unknown>;
}

@Injectable({
  providedIn: 'root',
})
export class LoadingService {
  private readonly loadingState = new BehaviorSubject<Map<string, LoadingItem>>(new Map());
  setLoading(loadingItem: LoadingItem): void {
    const currentLoading = this.loadingState.getValue();
    currentLoading.set(loadingItem.id, loadingItem);
    this.loadingState.next(new Map(currentLoading));
  }

  getLoading(): Observable<Map<string, LoadingItem>> {
    return this.loadingState.asObservable();
  }
  isAppLoading(): Observable<boolean> {
    return this.loadingState.pipe(
      map((loadingItems) => {
        return Array.from(loadingItems.values()).some((item) => item.isLoading && !item?.metadata?.['ignoreGlobalLoading']);
      }),
    );
  }

  getRequestLoading(reqId: string): Observable<LoadingItem | undefined> {
    return this.loadingState.pipe(map(loadingItems => loadingItems.get(reqId)));
  }
}
