import { computed, inject, Injectable, signal, effect } from '@angular/core';
import { AbstractControl, FormGroup } from '@angular/forms';
import { VALIDATION_MESSAGES_TOKEN, type MessageFunction } from './messages/public-api';
import { TranslateService } from '@ngx-translate/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { EMPTY } from 'rxjs';

/**
 * Validation Service - Simplified Version
 *
 * ✅ Dynamic placeholder replacement
 * ✅ Multi-language support (auto handled by TranslateService)
 * ✅ Support named placeholders: {{fieldName}}, {{minLength}}, {{max}}, etc.
 * ✅ Support indexed placeholders: {{0}}, {{1}}, {{2}}, etc.
 * ✅ Flexible and extensible
 * ✅ Function-based messages that automatically react to language changes
 * ✅ Injectable messages via VALIDATION_MESSAGES_TOKEN
 */
@Injectable({
  providedIn: 'root',
})
export class ValidationService {
  private translateService = inject(TranslateService, { optional: true });
  
  // Inject validation messages (functions that call TranslateService.instant())
  private injectedMessages = inject(VALIDATION_MESSAGES_TOKEN, { optional: true });
  
  // Track language changes to trigger reactivity
  private currentLang = toSignal(
    this.translateService?.onLangChange ?? EMPTY
  );
  
  // Signal containing validation messages (automatically reactive to language changes via TranslateService)
  private messagesSignal = signal(this.injectedMessages || {});

  // Computed signal that depends on current language - this makes it reactive!
  public messages = computed(() => {
    // Access currentLang to create dependency - when language changes, this will re-run
    this.currentLang();
    // Return messages - the message functions will use current language when called
    return this.messagesSignal();
  });

  /**
   * Get current messages (for reactivity tracking)
   */
  getMessages(): { [key: string]: string | MessageFunction } {
    return this.messages();
  }

  /**
   * Set or extend validation messages
   * 
   * Note: For application-wide custom messages, prefer using providers:
   * - provideValidationMessages()
   * - provideCustomValidationMessages()
   */
  setMessages(messages: { [key: string]: string | MessageFunction }): void {
    this.messagesSignal.set({
      ...this.messagesSignal(),
      ...messages,
    });
  }

  /**
   * Get error message for a control
   *
   * @param control - FormControl instance
   * @param fieldName - Display name of the field
   * @param customMessages - Optional custom messages for this field
   * @returns Error message string or empty string
   */
  getErrorMessage(
    control: AbstractControl | null,
    fieldName = 'Trường này',
    customMessages?: { [key: string]: string }
  ): string {
    if (!((control && control.errors ) && control.touched)) {
      return '';
    }

    // Get first error
    const errorKey = Object.keys(control.errors)[0];
    const errorValue = control.errors[errorKey];

    // Get message template (custom > default)
    const messageOrFunction = customMessages?.[errorKey] || this.messages()[errorKey];

    if (!messageOrFunction) {
      // Try to get message from TranslateService as fallback
      if (this.translateService) {
        const translationKey = `VALIDATION.${errorKey}`;
        const translated = this.translateService.instant(translationKey);
        
        // Check if translation was found (instant returns the key if not found)
        if (translated && translated !== translationKey) {
          const context = this.buildMessageContext(fieldName, errorKey, errorValue, control);
          return this.replacePlaceholders(translated, context);
        }
      }
      
      return `${fieldName} không hợp lệ`;
    }

    // Check if it's a function (new reactive approach)
    if (typeof messageOrFunction === 'function') {
      const context = this.buildMessageContext(fieldName, errorKey, errorValue, control);
      const messageFn = messageOrFunction as (params?: any) => string;
      return messageFn(context);
    }

    // Legacy string template approach
    const template = messageOrFunction as string;
    return this.formatMessage(
      template,
      fieldName,
      errorKey,
      errorValue,
      control
    );
  }

  /**
   * Get all error messages for a form
   */
  getAllErrorMessages(
    form: FormGroup,
    fieldNames: { [key: string]: string }
  ): { [key: string]: string } {
    const errors: { [key: string]: string } = {};

    Object.keys(form.controls).forEach((key) => {
      const control = form.get(key);
      const fieldName = fieldNames[key] || key;
      const errorMessage = this.getErrorMessage(control, fieldName);

      if (errorMessage) {
        errors[key] = errorMessage;
      }
    });

    return errors;
  }

  /**
   * Check if control has error (and is touched)
   */
  hasError(control: AbstractControl | null): boolean {
    return !!(control && control.errors && control.touched);
  }

  /**
   * Check if control has specific error
   */
  hasSpecificError(control: AbstractControl | null, errorKey: string): boolean {
    return !!(
      control &&
      control.errors &&
      control.errors[errorKey] &&
      control.touched
    );
  }

  /**
   * Mark all controls in a FormGroup as touched
   */
  markFormGroupTouched(formGroup: FormGroup): void {
    Object.keys(formGroup.controls).forEach((key) => {
      const control = formGroup.get(key);

      if (control instanceof FormGroup) {
        this.markFormGroupTouched(control);
      } else {
        control?.markAsTouched();
      }
    });
  }

  /**
   * Get validation classes for a control
   */
  getValidationClasses(control: AbstractControl | null): string {
    if (!(control && control.touched)) {
      return '';
    }
    return control.valid ? 'is-valid' : 'is-invalid';
  }

  /**
   * Format message with dynamic placeholders
   *
   * Supports:
   * 1. Named placeholders: {{fieldName}}, {{minLength}}, {{max}}, etc.
   * 2. Indexed placeholders: {{0}}, {{1}}, {{2}}, etc.
   * 3. Special placeholders: {{value}}, {{actualLength}}, etc.
   *
   * Examples:
   * - "{{fieldName}} là bắt buộc" → "Email là bắt buộc"
   * - "{{fieldName}} phải có ít nhất {{minLength}} ký tự" → "Username phải có ít nhất 6 ký tự"
   * - "Giá trị phải từ {{min}} đến {{max}}" → "Giá trị phải từ 1 đến 100"
   * - "{{0}} không đúng định dạng {{1}}" → "Email không đúng định dạng email"
   *
   * @private
   */
  private formatMessage(
    template: string,
    fieldName: string,
    errorKey: string,
    errorValue: any,
    control: AbstractControl
  ): string {
    // Build context object with all available data
    const context = this.buildMessageContext(
      fieldName,
      errorKey,
      errorValue,
      control
    );

    // Replace all placeholders
    return this.replacePlaceholders(template, context);
  }

  /**
   * Build context object for placeholder replacement
   *
   * @private
   */
  private buildMessageContext(
    fieldName: string,
    errorKey: string,
    errorValue: any,
    control: AbstractControl
  ): Record<string, any> {
    const context: Record<string, any> = {
      // Field info
      fieldName: fieldName,
      field: fieldName,
      name: fieldName,

      // Error info
      errorKey: errorKey,
      error: errorKey,

      // Control value
      value: control.value,
      actualValue: control.value,
      currentValue: control.value,

      // Indexed placeholders (for backward compatibility)
      '0': fieldName,
    };

    // Handle different error value types
    if (errorValue === true || errorValue === false) {
      // Boolean error (e.g., required: true)
      // No additional context needed
      return context;
    }

    if (typeof errorValue === 'object' && errorValue !== null) {
      // Extract all properties from error object
      Object.keys(errorValue).forEach((key) => {
        context[key] = errorValue[key];
      });

      // Add common aliases
      if ('requiredLength' in errorValue) {
        context['minLength'] = errorValue.requiredLength;
        context['required'] = errorValue.requiredLength;
        context['1'] = errorValue.requiredLength;
      }

      if ('actualLength' in errorValue) {
        context['length'] = errorValue.actualLength;
        context['currentLength'] = errorValue.actualLength;
      }

      if ('min' in errorValue) {
        context['minimum'] = errorValue.min;
        context['1'] = errorValue.min;
      }

      if ('max' in errorValue) {
        context['maximum'] = errorValue.max;
        context['1'] = errorValue.max;
      }

      if ('minDate' in errorValue) {
        context['1'] = this.formatDate(errorValue.minDate);
      }

      if ('maxDate' in errorValue) {
        context['1'] = this.formatDate(errorValue.maxDate);
      }

      if ('allowedTypes' in errorValue) {
        context['types'] = Array.isArray(errorValue.allowedTypes)
          ? errorValue.allowedTypes.join(', ')
          : errorValue.allowedTypes;
        context['1'] = context['types'];
      }

      if ('maxSize' in errorValue) {
        context['size'] = errorValue.maxSize;
        context['1'] = errorValue.maxSize;
      }

      // Add indexed placeholders from object values
      const values = Object.values(errorValue);
      values.forEach((val, index) => {
        if (!context[`${index + 1}`]) {
          context[`${index + 1}`] = val;
        }
      });
    } else {
      // Primitive value (string, number, etc.)
      context['1'] = errorValue?.toString() || '';
      context['param'] = errorValue?.toString() || '';
    }

    return context;
  }

  /**
   * Replace all placeholders in template with values from context
   *
   * Supports:
   * - {{fieldName}}, {{minLength}}, etc. (named)
   * - {{0}}, {{1}}, {{2}}, etc. (indexed)
   *
   * @private
   */
  private replacePlaceholders(
    template: string,
    context: Record<string, any>
  ): string {
    return template.replace(/\{\{(\w+)\}\}/g, (match, key) => {
      // Check if key exists in context
      if (key in context) {
        const value = context[key];

        // Convert to string
        if (value === null || value === undefined) {
          return '';
        }

        if (typeof value === 'object') {
          return JSON.stringify(value);
        }

        return String(value);
      }

      // Placeholder not found - return original
      return match;
    });
  }

  /**
   * Format date for display
   * @private
   */
  private formatDate(date: any): string {
    if (!date) return '';

    // Use browser's default locale
    const locale = navigator.language || 'vi-VN';

    if (date instanceof Date) {
      return date.toLocaleDateString(locale);
    }

    if (typeof date === 'string' || typeof date === 'number') {
      return new Date(date).toLocaleDateString(locale);
    }

    return String(date);
  }
}
