import { ChangeDetectionStrategy, Component, contentChild, input, model, output, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { PickListModule } from 'primeng/picklist';
import { ButtonProps } from 'primeng/button';
import {
  PickListMoveToSourceEvent,
  PickListMoveAllToSourceEvent,
  PickListMoveAllToTargetEvent,
  PickListMoveToTargetEvent,
  PickListSourceReorderEvent,
  PickListTargetReorderEvent,
  PickListSourceSelectEvent,
  PickListTargetSelectEvent,
  PickListSourceFilterEvent,
  PickListTargetFilterEvent,
} from './cmm-picklist.types';
import { PickListFilterMatchMode } from './cmm-picklist.constants';

/**
 * CmmPickListComponent - Angular 19 wrapper for PrimeNG PickList
 *
 * A thin wrapper component that provides signal-based inputs and two-way binding
 * for PrimeNG's PickList component. PickList is used to reorder items between
 * different lists with drag-drop and transfer operations.
 *
 * @example
 * ```html
 * <cmm-pick-list
 *   [(source)]="availableProducts"
 *   [(target)]="selectedProducts"
 *   sourceHeader="Available"
 *   targetHeader="Selected">
 *   <ng-template pTemplate="item" let-product>
 *     {{ product.name }}
 *   </ng-template>
 * </cmm-pick-list>
 * ```
 */
@Component({
  selector: 'cmm-pick-list',
  standalone: true,
  imports: [CommonModule, PickListModule],
  templateUrl: './cmm-picklist.component.html',
  styleUrl: './cmm-picklist.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  exportAs: 'cmmpicklist',
})
export class CmmPickListComponent {
  // Template references
  readonly itemTemplate = contentChild<TemplateRef<any>>('item');
  readonly sourceheaderTemplate = contentChild<TemplateRef<any>>('sourceheader');
  readonly targetheaderTemplate = contentChild<TemplateRef<any>>('targetheader');
  readonly sourcefilterTemplate = contentChild<TemplateRef<any>>('sourcefilter');
  readonly targetfilterTemplate = contentChild<TemplateRef<any>>('targetfilter');
  readonly emptymessagesourceTemplate = contentChild<TemplateRef<any>>('emptymessagesource');
  readonly emptyfiltermessagesourceTemplate = contentChild<TemplateRef<any>>('emptyfiltermessagesource');
  readonly emptymessagetargetTemplate = contentChild<TemplateRef<any>>('emptymessagetarget');
  readonly emptyfiltermessagetargetTemplate = contentChild<TemplateRef<any>>('emptyfiltermessagetarget');
  readonly moveupiconTemplate = contentChild<TemplateRef<any>>('moveupicon');
  readonly movetopiconTemplate = contentChild<TemplateRef<any>>('movetopicon');
  readonly movedowniconTemplate = contentChild<TemplateRef<any>>('movedownicon');
  readonly movebottomiconTemplate = contentChild<TemplateRef<any>>('movebottomicon');
  readonly movetotargeticonTemplate = contentChild<TemplateRef<any>>('movetotargeticon');
  readonly movealltotargeticonTemplate = contentChild<TemplateRef<any>>('movealltotargeticon');
  readonly movetosourceiconTemplate = contentChild<TemplateRef<any>>('movetosourceicon');
  readonly movealltosourceiconTemplate = contentChild<TemplateRef<any>>('movealltosourceicon');
  readonly targetfiltericonTemplate = contentChild<TemplateRef<any>>('targetfiltericon');
  readonly sourcefiltericonTemplate = contentChild<TemplateRef<any>>('sourcefiltericon');

  // Input properties
  /** Text for the source list caption */
  readonly sourceHeader = input<string>();
  /** Text for the target list caption */
  readonly targetHeader = input<string>();
  /** Index of the element in tabbing order */
  readonly tabindex = input<number>(0);
  /** Aria label for right button */
  readonly rightButtonAriaLabel = input<string>();
  /** Aria label for left button */
  readonly leftButtonAriaLabel = input<string>();
  /** Aria label for all right button */
  readonly allRightButtonAriaLabel = input<string>();
  /** Aria label for all left button */
  readonly allLeftButtonAriaLabel = input<string>();
  /** Aria label for up button */
  readonly upButtonAriaLabel = input<string>();
  /** Aria label for down button */
  readonly downButtonAriaLabel = input<string>();
  /** Aria label for top button */
  readonly topButtonAriaLabel = input<string>();
  /** Aria label for bottom button */
  readonly bottomButtonAriaLabel = input<string>();
  /** Whether the component should be responsive */
  readonly responsive = input<boolean>(false);
  /** Fields to search against when filtering */
  readonly filterBy = input<string>();
  /** Locale to use in filtering */
  readonly filterLocale = input<string>();
  /** Function to optimize dom operations by delegating to ngForTrackBy */
  readonly trackBy = input<Function>();
  /** Function to optimize dom operations for source list */
  readonly sourceTrackBy = input<Function>();
  /** Function to optimize dom operations for target list */
  readonly targetTrackBy = input<Function>();
  /** Whether to show filter input for source list */
  readonly showSourceFilter = input<boolean>(true);
  /** Whether to show filter input for target list */
  readonly showTargetFilter = input<boolean>(true);
  /** Whether metaKey needs to be pressed to select or unselect */
  readonly metaKeySelection = input<boolean>(false);
  /** Whether to enable dragdrop based reordering */
  readonly dragdrop = input<boolean>(false);
  /** Inline style of the component */
  readonly style = input<any>();
  /** Style class of the component */
  readonly styleClass = input<string>();
  /** Inline style of the source list element */
  readonly sourceStyle = input<any>();
  /** Inline style of the target list element */
  readonly targetStyle = input<any>();
  /** Whether to show buttons of source list */
  readonly showSourceControls = input<boolean>(true);
  /** Whether to show buttons of target list */
  readonly showTargetControls = input<boolean>(true);
  /** Placeholder text on source filter input */
  readonly sourceFilterPlaceholder = input<string>();
  /** Placeholder text on target filter input */
  readonly targetFilterPlaceholder = input<string>();
  /** When present, it specifies that the component should be disabled */
  readonly disabled = input<boolean>(false);
  /** Defines a string that labels the filter input of source list */
  readonly ariaSourceFilterLabel = input<string>();
  /** Defines a string that labels the filter input of target list */
  readonly ariaTargetFilterLabel = input<string>();
  /** Defines how the items are filtered */
  readonly filterMatchMode = input<PickListFilterMatchMode>('contains');
  /** Whether to displays rows with alternating colors */
  readonly stripedRows = input<boolean>(false);
  /** Keeps selection on the transfer list */
  readonly keepSelection = input<boolean>(false);
  /** Height of the viewport */
  readonly scrollHeight = input<string>('14rem');
  /** Whether to focus on the first visible or selected element */
  readonly autoOptionFocus = input<boolean>(true);
  /** Used to pass all properties to the Button component */
  readonly buttonProps = input<ButtonProps>();
  /** Used to pass all properties to the move up button */
  readonly moveUpButtonProps = input<ButtonProps>();
  /** Used to pass all properties to the move top button */
  readonly moveTopButtonProps = input<ButtonProps>();
  /** Used to pass all properties to the move down button */
  readonly moveDownButtonProps = input<ButtonProps>();
  /** Used to pass all properties to the move bottom button */
  readonly moveBottomButtonProps = input<ButtonProps>();
  /** Used to pass all properties to the move to target button */
  readonly moveToTargetProps = input<ButtonProps>();
  /** Used to pass all properties to the move all to target button */
  readonly moveAllToTargetProps = input<ButtonProps>();
  /** Used to pass all properties to the move to source button */
  readonly moveToSourceProps = input<ButtonProps>();
  /** Used to pass all properties to the move all to source button */
  readonly moveAllToSourceProps = input<ButtonProps>();
  /** Width of the screen at which the component should change its behavior */
  readonly breakpoint = input<string>();

  // Two-way bindable properties
  /** An array of objects for the source list */
  readonly source = model<any>();
  /** An array of objects for the target list */
  readonly target = model<any>();

  // Output events
  /** Callback to invoke when items are moved from target to source */
  readonly onMoveToSource = output<PickListMoveToSourceEvent>();
  /** Callback to invoke when all items are moved from target to source */
  readonly onMoveAllToSource = output<PickListMoveAllToSourceEvent>();
  /** Callback to invoke when all items are moved from source to target */
  readonly onMoveAllToTarget = output<PickListMoveAllToTargetEvent>();
  /** Callback to invoke when items are moved from source to target */
  readonly onMoveToTarget = output<PickListMoveToTargetEvent>();
  /** Callback to invoke when items are reordered within source list */
  readonly onSourceReorder = output<PickListSourceReorderEvent>();
  /** Callback to invoke when items are reordered within target list */
  readonly onTargetReorder = output<PickListTargetReorderEvent>();
  /** Callback to invoke when items are selected within source list */
  readonly onSourceSelect = output<PickListSourceSelectEvent>();
  /** Callback to invoke when items are selected within target list */
  readonly onTargetSelect = output<PickListTargetSelectEvent>();
  /** Callback to invoke when the source list is filtered */
  readonly onSourceFilter = output<PickListSourceFilterEvent>();
  /** Callback to invoke when the target list is filtered */
  readonly onTargetFilter = output<PickListTargetFilterEvent>();
  /** Callback to invoke when the list is focused */
  readonly onFocus = output<Event>();
  /** Callback to invoke when the list is blurred */
  readonly onBlur = output<Event>();
}
