import { Component, ChangeDetectionStrategy, model, input } from '@angular/core';
import { Stepper } from 'primeng/stepper';

/**
 * Stepper is a component that streamlines a wizard-like workflow,
 * organizing content into coherent steps and visually guiding users
 * through a numbered progression in a multistep process.
 * Wraps PrimeNG Stepper component.
 */
@Component({
  selector: 'cmm-stepper',
  standalone: true,
  imports: [Stepper],
  templateUrl: './cmm-stepper.component.html',
  styleUrl: './cmm-stepper.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmStepperComponent {
  // Model
  /**
   * A model that can hold a numeric value or be undefined
   */
  readonly value = model<number>();

  // Input properties
  /**
   * A boolean variable that captures user input
   */
  readonly linear = input<boolean>(false);

  /**
   * Transition options of the animation
   */
  readonly transitionOptions = input<string>('400ms cubic-bezier(0.86, 0, 0.07, 1)');
}
