/**
 * Upload Component Types & Interfaces
 * Following SOLID - Interface Segregation Principle
 */

import { TemplateRef } from '@angular/core';
import { FileUploadMethod } from '../base/public-api';

// ========================================
// Domain Models
// ========================================

export interface FileValidationError {
  type: 'size' | 'type' | 'limit' | 'duplicate' | 'custom';
  message: string;
  file?: File;
}

export interface FileMetadata {
  name: string;
  size: number;
  type: string;
  lastModified: number;
}

// ========================================
// Configuration Interfaces
// ========================================

export interface UploadValidationConfig {
  maxFileSize: number; // bytes
  maxFiles: number;
  minFiles: number;
  accept: string; // comma-separated file types
  invalidFileSizeMessageDetail?: string,
  invalidFileLimitMessageDetail?: string,
  invalidFileTypeMessageDetail?: string,
  invalidFileSizeMessageSummary?: string,
  invalidFileTypeMessageSummary?: string,
  invalidFileLimitMessageSummary?: string,
}

export interface UploadUIConfig {
  title: string;
  chooseLabel: string;
  dropZoneLabel: string;
  orLabel: string;
  acceptInfoLabel: string;
  primaryButtonLabel: string;
  secondaryButtonLabel: string;
  importNoteLabel: string;
  templateLinkLabel: string;
  importWarningLabel: string;
}

export interface UploadBehaviorConfig {
  name: string;
  url: string;
  method: FileUploadMethod;
  multiple: boolean;
  disabled: boolean;
  auto: boolean;
  showTemplateLink: boolean;
  showImportNotes: boolean;
  showFooter: boolean;
}

export interface UploadConfig extends UploadValidationConfig, UploadUIConfig, UploadBehaviorConfig { }

// ========================================
// Component Props Interface (Single Input)
// ========================================

export interface UploadProps {
  // Behavior Configuration
  name?: string;
  url?: string;
  method?: FileUploadMethod;
  multiple?: boolean;
  disabled?: boolean;
  auto?: boolean;

  // Validation Configuration
  maxFileSize?: number; // bytes
  maxFiles?: number;
  minFiles?: number;
  accept?: string; // comma-separated file types

  // UI Labels
  title?: string;
  chooseLabel?: string;
  dropZoneLabel?: string;
  orLabel?: string;
  acceptInfoLabel?: string;
  primaryButtonLabel?: string;
  secondaryButtonLabel?: string;
  importNoteLabel?: string;
  templateLinkLabel?: string;
  importWarningLabel?: string;

  // UI Visibility
  showTemplateLink?: boolean;
  showImportNotes?: boolean;
  showFooter?: boolean;

  showProgressBar?: boolean;
  uploading?: boolean;
  uploadPercent?: number;
  fileItemTemplate?: TemplateRef<unknown>;
  // messages
  invalidFileSizeMessageDetail?: string;
  invalidFileLimitMessageDetail?: string;
  invalidFileTypeMessageDetail?: string;
  invalidFileSizeMessageSummary?: string;
  invalidFileTypeMessageSummary?: string;
  invalidFileLimitMessageSummary?: string;
  // summary
  summary?: string;
  fileNameClass?: string;
  [key: string]: any; // Allow additional props for extensibility 
}

// ========================================
// Template Override Interfaces
// ========================================

export interface UploadTemplates {
  headerTemplate?: TemplateRef<any>;
  contentTemplate?: TemplateRef<any>;
  emptyTemplate?: TemplateRef<any>;
  infoTemplate?: TemplateRef<any>;
  footerTemplate?: TemplateRef<any>;
}

// ========================================
// State Interfaces
// ========================================

export interface UploadState {
  files: File[];
  errors: FileValidationError[];
  isUploading: boolean;
  isDragOver: boolean;
}

export interface UploadDerivedState {
  hasFiles: boolean;
  fileCount: number;
  totalSize: number;
  totalSizeFormatted: string;
  isValid: boolean;
  canSubmit: boolean;
}

// ========================================
// Event Interfaces
// ========================================

export interface FileSelectEventData {
  files: File[];
  timestamp: number;
}

export interface FileRemoveEventData {
  file: File;
  index: number;
}

export interface ValidationErrorEventData {
  errors: FileValidationError[];
  timestamp: number;
}

// ========================================
// Service Interfaces (Dependency Inversion)
// ========================================

export interface IFileValidator {
  validateFiles(files: File[], config: UploadValidationConfig): FileValidationError[];
  validateFileType(file: File, accept: string): boolean;
  validateFileSize(file: File, maxSize: number): boolean;
}

export interface IFileFormatter {
  formatFileSize(bytes: number): string;
  getFileIcon(file: File): string;
  extractFileExtension(filename: string): string;
}

export interface IUploadFacade {
  // State
  readonly files: () => File[];
  readonly errors: () => FileValidationError[];
  readonly isUploading: () => boolean;
  readonly isDragOver: () => boolean;
  readonly hasFiles: () => boolean;
  readonly fileCount: () => number;
  readonly isValid: () => boolean;
  readonly canSubmit: () => boolean;

  // Actions
  selectFiles(files: File[]): void;
  removeFile(index: number): void;
  clearFiles(): void;
  setDragOver(isDragOver: boolean): void;
  handleDrop(files: File[]): void;
}
