import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  model,
  contentChild,
  TemplateRef,
  forwardRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { ToggleButton } from 'primeng/togglebutton';

export interface ToggleButtonChangeEvent {
  originalEvent: Event;
  checked: boolean | undefined;
}

@Component({
  selector: 'cmm-togglebutton',
  standalone: true,
  imports: [CommonModule, FormsModule, ToggleButton],
  templateUrl: './cmm-togglebutton.component.html',
  styleUrl: './cmm-togglebutton.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmToggleButtonComponent),
      multi: true,
    },
  ],
})
export class CmmToggleButtonComponent implements ControlValueAccessor {
  checked = model<boolean>(false);
  onLabel = input<string>('Yes');
  offLabel = input<string>('No');
  onIcon = input<string>();
  offIcon = input<string>();
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();
  disabled = input<boolean>(false);
  style = input<Record<string, any>>();
  styleClass = input<string>('');
  inputId = input<string>();
  tabindex = input<number>(0);
  size = input<'small' | 'large' | null>();
  iconPos = input<'left' | 'right'>('left');
  autofocus = input<boolean>(false);
  allowEmpty = input<boolean>(false);

  onChange = output<ToggleButtonChangeEvent>();

  iconTemplate = contentChild<TemplateRef<any>>('icon');
  contentTemplate = contentChild<TemplateRef<any>>('content');

  private onTouched: () => void = () => {};
  private onChangeFn: (value: boolean) => void = () => {};

  writeValue(value: boolean): void {
    this.checked.set(value ?? false);
  }

  registerOnChange(fn: (value: boolean) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handled via disabled input
  }

  handleChange(event: ToggleButtonChangeEvent): void {
    const value = event.checked ?? false;
    this.checked.set(value);
    this.onChangeFn(value);
    this.onTouched();
    this.onChange.emit(event);
  }
}
