import { Component, ChangeDetectionStrategy, input, output, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { SplitButton } from 'primeng/splitbutton';
import { MenuItem } from 'primeng/api';

@Component({
  selector: 'cmm-splitbutton',
  standalone: true,
  imports: [CommonModule, SplitButton],
  templateUrl: './cmm-splitbutton.component.html',
  styleUrl: './cmm-splitbutton.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmSplitButtonComponent {
  model = input.required<MenuItem[]>();
  severity = input<'secondary' | 'success' | 'info' | 'warn' | 'danger' | 'contrast' | 'help' | null>();
  raised = input<boolean>(false);
  rounded = input<boolean>(false);
  text = input<boolean>(false);
  outlined = input<boolean>(false);
  size = input<'small' | 'large' | null>();
  plain = input<boolean>(false);
  icon = input<string>();
  iconPos = input<'left' | 'right'>('left');
  label = input<string>();
  tooltip = input<string>();
  tooltipOptions = input<any>();
  style = input<Record<string, any>>();
  styleClass = input<string>('');
  menuStyle = input<Record<string, any>>();
  menuStyleClass = input<string>('');
  dropdownIcon = input<string>();
  appendTo = input<string | HTMLElement>('body');
  disabled = input<boolean>(false);
  tabindex = input<number>();
  autofocus = input<boolean>(false);
  buttonProps = input<any>();
  menuButtonProps = input<any>();

  onClick = output<Event>();
  onDropdownClick = output<Event>();

  contentTemplate = contentChild<TemplateRef<any>>('content');
  dropdowniconTemplate = contentChild<TemplateRef<any>>('dropdownicon');
}
