import { Component, input } from "@angular/core";
import { TranslatePipe } from "@ngx-translate/core";
import { ProgressBar } from "primeng/progressbar";



@Component({
    selector: 'ubck-importing',
    template: `
   <div class="import-wrapper">
      <svg
        width="96"
        height="96"
        viewBox="0 0 96 96"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
      >
        <circle cx="48" cy="48" r="47.5" stroke="#F3F3F3" />
        <rect x="24" y="24" width="48" height="48" rx="24" fill="#EAFFEA" />
        <path
          d="M34 48C34 40.268 40.268 34 48 34V34C55.732 34 62 40.268 62 48V48C62 55.732 55.732 62 48 62V62C40.268 62 34 55.732 34 48V48Z"
          fill="#00894A"
        />
        <path
          d="M41.3906 48.0001L45.7928 52.4023L54.6128 43.5979"
          stroke="white"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
        />
      </svg>
      <header class="">
        <h5>{{fileInprogressTitleKey() | translate}}</h5>
      </header>
      <div class="file-info">
        <div class="flex items-center gap-2">
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M3 10C3 6.22876 3 4.34315 4.17157 3.17157C5.34315 2 7.22876 2 11 2H13C16.7712 2 18.6569 2 19.8284 3.17157C21 4.34315 21 6.22876 21 10V14C21 17.7712 21 19.6569 19.8284 20.8284C18.6569 22 16.7712 22 13 22H11C7.22876 22 5.34315 22 4.17157 20.8284C3 19.6569 3 17.7712 3 14V10Z"
              stroke="#0F5A43"
              stroke-width="1.5"
            />
            <path
              d="M8 10H16"
              stroke="#0F5A43"
              stroke-width="1.5"
              stroke-linecap="round"
            />
            <path
              d="M8 14H13"
              stroke="#0F5A43"
              stroke-width="1.5"
              stroke-linecap="round"
            />
          </svg>

          <span class="filename">{{ file().name }}</span>
        </div>
        
       <div class="progress-bar-container">
             <p-progressbar [value]="progress()" [showValue]="false"  styleClass="progress-bar" /> {{progress()}}%
        </div>
      </div>
    `,
    imports: [ProgressBar, TranslatePipe],
    styleUrls: ['./importing.scss'],
})
export class Importing {
    file = input.required<File>();
    progress = input.required<number>();
    fileInprogressTitleKey = input<string>('Đang tải file....');
}