import {
  Component,
  input,
  output,
  model,
  forwardRef,
  ChangeDetectionStrategy,
} from '@angular/core';

import {
  FormsModule,
  NG_VALUE_ACCESSOR,
  ControlValueAccessor,
  ReactiveFormsModule,
} from '@angular/forms';
import { RadioButtonModule, RadioButtonClickEvent } from 'primeng/radiobutton';
import { RadioButtonVariant, RadioButtonSize } from './cmm-radiobutton.types';
import { RADIOBUTTON_DEFAULTS } from './cmm-radiobutton.constants';

@Component({
  selector: 'cmm-radiobutton, div[cmm-radiobutton]',
  standalone: true,
  imports: [FormsModule, RadioButtonModule, ReactiveFormsModule],
  template: `
    <p-radiobutton
      [value]="optionValue()"
      [name]="name()"
      [disabled]="disabled()"
      [variant]="variant()"
      [tabindex]="tabindex()"
      [inputId]="inputId()"
      [ariaLabelledBy]="ariaLabelledBy() ?? undefined"
      [ariaLabel]="ariaLabel() ?? undefined"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined"
      [autofocus]="autofocus()"
      (onClick)="handleClick($event)"
      (onFocus)="handleFocus($event)"
      (onBlur)="handleBlur($event)"
    />
  `,
  styleUrl: './cmm-radiobutton.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmRadiobuttonComponent),
      multi: true,
    },
  ]
})
export class CmmRadiobuttonComponent implements ControlValueAccessor {
  // Model
  value = model<any>();

  // Core props
  optionValue = model<any>();
  name = input<string>('');
  disabled = model<boolean>(RADIOBUTTON_DEFAULTS.DISABLED);
  variant = input<RadioButtonVariant>(RADIOBUTTON_DEFAULTS.VARIANT);
  size = input<RadioButtonSize>();
  tabindex = input<number>(RADIOBUTTON_DEFAULTS.TABINDEX);
  inputId = input<string>('');
  ariaLabelledBy = input<string>();
  ariaLabel = input<string>();
  style = input<Record<string, any>>();
  styleClass = input<string>();
  autofocus = input<boolean>(false);

  // Output events
  onClick = output<RadioButtonClickEvent>();
  onFocus = output<Event>();
  onBlur = output<Event>();

  // ControlValueAccessor
  private onChangeFn: (value: any) => void = () => { };
  private onTouchedFn: () => void = () => { };

  writeValue(value: any): void {
    this.optionValue.set(value);
  }

  registerOnChange(fn: (value: any) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handle if needed
    this.disabled.set(isDisabled);
  }

  handleClick(event: RadioButtonClickEvent): void {
    this.onClick.emit(event);
    this.onChangeFn(event.value);
  }

  handleFocus(event: Event): void {
    this.onFocus.emit(event);
  }

  handleBlur(event: Event): void {
    this.onBlur.emit(event);
    this.onTouchedFn();
  }
}
