import { Injectable } from "@angular/core";
import { BaseStyle } from "primeng/base";

const theme = ({ dt }: any) => `
    .cmm-typography{
        color: ${dt('text.color')};
        word-break: break-word;
    }
    .cmm-typography-secondary{color: ${dt('text.secondary')}}
    .cmm-typography-muted{color: ${dt('text.muted.color')}}
    .cmm-typography-success{color: ${dt('green.500')}}
    .cmm-typography-warning{color: ${dt('amber.500')}}
    .cmm-typography-danger{color: ${dt('red.500')}}
    .cmm-typography-form-required{position: relative}
    .cmm-typography-form-required::after{content: '*'; color: ${dt('red.500')}; margin-left: 4px}
    .cmm-typography-disabled{color: ${dt('form.field.disabled.color')}; cursor: not-allowed; user-select: none}
    .cmm-typography-copyable{cursor: pointer}
    .cmm-typography-ellipsis{overflow: hidden; text-overflow: ellipsis;}
    .cmm-typography-ellipsis.text-paragraph{white-space: normal;}
    .cmm-heading{margin: 0; margin-bottom: 0.5em; color: ${dt('text.color')}; font-family: ${dt('typography.font.family.base')};  line-height: 1.2}
    .cmm-heading-1{font-size: 32px; line-height: 1.2; margin-bottom: 0.5em; font-family: ${dt('typography.font.family.base')}; }
    .cmm-heading-2{font-size: 28px; line-height: 1.3; margin-bottom: 0.5em; font-family: ${dt('typography.font.family.base')}; }
    .cmm-heading-3{font-size: 24px; line-height: 1.35; margin-bottom: 0.5em; font-family: ${dt('typography.font.family.base')}; }
    .cmm-heading-4{font-size: 20px; line-height: 1.4; margin-bottom: 0.5em; font-family: ${dt('typography.font.family.base')};}
    .cmm-heading-5{font-size: 18px; line-height: 1.5; margin-bottom: 0.5em; font-family: ${dt('typography.font.family.base')};}
    .cmm-heading-6{font-size: 16px; line-height: 1.5; margin-bottom: 0.5em; font-family: ${dt('typography.font.family.base')};}
    .cmm-heading.typography-secondary{color: ${dt('text.secondary')}}
    .cmm-heading.typography-muted{color: ${dt('text.muted.color')}}
    .cmm-heading.typography-success{color: ${dt('green.500')}}
    .cmm-heading.typography-warning{color: ${dt('amber.500')}}
    .cmm-heading.typography-danger{color: ${dt('red.500')}}
    .cmm-text{font-size: var(--font-size, 14px); color: ${dt('text.color')}}
    .cmm-text-paragraph{margin: 0; margin-bottom: 1em; line-height: 1.6}
    .cmm-text-paragraph:last-child{margin-bottom: 0}
    .cmm-text-inline{display: inline; line-height: inherit}
    .cmm-text-small{font-size: 14px}
    .cmm-text-base{font-size: var(--font-size, 14px);}
    .cmm-text-large{font-size: 18px}
    .cmm-text.typography-secondary{color: ${dt('text.secondary')}}
    .cmm-text.typography-muted{color: ${dt('text.muted.color')};}
    .cmm-text.typography-success{color: ${dt('green.500')}}
    .cmm-text.typography-warning{color: ${dt('amber.500')}}
    .cmm-text.typography-danger{color: ${dt('red.500')}}
    .cmm-text.typography-disabled{color: ${dt('form.field.disabled.color')}; cursor: not-allowed; user-select: none}
    .text-muted{color: ${dt('text.muted.color')};}
    .text-secondary{color: ${dt('text.secondary')}}
    .text-success{color: ${dt('green.500')}}
    .text-warning{color: ${dt('amber.500')}}
    .text-danger{color: ${dt('red.500')}}
    .text-disabled{color: ${dt('form.field.disabled.color')}}
    .text-sm{font-size: 14px}
    .text-base{font-size: var(--font-size, 14px);}
    .text-lg{font-size: 18px}
    .font-normal{font-weight: 400}
    .font-medium{font-weight: 500}
    .font-semibold{font-weight: 600}
    .font-bold{font-weight: 700}
    .typography-ellipsis-single-line{overflow: hidden; white-space: nowrap; text-overflow: ellipsis}
    .typography-ellipsis-multiple-line{overflow: hidden; display: -webkit-box; -webkit-box-orient: vertical; word-break: break-word}
    .copyable{position: relative; cursor: pointer; user-select: none; display: inline-block}
    .copyable:hover{opacity: 0.8}
    .copyable:active{background-color: rgba(0, 0, 0, 0.08)}
    .copy-tooltip-show{opacity: 1}
    @media (max-width: 768px){
        .cmm-heading-1{font-size: 28px}
        .cmm-heading-2{font-size: 24px}
        .cmm-heading-3{font-size: 20px}
        .cmm-heading-4{font-size: 18px}
        .cmm-heading-5{font-size: 16px}
        .cmm-heading-6{font-size: 14px}
        .cmm-text{font-size: var(--font-size, 14px);}
        .cmm-text-large{font-size: 16px}
    }
    @media print{
        .typography, .heading, .text{color: #000}
        .typography-copyable, .typography-editable{cursor: default}
    }
`;

@Injectable()
export class UBCKCustomTypographyStyles extends BaseStyle {
    override style: any = theme;
    override name = 'typography';
    override classes = {}
}