/**
 * Upload Validation Service
 * Following SOLID:
 * - Single Responsibility: File validation only
 * - Open/Closed: Extensible via custom validators
 * - Dependency Inversion: Implements IFileValidator interface
 *
 * NO STATE - Pure business logic only
 */

import { Injectable } from '@angular/core';
import { FileValidationError, IFileValidator, UploadValidationConfig } from './upload.types';
import {
  buildDuplicateFileErrorMessage,
  buildFileLimitErrorMessage,
  buildFileSizeErrorMessage,
  buildFileTypeErrorMessage,
  buildMinFilesErrorMessage,
  isFileDuplicate,
  isFileTypeAccepted,
} from './upload.utils';

@Injectable()
export class FileValidationService implements IFileValidator {
  /**
   * Validate array of files against configuration
   * Returns array of validation errors (empty if valid)
   */
  validateFiles(files: File[], config: UploadValidationConfig, existingFiles: File[] = []): FileValidationError[] {
    const errors: FileValidationError[] = [];

    // Validate file count limits
    const countErrors = this.validateFileCount(files.length, config);
    errors.push(...countErrors);

    // Validate each individual file
    files.forEach((file) => {
      const fileErrors = this.validateSingleFile(file, config, existingFiles);
      errors.push(...fileErrors);
    });

    return errors;
  }

  /**
   * Validate file count against min/max limits
   */
  private validateFileCount(count: number, config: UploadValidationConfig): FileValidationError[] {
    const errors: FileValidationError[] = [];

    if (count > config.maxFiles) {
      errors.push({
        type: 'limit',
        message: buildFileLimitErrorMessage(config.maxFiles),
      });
    }

    if (count < config.minFiles && count > 0) {
      errors.push({
        type: 'limit',
        message: buildMinFilesErrorMessage(config.minFiles),
      });
    }

    return errors;
  }

  /**
   * Validate individual file
   */
  private validateSingleFile(
    file: File,
    config: UploadValidationConfig,
    existingFiles: File[] = [],
  ): FileValidationError[] {
    const errors: FileValidationError[] = [];

    // Duplicate file validation
    if (isFileDuplicate(file, existingFiles)) {
      errors.push({
        type: 'duplicate',
        message: buildDuplicateFileErrorMessage(file.name),
        file,
      });
    }

    // File size validation
    if (!this.validateFileSize(file, config.maxFileSize)) {
      errors.push({
        type: 'size',
        message: buildFileSizeErrorMessage(file.name, file.size, config.maxFileSize),
        file,
      });
    }

    // File type validation
    if (!this.validateFileType(file, config.accept)) {
      errors.push({
        type: 'type',
        message: buildFileTypeErrorMessage(file.name),
        file,
      });
    }

    return errors;
  }

  /**
   * Validate file type against accept pattern
   */
  validateFileType(file: File, accept: string): boolean {
    return isFileTypeAccepted(file, accept);
  }

  /**
   * Validate file size against max size
   */
  validateFileSize(file: File, maxSize: number): boolean {
    return file.size <= maxSize;
  }

  /**
   * Check if files array is valid
   */
  isValid(files: File[], config: UploadValidationConfig): boolean {
    const errors = this.validateFiles(files, config);
    return errors.length === 0 && files.length >= config.minFiles && files.length <= config.maxFiles;
  }
}
