import { booleanAttribute, Directive, ElementRef, EventEmitter, inject, Input, Output } from "@angular/core";
import { UBCKCustomTypographyStyles } from "../styles/typography.style";
import { BaseComponent } from "primeng/basecomponent";

/**
 * Editable feature - can be used independently
 */
@Directive({
  selector: '[cmmEditable]',
  standalone: true,
  host: {
    '[contentEditable]': 'appEditable && !disabled',
    '(blur)': 'handleBlur()',
    '[class.editable]': 'appEditable'
  },
  providers: [UBCKCustomTypographyStyles]
})
export class CmmEditableDirective extends BaseComponent {
  _componentStyle = inject(UBCKCustomTypographyStyles)


  @Input({ transform: booleanAttribute }) appEditable = false;
  @Input({ transform: booleanAttribute }) disabled = false;
  @Output() contentChange = new EventEmitter<string>();

  handleBlur(): void {
    if (!this.appEditable) return;

    const newContent = this.el.nativeElement.textContent || '';
    this.contentChange.emit(newContent);
  }
}
