import { Component, ChangeDetectionStrategy, input, output, model, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Panel } from 'primeng/panel';

export interface PanelBeforeToggleEvent {
  originalEvent: Event;
  collapsed: boolean;
}

export interface PanelAfterToggleEvent {
  originalEvent: Event;
  collapsed: boolean;
}

@Component({
  selector: 'cmm-panel',
  standalone: true,
  imports: [CommonModule, Panel],
  templateUrl: './cmm-panel.component.html',
  styleUrl: './cmm-panel.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmPanelComponent {
  toggleable = input<boolean>(false);
  header = input<string>();
  collapsed = model<any>(false);
  style = input<Record<string, any>>();
  styleClass = input<string>('');
  iconPos = input<'center' | 'start' | 'end'>('end');
  expandIcon = input<string>();
  collapseIcon = input<string>();
  showHeader = input<boolean>(true);
  toggler = input<'header' | 'icon'>('icon');
  transitionOptions = input<string>('400ms cubic-bezier(0.86, 0, 0.07, 1)');
  toggleButtonProps = input<any>();

  onBeforeToggle = output<any>();
  onAfterToggle = output<any>();

  headerTemplate = contentChild<TemplateRef<any>>('header');
  iconsTemplate = contentChild<TemplateRef<any>>('icons');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
}
