import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { IUserActionHeader } from './user-action-header.const';

import { AvatarModule } from 'primeng/avatar';
import { OverlayBadgeModule } from 'primeng/overlaybadge';

@Component({
  selector: 'cmm-user-action-header',
  imports: [OverlayBadgeModule, AvatarModule],
  templateUrl: './user-action-header.component.html',
  styleUrl: './user-action-header.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class UserActionHeaderComponent {
  meta = input.required<IUserActionHeader>();
  eventClickAvatar = output<MouseEvent>();
  eventClickNotification = output<MouseEvent>();

  avatarClick(evt: MouseEvent) {
    this.eventClickAvatar.emit(evt);
  }
  notificationClick(evt: MouseEvent) {
    this.eventClickNotification.emit(evt);
  }
}
