import { ChangeDetectionStrategy, Component, contentChild, TemplateRef } from '@angular/core';

import { TabsModule } from 'primeng/tabs';

@Component({
  selector: 'cmm-tablist',
  standalone: true,
  imports: [TabsModule],
  templateUrl: './cmm-tablist.component.html',
  styleUrl: './cmm-tablist.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmTabListComponent {
  // Content child templates
  previcon = contentChild<TemplateRef<any>>('previcon');
  nexticon = contentChild<TemplateRef<any>>('nexticon');
}
