import { Component, input, viewChild, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ScrollPanel, ScrollPanelModule } from 'primeng/scrollpanel';
import { SCROLLPANEL_DEFAULTS } from './cmm-scrollpanel.constants';

@Component({
  selector: 'cmm-scrollpanel',
  standalone: true,
  imports: [CommonModule, ScrollPanelModule],
  template: `
    <p-scrollPanel
      #scrollPanel
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined"
      [step]="step()">
      @if (contentTemplate()) {
        <ng-template pTemplate="content">
          <ng-container *ngTemplateOutlet="contentTemplate()!" />
        </ng-template>
      } @else {
        <ng-content />
      }
    </p-scrollPanel>
  `,
  styleUrl: './cmm-scrollpanel.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmScrollpanelComponent {
  scrollPanel = viewChild<ScrollPanel>('scrollPanel');

  // Core props
  style = input<Record<string, any>>();
  styleClass = input<string>();
  step = input<number>(SCROLLPANEL_DEFAULTS.STEP);

  // Templates
  contentTemplate = contentChild<TemplateRef<any>>('content');

  // Public methods
  scrollTop(scrollTop: number): void {
    this.scrollPanel()?.scrollTop(scrollTop);
  }

  refresh(): void {
    this.scrollPanel()?.refresh();
  }
}
