import { Component, input, output, model, forwardRef, ChangeDetectionStrategy } from '@angular/core';

import { FormsModule, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import { InputNumberModule, InputNumberInputEvent } from 'primeng/inputnumber';
import { InputNumberButtonLayout, InputNumberMode, InputNumberSize, InputNumberVariant } from './cmm-inputnumber.types';
import { INPUTNUMBER_DEFAULTS } from './cmm-inputnumber.constants';

@Component({
  selector: 'cmm-inputnumber',
  standalone: true,
  imports: [FormsModule, InputNumberModule],
  template: `
    <p-inputnumber
      [(ngModel)]="value"
      [showButtons]="showButtons()"
      [format]="format()"
      [buttonLayout]="buttonLayout()"
      [inputId]="inputId()"
      [styleClass]="styleClass() ?? undefined"
      [style]="style() ?? undefined"
      [placeholder]="placeholder() ?? undefined"
      [maxlength]="maxlength()!"
      [tabindex]="tabindex()"
      [title]="title() ?? undefined"
      [ariaLabelledBy]="ariaLabelledBy() ?? undefined"
      [ariaLabel]="ariaLabel() ?? undefined"
      [ariaRequired]="ariaRequired()"
      [attr.name]="name()"
      [required]="required()"
      [autocomplete]="autocomplete() ?? undefined"
      [min]="min() ?? undefined"
      [max]="max() ?? undefined"
      [incrementButtonClass]="incrementButtonClass() ?? undefined"
      [decrementButtonClass]="decrementButtonClass() ?? undefined"
      [incrementButtonIcon]="incrementButtonIcon() ?? undefined"
      [decrementButtonIcon]="decrementButtonIcon() ?? undefined"
      [disabled]="disabled()"
      [readonly]="readonly()"
      [step]="step()"
      [allowEmpty]="allowEmpty()"
      [locale]="locale() ?? undefined"
      [localeMatcher]="localeMatcher() ?? undefined"
      [mode]="mode()"
      [currency]="currency()"
      [currencyDisplay]="currencyDisplay()"
      [useGrouping]="useGrouping()"
      [minFractionDigits]="minFractionDigits() ?? undefined"
      [maxFractionDigits]="maxFractionDigits() ?? undefined"
      [prefix]="prefix() ?? undefined"
      [suffix]="suffix() ?? undefined"
      [variant]="variant()"
      [fluid]="fluid()"
      (onInput)="handleInput($event)"
      (onFocus)="handleFocus($event)"
      (onBlur)="handleBlur($event)"
      (onKeyDown)="handleKeyDown($event)"
      (onClear)="handleClear()"
    />
  `,
  styleUrl: './cmm-inputnumber.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmInputnumberComponent),
      multi: true,
    },
  ],
})
export class CmmInputnumberComponent implements ControlValueAccessor {
  // Model
  value = model<number | null>();

  // Core props
  showButtons = input<boolean>(INPUTNUMBER_DEFAULTS.SHOW_BUTTONS);
  format = input<boolean>(INPUTNUMBER_DEFAULTS.FORMAT);
  buttonLayout = input<InputNumberButtonLayout>(INPUTNUMBER_DEFAULTS.BUTTON_LAYOUT);
  inputId = input<string>('');
  styleClass = input<string>();
  style = input<Record<string, any>>();
  placeholder = input<string>();
  size = input<InputNumberSize>();
  maxlength = input<number>();
  tabindex = input<number>(INPUTNUMBER_DEFAULTS.TABINDEX);
  title = input<string>();
  ariaLabelledBy = input<string>();
  ariaLabel = input<string>();
  ariaRequired = input<boolean>(false);
  name = input<string>();
  required = input<boolean>(INPUTNUMBER_DEFAULTS.REQUIRED);
  autocomplete = input<string>();
  min = input<number>();
  max = input<number>();
  incrementButtonClass = input<string>();
  decrementButtonClass = input<string>();
  incrementButtonIcon = input<string>();
  decrementButtonIcon = input<string>();
  disabled = input<boolean>(INPUTNUMBER_DEFAULTS.DISABLED);
  readonly = input<boolean>(INPUTNUMBER_DEFAULTS.READONLY);
  step = input<number>(INPUTNUMBER_DEFAULTS.STEP);
  allowEmpty = input<boolean>(INPUTNUMBER_DEFAULTS.ALLOW_EMPTY);
  locale = input<string>();
  localeMatcher = input<string>();
  mode = input<InputNumberMode>(INPUTNUMBER_DEFAULTS.MODE);
  currency = input<string>(INPUTNUMBER_DEFAULTS.CURRENCY);
  currencyDisplay = input<string>(INPUTNUMBER_DEFAULTS.CURRENCY_DISPLAY);
  useGrouping = input<boolean>(INPUTNUMBER_DEFAULTS.USE_GROUPING);
  minFractionDigits = input<number>();
  maxFractionDigits = input<number>();
  prefix = input<string>();
  suffix = input<string>();
  variant = input<InputNumberVariant>(INPUTNUMBER_DEFAULTS.VARIANT);
  fluid = input<boolean>(INPUTNUMBER_DEFAULTS.FLUID);

  // Output events
  onInput = output<InputNumberInputEvent>();
  onFocus = output<Event>();
  onBlur = output<Event>();
  onKeyDown = output<KeyboardEvent>();
  onClear = output<void>();

  // ControlValueAccessor
  private onChangeFn: (value: number | null) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: number | null): void {
    this.value.set(value);
  }

  registerOnChange(fn: (value: number | null) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handle if needed
  }

  handleInput(event: InputNumberInputEvent): void {
    this.onInput.emit(event);
    const numValue = typeof event.value === 'number' ? event.value : null;
    this.onChangeFn(numValue);
  }

  handleFocus(event: Event): void {
    this.onFocus.emit(event);
  }

  handleBlur(event: Event): void {
    this.onBlur.emit(event);
    this.onTouchedFn();
  }

  handleKeyDown(event: KeyboardEvent): void {
    this.onKeyDown.emit(event);
  }

  handleClear(): void {
    this.onClear.emit();
    this.onChangeFn(null);
  }
}
