import { Component, input, output, model, forwardRef, ChangeDetectionStrategy } from '@angular/core';

import { FormsModule, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import { KnobModule } from 'primeng/knob';
import { KnobSize } from './cmm-knob.types';
import { KNOB_DEFAULTS } from './cmm-knob.constants';

@Component({
  selector: 'cmm-knob',
  standalone: true,
  imports: [FormsModule, KnobModule],
  template: `
    <p-knob
      [(ngModel)]="value"
      [min]="min()"
      [max]="max()"
      [step]="step()"
      [disabled]="disabled()"
      [readonly]="readonly()"
      [showValue]="showValue()"
      [valueTemplate]="valueTemplate()"
      [size]="knobSize()"
      [strokeWidth]="strokeWidth()"
      [textColor]="textColor()"
      [valueColor]="valueColor()"
      [rangeColor]="rangeColor()"
      [styleClass]="styleClass()!"
      [style]="style() ?? undefined"
      (onChange)="handleChange($event)"
    />
  `,
  styleUrl: './cmm-knob.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmKnobComponent),
      multi: true,
    },
  ],
})
export class CmmKnobComponent implements ControlValueAccessor {
  // Model
  value = model<number>(KNOB_DEFAULTS.MIN);

  // Core props
  min = input<number>(KNOB_DEFAULTS.MIN);
  max = input<number>(KNOB_DEFAULTS.MAX);
  step = input<number>(KNOB_DEFAULTS.STEP);
  disabled = input<boolean>(KNOB_DEFAULTS.DISABLED);
  readonly = input<boolean>(KNOB_DEFAULTS.READONLY);
  showValue = input<boolean>(KNOB_DEFAULTS.SHOW_VALUE);
  valueTemplate = input<string>(KNOB_DEFAULTS.VALUE_TEMPLATE);
  size = input<KnobSize>();
  knobSize = input<number>(KNOB_DEFAULTS.SIZE);
  strokeWidth = input<number>(KNOB_DEFAULTS.STROKE_WIDTH);
  textColor = input<string>(KNOB_DEFAULTS.TEXT_COLOR);
  valueColor = input<string>(KNOB_DEFAULTS.VALUE_COLOR);
  rangeColor = input<string>(KNOB_DEFAULTS.RANGE_COLOR);
  styleClass = input<string>();
  style = input<Record<string, any>>();

  // Output events
  onChange = output<{ value: number }>();

  // ControlValueAccessor
  private onChangeFn: (value: number) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: number): void {
    this.value.set(value ?? KNOB_DEFAULTS.MIN);
  }

  registerOnChange(fn: (value: number) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handle if needed
  }

  handleChange(event: number): void {
    this.onChange.emit({ value: event });
    this.onChangeFn(event);
    this.onTouchedFn();
  }
}
