import { Component, computed } from '@angular/core';
import { IamBasIcon } from './base/base';

@Component({
  selector: 'span[arrowBottomIcon]',
  template: `
    @let data = computedProps();
    <svg [attr.width]="data.width" [attr.height]="data.height" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M15.8337 7.5L10.0003 12.5L4.16699 7.5" [attr.stroke]="data.stroke" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
    </svg>
  `,
})
export class IamArrowBottomIcon extends IamBasIcon {
  computedProps = computed(() => {
    const p = this.props();
    return {
      ...p,
      width: p.width || '20',
      height: p.height || '20',
      stroke: p.stroke || '#0F1110',
    };
  });
}
