import {
  ChangeDetectionStrategy,
  Component,
  contentChild,
  input,
  model,
  output,
  TemplateRef,
  viewChild,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { OrderList, OrderListModule } from 'primeng/orderlist';
import { ButtonProps } from 'primeng/button';
import { OrderListSelectionChangeEvent, OrderListFilterEvent, OrderListFilterOptions } from './cmm-orderlist.types';
import { OrderListControlsPosition, OrderListFilterMatchMode } from './cmm-orderlist.constants';

/**
 * CmmOrderListComponent - Angular 19 wrapper for PrimeNG OrderList
 *
 * A thin wrapper component that provides signal-based inputs and two-way binding
 * for PrimeNG's OrderList component. OrderList is used to manage the order of a collection
 * with drag-drop and control buttons for reordering.
 *
 * @example
 * ```html
 * <cmm-order-list
 *   [(value)]="products"
 *   [(selection)]="selectedProducts"
 *   [dragdrop]="true"
 *   header="Product List">
 *   <ng-template pTemplate="item" let-product>
 *     {{ product.name }}
 *   </ng-template>
 * </cmm-order-list>
 * ```
 */
@Component({
  selector: 'cmm-order-list',
  standalone: true,
  imports: [OrderListModule, CommonModule],
  templateUrl: './cmm-orderlist.component.html',
  styleUrl: './cmm-orderlist.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  exportAs: 'cmmorderlist',
})
export class CmmOrderListComponent {
  /** Reference to the PrimeNG OrderList component */
  private readonly orderListRef = viewChild<OrderList>('orderListRef');

  // Template references
  readonly itemTemplate = contentChild<TemplateRef<any>>('item');
  readonly emptymessageTemplate = contentChild<TemplateRef<any>>('emptymessage');
  readonly emptyfiltermessageTemplate = contentChild<TemplateRef<any>>('emptyfiltermessage');
  readonly filterTemplate = contentChild<TemplateRef<any>>('filter');
  readonly headerTemplate = contentChild<TemplateRef<any>>('header');
  readonly moveupiconTemplate = contentChild<TemplateRef<any>>('moveupicon');
  readonly movetopiconTemplate = contentChild<TemplateRef<any>>('movetopicon');
  readonly movedowniconTemplate = contentChild<TemplateRef<any>>('movedownicon');
  readonly movebottomiconTemplate = contentChild<TemplateRef<any>>('movebottomicon');
  readonly filtericonTemplate = contentChild<TemplateRef<any>>('filtericon');

  // Input properties
  /** Text for the caption */
  readonly header = input<string>();
  /** Inline style of the component */
  readonly style = input<any>();
  /** Style class of the component */
  readonly styleClass = input<string>();
  /** Index of the element in tabbing order */
  readonly tabindex = input<number>();
  /** Defines a string that labels the input for accessibility */
  readonly ariaLabel = input<string>();
  /** Specifies one or more IDs in the DOM that labels the input field */
  readonly ariaLabelledBy = input<string>();
  /** Inline style of the list element */
  readonly listStyle = input<any>();
  /** Whether the component should be responsive */
  readonly responsive = input<boolean>(false);
  /** Fields to search against when filtering */
  readonly filterBy = input<string>();
  /** Placeholder of the filter input */
  readonly filterPlaceholder = input<string>();
  /** Locale to use in filtering */
  readonly filterLocale = input<string>();
  /** Whether metaKey needs to be pressed to select or unselect an item */
  readonly metaKeySelection = input<boolean>(false);
  /** Whether to enable dragdrop based reordering */
  readonly dragdrop = input<boolean>(false);
  /** Location of the buttons with respect to the list */
  readonly controlsPosition = input<OrderListControlsPosition>('left');
  /** Defines a string that labels the filter input */
  readonly ariaFilterLabel = input<string>();
  /** Defines how the items are filtered */
  readonly filterMatchMode = input<OrderListFilterMatchMode>('contains');
  /** Width of the screen at which the component should change its behavior */
  readonly breakpoint = input<string>('960px');
  /** Whether to displays rows with alternating colors */
  readonly stripedRows = input<boolean>(false);
  /** When present, it specifies that the component should be disabled */
  readonly disabled = input<boolean>(false);
  /** Function to optimize the dom operations by delegating to ngForTrackBy */
  readonly trackBy = input<Function>();
  /** Height of the viewport */
  readonly scrollHeight = input<string>('14rem');
  /** Whether to focus on the first visible or selected element */
  readonly autoOptionFocus = input<boolean>(true);
  /** Used to pass all properties to the Button component */
  readonly buttonProps = input<ButtonProps>();
  /** Used to pass all properties to the move up button */
  readonly moveUpButtonProps = input<ButtonProps>();
  /** Used to pass all properties to the move top button */
  readonly moveTopButtonProps = input<ButtonProps>();
  /** Used to pass all properties to the move down button */
  readonly moveDownButtonProps = input<ButtonProps>();
  /** Used to pass all properties to the move bottom button */
  readonly moveBottomButtonProps = input<ButtonProps>();

  // Two-way bindable properties
  /** Array of values to be displayed in the component */
  readonly value = model<any[]>();
  /** A list of values that are currently selected */
  readonly selection = model<any[]>();

  // Output events
  /** Callback to invoke when selection changes */
  readonly onSelectionChange = output<OrderListSelectionChangeEvent>();
  /** Callback to invoke when list is reordered */
  readonly onReorder = output<any>();
  /** Callback to invoke when filtering occurs */
  readonly onFilterEvent = output<OrderListFilterEvent>();
  /** Callback to invoke when the list is focused */
  readonly onFocus = output<Event>();
  /** Callback to invoke when the list is blurred */
  readonly onBlur = output<Event>();

  /**
   * Resets the filter
   */
  resetFilter(): void {
    this.orderListRef()?.resetFilter();
  }
}
