import { Component, input, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MegaMenuModule } from 'primeng/megamenu';
import type { MegaMenuItem } from 'primeng/api';
import { MegaMenuOrientation } from './cmm-megamenu.types';
import { MEGAMENU_DEFAULTS } from './cmm-megamenu.constants';

@Component({
  selector: 'cmm-megamenu',
  standalone: true,
  imports: [CommonModule, MegaMenuModule],
  template: `
    <p-megaMenu
      [id]="id() ?? undefined"
      [model]="model()"
      [orientation]="orientation()"
      [breakpoint]="breakpoint()"
      [scrollHeight]="scrollHeight()"
      [disabled]="disabled()"
      [tabindex]="tabindex()"
      [ariaLabel]="ariaLabel() ?? undefined"
      [ariaLabelledBy]="ariaLabelledBy() ?? undefined"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined">
      @if (startTemplate()) {
        <ng-template pTemplate="start">
          <ng-container *ngTemplateOutlet="startTemplate()!" />
        </ng-template>
      }
      @if (endTemplate()) {
        <ng-template pTemplate="end">
          <ng-container *ngTemplateOutlet="endTemplate()!" />
        </ng-template>
      }
      @if (menuIconTemplate()) {
        <ng-template pTemplate="menuicon">
          <ng-container *ngTemplateOutlet="menuIconTemplate()!" />
        </ng-template>
      }
      @if (submenuIconTemplate()) {
        <ng-template pTemplate="submenuicon">
          <ng-container *ngTemplateOutlet="submenuIconTemplate()!" />
        </ng-template>
      }
      @if (itemTemplate()) {
        <ng-template pTemplate="item" let-item>
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
      @if (buttonTemplate()) {
        <ng-template pTemplate="button">
          <ng-container *ngTemplateOutlet="buttonTemplate()!" />
        </ng-template>
      }
      @if (buttonIconTemplate()) {
        <ng-template pTemplate="buttonicon">
          <ng-container *ngTemplateOutlet="buttonIconTemplate()!" />
        </ng-template>
      }
    </p-megaMenu>
  `,
  styleUrl: './cmm-megamenu.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmMegamenuComponent {
  // Core props
  id = input<string>();
  model = input<MegaMenuItem[]>([]);
  orientation = input<MegaMenuOrientation>(MEGAMENU_DEFAULTS.ORIENTATION);
  breakpoint = input<string>('960px');
  scrollHeight = input<string>('20rem');
  disabled = input<boolean>(false);
  tabindex = input<number>(0);
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Templates
  startTemplate = contentChild<TemplateRef<any>>('start');
  endTemplate = contentChild<TemplateRef<any>>('end');
  menuIconTemplate = contentChild<TemplateRef<any>>('menuicon');
  submenuIconTemplate = contentChild<TemplateRef<any>>('submenuicon');
  itemTemplate = contentChild<TemplateRef<any>>('item');
  buttonTemplate = contentChild<TemplateRef<any>>('button');
  buttonIconTemplate = contentChild<TemplateRef<any>>('buttonicon');
}
