
import { Component, EventEmitter, inject, Input, OnChanges, Output } from '@angular/core';
import { CardWrapperComponent } from '../../Atoms/card-wrapper/card-wrapper.component';
import { TranslateModule } from '@ngx-translate/core';
import { MessageService } from 'primeng/api';
import { CardModule } from 'primeng/card';
import { FileUploadModule } from 'primeng/fileupload';

@Component({
  selector: 'upload-card-wrapper',
  standalone: true,
  imports: [CardModule, FileUploadModule, CardWrapperComponent, TranslateModule],
  templateUrl: './card-upload.component.html',
  styleUrls: ['./card-upload.component.scss'],
})
export class CardUploadComponent implements OnChanges {
  @Input() fileList: File[] = [];
  @Input() minWidth = 'unset';
  @Input() maxWidth = 'unset';
  @Input() minHeight = 'unset';
  @Input() maxHeight = 'unset';
  @Input() styleClassName = '';
  @Input() headerCard = '';
  @Input() uploadWithButton = false;
  @Input() filemime = '.docx, .pdf, .png, .jpeg, .jpg,.xlsx';
  @Input() maxFileSize = 5000000;
  @Input() maxAllow: number | null = null;
  @Output() existingFilesEmit = new EventEmitter<any[]>();
  @Output() filesSelected = new EventEmitter<File[]>();
  @Input() ignoreDisplay!: boolean;
  //todo input
  existingFiles: any[] = [];
  messageService = inject(MessageService);
  @Input() labelUploadAction = 'COMMON.UPLOAD.ACTION';
  @Input() labelUploadOr = 'COMMON.UPLOAD.OR';
  @Input() labelUploadBrowse = 'COMMON.UPLOAD.BROWSE_LABEL';
  @Input() labelFileType = 'COMMON.UPLOAD.REGULATIONS.FILE_TYPE';
  @Input() labelMaxFileSize = 'COMMON.UPLOAD.MAX_SIZE';
  @Input() labelEachFile = 'COMMON.UPLOAD.EACH_FILE';
  @Input() messMaxFileSize = 'COMMON.UPLOAD.WRONG.FORMAT';
  @Input() messExceeds = 'COMMON.UPLOAD.EXCEEDS_5MB';

  @Input() isShowAllowContentText = false;

  selectedFiles: File[] = [];
  fileIcons: { [key: string]: string } = {
    png: '/image/file-type/file_png.png',
    jpg: '/image/file-type/file_jpg.png',
    jpeg: '/image/file-type/file_jpeg.png',
    svg: '/image/file-type/file_svg.svg',
    pdf: '/image/file-type/file_pdf.png',
    doc: '/image/file-type/file_doc.png',
    docx: '/image/file-type/file_docx.png',
    xls: '/image/file-type/file_xls.png',
    xlsx: '/image/file-type/file_xlsx.png',
    csv: '/image/file-type/file_csv.png',
    txt: '/image/file-type/file_txt.png',
    mp3: '/image/file-type/file_mp3.png',
    ppt: '/image/file-type/file_ppt.png',
    pptx: '/image/file-type/file_pptx.png',
    eps: '/image/file-type/file_eps.png',
  };
  constructor() {
    this.selectedFiles = this.fileList;
  }
  ngOnChanges() {
    if (this.fileList) {
      this.selectedFiles = [...this.fileList];
    } else {
      this.selectedFiles = [];
    }
  }

  onFileSelected(event: any) {
    const filesArray = Array.from(event.files);
    const validFiles: File[] = [];

    filesArray.forEach((file: any) => {
      const fileExtension = file.name.split('.').pop().toLowerCase();
      if (!this.filemime.includes(fileExtension)) {
        this.showMessageError(`File ${file.name} ` + this.messMaxFileSize);
      } else if (file.size > this.maxFileSize) {
        this.showMessageError(`File ${file.name} ` + this.messExceeds);
      } else {
        validFiles.push(file);
      }
    });

    if (validFiles.length > 0) {
      if (this.maxAllow !== null && validFiles.length + this.selectedFiles.length > this.maxAllow) {
        this.showMessageError(`Maximum ${this.maxAllow} file uploads`);
        return;
      }
      this.selectedFiles.push(...validFiles);
      this.filesSelected.emit(this.selectedFiles);
    }
  }

  getFileIcon(file: File): string {
    const fileType = file.name.split('.').pop()?.toLowerCase();
    return this.fileIcons[fileType!] || 'assets/images/file-type/default.png';
  }

  removeFile(file: File) {
    this.selectedFiles = this.selectedFiles.filter((f) => f !== file);
    this.filesSelected.emit(this.selectedFiles);
  }

  getExistingFileIcon(nameFile: string): string {
    const fileType = nameFile.split('.').pop()?.toLowerCase();
    return this.fileIcons[fileType!] || 'assets/images/file-type/default.png';
  }

  removeExistingFile(file: File) {
    this.existingFiles = this.existingFiles.filter((f) => f !== file);
    this.filesSelected.emit(this.existingFiles);
  }

  showMessageError(mess: string) {
    this.messageService.add({
      severity: 'error',
      summary: 'Thông báo',
      detail: mess,
    });
  }
}
