/**
 * Badge size options
 */
export const BADGE_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type BadgeSize = (typeof BADGE_SIZES)[keyof typeof BADGE_SIZES];

/**
 * PrimeNG Badge native size options
 */
export const PRIMENG_BADGE_SIZES = {
  LARGE: 'large',
  XLARGE: 'xlarge',
} as const;

export type PrimeNGBadgeSize = (typeof PRIMENG_BADGE_SIZES)[keyof typeof PRIMENG_BADGE_SIZES];

/**
 * Badge severity options
 */
export const BADGE_SEVERITIES = {
  SUCCESS: 'success',
  INFO: 'info',
  WARNING: 'warning',
  DANGER: 'danger',
} as const;

export type BadgeSeverity = (typeof BADGE_SEVERITIES)[keyof typeof BADGE_SEVERITIES];

/**
 * Badge style variants
 */
export const BADGE_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export type BadgeVariant = (typeof BADGE_VARIANTS)[keyof typeof BADGE_VARIANTS];
