import { FileMetadata } from './upload.types';

// ========================================
// Extension to MIME Type Mapping
// ========================================

/**
 * Map common file extensions to their MIME types
 * @pure
 */
export function extensionToMimeType(extension: string): string[] {
  const ext = extension.toLowerCase().replace('.', '');

  const mimeMap: Record<string, string[]> = {
    // Microsoft Office
    xls: ['application/vnd.ms-excel'],
    xlsx: ['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'],
    doc: ['application/msword'],
    docx: ['application/vnd.openxmlformats-officedocument.wordprocessingml.document'],
    ppt: ['application/vnd.ms-powerpoint'],
    pptx: ['application/vnd.openxmlformats-officedocument.presentationml.presentation'],

    // OpenDocument
    ods: ['application/vnd.oasis.opendocument.spreadsheet'],
    odt: ['application/vnd.oasis.opendocument.text'],
    odp: ['application/vnd.oasis.opendocument.presentation'],

    // Images
    jpg: ['image/jpeg'],
    jpeg: ['image/jpeg'],
    png: ['image/png'],
    gif: ['image/gif'],
    svg: ['image/svg+xml'],
    webp: ['image/webp'],

    // Documents
    pdf: ['application/pdf'],
    txt: ['text/plain'],
    csv: ['text/csv'],
    json: ['application/json'],
    xml: ['application/xml', 'text/xml'],

    // Archives
    zip: ['application/zip'],
    rar: ['application/x-rar-compressed'],
    '7z': ['application/x-7z-compressed'],
  } as const;

  return mimeMap[ext] || [];
}

// ========================================
// File Size Formatting
// ========================================

/**
 * Format bytes to human-readable file size
 * @pure
 */
export function formatFileSize(bytes: number): string {
  if (bytes === 0) {
    return '0 Bytes';
  }

  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));

  return `${Math.round((bytes / k ** i) * 100) / 100} ${sizes[i]}`;
}

/**
 * Convert human-readable size to bytes
 * @pure
 */
export function parseFileSize(size: string): number {
  const units: Record<string, number> = {
    B: 1,
    KB: 1024,
    MB: 1024 * 1024,
    GB: 1024 * 1024 * 1024,
  };

  const match = size.match(/^(\d+(?:\.\d+)?)\s*([A-Z]+)$/i);
  if (!match) {
    return 0;
  }

  const value = Number.parseFloat(match[1]);
  const unit = match[2].toUpperCase();

  return value * (units[unit] || 1);
}

// ========================================
// File Type Validation
// ========================================

/**
 * Check if file matches accepted type pattern
 * @pure
 */
export function isFileTypeAccepted(file: File, accept: string): boolean {
  const acceptTypes = accept
    .split(',')
    .map((type) => type.trim())
    .filter(Boolean);

  if (acceptTypes.length === 0) {
    return true;
  }

  return acceptTypes.some((type) => {
    // Extension match (e.g., .pdf, .xlsx)
    if (type.startsWith('.')) {
      return file.name.toLowerCase().endsWith(type.toLowerCase());
    }

    // MIME type wildcard (e.g., image/*)
    if (type.endsWith('/*')) {
      const baseType = type.split('/')[0];
      return file.type.startsWith(`${baseType}/`);
    }

    // Exact MIME type (e.g., application/pdf)
    return file.type === type;
  });
}

/**
 * Extract file extension from filename
 * @pure
 */
export function getFileExtension(filename: string): string {
  const parts = filename.split('.');
  return parts.length > 1 ? parts[parts.length - 1].toLowerCase() : '';
}

/**
 * Get PrimeNG icon class for file type
 * @pure
 */
export function getFileIcon(file: File): string {
  const ext = getFileExtension(file.name);

  const iconMap: Record<string, string> = {
    // Documents
    pdf: 'pi-file-pdf',
    doc: 'pi-file-word',
    docx: 'pi-file-word',
    xls: 'pi-file-excel',
    xlsx: 'pi-file-excel',
    ods: 'pi-file-excel',
    ppt: 'pi-file',
    pptx: 'pi-file',

    // Data
    csv: 'pi-file',
    json: 'pi-file',
    xml: 'pi-file',
    txt: 'pi-file',

    // Images
    jpg: 'pi-image',
    jpeg: 'pi-image',
    png: 'pi-image',
    gif: 'pi-image',
    svg: 'pi-image',
    webp: 'pi-image',

    // Archives
    zip: 'pi-file',
    rar: 'pi-file',
    '7z': 'pi-file',
  };

  return iconMap[ext] || 'pi-file';
}

// ========================================
// File Metadata Extraction
// ========================================

/**
 * Extract metadata from File object
 * @pure
 */
export function extractFileMetadata(file: File): FileMetadata {
  return {
    name: file.name,
    size: file.size,
    type: file.type,
    lastModified: file.lastModified,
  };
}

/**
 * Convert FileList to File array
 * @pure
 */
export function fileListToArray(fileList: FileList | null): File[] {
  if (!fileList) {
    return [];
  }
  return Array.from(fileList);
}

// ========================================
// Array Utilities
// ========================================

/**
 * Filter files by accepted types
 * @pure
 */
export function filterFilesByType(files: File[], accept: string): File[] {
  return files.filter((file) => isFileTypeAccepted(file, accept));
}

/**
 * Remove file at index immutably
 * @pure
 */
export function removeFileAtIndex(files: File[], index: number): File[] {
  return files.filter((_, i) => i !== index);
}

/**
 * Add files respecting multiple flag
 * @pure
 */
export function addFiles(currentFiles: File[], newFiles: File[], multiple: boolean): File[] {
  if (!multiple) {
    return newFiles.length > 0 ? [newFiles[0]] : currentFiles;
  }
  const fileSet = new Set(currentFiles.concat(newFiles));
  const arrayFromSet = Array.from(fileSet);

  return arrayFromSet;
}

/**
 * Limit files to max count
 * @pure
 */
export function limitFiles(files: File[], maxFiles: number): File[] {
  return files.slice(0, maxFiles);
}

// ========================================
// Validation Message Builders
// ========================================

/**
 * Build file size error message
 * @pure
 */
export function buildFileSizeErrorMessage(filename: string, actualSize: number, maxSize: number): string {
  return `${filename}: Kích thước ${formatFileSize(actualSize)} vượt quá ${formatFileSize(maxSize)}`;
}

/**
 * Build file type error message
 * @pure
 */
export function buildFileTypeErrorMessage(filename: string): string {
  return `${filename}: Loại tệp không hợp lệ`;
}

/**
 * Build file limit error message
 * @pure
 */
export function buildFileLimitErrorMessage(limit: number): string {
  return `Vượt quá giới hạn ${limit} tệp`;
}

/**
 * Build min files error message
 * @pure
 */
export function buildMinFilesErrorMessage(minFiles: number): string {
  return `Cần ít nhất ${minFiles} tệp`;
}

/**
 * Build duplicate file error message
 * @pure
 */
export function buildDuplicateFileErrorMessage(filename: string): string {
  return `${filename}: Tệp đã tồn tại trong danh sách`;
}

/**
 * Check if file already exists in the file list
 * Compares by name, size, and lastModified timestamp
 * @pure
 */
export function isFileDuplicate(file: File, existingFiles: File[]): boolean {
  return existingFiles.some(
    (existing) =>
      existing.name === file.name && existing.size === file.size && existing.lastModified === file.lastModified,
  );
}

/**
 * Filter out duplicate files from a new file list
 * @pure
 */
export function filterDuplicateFiles(newFiles: File[], existingFiles: File[]): File[] {
  return newFiles.filter((file) => !isFileDuplicate(file, existingFiles));
}

// ========================================
// Drag & Drop Utilities
// ========================================

/**
 * Extract files from DragEvent
 * @pure
 */
export function extractFilesFromDragEvent(event: DragEvent): File[] {
  return fileListToArray(event.dataTransfer?.files || null);
}

/**
 * Check if drag event contains files
 * @pure
 */
export function dragEventHasFiles(event: DragEvent): boolean {
  return !!event.dataTransfer?.types?.includes('Files');
}

/**
 * Get file extensions from drag event items during dragover
 * Note: Full file access only available on drop, but we can check types
 * @pure
 */
export function getDraggedFileTypes(event: DragEvent): string[] {
  const items = event.dataTransfer?.items;
  if (!items) {
    return [];
  }

  const types: string[] = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item.kind === 'file') {
      types.push(item.type);
    }
  }
  return types;
}

/**
 * Check if any dragged file types match the accept pattern
 * @pure
 */
export function validateDraggedTypes(event: DragEvent, accept: string): boolean {
  const types = getDraggedFileTypes(event);
  if (types.length === 0) {
    return true; // Can't validate, allow it
  }

  const acceptTypes = accept
    .split(',')
    .map((type) => type.trim())
    .filter(Boolean);

  if (acceptTypes.length === 0) {
    return true;
  }

  // Check if any type matches
  return types.some((fileType) => {
    return acceptTypes.some((acceptType) => {
      // For MIME types
      if (!acceptType.startsWith('.')) {
        if (acceptType.endsWith('/*')) {
          const baseType = acceptType.split('/')[0];
          return fileType.startsWith(`${baseType}/`);
        }
        return fileType === acceptType;
      }
      // For extensions, we can't validate during dragover
      // Browser doesn't provide file names in items during dragover
      return true;
    });
  });
}

// ========================================
// File Type Detection
// ========================================

/**
 * File type categories
 */
export type FileType = 'excel' | 'pdf' | 'word' | 'image' | 'other';

/**
 * Get file type category based on MIME type and extension
 * @pure
 */
export function getFileType(file: File): FileType {
  const mimeType = file.type.toLowerCase();
  const extension = file.name.split('.').pop()?.toLowerCase() || '';

  // Check Excel files
  if (
    mimeType === 'application/vnd.ms-excel' ||
    mimeType === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' ||
    mimeType === 'application/vnd.oasis.opendocument.spreadsheet' ||
    extension === 'xls' ||
    extension === 'xlsx' ||
    extension === 'ods'
  ) {
    return 'excel';
  }

  // Check PDF files
  if (mimeType === 'application/pdf' || extension === 'pdf') {
    return 'pdf';
  }

  // Check Word files
  if (
    mimeType === 'application/msword' ||
    mimeType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' ||
    extension === 'doc' ||
    extension === 'docx'
  ) {
    return 'word';
  }

  // Check Image files
  if (mimeType.startsWith('image/') || ['jpg', 'jpeg', 'png', 'gif', 'svg', 'webp', 'bmp'].includes(extension)) {
    return 'image';
  }

  return 'other';
}
