import { Directive, input, output, HostListener, ElementRef } from '@angular/core';
import { DragEffect } from './cmm-dragdrop.types';
import { DRAGDROP_DEFAULTS } from './cmm-dragdrop.constants';

@Directive({
  selector: '[cmmDraggable]',
  standalone: true,
  host: {
    '[draggable]': 'true',
  },
})
export class CmmDraggableDirective {
  // Core props
  dragEffect = input<DragEffect>(DRAGDROP_DEFAULTS.DRAG_EFFECT);
  dragHandle = input<string>();

  // Output events
  onDragStart = output<DragEvent>();
  onDragEnd = output<DragEvent>();
  onDrag = output<DragEvent>();

  constructor(private el: ElementRef) {}

  @HostListener('dragstart', ['$event'])
  handleDragStart(event: DragEvent): void {
    if (this.dragHandle()) {
      const handle = this.el.nativeElement.querySelector(this.dragHandle());
      if (handle && !handle.contains(event.target as Node)) {
        event.preventDefault();
        return;
      }
    }
    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = this.dragEffect();
    }
    this.onDragStart.emit(event);
  }

  @HostListener('drag', ['$event'])
  handleDrag(event: DragEvent): void {
    this.onDrag.emit(event);
  }

  @HostListener('dragend', ['$event'])
  handleDragEnd(event: DragEvent): void {
    this.onDragEnd.emit(event);
  }
}
