import { UbckImportProps } from '../import-file.types';

export function computedUploadProps(props: UbckImportProps): UbckImportProps {
  return {
    ...props,
    showTemplateLink: props.showTemplateLink ?? false,
    multiple: props.multiple ?? false,
    maxFileSize: props.maxFileSize ?? 5 * 1024 * 1024, // 5MB
    accept: props.accept ?? '.xlsx',
    showFooter: false,
    showImportNotes: false,
    showProgressBar: false,
  };
}
