import { Component, ChangeDetectionStrategy, input, output, contentChild, viewChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Tree, TreeFilterEvent, TreeModule, TreeNodeSelectEvent, TreeNodeUnSelectEvent } from 'primeng/tree';
import type { TreeNode, ScrollerOptions } from 'primeng/api';




export interface TreeNodeExpandEvent {
  originalEvent: Event;
  node: TreeNode;
}

export interface TreeNodeCollapseEvent {
  originalEvent: Event;
  node: TreeNode;
}

export interface TreeNodeContextMenuSelectEvent {
  originalEvent: Event;
  node: TreeNode;
}

export interface TreeNodeDropEvent {
  originalEvent?: DragEvent;
  dragNode?: TreeNode | null;
  dropNode?: TreeNode | null;
  index?: number;
  accept?: Function;
}

export interface TreeLazyLoadEvent {
  first: number;
  last: number;
}

export interface TreeScrollIndexChangeEvent {
  first: number;
  last: number;
}

export interface TreeScrollEvent {
  originalEvent?: Event;
}


@Component({
  selector: 'cmm-tree',
  standalone: true,
  imports: [CommonModule, TreeModule],
  templateUrl: './cmm-tree.component.html',
  styleUrl: './cmm-tree.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmTreeComponent {
  treeValue = input<TreeNode[]>([], { alias: 'value' });
  selectionMode = input<'single' | 'multiple' | 'checkbox'>();
  loadingMode = input<'mask' | 'icon'>('mask');
  selection = input<any>();
  style = input<Record<string, any>>();
  styleClass = input<string>();
  contextMenu = input<any>();
  draggableScope = input<any>();
  droppableScope = input<any>();
  draggableNodes = input<boolean>(false);
  droppableNodes = input<boolean>(false);
  metaKeySelection = input<boolean>(false);
  propagateSelectionUp = input<boolean>(true);
  propagateSelectionDown = input<boolean>(true);
  loading = input<boolean>(false);
  loadingIcon = input<string>();
  emptyMessage = input<string>('');
  ariaLabel = input<string>();
  togglerAriaLabel = input<string>();
  ariaLabelledBy = input<string>();
  validateDrop = input<boolean>(false);
  filter = input<boolean>(false);
  filterBy = input<string>('label');
  filterMode = input<string>('lenient');
  filterOptions = input<any>();
  filterPlaceholder = input<string>();
  filteredNodes = input<TreeNode[]>();
  filterLocale = input<string>();
  scrollHeight = input<string>();
  lazy = input<boolean>(false);
  virtualScroll = input<boolean>(false);
  virtualScrollItemSize = input<number>();
  virtualScrollOptions = input<ScrollerOptions>();
  indentation = input<number>(1.5);
  _templateMap = input<any>();
  trackBy = input<Function>();
  highlightOnSelect = input<boolean>(false);

  selectionChange = output<any>();
  onNodeSelect = output<TreeNodeSelectEvent>();
  onNodeUnselect = output<TreeNodeUnSelectEvent>();
  onNodeExpand = output<TreeNodeExpandEvent>();
  onNodeCollapse = output<TreeNodeCollapseEvent>();
  onNodeContextMenuSelect = output<TreeNodeContextMenuSelectEvent>();
  onNodeDrop = output<TreeNodeDropEvent>();
  onLazyLoad = output<TreeLazyLoadEvent>();
  onScroll = output<TreeScrollEvent>();
  onScrollIndexChange = output<TreeScrollIndexChangeEvent>();
  onFilter = output<TreeFilterEvent>();

  nodeTemplate = contentChild<TemplateRef<any>>('node');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  loaderTemplate = contentChild<TemplateRef<any>>('loader');
  emptyMessageTemplate = contentChild<TemplateRef<any>>('emptymessage');
  togglerIconTemplate = contentChild<TemplateRef<any>>('togglericon');
  checkboxIconTemplate = contentChild<TemplateRef<any>>('checkboxicon');
  loadingIconTemplate = contentChild<TemplateRef<any>>('loadingicon');
  filterIconTemplate = contentChild<TemplateRef<any>>('filtericon');

  treeRef = viewChild<Tree>('treeRef');

  resetFilter() {
    this.treeRef()?.resetFilter();
  }

  scrollToVirtualIndex(index: number) {
    this.treeRef()?.scrollToVirtualIndex(index);
  }

  scrollTo(options: any) {
    this.treeRef()?.scrollTo(options);
  }
}
