import {
  Component,
  input,
  output,
  model,
  contentChild,
  TemplateRef,
  ChangeDetectionStrategy,
  forwardRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { CascadeSelectModule } from 'primeng/cascadeselect';
import { NG_VALUE_ACCESSOR, ControlValueAccessor, FormsModule } from '@angular/forms';
import { CascadeSelectSize, CascadeSelectVariant } from './cmm-cascadeselect.types';
import { CASCADESELECT_DEFAULTS } from './cmm-cascadeselect.constants';

@Component({
  selector: 'cmm-cascadeselect',
  standalone: true,
  imports: [CommonModule, CascadeSelectModule, FormsModule],
  template: `
    <p-cascadeSelect
      [id]="id() ?? undefined"
      [(ngModel)]="value"
      [options]="options()"
      [optionLabel]="optionLabel() ?? undefined"
      [optionValue]="optionValue() ?? undefined"
      [optionGroupLabel]="optionGroupLabel() ?? undefined"
      [optionGroupChildren]="optionGroupChildren() ?? undefined"
      [placeholder]="placeholder() ?? undefined"
      [disabled]="disabled()"
      [dataKey]="dataKey() ?? undefined"
      [inputId]="inputId() ?? undefined"
      [tabindex]="tabindex()"
      [ariaLabelledBy]="ariaLabelledBy() ?? undefined"
      [inputLabel]="inputLabel() ?? undefined"
      [ariaLabel]="ariaLabel() ?? undefined"
      [appendTo]="appendTo() ?? undefined"
      [showClear]="showClear()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined"
      [panelStyle]="panelStyle() ?? undefined"
      [panelStyleClass]="panelStyleClass() ?? undefined"
      [overlayOptions]="overlayOptions() ?? undefined"
      [autofocus]="autofocus()"
      [variant]="variant()"
      [loading]="loading()"
      [loadingIcon]="loadingIcon() ?? undefined"
      [size]="size()"
      [selectOnFocus]="selectOnFocus()"
      [autoOptionFocus]="autoOptionFocus()"
      [optionDisabled]="optionDisabled() ?? undefined"
      [searchMessage]="searchMessage() ?? undefined"
      [emptyMessage]="emptyMessage() ?? undefined"
      [selectionMessage]="selectionMessage() ?? undefined"
      [emptySearchMessage]="emptySearchMessage() ?? undefined"
      [emptySelectionMessage]="emptySelectionMessage() ?? undefined"
      [searchLocale]="searchLocale() ?? undefined"
      [fluid]="fluid()"
      [breakpoint]="breakpoint() || ''"
      [attr.data-pc-section]="'root'"
      (onChange)="handleChange($event)"
      (onGroupChange)="onGroupChange.emit($event)"
      (onShow)="onShow.emit($event)"
      (onHide)="onHide.emit($event)"
      (onClear)="onClear.emit($event)"
      (onBeforeShow)="onBeforeShow.emit($event)"
      (onBeforeHide)="onBeforeHide.emit($event)"
      (onFocus)="onFocus.emit($event)"
      (onBlur)="handleBlur($event)">
      @if (valueTemplate()) {
        <ng-template pTemplate="value" let-value>
          <ng-container *ngTemplateOutlet="valueTemplate()!; context: { $implicit: value }" />
        </ng-template>
      }
      @if (optionTemplate()) {
        <ng-template pTemplate="option" let-option>
          <ng-container *ngTemplateOutlet="optionTemplate()!; context: { $implicit: option }" />
        </ng-template>
      }
      @if (headerTemplate()) {
        <ng-template pTemplate="header">
          <ng-container *ngTemplateOutlet="headerTemplate()!" />
        </ng-template>
      }
      @if (footerTemplate()) {
        <ng-template pTemplate="footer">
          <ng-container *ngTemplateOutlet="footerTemplate()!" />
        </ng-template>
      }
      @if (triggerIconTemplate()) {
        <ng-template pTemplate="triggericon">
          <ng-container *ngTemplateOutlet="triggerIconTemplate()!" />
        </ng-template>
      }
      @if (loadingIconTemplate()) {
        <ng-template pTemplate="loadingicon">
          <ng-container *ngTemplateOutlet="loadingIconTemplate()!" />
        </ng-template>
      }
      @if (optionGroupIconTemplate()) {
        <ng-template pTemplate="optiongroupicon">
          <ng-container *ngTemplateOutlet="optionGroupIconTemplate()!" />
        </ng-template>
      }
      @if (clearIconTemplate()) {
        <ng-template pTemplate="clearicon">
          <ng-container *ngTemplateOutlet="clearIconTemplate()!" />
        </ng-template>
      }
    </p-cascadeSelect>
  `,
  styleUrl: './cmm-cascadeselect.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmCascadeselectComponent),
      multi: true,
    },
  ],
})
export class CmmCascadeselectComponent implements ControlValueAccessor {
  // Core props
  id = input<string>();
  value = model<any>();
  options = input<any[]>([]);
  optionLabel = input<string>();
  optionValue = input<string>();
  optionGroupLabel = input<string>();
  optionGroupChildren = input<string>();
  placeholder = input<string>();
  disabled = input<boolean>(CASCADESELECT_DEFAULTS.DISABLED);
  dataKey = input<string>();
  inputId = input<string>();
  tabindex = input<number>(CASCADESELECT_DEFAULTS.TABINDEX);
  ariaLabelledBy = input<string>();
  inputLabel = input<string>();
  ariaLabel = input<string>();
  appendTo = input<unknown>('body');
  showClear = input<boolean>(CASCADESELECT_DEFAULTS.SHOW_CLEAR);
  style = input<Record<string, any>>();
  styleClass = input<string>();
  panelStyle = input<Record<string, any>>();
  panelStyleClass = input<string>();
  overlayOptions = input<any>();
  autofocus = input<boolean>();
  variant = input<CascadeSelectVariant>(CASCADESELECT_DEFAULTS.VARIANT);
  loading = input<boolean>(CASCADESELECT_DEFAULTS.LOADING);
  loadingIcon = input<string>();
  selectOnFocus = input<boolean>(CASCADESELECT_DEFAULTS.SELECT_ON_FOCUS);
  autoOptionFocus = input<boolean>(CASCADESELECT_DEFAULTS.AUTO_OPTION_FOCUS);
  optionDisabled = input<any>();
  searchMessage = input<string>();
  emptyMessage = input<string>();
  selectionMessage = input<string>();
  emptySearchMessage = input<string>();
  emptySelectionMessage = input<string>();
  searchLocale = input<string>();
  fluid = input<boolean>(CASCADESELECT_DEFAULTS.FLUID);
  breakpoint = input<string>();
  size = input<CascadeSelectSize>('small');

  // Templates
  valueTemplate = contentChild<TemplateRef<any>>('value');
  optionTemplate = contentChild<TemplateRef<any>>('option');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  triggerIconTemplate = contentChild<TemplateRef<any>>('triggericon');
  loadingIconTemplate = contentChild<TemplateRef<any>>('loadingicon');
  optionGroupIconTemplate = contentChild<TemplateRef<any>>('optiongroupicon');
  clearIconTemplate = contentChild<TemplateRef<any>>('clearicon');

  // Events
  onChange = output<any>();
  onGroupChange = output<Event>();
  onShow = output<any>();
  onHide = output<any>();
  onClear = output<any>();
  onBeforeShow = output<any>();
  onBeforeHide = output<any>();
  onFocus = output<FocusEvent>();
  onBlur = output<FocusEvent>();

  // CVA implementation
  private onChangeFn: (value: any) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: any): void {
    this.value.set(value);
  }

  registerOnChange(fn: (value: any) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handled by disabled input
  }

  handleChange(event: any): void {
    this.onChangeFn(event.value);
    this.onChange.emit(event);
  }

  handleBlur(event: FocusEvent): void {
    this.onTouchedFn();
    this.onBlur.emit(event);
  }
}
