import { Directive, ElementRef, Renderer2, afterNextRender, Injector, inject } from '@angular/core';

/**
 * CmmContentDirective - Main content area that fills remaining height
 *
 * Automatically fills the remaining vertical space after header.
 * Sets up horizontal flexbox container for left and right panels.
 * Must be used inside cmmLayout directive.
 *
 * @example
 * ```html
 * <div cmmLayout>
 *   <div cmmHeader>Header</div>
 *   <div cmmContent>
 *     <div cmmLeftContent>Left panel</div>
 *     <div cmmRightContent>Right panel</div>
 *   </div>
 * </div>
 * ```
 */
@Directive({
  selector: '[cmmContent]',
  standalone: true,
})
export class CmmContentDirective {
  private el = inject(ElementRef);
  private renderer = inject(Renderer2);
  private injector = inject(Injector);

  private static stylesInjected = false;
  private static readonly minifiedCss =
    '.cmm-content{box-sizing:border-box}.cmm-content-gap{gap:1rem}@media(max-width:768px){.cmm-content-gap{gap:.5rem}}';

  constructor() {
    afterNextRender(
      () => {
        this.injectStyles();
        this.applyStyles();
      },
      { injector: this.injector },
    );
  }

  private injectStyles(): void {
    if (!CmmContentDirective.stylesInjected && typeof document !== 'undefined') {
      const style = this.renderer.createElement('style');
      this.renderer.setAttribute(style, 'data-cmm-content', '');
      const text = this.renderer.createText(CmmContentDirective.minifiedCss);
      this.renderer.appendChild(style, text);
      this.renderer.appendChild(document.head, style);
      CmmContentDirective.stylesInjected = true;
    }
  }

  private applyStyles(): void {
    const element = this.el.nativeElement;

    // Content grows to fill remaining space
    this.renderer.addClass(element, 'cmm-content');
    this.renderer.setStyle(element, 'flex', '1 1 auto');
    this.renderer.setStyle(element, 'min-height', '0'); // Important for flex scrolling
    this.renderer.setStyle(element, 'display', 'flex');
    this.renderer.setStyle(element, 'flex-direction', 'row');
    this.renderer.setStyle(element, 'overflow', 'hidden');
    this.renderer.setStyle(element, 'width', '100%');
  }
}
