import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { AnimationOptions } from 'ngx-lottie';
import { ANIMATION_TOKEN_LOADING } from './animation.token';
import { LoadingService } from './loading.service';
import { delayWhen, map, timer } from 'rxjs';

@Component({
  selector: 'ubck-loading',
  templateUrl: './loading.component.html',
  styleUrl: './loading.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: false
})
export class UbckLoading {
  private readonly ANIMATION_TOKEN_LOADING = inject(ANIMATION_TOKEN_LOADING)
  public readonly loadingService = inject(LoadingService)
  options = signal<AnimationOptions>(this.ANIMATION_TOKEN_LOADING);

  getLoading = this.loadingService.isAppLoading().pipe(
    delayWhen((value) => !value ? timer(500) : timer(0)),
    map((value) => value)
  )
}
