/**
 * BaseComponent size options
 */
export const BASECOMPONENT_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type BaseComponentSize = (typeof BASECOMPONENT_SIZES)[keyof typeof BASECOMPONENT_SIZES];

/**
 * BaseComponent style variants
 */
export const BASECOMPONENT_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export type BaseComponentVariant = (typeof BASECOMPONENT_VARIANTS)[keyof typeof BASECOMPONENT_VARIANTS];
