import { ElementRef } from '@angular/core';

/**
 * DOM Selector Helper
 * Single Responsibility: Find and match DOM elements
 */
export class DOMSelectorHelper {
  /**
   * Find element by selector searching upwards in DOM tree
   */
  static findElementBySelector(
    el: ElementRef,
    selector: string
  ): HTMLElement | undefined {
    const element = el.nativeElement;
    let current = element.parentElement;
    
    while (current) {
      if (DOMSelectorHelper.matchesSelector(current, selector)) {
        return current;
      }
      current = current.parentElement;
      if (current === document.body) break;
    }
    
    return undefined;
  }

  /**
   * Check if element matches selector (supports comma-separated)
   */
  static matchesSelector(element: HTMLElement, selector: string): boolean {
    const selectors = selector.split(',').map(s => s.trim());
    
    for (const sel of selectors) {
      if (!((sel.startsWith('.') || sel.startsWith('#') ) || sel.startsWith('['))) {
        if (element.tagName.toLowerCase() === sel.toLowerCase()) return true;
      } else if (sel.startsWith('.')) {
        if (element.classList.contains(sel.substring(1))) return true;
      } else if (sel.startsWith('#')) {
        if (element.id === sel.substring(1)) return true;
      } else {
        try {
          if (element.matches(sel)) return true;
        } catch (e) {}
      }
    }
    
    return false;
  }

  /**
   * Find error insert target by selector
   * Searches for the target element in multiple scopes:
   * 1. Within the same form group (siblings)
   * 2. Upwards in DOM tree (ancestors)
   * 3. Within ancestors (descendant search)
   */
  static findErrorInsertTarget(
    el: ElementRef,
    selector: string
  ): HTMLElement | undefined {
    const element = el.nativeElement;
    
    // First check immediate parent
    if (element.parentElement && DOMSelectorHelper.matchesSelector(element.parentElement, selector)) {
      return element.parentElement;
    }
    
    // Check siblings (within the same parent) - IMPORTANT for radio buttons
    if (element.parentElement) {
      const siblingFound = element.parentElement.querySelector(selector) as HTMLElement;
      if (siblingFound) {
        return siblingFound;
      }
    }
    
    // Search upwards in DOM tree
    let current = element.parentElement;
    
    while (current) {
      // Check if current element matches
      if (DOMSelectorHelper.matchesSelector(current, selector)) {
        return current;
      }
      
      // Check children of current element
      const found = current.querySelector(selector) as HTMLElement;
      if (found) {
        return found;
      }
      
      current = current.parentElement;
      if (current === document.body) break;
    }
    
    return undefined;
  }
}
