import { Injectable, Type } from '@angular/core';
import { DialogService as TheDialogService, DynamicDialogConfig, DynamicDialogRef } from 'primeng/dynamicdialog';
import { debounceTime, Observable } from 'rxjs';
export interface DialogTemplates {
  header?: Type<any>;
  footer?: Type<any>;
  content?: Type<any>;
}
@Injectable({
  providedIn: 'root',
})
export class CommonDialogService extends TheDialogService {
  private readonly commonConfig = {
    closable: false,
    showHeader: false,
    focusOnShow: false,
    focusTrap: true,
    closeOnEscape: true,
    contentStyle: { overflow: 'auto' },
    modal: true,
    appendTo: 'body',

    autoZIndex: false,
    baseZIndex: 99999,
    breakpoints: {
      '576px': '90vw',
      '768px': '70vw',
      '992px': '60vw',
    },
  };
  openDialog<C, D>(
    component: Type<C>,
    data: D,

    config?: DynamicDialogConfig & { templates?: DialogTemplates },
  ): Observable<unknown> {
    const dialogRef = this.open(component, {
      ...config,
      data: data,
       maskStyleClass: config?.maskStyleClass || 'z-40',
      templates: {
        header: config?.templates?.header,
        footer: config?.templates?.footer,
        content: config?.templates?.content,
      },
      ...this.commonConfig,
    });

    return dialogRef.onClose.pipe(debounceTime(150));
  }
  openDialogWithRef<C, D>(
    component: Type<C>,
    data: D,
    config?: DynamicDialogConfig & { templates?: DialogTemplates },
  ): DynamicDialogRef {
    return this.open(component, {
      ...config,
        maskStyleClass: config?.maskStyleClass || 'z-40',
      templates: {
        header: config?.templates?.header,
        footer: config?.templates?.footer,
        content: config?.templates?.content,
      },
      data: data,

      ...this.commonConfig, 
    });
  }
  override open(component: Type<any>, config: DynamicDialogConfig): DynamicDialogRef<any> {
    const mergedConfig: DynamicDialogConfig = {
      ...config,
      style: {
        zIndex: 99999,
        ...(config.style || {}),
      },
      maskStyleClass: config?.maskStyleClass || 'z-40',
    };
    return super.open(component, mergedConfig) as DynamicDialogRef<any>;
  }
}
