import { MenuItem } from 'primeng/api';

/**
 * Breadcrumb size options
 */
export const BREADCRUMB_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type BreadcrumbSize = (typeof BREADCRUMB_SIZES)[keyof typeof BREADCRUMB_SIZES];

/**
 * Breadcrumb spacing variants
 */
export const BREADCRUMB_VARIANTS = {
  DEFAULT: 'default',
  COMPACT: 'compact',
  SPACIOUS: 'spacious',
} as const;

export type BreadcrumbVariant = (typeof BREADCRUMB_VARIANTS)[keyof typeof BREADCRUMB_VARIANTS];

/**
 * Common breadcrumb configurations
 */
