import {
  CdkVirtualScrollViewport,
  ScrollingModule,
} from '@angular/cdk/scrolling';
import { CommonModule } from '@angular/common';
import {
  afterNextRender,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  computed,
  contentChild,
  effect,
  ElementRef,
  forwardRef,
  HostBinding,
  inject,
  input,
  Injector,
  OnDestroy,
  output,
  Renderer2,
  NgZone,
  TemplateRef,
  viewChild,
  model,
  signal,
  HostListener,
  untracked,
} from '@angular/core';
import {
  ControlValueAccessor,
  FormsModule,
  NgControl,
  NG_VALUE_ACCESSOR,
} from '@angular/forms';
import { InputTextModule } from 'primeng/inputtext';
import { OverlayModule } from 'primeng/overlay';
import { TooltipModule } from 'primeng/tooltip';
import { IDropdownItemMultiSelect } from '../dropdown.model';
import { CheckboxModule } from 'primeng/checkbox';
import { TranslateModule } from '@ngx-translate/core';
import { Popover } from 'primeng/popover';
import {
  DropdownCheckboxFilterState,
  DropdownCheckboxProps,
} from './dropdown-checkbox.types';
import { CmmTypepographyModule } from '../../typography/public-api';
import { handleOutsideClick } from '../../../utils/document-event.utils';
import { useElementWidth, useFormControlReset } from '../../../utils/dropdown-helpers';


@Component({
  selector: 'cmm-dropdown-checkbox',
  standalone: true,
  imports: [
    CommonModule,
    ScrollingModule,
    OverlayModule,
    TooltipModule,
    InputTextModule,
    CheckboxModule,
    FormsModule,
    TranslateModule,
    Popover,
    CmmTypepographyModule,
  ],
  templateUrl: './dropdown-checkbox.component.html',
  styleUrl: './dropdown-checkbox.component.scss',
  changeDetection: ChangeDetectionStrategy.Default,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => DropdownCheckboxComponent),
      multi: true,
    },
  ],
})
export class DropdownCheckboxComponent
  implements ControlValueAccessor, OnDestroy {
  private injector = inject(Injector);
  private onTouch!: Function;
  private onChange!: Function;
  isDisabled!: boolean;
  readonly id = signal<string>(Math.random().toString(36).substring(2, 9));

  // Bind validation classes to host element
  @HostBinding('class.ng-invalid')
  get isInvalid(): boolean {
    const ngControl = this.injector.get(NgControl, null);
    return !!(ngControl?.control?.invalid && ngControl?.control?.touched);
  }

  @HostBinding('class.ng-touched')
  get isTouched(): boolean {
    const ngControl = this.injector.get(NgControl, null);
    return !!ngControl?.control?.touched;
  }

  @HostBinding('class.ng-dirty')
  get isDirty(): boolean {
    const ngControl = this.injector.get(NgControl, null);
    return !!ngControl?.control?.dirty;
  }

  getViewportHeight(): string {
    const { maxVisibleSearchItems, itemHeight } = this.computedProps();
    const defaultPadding = 8;

    return `${maxVisibleSearchItems * itemHeight + defaultPadding}px`;
  }
  writeValue(
    obj: IDropdownItemMultiSelect[] | IDropdownItemMultiSelect | null,
  ): void {
    this.currentSelected = this.computedProps().items.filter(
      (item: IDropdownItemMultiSelect) => item.active,
    );
    this.updateLabelSelected();
    if (obj === null || obj === undefined || (Array.isArray(obj) && obj.length === 0)) {
      this.inputValue.set('');
      this.localSearchItemList = undefined; // Clear search item list
    }
  }

  // setUpListenterChange() {
  //   const control = this.injector.get(NgControl, null);

  //   if (control?.control) {
  //     // Watch for status changes to detect reset
  //     control.control.statusChanges?.subscribe(() => {
  //       if (control.control?.pristine && control.control?.untouched) {
  //         const value = control.control.value;
  //         if (value === null || value?.length === 0) {
  //           this.inputValue.set('');
  //           this.currentSelected = [];
  //           this.eventFilter.emit('');
  //         }
  //       }
  //     });
  //   }
  // }

  handleClearSearch(): void {
    this.inputValue.set('');
    const prop = this.computedProps();
    if (!prop.hasApplyLazyLoad) {
      this.localSearchItemList = undefined;
    }
    this.viewport().scrollTo({ top: 0 });
    this.eventFilter.emit('');
    this.eventFilterState.emit({
      value: '',
      checkAll: this.checkAllInternal(),
      selectedCount: this.selectedCountSignal(),
    });
  }

  registerOnChange(
    fn: (
      value: IDropdownItemMultiSelect[] | IDropdownItemMultiSelect | null,
    ) => void,
  ): void {
    this.onChange = fn;
  }
  registerOnTouched(fn: () => void): void {
    this.onTouch = fn;
  }
  setDisabledState?(isDisabled: boolean): void {
    this.isDisabled = isDisabled;
  }
  handleCloseDropdown(): void {
    this.onTouch?.();
  }

  /**
   * Component props
   */
  props = input.required<DropdownCheckboxProps>();

  computedProps = computed(() => {
    const p = this.props();
    return {
      ...p,
      isLoading: p.isLoading ?? false,
      items: p.items ?? [],
      totalItems: p.totalItems ?? 0,
      itemPerPage: p.itemPerPage ?? 10,
      itemHeight: p.itemHeight ?? 36,
      placeholder: p.placeholder ?? '',
      filter: p.filter ?? false,
      appendOnly: p.appendOnly ?? true,
      itemSelectedBeforeSearch: p.itemSelectedBeforeSearch ?? [],
      customPlaceHolderTemplate: p.customPlaceHolderTemplate,
      checkAll: p.checkAll ?? false,
      showCheckAll: p.showCheckAll ?? true,
      hasApplyLazyLoad: p.hasApplyLazyLoad ?? false,
      labelItemClazz: p.labelItemClazz ?? '',
      isNeedClearItem: p.isNeedClearItem ?? false,
      hasEventBlur: p.hasEventBlur ?? false,
      maxLength: p.maxLength ?? 1000,
      searchPlaceholderLabel: p.searchPlaceholderLabel ?? 'Search',
      allLabel: p.allLabel ?? 'Tất cả',
      emptyMessage: p.emptyMessage ?? 'Không có bản ghi nào',
      maxLabelSelected: p.maxLabelSelected ?? 3,
      seletedItemLabel: p.seletedItemLabel ?? '',
      maxVisibleSearchItems: p.maxVisibleSearchItems ?? 5,
      dropdownIcon: p.dropdownIcon ?? 'pi pi-chevron-down',
      showClear: p.showClear ?? true,
      disableCheckAllWhenNoResult: p.disableCheckAllWhenNoResult ?? false,
      checkAllCheckboxStyleClass: p.checkAllCheckboxStyleClass ?? '',
      floatLabel: p.floatLabel ?? false,
      label: p.label ?? '',
    };
  });

  /**
   * Callback to emit when load more is needed
   */
  eventEmitLoadMore = output<void>();

  /**
   * Legacy filter output. Emits only the submitted filter text so existing
   * consumers that bind (eventFilter) continue receiving a string.
   */
  eventFilter = output<string>();

  /**
   * Emits a filter-action snapshot for consumers that also need selection
   * context at the moment search is submitted.
   */
  eventFilterState = output<DropdownCheckboxFilterState>();

  /**
   * Callback to emit when item is clicked
   */
  eventClickItem = output<IDropdownItemMultiSelect[] | null>();

  /**
   * Callback to emit when check all is toggled
   */
  eventEmitCheckAll = output<boolean>();

  /**
   * Callback to emit when item is unchecked
   */
  eventUncheckedItem = output<IDropdownItemMultiSelect>();

  /**
   * Callback to emit when item is checked separately
   */
  eventCheckedSeparatelyItem = output<IDropdownItemMultiSelect>();

  /**
   * Custom item template
   */
  itemTemplate = contentChild<TemplateRef<unknown>>('itemTemplate');

  /**
   * Custom empty template
   */
  emptyTemplate = contentChild<TemplateRef<unknown>>('emptyTemplate');

  viewport = viewChild.required<CdkVirtualScrollViewport>(
    CdkVirtualScrollViewport,
  );
  op = viewChild.required<Popover>('op');
  dropdownWrapper = viewChild.required<ElementRef>('dropdownWrapper');

  dropdownWidth = useElementWidth(
    this.dropdownWrapper,
    () => this.calculateLabelWidths()
  )

  cdr = inject(ChangeDetectorRef);
  // dropdownWidth = signal<number>(0);
  render2 = inject(Renderer2);
  private ngZone = inject(NgZone);
  private resizeObserver?: ResizeObserver;
  private scrollUnlisten?: () => void;
  labelItemMaxWidths: number[] = [];
  currentSelected: IDropdownItemMultiSelect[] = [];
  private selectedCountSignal = signal<number>(0);
  activeIndex = -1;
  labelSelected = '';
  // Filtered item subset shown while searching; undefined means render the full props.items list.
  localSearchItemList!: IDropdownItemMultiSelect[] | undefined;
  inputValue = model('');
  checkAllInternal = signal(false);
  private previousCheckAllInput?: boolean;
  appendOnlyInternal = true;
  isDropdownOpen = signal(false);
  isLabelFloated = computed(() => this.selectedCountSignal() > 0 || this.isDropdownOpen());

  constructor() {
    // afterNextRender({
    //   read: () => {
    //     this.dropdownWidth.set(this.dropdownWrapper().nativeElement.clientWidth);
    //     this.setupResizeObserver();
    //     this.calculateLabelWidths();
    //   },
    // });

    // custom hook to check form control state for reset
    useFormControlReset((value) => {
      if (value === null || value?.length === 0) {
        this.inputValue.set('');
        this.currentSelected = [];
        this.eventFilter.emit('')
      }
    })

    // Watch for props changes
    effect(() => {
      const prop = this.computedProps();
      // If parent explicitly changed props.checkAll, trust parent's value
      // Otherwise preserve internal state
      const checkAllInputChanged = this.previousCheckAllInput !== prop.checkAll;
      let isCheckAllInternal = checkAllInputChanged
        ? prop.checkAll
        : untracked(() => this.checkAllInternal()); // if parent don't change checkAll, preserve internal state
      this.previousCheckAllInput = prop.checkAll;

      if (
        prop.itemSelectedBeforeSearch &&
        prop.itemSelectedBeforeSearch?.length > 0
        && !isCheckAllInternal
        && !prop.hasApplyLazyLoad
      ) {
        isCheckAllInternal =
          prop.itemSelectedBeforeSearch.length > 0 &&
          prop.items.length > 0 &&
          !prop.items.find(
            (item: IDropdownItemMultiSelect) => item.active === false,
          );
      }

      // If checkAll is true, mark all items as active
      if (isCheckAllInternal) {
        prop.items.forEach((item) => {
          item.active = true;
        });
      } else {
        // Else mark items as active only if they are in currentSelected
        const selectedValues = new Set(
          [...this.currentSelected.map((item) => item.value),
          ...(prop.itemSelectedBeforeSearch ?? []).map((item) => item.value)]
        );
        prop.items.forEach((item) => {
          if (selectedValues.has(item.value)) {
            item.active = true;
          }
        });
      }

      const filteredActiveItems = prop.items.filter(
        (item: IDropdownItemMultiSelect) => item.active,
      );

      this.currentSelected = this.mergeDistinctLists(
        filteredActiveItems,
        (prop.itemSelectedBeforeSearch && prop.itemSelectedBeforeSearch?.length > 0 ? prop.itemSelectedBeforeSearch : this.currentSelected)
      )

      this.checkAllInternal.set(isCheckAllInternal);
      this.updateLabelSelected(
        isCheckAllInternal ? prop.totalItems : this.currentSelected.length,
      );
      if (
        prop.showCheckAll &&
        isCheckAllInternal &&
        !prop.hasApplyLazyLoad
      ) {
        // handle re-select check all if data add new
        this.handleCheckAll(true);
      }
    });
  }

  /**
   * handle check all items
   * @param evt
   */
  handleCheckAll(evt: boolean): void {
    const prop = this.computedProps();
    this.checkAllInternal.set(evt);
    /**
     * check if is searching
     */
    if (this.localSearchItemList?.length && evt) {
      this.localSearchItemList.forEach((item) => {
        item.active = evt;
      });
      this.currentSelected = [
        ...this.currentSelected,
        ...this.localSearchItemList.filter((item) => item.active),
      ];
    } else if (evt) {
      // if not searching
      prop.items.forEach((item) => {
        item.active = evt;
      });
      this.currentSelected = prop.items.filter((item) => item.active);
    }
    if (this.localSearchItemList?.length && !evt) {
      this.localSearchItemList.forEach((item) => {
        item.active = evt;
      });
      this.currentSelected = prop.items.filter((item) => item.active);
    } else if (!(this.localSearchItemList?.length || evt)) {
      prop.items.forEach((item) => {
        item.active = evt;
      });
      this.currentSelected = prop.items.filter((item) => item.active);
    }
    this.updateLabelSelected(
      evt ? prop.totalItems : this.currentSelected.length,
    );
    this.eventEmitCheckAll.emit(this.checkAllInternal());
  }
  /**
   * check click item
   * @param item
   */
  handleClickItem(item: IDropdownItemMultiSelect): void {
    if (item['disabled']) {
      return;
    }

    const prop = this.computedProps();
    const selectedCountBeforeChange = this.selectedCountSignal();
    const wasActive = item.active;

    if (item.active) {
      this.eventUncheckedItem.emit(item);
    }
    if (!item.active) {
      this.eventCheckedSeparatelyItem.emit(item);
    }
    if (item) {
      item.active = !item.active;
    }
    // if item not existing in list
    if (
      item.active &&
      this.currentSelected.findIndex((_item) => _item.value === item.value) ===
      -1
    ) {
      this.currentSelected.push(item);
    }
    this.currentSelected = this.currentSelected.filter(
      (_: IDropdownItemMultiSelect) => _.active,
    );
    // check if searching
    if (this.localSearchItemList?.length) {
      if (this.currentSelected.length < this.localSearchItemList.length) {
        if (prop.showCheckAll) {
          this.checkAllInternal.set(false);
        }
      }

      // check if currentselected contain tempList
      const isIncludeEachOther = this.localSearchItemList.every((value) =>
        this.currentSelected.some(
          (_item: IDropdownItemMultiSelect) => _item.value === value.value,
        ),
      );
      if (prop.showCheckAll) {
        this.checkAllInternal.set(
          this.currentSelected.length >= this.localSearchItemList.length &&
          isIncludeEachOther,
        );
      }
    } else if (prop.showCheckAll) {
      this.checkAllInternal.set(this.currentSelected.length >= prop.totalItems);
    }

    /**
     * Normal mode uses currentSelected.length. Select-all remote mode changes from the previous total by one because unloaded items are not in memory.
     */
    const selectedCount =
      selectedCountBeforeChange > this.currentSelected.length
        ? Math.min(
          prop.totalItems,
          selectedCountBeforeChange + (wasActive ? -1 : 1),
        )
        : this.currentSelected.length;

    if (prop.showCheckAll) {
      this.checkAllInternal.set(selectedCount >= prop.totalItems);
    }

    this.updateLabelSelected(selectedCount);

    this.eventClickItem.emit(this.currentSelected);
    this.onChange?.(this.currentSelected);
    this.onTouch?.();
  }
  updateLabelSelected(selectedCount = this.currentSelected.length): void {
    this.labelSelected = this.currentSelected
      .map((data: IDropdownItemMultiSelect) => data.label)
      .join(',');
    this.selectedCountSignal.set(selectedCount ?? 0);
    this.calculateLabelWidths();
  }

  mergeDistinctLists(
    currentList: IDropdownItemMultiSelect[] = [],
    beforeList: IDropdownItemMultiSelect[] = [],
  ): IDropdownItemMultiSelect[] {
    const map = new Map<string | number, IDropdownItemMultiSelect>();
    beforeList.forEach((item: IDropdownItemMultiSelect) => {
      map.set(item.value, item);
    });
    currentList.forEach((item: IDropdownItemMultiSelect) => {
      map.set(item.value, item);
    });
    return Array.from(map.values());
  }

  handleFilterUniqueItem(
    list: IDropdownItemMultiSelect[],
  ): IDropdownItemMultiSelect[] {
    const uniqueValues = Array.from(new Set(list.map((item) => item.value)));
    return uniqueValues
      .map(
        (value: string | number) =>
          list.find((_) => _.value === value) as IDropdownItemMultiSelect,
      )
      .filter(
        (item): item is IDropdownItemMultiSelect => typeof item !== 'undefined',
      );
  }
  handleScroll(evt: Event): void {
    const { scrollHeight, clientHeight, scrollTop } = evt.target as Element;
    if (scrollHeight <= clientHeight + scrollTop) {
      this.eventEmitLoadMore.emit();
    }
  }

  handleClearItem(): void {
    if (this.isDisabled) {
      return;
    }
    const prop = this.computedProps();
    if (prop.showCheckAll) {
      this.checkAllInternal.set(false);
    }
    this.eventClickItem.emit(null);
    this.onTouch?.();
    this.onChange?.(null);
    this.resetMultiSelect();
    if (prop.showCheckAll) {
      this.eventEmitCheckAll.emit(this.checkAllInternal());
    }
  }

  resetMultiSelect(): void {
    this.currentSelected = [];
    const prop = this.computedProps();
    prop.items.forEach((data: IDropdownItemMultiSelect) => {
      data.active = false;
    });
    this.updateLabelSelected();
  }
  resetFunction(options: { reset: () => void }): void {
    options.reset();
  }

  customFilterFunction(val = ''): void {
    const trimmedVal = (val ?? '').trim();
    this.inputValue.set(trimmedVal);
    const prop = this.computedProps();

    if (!(prop.hasApplyLazyLoad || trimmedVal)) {
      this.localSearchItemList = undefined;
    }

    if (!prop.hasApplyLazyLoad && trimmedVal) {
      this.localSearchItemList = prop.items.filter((item) =>
        (item.label?.toString() || '')
          .toUpperCase()
          .includes(trimmedVal.toUpperCase()),
      );
    }
    this.viewport().scrollTo({ top: 0 });
    this.eventFilter.emit(trimmedVal);
    this.eventFilterState.emit({
      value: trimmedVal,
      checkAll: this.checkAllInternal(),
      selectedCount: this.selectedCountSignal(),
    });
  }
  handleOpenDropdown(evt: MouseEvent | Event): void {
    if (this.isDisabled) {
      return;
    }

    const target = this.dropdownWrapper().nativeElement as HTMLElement;
    this.op().toggle(evt, target);
    this.removeScrollListener();
    this.ngZone.runOutsideAngular(() => {
      const handler = (event: Event) => {
        const target = event.target as Node;
        const viewport = this.viewport()?.elementRef?.nativeElement as Node | undefined;
        // Allow scrolling inside cdk-virtual-scroll-viewport
        if (viewport && (viewport === target || viewport.contains(target))) {
          return;
        }

        // Allow scroll events originating inside the popover overlay
        // (e.g. horizontal scroll inside the filter <input> when typing past its width).
        const overlay = this.op()?.container as Node | undefined;
        if (overlay && (overlay === target || overlay.contains(target))) {
          return;
        }

        // Hide popover for any other scroll (parent container, window, etc.)
        this.ngZone.run(() => {
          if (this.op().overlayVisible) {
            this.op().hide();
          }
        });
      };

      document.addEventListener('scroll', handler, { capture: true, passive: true });
      this.scrollUnlisten = () => document.removeEventListener('scroll', handler, { capture: true });
    })
  }

  /**
   * Register a document-level scroll listener when the popover opens.
   * Ignores scrolls that originate inside the cdk-virtual-scroll-viewport
   * so that the item list can be scrolled freely without closing the dropdown.
   */
  onPopoverShow(): void {
    /**
     Calling align() in onShow reruns PrimeNG’s positioning after DOM layout is stable, so the popover uses correct trigger coordinates and viewport space.
    */
    this.isDropdownOpen.set(true);
    this.op().align();
  }

  /** Remove the document scroll listener (called on popover hide and destroy). */
  onPopoverHide(): void {
    this.isDropdownOpen.set(false);
    this.handleCloseDropdown();
  }

  private removeScrollListener(): void {
    this.scrollUnlisten?.();
    this.scrollUnlisten = undefined;
  }

  /**
   * Handle document mouse down event
   * @param event Mouse event
   */
  @HostListener('document:mousedown', ['$event'])
  handleDocumentMouseDown(event: MouseEvent): void {
    const triggerElement = this.dropdownWrapper().nativeElement as HTMLElement;
    const overlayElement = this.op().container;

    handleOutsideClick(
      event,
      [triggerElement, overlayElement],
      () => { this.op().hide() },
      this.op().overlayVisible
    )
  }
  handleToggleDropdown(evt: Event): void {
    if (!this.op().overlayVisible) {
      this.op().show(evt, this.dropdownWrapper().nativeElement);
    }
  }

  handleKeyDown(event: KeyboardEvent): void {
    const items = this.computedProps().items;


    switch (event.key) {
      case 'ArrowDown':
        this.activeIndex = (this.activeIndex + 1) % items.length;
        event.preventDefault();
        break;

      case 'ArrowUp':
        this.activeIndex =
          this.activeIndex > 0 ? this.activeIndex - 1 : items.length - 1;
        event.preventDefault();
        break;

      case 'Enter':
        if (this.activeIndex >= 0 && this.activeIndex < items.length) {
          this.handleClickItem(items[this.activeIndex]);
          this.op().hide();
        }
        event.preventDefault();
        break;

      case 'Escape':
        this.op().hide();
        break;

      case 'Tab':
        // Allow tab move to the next element
        this.op().hide();
        break;

      default:
        break;
    }

    this.viewport().scrollToIndex(this.activeIndex);
  }
  /**
   *  handle unselect items
   * @param evt
   */
  handleUnSelectItem(evt: IDropdownItemMultiSelect): void {
    this.currentSelected = this.currentSelected.filter(
      (_item) => evt.value !== _item.value,
    );
    const prop = this.computedProps();
    // evt.active = false;
    if (this.localSearchItemList) {
      const indexItem = this.localSearchItemList.findIndex((item) => item.value === evt.value);
      if (indexItem === -1) {
        if (prop.showCheckAll) {
          this.checkAllInternal.set(false);
        }
      } else {
        this.localSearchItemList[indexItem].active = false;

      }
    } else if (prop.showCheckAll) {
      this.checkAllInternal.set(false);
    }
    this.handleClickItem(evt);
  }
  trackByFn(index: number, item: IDropdownItemMultiSelect): string | number {
    return item.id || item.code || index;
  }

  /**
   * Calculate max-width for each label item based on available space
   */
  private calculateLabelWidths(): void {
    if (!this.currentSelected?.length) {
      this.labelItemMaxWidths = [];
      return;
    }

    const containerWidth = this.dropdownWrapper().nativeElement.clientWidth;
    // Reserved space: icon group (40px) + padding + gaps
    const reservedSpace = 80;
    const availableWidth = containerWidth - reservedSpace;

    // Gap between items (4px per gap)
    const gapWidth = 4;
    const itemPadding = 14; // 2px + 4px + 2px + 10px horizontal padding
    const deleteIconWidth = 20; // pi-times icon + gap
    const minItemWidth = 60; // minimum width for an item
    const maxItemWidth = 150; // maximum width for single item

    const itemCount = this.currentSelected.length;

    // Total gaps between items
    const totalGaps = (itemCount - 1) * gapWidth;

    // Calculate width per item
    let widthPerItem = (availableWidth - totalGaps) / itemCount;

    // Ensure each item has reasonable width
    widthPerItem = Math.max(minItemWidth, Math.min(widthPerItem, maxItemWidth));

    // Calculate text width (item width - padding - delete icon)
    const textWidth = widthPerItem - itemPadding - deleteIconWidth;

    this.labelItemMaxWidths = new Array(itemCount).fill(
      Math.max(textWidth, 30),
    );
  }

  /**
   * Get max-width for label text at specific index
   */
  getLabelTextMaxWidth(index: number): string {
    return this.labelItemMaxWidths[index]
      ? `${this.labelItemMaxWidths[index]}px`
      : 'auto';
  }

  /**
   * Check if should show count instead of individual labels
   * Returns true if:
   * 1. Number of selected items exceeds maxLabelSelected OR
   * 2. Labels would overflow the container
   */
  shouldShowCount = computed(() => {
    const prop = this.computedProps();
    // Read signals to make computed reactive
    const selectedCount = this.selectedCountSignal();
    const containerWidth = this.dropdownWidth();

    // Case 1: No item to show
    if (selectedCount === 0 && !this.checkAllInternal()) {
      return false;
    }

    // Case 2: If user click select all
    if (this.checkAllInternal() && selectedCount > 0) {
      return true;
    }

    // Case 3: Check maxLabelSelected limit
    if (selectedCount > prop.maxLabelSelected) {
      return true;
    }

    // Case 4: Check if labels would overflow container
    // if (selectedCount === 0) {
    //   return false;
    // }

    if (!containerWidth) {
      return false;
    }

    // Reserved space: icon group (40px) + padding + gaps + margins
    const reservedSpace = 80;
    const availableWidth = containerWidth - reservedSpace;

    // Calculate estimated width for all label items
    const gapWidth = 4; // gap between items
    const itemPadding = 14; // horizontal padding
    const deleteIconWidth = 20; // delete icon width
    const minItemWidth = 60; // minimum width per item

    // Estimate total width needed
    const totalGaps = (selectedCount - 1) * gapWidth;
    const estimatedTotalWidth = selectedCount * (minItemWidth + itemPadding + deleteIconWidth) + totalGaps;

    return estimatedTotalWidth > availableWidth;
  });

  /**
   * Count number of selected items
   * @returns Number of selected items
   */
  countValue = computed(() => {
    return this.selectedCountSignal();
  })

  isCheckAllIndeterminate = computed(() => {
    const prop = this.computedProps();
    const totalItems = prop.totalItems || prop.items.length;
    const selectedCount = this.selectedCountSignal();

    return selectedCount > 0 && selectedCount < totalItems;
  });

  /**
   * Disable check all if there's no result to show
   */
  shouldInternalDisableCheckAll(): boolean {
    const prop = this.computedProps();
    const resultCount =
      this.localSearchItemList !== undefined ? this.localSearchItemList.length : prop.totalItems;

    return prop.disableCheckAllWhenNoResult && resultCount <= 0;
  }

  ngOnDestroy(): void {
    this.resizeObserver?.disconnect();
    this.removeScrollListener();
  }
}
