import { Component, input, output } from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import { Button } from 'primeng/button';
import { ImportResult } from '../../public-api';

export interface ImportReportData extends ImportResult {
  // Translation keys
  titleKey?: string;
  successCountKey?: string;
  failureCountKey?: string;
  downloadDescriptionKey?: string;
}

@Component({
  selector: 'ubck-import-report',
  template: `
    <div class="import-wrapper">
      <header>
        <h4>{{ (reportData().titleKey || 'Kết quả tải lên tệp tin') | translate }}</h4>
      </header>
      <p>
        {{ (reportData().successCountKey || 'Số bản ghi thành công:') | translate }} 
        <span class="success">{{ reportData().successCount }}/{{ reportData().totalRows }}</span>
      </p>
      <p>
        {{ (reportData().failureCountKey || 'Số bản ghi thất bại:') | translate }} 
        <span class="failure">{{ reportData().errorCount }}/{{ reportData().totalRows }}</span>
      </p>
      @if(reportData().errorFileName || '') {
      <p-button 
          size="small" 
          [label]="reportData().errorFileName || ''" 
          [text]="true" 
          severity="primary"
          (onClick)="handleDownloadFile()"
        >
          <ng-template #icon>
            <svg
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                d="M17 9.00195C19.175 9.01406 20.3529 9.11051 21.1213 9.8789C22 10.7576 22 12.1718 22 15.0002V16.0002C22 18.8286 22 20.2429 21.1213 21.1215C20.2426 22.0002 18.8284 22.0002 16 22.0002H8C5.17157 22.0002 3.75736 22.0002 2.87868 21.1215C2 20.2429 2 18.8286 2 16.0002L2 15.0002C2 12.1718 2 10.7576 2.87868 9.87889C3.64706 9.11051 4.82497 9.01406 7 9.00195"
                stroke="#0F5A43"
                stroke-width="1.5"
                stroke-linecap="round"
              />
              <path
                d="M12 2L12 15M12 15L9 11.5M12 15L15 11.5"
                stroke="#0F5A43"
                stroke-width="1.5"
                stroke-linecap="round"
                stroke-linejoin="round"
              />
            </svg>
          </ng-template>
        </p-button>
          <p>
        {{ (reportData().downloadDescriptionKey || 'Tải tệp tin về để xem thông tin chi tiết, nguyên nhân về kết quả tải lên tập tin') | translate }}
      </p>
      }
     
    
    </div>
  `,
  imports: [TranslatePipe, Button],
  styleUrls: ['./import-report.scss'],
  standalone: true
})
export class UbckImportReport {
  // Props
  reportData = input.required<ImportReportData>();

  // Events
  downloadFileEvent = output<{ fileName?: string | null }>({
    alias: 'onDownloadFile'
  });

  handleDownloadFile() {
    const data = this.reportData();
    this.downloadFileEvent.emit({
      fileName: data.errorFileName,
    });
  }
}
