export const AUTOCOMPLETE_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export const AUTOCOMPLETE_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export const DEFAULT_MIN_LENGTH = 1;
export const DEFAULT_DELAY = 300;
export const DEFAULT_SCROLL_HEIGHT = '200px';
export const DEFAULT_EMPTY_MESSAGE = 'No results found';

export type AutoCompleteSize = (typeof AUTOCOMPLETE_SIZES)[keyof typeof AUTOCOMPLETE_SIZES];
export type AutoCompleteVariant = (typeof AUTOCOMPLETE_VARIANTS)[keyof typeof AUTOCOMPLETE_VARIANTS];
