import { Directive, input, HostBinding } from '@angular/core';
import { InputText } from 'primeng/inputtext';
import { InputTextVariant, InputTextSize } from './cmm-inputtext.types';
import { INPUTTEXT_DEFAULTS } from './cmm-inputtext.constants';

@Directive({
  selector: 'input[cmmInputText]',
  standalone: true,
  hostDirectives: [
    {
      directive: InputText,
    },
  ],
})
export class CmmInputText {
  variant = input<InputTextVariant>(INPUTTEXT_DEFAULTS.VARIANT);
  fluid = input<boolean>(INPUTTEXT_DEFAULTS.FLUID);
  size = input<InputTextSize>();

  @HostBinding('class.p-inputtext')
  get inputTextClass() {
    return true;
  }
}
