import { Component, input, output, contentChild, TemplateRef, ChangeDetectionStrategy, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ConfirmDialogModule } from 'primeng/confirmdialog';
import { ConfirmationService, ConfirmEventType } from 'primeng/api';
import { ConfirmDialogDefaultFocus } from './cmm-confirmdialog.types';
import { CONFIRMDIALOG_DEFAULTS } from './cmm-confirmdialog.constants';

@Component({
  selector: 'cmm-confirmdialog',
  standalone: true,
  imports: [CommonModule, ConfirmDialogModule],
  template: `
    <p-confirmDialog
      [header]="header() ?? undefined"
      [icon]="icon() ?? undefined"
      [message]="message() ?? undefined"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined"
      [maskStyleClass]="maskStyleClass() ?? undefined"
      [acceptIcon]="acceptIcon() ?? undefined"
      [acceptLabel]="acceptLabel() ?? undefined"
      [acceptAriaLabel]="acceptAriaLabel() ?? undefined"
      [acceptVisible]="acceptVisible()"
      [acceptButtonStyleClass]="acceptButtonStyleClass() ?? undefined"
      [rejectIcon]="rejectIcon() ?? undefined"
      [rejectLabel]="rejectLabel() ?? undefined"
      [rejectAriaLabel]="rejectAriaLabel() ?? undefined"
      [rejectVisible]="rejectVisible()"
      [rejectButtonStyleClass]="rejectButtonStyleClass() ?? undefined"
      [closable]="closable()"
      [closeAriaLabel]="closeAriaLabel() ?? undefined"
      [closeOnEscape]="closeOnEscape()"
      [dismissableMask]="dismissableMask()"
      [blockScroll]="blockScroll()"
      [rtl]="rtl()"
      [appendTo]="appendTo()"
      [key]="key() ?? undefined"
      [autoZIndex]="autoZIndex()"
      [baseZIndex]="baseZIndex()"
      [transitionOptions]="transitionOptions()"
      [focusTrap]="focusTrap()"
      [defaultFocus]="defaultFocus()"
      [breakpoints]="breakpoints() ?? undefined"
      [visible]="visible() ?? undefined"
      [attr.data-pc-section]="'root'"
      (onHide)="onHide.emit($event)">
      @if (headerTemplate()) {
        <ng-template pTemplate="header">
          <ng-container *ngTemplateOutlet="headerTemplate()!" />
        </ng-template>
      }
      @if (footerTemplate()) {
        <ng-template pTemplate="footer">
          <ng-container *ngTemplateOutlet="footerTemplate()!" />
        </ng-template>
      }
      @if (messageTemplate()) {
        <ng-template pTemplate="message" let-message>
          <ng-container *ngTemplateOutlet="messageTemplate()!; context: { $implicit: message }" />
        </ng-template>
      }
      @if (iconTemplate()) {
        <ng-template pTemplate="icon">
          <ng-container *ngTemplateOutlet="iconTemplate()!" />
        </ng-template>
      }
      @if (acceptIconTemplate()) {
        <ng-template pTemplate="accepticon">
          <ng-container *ngTemplateOutlet="acceptIconTemplate()!" />
        </ng-template>
      }
      @if (rejectIconTemplate()) {
        <ng-template pTemplate="rejecticon">
          <ng-container *ngTemplateOutlet="rejectIconTemplate()!" />
        </ng-template>
      }
      @if (closeIconTemplate()) {
        <ng-template pTemplate="closeicon">
          <ng-container *ngTemplateOutlet="closeIconTemplate()!" />
        </ng-template>
      }
    </p-confirmDialog>
  `,
  styleUrl: './cmm-confirmdialog.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [ConfirmationService],
})
export class CmmConfirmdialogComponent {
  private confirmationService = inject(ConfirmationService);

  // Content
  header = input<string>();
  icon = input<string>();
  message = input<string>();
  style = input<Record<string, any>>();
  styleClass = input<string>();
  maskStyleClass = input<string>();

  // Accept button
  acceptIcon = input<string>();
  acceptLabel = input<string>();
  acceptAriaLabel = input<string>();
  acceptVisible = input<boolean>(CONFIRMDIALOG_DEFAULTS.ACCEPT_VISIBLE);
  acceptButtonStyleClass = input<string>();

  // Reject button
  rejectIcon = input<string>();
  rejectLabel = input<string>();
  rejectAriaLabel = input<string>();
  rejectVisible = input<boolean>(CONFIRMDIALOG_DEFAULTS.REJECT_VISIBLE);
  rejectButtonStyleClass = input<string>();

  // Dialog behavior
  closable = input<boolean>(CONFIRMDIALOG_DEFAULTS.CLOSABLE);
  closeAriaLabel = input<string>();
  closeOnEscape = input<boolean>(CONFIRMDIALOG_DEFAULTS.CLOSE_ON_ESCAPE);
  dismissableMask = input<boolean>(CONFIRMDIALOG_DEFAULTS.DISMISSABLE_MASK);
  blockScroll = input<boolean>(CONFIRMDIALOG_DEFAULTS.BLOCK_SCROLL);
  rtl = input<boolean>(CONFIRMDIALOG_DEFAULTS.RTL);

  // Positioning
  appendTo = input<any>(CONFIRMDIALOG_DEFAULTS.APPEND_TO);
  key = input<string>();
  autoZIndex = input<boolean>(CONFIRMDIALOG_DEFAULTS.AUTO_Z_INDEX);
  baseZIndex = input<number>(CONFIRMDIALOG_DEFAULTS.BASE_Z_INDEX);
  transitionOptions = input<string>(CONFIRMDIALOG_DEFAULTS.TRANSITION_OPTIONS);

  // Focus management
  focusTrap = input<boolean>(CONFIRMDIALOG_DEFAULTS.FOCUS_TRAP);
  defaultFocus = input<ConfirmDialogDefaultFocus>(CONFIRMDIALOG_DEFAULTS.DEFAULT_FOCUS);

  // Responsive
  breakpoints = input<any>();
  visible = input<any>();
  position = input<string>();

  // Templates
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  messageTemplate = contentChild<TemplateRef<any>>('message');
  iconTemplate = contentChild<TemplateRef<any>>('icon');
  acceptIconTemplate = contentChild<TemplateRef<any>>('accepticon');
  rejectIconTemplate = contentChild<TemplateRef<any>>('rejecticon');
  closeIconTemplate = contentChild<TemplateRef<any>>('closeicon');

  // Events
  onHide = output<ConfirmEventType>();
}
