import { Component, ChangeDetectionStrategy, input, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Toolbar } from 'primeng/toolbar';

@Component({
  selector: 'cmm-toolbar',
  standalone: true,
  imports: [CommonModule, Toolbar],
  templateUrl: './cmm-toolbar.component.html',
  styleUrl: './cmm-toolbar.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmToolbarComponent {
  style = input<Record<string, any>>();
  styleClass = input<string>('');
  ariaLabelledBy = input<string>();

  startTemplate = contentChild<TemplateRef<any>>('start');
  endTemplate = contentChild<TemplateRef<any>>('end');
  centerTemplate = contentChild<TemplateRef<any>>('center');
}
