import { Component, inject, Injector, input } from '@angular/core';
import { CommonModule } from '@angular/common';
import { CmmToastComponent } from '../base/primeng/toast/cmm-toast.component';

import { CmmAvatarComponent } from '../base/primeng/avatar/cmm-avatar.component';
import { CmmTypepographyModule } from '../typography/public-api';
import { ToastPosition } from '../base/public-api';
import { Button } from 'primeng/button';
import { ToastService } from './toast.service';
import { MessageService } from 'primeng/api';

@Component({
  selector: 'app-toast',
  standalone: true,
  imports: [CommonModule, CmmToastComponent, CmmAvatarComponent, CmmTypepographyModule, Button],
  templateUrl: './toast.component.html',
  styleUrls: ['./toast.component.scss'],
})
export class ToastComponent {
  key = input<string | undefined>();
  position = input<ToastPosition>('top-right');
  life = input<number>(3000);
  showTransitionOptions = input<string>('300ms ease-out');
  hideTransitionOptions = input<string>('250ms ease-in');
  autoZIndex = input<boolean>(true);
  baseZIndex = input<number>(999999);
  preventOpenDuplicates = input<boolean>(false);
  preventDuplicates = input<boolean>(false);
  styleClass = input<string | undefined>();
  breakpoints = input<Record<string, unknown> | undefined>();
  style = input<Record<string, any>>({ zIndex: this.baseZIndex() });
  ellipsisRows = input<number>(3);
  readonly toastService = inject(ToastService);

  readonly injector = inject(Injector)
  getSeverityIcon(severity?: string): string {
    switch (severity) {
      case 'success':
        return 'pi pi-check';
      case 'info':
        return 'pi pi-info';
      case 'warn':
        return 'pi pi-exclamation-triangle';
      case 'error':
        return 'pi pi-info';
      default:
        return 'pi pi-info-circle';
    }
  }

  getSeverityClass(severity?: string): string {
    switch (severity) {
      case 'success':
        return 'bg-green-500 text-white';
      case 'info':
        return 'bg-blue-500 text-white';
      case 'warn':
        return 'bg-orange-500 text-white';
      case 'error':
        return 'bg-red-500 text-white';
      default:
        return 'text-gray-500';
    }
  }

  getToastSummaryClass(severity?: string): string {
    switch (severity) {
      case 'success':
        return 'toast-summary-success';
      case 'info':
        return 'toast-summary-info';
      case 'warn':
        return 'toast-summary-warn';
      case 'error':
        return 'toast-summary-error';
      default:
        return 'toast-summary-default';
    }
  }

  handleAction(message: any): void {
    if (message.data?.actionCallback) {
      message.data.actionCallback();
    }
  }

  handleClose(message: any): void {
    if (message.data?.onCloseCallback) {
      message.data.onCloseCallback();
    }
    console.log(message);

    this.injector.get(MessageService).clear(message.key);
  }
}
