/**
 * Detects if a mouse click occurred outside a provided list of elements.
 * * @param event - The mouse event to inspect.
 * @param ignoreElements - Array of elements; if the click is inside any of these, it is ignored.
 * @param action - The callback function to execute when an outside click is detected.
 * @param isOverlayActive - Boolean flag to toggle the check (e.g., only run if overlay is visible).
 */
export function handleOutsideClick(
  event: MouseEvent,
  ignoreElements: (HTMLElement | undefined | null)[],
  action: () => void,
  isOverlayActive: boolean = true
): void {
  if (!isOverlayActive) return;

  const target = event.target as Node | null;
  if (!target) return;

  const clickedInside = ignoreElements.some(el => el?.contains(target));

  if (!clickedInside) {
    action();
  }
}
