import {
  Component,
  input,
  output,
  model,
  contentChild,
  viewChild,
  TemplateRef,
  ChangeDetectionStrategy,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { Galleria, GalleriaModule } from 'primeng/galleria';
import { GalleriaResponsiveOptions, GalleriaThumbnailsPosition } from './cmm-galleria.types';
import { GALLERIA_DEFAULTS } from './cmm-galleria.constants';

@Component({
  selector: 'cmm-galleria',
  standalone: true,
  imports: [CommonModule, GalleriaModule],
  template: `
    <p-galleria
      #galleria
      [id]="id() ?? undefined"
      [value]="value()"
      [(visible)]="visible"
      [(activeIndex)]="activeIndex"
      [responsiveOptions]="responsiveOptions()"
      [numVisible]="numVisible()"
      [circular]="circular()"
      [autoPlay]="autoPlay()"
      [shouldStopAutoplayByClick]="shouldStopAutoplayByClick()"
      [transitionInterval]="transitionInterval()"
      [showThumbnails]="showThumbnails()"
      [thumbnailsPosition]="thumbnailsPosition()"
      [verticalThumbnailViewPortHeight]="verticalThumbnailViewPortHeight()"
      [showIndicators]="showIndicators()"
      [showIndicatorsOnItem]="showIndicatorsOnItem()"
      [indicatorsPosition]="indicatorsPosition()"
      [showItemNavigators]="showItemNavigators()"
      [showItemNavigatorsOnHover]="showItemNavigatorsOnHover()"
      [showThumbnailNavigators]="showThumbnailNavigators()"
      [changeItemOnIndicatorHover]="changeItemOnIndicatorHover()"
      [fullScreen]="fullScreen()"
      [baseZIndex]="baseZIndex()"
      [maskClass]="maskClass() ?? undefined"
      [containerClass]="containerClass() ?? undefined"
      [containerStyle]="style() ?? undefined"
      [class]="styleClass() ?? undefined"
      [showTransitionOptions]="showTransitionOptions()"
      [hideTransitionOptions]="hideTransitionOptions()"
      (onShow)="onShow.emit()"
      (onHide)="onHide.emit()"
      (activeIndexChange)="handleActiveIndexChange($event)">
      @if (headerTemplate()) {
        <ng-template pTemplate="header">
          <ng-container *ngTemplateOutlet="headerTemplate()!" />
        </ng-template>
      }
      @if (footerTemplate()) {
        <ng-template pTemplate="footer">
          <ng-container *ngTemplateOutlet="footerTemplate()!" />
        </ng-template>
      }
      @if (itemTemplate()) {
        <ng-template pTemplate="item" let-item>
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
      @if (thumbnailTemplate()) {
        <ng-template pTemplate="thumbnail" let-item>
          <ng-container *ngTemplateOutlet="thumbnailTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
      @if (captionTemplate()) {
        <ng-template pTemplate="caption" let-item>
          <ng-container *ngTemplateOutlet="captionTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
      @if (indicatorTemplate()) {
        <ng-template pTemplate="indicator" let-index>
          <ng-container *ngTemplateOutlet="indicatorTemplate()!; context: { $implicit: index }" />
        </ng-template>
      }
      @if (closeIconTemplate()) {
        <ng-template pTemplate="closeicon">
          <ng-container *ngTemplateOutlet="closeIconTemplate()!" />
        </ng-template>
      }
      @if (itemNextIconTemplate()) {
        <ng-template pTemplate="itemnexticon">
          <ng-container *ngTemplateOutlet="itemNextIconTemplate()!" />
        </ng-template>
      }
      @if (itemPreviousIconTemplate()) {
        <ng-template pTemplate="itempreviousicon">
          <ng-container *ngTemplateOutlet="itemPreviousIconTemplate()!" />
        </ng-template>
      }
      @if (previousThumbnailIconTemplate()) {
        <ng-template pTemplate="previousthumbnailicon">
          <ng-container *ngTemplateOutlet="previousThumbnailIconTemplate()!" />
        </ng-template>
      }
      @if (nextThumbnailIconTemplate()) {
        <ng-template pTemplate="nextthumbnailicon">
          <ng-container *ngTemplateOutlet="nextThumbnailIconTemplate()!" />
        </ng-template>
      }
    </p-galleria>
  `,
  styleUrl: './cmm-galleria.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmGalleriaComponent {
  // ViewChild reference
  readonly galleria = viewChild<Galleria>('galleria');

  // Two-way binding models
  visible = model<boolean>(false);
  activeIndex = model<number>(0);

  // Input properties
  readonly id = input<string>();
  readonly value = input<any[]>([]);
  readonly responsiveOptions = input<GalleriaResponsiveOptions[]>();
  readonly numVisible = input<number>(GALLERIA_DEFAULTS.NUM_VISIBLE);
  readonly circular = input<boolean>(GALLERIA_DEFAULTS.CIRCULAR);
  readonly autoPlay = input<boolean>(GALLERIA_DEFAULTS.AUTO_PLAY);
  readonly shouldStopAutoplayByClick = input<boolean>(true);
  readonly transitionInterval = input<number>(GALLERIA_DEFAULTS.TRANSITION_INTERVAL);

  // Display options
  readonly showThumbnails = input<boolean>(GALLERIA_DEFAULTS.SHOW_THUMBNAILS);
  readonly thumbnailsPosition = input<GalleriaThumbnailsPosition>(GALLERIA_DEFAULTS.THUMBNAILS_POSITION);
  readonly verticalThumbnailViewPortHeight = input<string>('300px');
  readonly showIndicators = input<boolean>(GALLERIA_DEFAULTS.SHOW_INDICATORS);
  readonly showIndicatorsOnItem = input<boolean>(GALLERIA_DEFAULTS.SHOW_INDICATORS_ON_ITEM);
  readonly indicatorsPosition = input<'bottom' | 'top' | 'left' | 'right'>('bottom');
  readonly showItemNavigators = input<boolean>(GALLERIA_DEFAULTS.SHOW_ITEM_NAVIGATORS);
  readonly showItemNavigatorsOnHover = input<boolean>(false);
  readonly showThumbnailNavigators = input<boolean>(GALLERIA_DEFAULTS.SHOW_THUMBNAIL_NAVIGATORS);
  readonly changeItemOnIndicatorHover = input<boolean>(false);

  // Advanced
  readonly fullScreen = input<boolean>(GALLERIA_DEFAULTS.FULL_SCREEN);
  readonly baseZIndex = input<number>(GALLERIA_DEFAULTS.BASE_Z_INDEX);
  readonly maskClass = input<string>();
  readonly containerClass = input<string>();
  readonly style = input<Record<string, any>>();
  readonly styleClass = input<string>();
  readonly showTransitionOptions = input<string>('150ms cubic-bezier(0, 0, 0.2, 1)');
  readonly hideTransitionOptions = input<string>('150ms cubic-bezier(0, 0, 0.2, 1)');

  // Template references
  readonly headerTemplate = contentChild<TemplateRef<any>>('header');
  readonly footerTemplate = contentChild<TemplateRef<any>>('footer');
  readonly itemTemplate = contentChild<TemplateRef<any>>('item');
  readonly thumbnailTemplate = contentChild<TemplateRef<any>>('thumbnail');
  readonly captionTemplate = contentChild<TemplateRef<any>>('caption');
  readonly indicatorTemplate = contentChild<TemplateRef<any>>('indicator');
  readonly closeIconTemplate = contentChild<TemplateRef<any>>('closeicon');
  readonly itemNextIconTemplate = contentChild<TemplateRef<any>>('itemnexticon');
  readonly itemPreviousIconTemplate = contentChild<TemplateRef<any>>('itempreviousicon');
  readonly previousThumbnailIconTemplate = contentChild<TemplateRef<any>>('previousthumbnailicon');
  readonly nextThumbnailIconTemplate = contentChild<TemplateRef<any>>('nextthumbnailicon');

  // Output events
  readonly onShow = output<void>();
  readonly onHide = output<void>();
  readonly onActiveIndexChange = output<number>();

  handleActiveIndexChange(index: number): void {
    this.onActiveIndexChange.emit(index);
  }
}
