import { Component, input, output, model, forwardRef, ChangeDetectionStrategy } from '@angular/core';

import { FormsModule, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import { SliderModule, SliderSlideEndEvent } from 'primeng/slider';
import { SliderOrientation, SliderVariant } from './cmm-slider.types';
import { SLIDER_DEFAULTS } from './cmm-slider.constants';

@Component({
  selector: 'cmm-slider',
  standalone: true,
  imports: [FormsModule, SliderModule],
  template: `
    <p-slider
      [(ngModel)]="value"
      [min]="min()"
      [max]="max()"
      [step]="step()"
      [orientation]="orientation()"
      [disabled]="disabled()"
      [range]="range()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass()!"
      [ariaLabel]="ariaLabel()!"
      [ariaLabelledBy]="ariaLabelledBy()!"
      (onChange)="handleChange($event)"
      (onSlideEnd)="handleSlideEnd($event)"
    />
  `,
  styleUrl: './cmm-slider.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmSliderComponent),
      multi: true,
    },
  ],
})
export class CmmSliderComponent implements ControlValueAccessor {
  // Model - can be number or [number, number] for range
  value = model<number | number[]>(SLIDER_DEFAULTS.MIN);

  // Core props
  min = input<number>(SLIDER_DEFAULTS.MIN);
  max = input<number>(SLIDER_DEFAULTS.MAX);
  step = input<number>(SLIDER_DEFAULTS.STEP);
  orientation = input<SliderOrientation>(SLIDER_DEFAULTS.ORIENTATION);
  disabled = input<boolean>(SLIDER_DEFAULTS.DISABLED);
  range = input<boolean>(SLIDER_DEFAULTS.RANGE);
  variant = input<SliderVariant>(SLIDER_DEFAULTS.VARIANT);
  style = input<Record<string, any>>();
  styleClass = input<string>();
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();

  // Output events
  onChange = output<{ value?: number | number[] }>();
  onSlideEnd = output<SliderSlideEndEvent>();

  // ControlValueAccessor
  private onChangeFn: (value: number | number[]) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: number | number[]): void {
    this.value.set(value ?? SLIDER_DEFAULTS.MIN);
  }

  registerOnChange(fn: (value: number | number[]) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handle if needed
  }

  handleChange(event: { value?: number | number[] }): void {
    this.onChange.emit(event);
    if (event.value !== undefined) {
      this.onChangeFn(event.value);
    }
  }

  handleSlideEnd(event: SliderSlideEndEvent): void {
    this.onSlideEnd.emit(event);
    this.onTouchedFn();
  }
}
