import { Injectable, signal, computed } from '@angular/core';
import {
  HttpContext,
  HttpErrorResponse,
  HttpEvent,
  HttpEventType,
  HttpResponse,
} from '@angular/common/http';
import {
  Observable,
  Subject,
  tap,
  catchError,
  throwError,
  map,
  filter,
} from 'rxjs';
import { HttpApiService, IHttpApiResponse } from '@khcn-core/common';

// Types & Interfaces
export enum ImportStep {
  SELECT_FILE = 'select-file',
  SHOW_SUCCESS_INFO = 'show-success-info',
  UPLOAD_IN_PROGRESS = 'upload-in-progress',
  SHOW_RESULT = 'show-result',
}

export interface ImportResult  {
totalRows: number,
  successCount: number,
  errorCount: number,
  message: string,
  errorFileName: string | null,
}

export interface ImportConfig {
  templateUrl?: string;
  uploadEndpoint?: string;
  progressInterval?: number;
  baseUrl?: string;
  httpService: HttpApiService;
  downloadFileUrl: string
}

type ImportUploadEvent = HttpEvent<IHttpApiResponse<ImportResult>>;



@Injectable()
export class ImportFileService {

  // Private signals for state management
  private fileSelected = signal<File | null>(null);
  private currentStep = signal<ImportStep>(ImportStep.SELECT_FILE);
  private uploadProgress = signal<number>(0);
  private uploadResult = signal<ImportResult | null>(null);
  private isUploading = signal<boolean>(false);

  private progressSubject = new Subject<number>();

  public readonly file = this.fileSelected.asReadonly();
  public readonly step = this.currentStep.asReadonly();
  public readonly progress = this.uploadProgress.asReadonly();
  public readonly result = this.uploadResult.asReadonly();
  public readonly uploading = this.isUploading.asReadonly();

  public readonly computedStep = computed(() => {
    const file = this.fileSelected();
    const isUploading = this.isUploading();
    const result = this.uploadResult();

    if (!file) return ImportStep.SELECT_FILE;
    if (result !== null) return ImportStep.SHOW_RESULT;
    if (isUploading) return ImportStep.UPLOAD_IN_PROGRESS;
    if (file && !isUploading && result === null)
      return ImportStep.SHOW_SUCCESS_INFO;

    return this.currentStep();
  });

  // Public API Methods
  selectFile(file: File): void {
    this.fileSelected.set(file);
    this.currentStep.set(ImportStep.SHOW_SUCCESS_INFO);
    this.resetProgress();
  }

  removeFile(): void {
    this.fileSelected.set(null);
    this.currentStep.set(ImportStep.SELECT_FILE);
    this.resetProgress();
  }

  startImport(config?: ImportConfig): Observable<ImportResult> {
    const file = this.fileSelected();
    if (!file) {
      return throwError(() => new Error('No file selected'));
    }

    this.isUploading.set(true);
    this.currentStep.set(ImportStep.UPLOAD_IN_PROGRESS);
    this.uploadProgress.set(0);

    const formData = new FormData();
    formData.append('file', file);
    formData.append('fileName', file.name);

    const endpoint = config?.uploadEndpoint || '/import';

    return config!.httpService
      .post<ImportUploadEvent, FormData>(config?.baseUrl || null, formData, endpoint, {
        reportProgress: true,
        observe: 'events',
        context: new HttpContext().set(HttpApiService.HTTP_METADATA, {
          ignoreLoadingIndicator: true,
        }),
      })
      .pipe(
        tap((event) => {
          if (event && Object.hasOwn(event, 'type') && event.type === HttpEventType.UploadProgress) {
            if (event.total) {
              const progress = Math.round((100 * event.loaded) / event.total);
              this.uploadProgress.set(progress);
              this.progressSubject.next(progress);
            }
          } else if (event && Object.hasOwn(event, 'type') && event.type === HttpEventType.Response) {
            // Handle successful response
            const result = event.body?.data;
            if (!result) {
              return;
            }
            this.uploadResult.set(result);
            this.currentStep.set(ImportStep.SHOW_RESULT);
            this.isUploading.set(false);
          }
        }),
        filter((event): event is HttpResponse<IHttpApiResponse<ImportResult>> => (
          event.type === HttpEventType.Response
        )),
        map((event) => event.body?.data),
        filter((result) => !!result),
        catchError((error: HttpErrorResponse) => {
          console.error('Upload error:', error);

          const errorResult: ImportResult = {
            totalRows: 0,
            successCount: 0,
            errorCount: 0,
            errorFileName: file.name,
            message: error?.message || 'Upload failed',
          };

          this.uploadResult.set(errorResult);
          this.currentStep.set(ImportStep.SHOW_RESULT);
          this.isUploading.set(false);

          return throwError(() => errorResult);
        })
      );
  }

  downloadTemplate(config: ImportConfig, templateUrl: string): void {
    const endpoint = templateUrl;
    let fileName: string = 'import-template.xlsx';
    config!.httpService
      .get<HttpResponse<Blob>>(null, endpoint, {
        responseType: 'blob',
        observe: 'response',
      })
      .subscribe({
        next: (res) => {
          if (res.body) {
            fileName = this.getFileNameFromResponse(res) as string;
            const blobFile = new Blob([res.body], { type: this.getContentTypeFromResponse(res) });
            this.downloadBlob(blobFile, fileName);
          }
        },
        error: (error: HttpErrorResponse) => {
          console.error('Template download failed:', error);
          // Fallback to direct link
          this.downloadDirect(endpoint, 'import-template.xlsx');
        },
      });
  }

  downloadErrorReport(config: ImportConfig, fileName: string): void {
    // Use HttpApiService directly for blob download
    config!.httpService
      .get<HttpResponse<Blob>>(null, config.downloadFileUrl, {
        responseType: 'blob',
        observe: 'response',
        fileName: fileName,
      })
      .subscribe({
        next: (res) => {
          if (res.body) {
            const finalFileName =
              fileName ||
              this.getFileNameFromResponse(res) ||
              'error-report.xlsx';
            this.downloadBlob(res.body, finalFileName);
          }
        },
        error: (error: HttpErrorResponse) => {
          console.error('Error report download failed:', error);
          // Fallback to direct link
          this.downloadDirect(fileName, fileName || 'error-report.xlsx');
        },
      });
  }

  reset(): void {
    this.fileSelected.set(null);
    this.currentStep.set(ImportStep.SELECT_FILE);
    this.resetProgress();
  }

  // Private helper methods
  private resetProgress(): void {
    this.uploadProgress.set(0);
    this.uploadResult.set(null);
    this.isUploading.set(false);
  }

  private downloadBlob(blob: Blob, fileName: string): void {
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.URL.revokeObjectURL(url);
  }

  private downloadDirect(url: string, fileName: string): void {
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    link.target = '_blank';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  private getFileNameFromResponse(response: HttpResponse<Blob>): string | null {
    const contentDisposition = response?.headers?.get('content-disposition');
    if (contentDisposition) {
      const fileNameMatch = contentDisposition?.match(
        /filename[^;=\n]*=((['"]).*?\2|[^;\n]*)/i,
      );
      if (fileNameMatch && fileNameMatch[1]) {
        return fileNameMatch[1]?.replace(/["']/g, '');
      }
    }
    return 'import-template.xlsx';
  }

  private getContentTypeFromResponse(response: HttpResponse<Blob>): string {
    const contentType = response?.headers?.get('content-type');
    return contentType || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
  }

  public getProgressStream(): Observable<number> {
    return this.progressSubject.asObservable();
  }

  public getImportStatus(): {
    step: ImportStep;
    progress: number;
    isUploading: boolean;
    hasResult: boolean;
  } {
    return {
      step: this.computedStep(),
      progress: this.uploadProgress(),
      isUploading: this.isUploading(),
      hasResult: this.uploadResult() !== null,
    };
  }

  public checkImportStatus(
    importId: string,
    config: ImportConfig,
  ): Observable<any> {
    const endpoint = `/import/status/{importId}`;
    return config!.httpService.get(config?.baseUrl || null, endpoint, { importId });
  }

  public getImportHistory(config: ImportConfig): Observable<any[]> {
    const endpoint = '/import/history';
    return config!.httpService.get(config?.baseUrl || null, endpoint);
  }
}
