import {
  Component,
  input,
  output,
  model,
  forwardRef,
  ChangeDetectionStrategy,
  contentChild,
  TemplateRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import { SelectButtonModule, SelectButtonChangeEvent } from 'primeng/selectbutton';
import { SelectButtonSize } from './cmm-selectbutton.types';
import { SELECTBUTTON_DEFAULTS } from './cmm-selectbutton.constants';

@Component({
  selector: 'cmm-selectbutton',
  standalone: true,
  imports: [CommonModule, FormsModule, SelectButtonModule],
  template: `
    <p-selectbutton
      [(ngModel)]="value"
      [options]="options()"
      [optionLabel]="optionLabel()"
      [optionValue]="optionValue()"
      [optionDisabled]="optionDisabled()"
      [multiple]="multiple()"
      [disabled]="disabled()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass()!"
      [ariaLabelledBy]="ariaLabelledBy()!"
      (onChange)="handleChange($event)"
    >
      @if (itemTemplate()) {
        <ng-template let-item pTemplate="item">
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
    </p-selectbutton>
  `,
  styleUrl: './cmm-selectbutton.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmSelectbuttonComponent),
      multi: true,
    },
  ],
})
export class CmmSelectbuttonComponent implements ControlValueAccessor {
  // Model - can be single value or array for multiple
  value = model<any | any[]>();

  // Content children templates
  itemTemplate = contentChild<TemplateRef<any>>('item');

  // Core props
  options = input<any[]>([]);
  optionLabel = input<string>(SELECTBUTTON_DEFAULTS.OPTION_LABEL);
  optionValue = input<string>(SELECTBUTTON_DEFAULTS.OPTION_VALUE);
  optionDisabled = input<string>(SELECTBUTTON_DEFAULTS.OPTION_DISABLED);
  multiple = input<boolean>(SELECTBUTTON_DEFAULTS.MULTIPLE);
  disabled = input<boolean>(SELECTBUTTON_DEFAULTS.DISABLED);
  size = input<SelectButtonSize>();
  style = input<Record<string, any>>();
  styleClass = input<string>();
  ariaLabelledBy = input<string>();

  // Output events
  onChange = output<SelectButtonChangeEvent>();

  // ControlValueAccessor
  private onChangeFn: (value: any) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: any): void {
    this.value.set(value);
  }

  registerOnChange(fn: (value: any) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handle if needed
  }

  handleChange(event: SelectButtonChangeEvent): void {
    this.onChange.emit(event);
    this.onChangeFn(event.value);
    this.onTouchedFn();
  }
}
