import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { IDialogDelete } from '../dialog.model';

import { CmmTypepographyModule } from '../../typography/public-api';
import { TranslatePipe } from '@ngx-translate/core';
import { TextareaModule } from 'primeng/textarea';
import { ReactiveFormsModule } from '@angular/forms';
import { DynamicDialogConfig, DynamicDialogRef } from 'primeng/dynamicdialog';
import { ValidationModule } from '../../validation/public-api';
import { Button } from 'primeng/button';
import { UBCKBaseDialogIcon } from '../icons/base-icon';
import { AutoFocus } from 'primeng/autofocus';



@Component({
  selector: '[cmm-dialog-delete]',
  imports: [
    ReactiveFormsModule,
    CmmTypepographyModule,
    TranslatePipe,
    TextareaModule,
    ValidationModule,
    Button,
    UBCKBaseDialogIcon,
    AutoFocus
],
  templateUrl: './dialog-delete.component.html',
  styleUrls: ['./dialog-delete.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DialogDeleteComponent {
  meta = inject(DynamicDialogConfig);
  dialogRef = inject(DynamicDialogRef);
  submitted = false;
  data = {
    ...this.meta.data,
    btnCancelSeverity: this.meta.data['btnCancelSeverity'] || 'primary',
    btnConfirmSeverity: this.meta.data['btnConfirmSeverity'] || 'primary',
    withHeader: {
      title: '',
      styleClass: 'w-full',
      closeHandler: this.meta.data.closeHandler,

    },
    iconType: this.meta.data.iconType,
  } as IDialogDelete;

  constructor() { }

  getFormControlNameKey() {
    return Object.keys(this.data?.formGrDelete?.controls || {}).includes('deleteReason') ? 'deleteReason' : 'reason';
  }

  defaultMaxLength = 255;
  handleSubmitForm() {
    this.submitted = true;
    this.data?.formGrDelete?.markAllAsTouched();
    
    if (this.data?.formGrDelete.valid) {
      this.data.submitHandler && this.data.submitHandler(this.dialogRef, this.data?.formGrDelete);
    }
  }
}
