
import { Component, input, output } from '@angular/core';
import { TranslatePipe } from '@ngx-translate/core';
import { Button } from 'primeng/button';

@Component({
  selector: 'ubck-import-success',
  template: `
    <div class="import-wrapper">
      <svg
        width="96"
        height="96"
        viewBox="0 0 96 96"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
      >
        <circle cx="48" cy="48" r="47.5" stroke="#F3F3F3" />
        <rect x="24" y="24" width="48" height="48" rx="24" fill="#EAFFEA" />
        <path
          d="M34 48C34 40.268 40.268 34 48 34V34C55.732 34 62 40.268 62 48V48C62 55.732 55.732 62 48 62V62C40.268 62 34 55.732 34 48V48Z"
          fill="#00894A"
        />
        <path
          d="M41.3906 48.0001L45.7928 52.4023L54.6128 43.5979"
          stroke="white"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
        />
      </svg>
      <header>
        <h4>{{importFileSuccessTitleKey() | translate}}</h4>
      </header>
      <div class="flex justify-center items-center gap-2">
        <div class="flex items-center gap-2">
          <svg
            width="20"
            height="20"
            viewBox="0 0 24 24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M3 10C3 6.22876 3 4.34315 4.17157 3.17157C5.34315 2 7.22876 2 11 2H13C16.7712 2 18.6569 2 19.8284 3.17157C21 4.34315 21 6.22876 21 10V14C21 17.7712 21 19.6569 19.8284 20.8284C18.6569 22 16.7712 22 13 22H11C7.22876 22 5.34315 22 4.17157 20.8284C3 19.6569 3 17.7712 3 14V10Z"
              stroke="#0F5A43"
              stroke-width="1.5"
            />
            <path
              d="M8 10H16"
              stroke="#0F5A43"
              stroke-width="1.5"
              stroke-linecap="round"
            />
            <path
              d="M8 14H13"
              stroke="#0F5A43"
              stroke-width="1.5"
              stroke-linecap="round"
            />
          </svg>

          <span class="filename">{{ file().name }}</span>
        </div>
        <i
          class="pi pi-times-circle cursor-pointer icon-close"
          (click)="handleRemoveFile()"
        ></i>
      </div>
      <p-button
        [outlined]="true"
        class="choose-btn"
        styleClass="rounded-16"
        size="small"
        [label]="chooseAnotherFileKey() | translate"
        (onClick)="handleBackPreviousStep()"
      >
        <ng-template #icon>
          <svg
            width="16"
            height="16"
            viewBox="0 0 16 16"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M11.3359 6.00122C12.786 6.00929 13.5712 6.07359 14.0835 6.58585C14.6693 7.17164 14.6693 8.11444 14.6693 10.0001V10.6667C14.6693 12.5523 14.6693 13.4952 14.0835 14.0809C13.4977 14.6667 12.5549 14.6667 10.6693 14.6667H5.33594C3.45032 14.6667 2.50751 14.6667 1.92172 14.0809C1.33594 13.4952 1.33594 12.5523 1.33594 10.6667L1.33594 10.0001C1.33594 8.11444 1.33594 7.17163 1.92172 6.58585C2.43398 6.07359 3.21925 6.00929 4.66927 6.00122"
              stroke="#0F5A43"
              stroke-width="1.5"
              stroke-linecap="round"
            />
            <path
              d="M8 10L8 1.33333M8 1.33333L10 3.66667M8 1.33333L6 3.66667"
              stroke="#0F5A43"
              stroke-width="1.5"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </ng-template>
      </p-button>
    </div>
  `,
  styleUrls: ['./import-success.scss'],
  standalone: true,
  imports: [Button, TranslatePipe],
})
export class UbckImportSuccess {
  file = input.required<File>();
  eventBackToPreviousStep = output<void>({ alias: 'onBackToPreviousStep' });
  eventRemoveFile = output<void>({ alias: 'onRemoveFile' });
  importFileSuccessTitleKey  = input<string>('Tải file thành công');
  chooseAnotherFileKey = input<string>('Chọn tệp khác');

  handleBackPreviousStep() {
    this.eventBackToPreviousStep.emit();
  }
  
  handleRemoveFile() {
    this.eventRemoveFile.emit();
  }
  
}
