/**
 * AvatarGroup size options
 */
export const AVATAR_GROUP_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type AvatarGroupSize = (typeof AVATAR_GROUP_SIZES)[keyof typeof AVATAR_GROUP_SIZES];

/**
 * AvatarGroup style variants
 */
export const AVATAR_GROUP_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export type AvatarGroupVariant = (typeof AVATAR_GROUP_VARIANTS)[keyof typeof AVATAR_GROUP_VARIANTS];
