import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { IBtnHeader } from './btn-header.model';
import { CommonModule } from '@angular/common';
import { TieredMenu } from 'primeng/tieredmenu';

@Component({
  selector: 'cmm-btn-header',
  imports: [CommonModule, TieredMenu],
  templateUrl: './btn-header.component.html',
  styleUrl: './btn-header.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BtnHeaderComponent {
  meta = input.required<IBtnHeader>();
  eventClick = output<MouseEvent>();
  eventClickTiredItem = output<unknown>();

  handleClick(event: MouseEvent) {
    if (this.meta().status !== 'disabled') {
      this.eventClick.emit(event);
    }
  }
  handleClickTiredItem(event: unknown) {
    this.meta().clickTiredItem?.(this.meta(), event as any);
    this.eventClickTiredItem.emit(event);
  }
}
