import { inject } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';

import type { MessageFunction } from './validation-messages.token';

/**
 * Validation Messages Factory Functions
 *
 * Each message is a function that uses TranslateService to get the message
 * This approach provides:
 * - Reactive language switching
 * - Type safety
 * - Centralized translation management
 * - No need for manual factory setup
 *
 * Usage in validation:
 * - {{0}} = field name/label
 * - {{1}} = parameter value (min, max, minLength, maxLength, etc.)
 *
 * Translation key format: VALIDATION.{errorKey}
 * Example: VALIDATION.required, VALIDATION.email
 */

/**
 * Create validation messages object with translate functions
 * Call this function to get messages that are reactive to language changes
 */
export function createValidationMessages(translateService?: TranslateService): { [key: string]: MessageFunction } {
  const t = translateService || inject(TranslateService);
  
  return {
    // Basic validators
    required: (params?: any) => t.instant('VALIDATION.required', params),
    requiredTrue: (params?: any) => t.instant('VALIDATION.requiredTrue', params),

    // Email validator
    email: (params?: any) => t.instant('VALIDATION.email', params),

    // Pattern validator
    pattern: (params?: any) => t.instant('VALIDATION.pattern', params),

    // Min/Max validators
    min: (params?: any) => t.instant('VALIDATION.min', params),
    max: (params?: any) => t.instant('VALIDATION.max', params),

    // Length validators
    minlength: (params?: any) => t.instant('VALIDATION.minlength', params),
    maxlength: (params?: any) => t.instant('VALIDATION.maxlength', params),

    // Custom validators
    passwordMismatch: (params?: any) => t.instant('VALIDATION.passwordMismatch', params),
    invalidPhone: (params?: any) => t.instant('VALIDATION.invalidPhone', params),
    invalidUrl: (params?: any) => t.instant('VALIDATION.invalidUrl', params),
    whitespace: (params?: any) => t.instant('VALIDATION.whitespace', params),

    // Date validators
    invalidDate: (params?: any) => t.instant('VALIDATION.invalidDate', params),
    dateMin: (params?: any) => t.instant('VALIDATION.dateMin', params),
    dateMax: (params?: any) => t.instant('VALIDATION.dateMax', params),
    incompleteDateRange: (params?: any) => t.instant('VALIDATION.incompleteDateRange', params),

    // File validators
    invalidFileType: (params?: any) => t.instant('VALIDATION.invalidFileType', params),
    fileSizeExceeded: (params?: any) => t.instant('VALIDATION.fileSizeExceeded', params),

    // Number validators
    invalidNumber: (params?: any) => t.instant('VALIDATION.invalidNumber', params),

    // Custom business validators
    duplicateValue: (params?: any) => t.instant('VALIDATION.duplicateValue', params),
    invalidRange: (params?: any) => t.instant('VALIDATION.invalidRange', params),
    strongPassword: (params?: any) => t.instant('VALIDATION.strongPassword', params),
  };
}

