import { Component, inject } from '@angular/core';
import { UbckImport } from './import-file';
import { DynamicDialogConfig } from 'primeng/dynamicdialog';
import { UbckImportProps } from './import-file.types';
import { ToastService } from '../public-api';

@Component({
  selector: 'ubck-import-dialog',
  template: `
    <ubck-import
      [props]="dialogData || {}"
      [config]="dialogData.config || {}"
      (uploadErrorEvent)="handleError($event)"
      (uploadSuccessEvent)="dialogData.importSuccessHandler($event)"
    ></ubck-import>
  `,
  imports: [UbckImport],
})
export class DialogImportFile {
  // Dialog state
  dialogData = inject(DynamicDialogConfig).data as UbckImportProps;
  messageService = this.dialogData.toastService as ToastService;
  

  handleError(event: any) {
    switch (event.type) {
      case 'size':
        this.messageService.error(this.dialogData.summary || 'Lỗi', this.dialogData.invalidFileSizeMessageDetail);
        break;
      case 'type':
        this.messageService.error(this.dialogData.summary || 'Lỗi', this.dialogData.invalidFileTypeMessageDetail);
        break;
      default:
        this.messageService.error(this.dialogData.summary || 'Lỗi', event.message);
    }
  }
}
