import { ImportConfig, ToastService, UbckImportProps } from '../public-api';
import { IMPORT_TRANSLATION_KEYS } from './import-file-translations';
import { TranslateService } from '@ngx-translate/core';

/**
 * Helper để tạo default import props với translation keys
 */
export function createDefaultImportProps(
  config: ImportConfig,
  toastService: ToastService,
  importSuccessHandler: (data: any) => void,
  options?: Partial<UbckImportProps>
): UbckImportProps {
  return {
    // Default error messages (sử dụng translation keys)
    summary: IMPORT_TRANSLATION_KEYS.errorSummary,
    invalidFileSizeMessageDetail: IMPORT_TRANSLATION_KEYS.errorFileSize,
    invalidFileLimitMessageDetail: IMPORT_TRANSLATION_KEYS.errorFileLimit,
    invalidFileTypeMessageDetail: IMPORT_TRANSLATION_KEYS.errorFileType,
    
    // Translation keys cho UI
    templateInstructionKey: IMPORT_TRANSLATION_KEYS.templateInstruction,
    downloadTemplateKey: IMPORT_TRANSLATION_KEYS.downloadTemplate,
    recordInstructionKey: IMPORT_TRANSLATION_KEYS.recordInstruction,
    closeButtonKey: IMPORT_TRANSLATION_KEYS.closeButton,
    continueButtonKey: IMPORT_TRANSLATION_KEYS.continueButton,
    fileInprogressTitleKey: IMPORT_TRANSLATION_KEYS.fileInprogressTitle,
    importFileSuccessTitleKey: IMPORT_TRANSLATION_KEYS.fileSuccessTitle,
    chooseAnotherFileKey: IMPORT_TRANSLATION_KEYS.chooseAnother,
    
    // Required props
    config,
    toastService,
    importSuccessHandler,
    
    // Default accept type
    accept: '.xlsx',
    
    // Override với custom options nếu có
    ...options,
  };
}


/**
 * Helper để tạo ImportConfig object
 */
export function createImportConfig(config: {
  templateUrl: string;
  uploadEndpoint: string;
  downloadFileUrl: string;
  httpService: any;
}): ImportConfig {
  return {
    templateUrl: config.templateUrl,
    httpService: config.httpService,
    uploadEndpoint: config.uploadEndpoint,
    downloadFileUrl: config.downloadFileUrl,
  };
}

/**
 * Các preset config cho loại file thông dụng
 */
export const IMPORT_FILE_PRESETS = {
  xlsx: {
    accept: '.xlsx',
    invalidFileTypeMessage: 'File tải lên không đúng định dạng .xlsx. Bạn vui lòng kiểm tra lại.',
    invalidFileTypeMessageKey: IMPORT_TRANSLATION_KEYS.errorFileType,
  },
  csv: {
    accept: '.csv',
    invalidFileTypeMessage: 'File tải lên không đúng định dạng .csv. Bạn vui lòng kiểm tra lại.',
    invalidFileTypeMessageKey: 'import.error.file.type.csv',
  },
  excel: {
    accept: '.xlsx,.xls',
    invalidFileTypeMessage: 'File tải lên không đúng định dạng Excel. Bạn vui lòng kiểm tra lại.',
    invalidFileTypeMessageKey: 'import.error.file.type.excel',
  },
} as const;

/**
 * Helper để translate messages nếu cần
 * Sử dụng khi muốn get translated message trước khi truyền vào dialog
 */
export function getTranslatedImportMessages(translateService: TranslateService) {
  return {
    summary: translateService.instant(IMPORT_TRANSLATION_KEYS.errorSummary),
    invalidFileSizeMessageDetail: translateService.instant(IMPORT_TRANSLATION_KEYS.errorFileSize),
    invalidFileLimitMessageDetail: translateService.instant(IMPORT_TRANSLATION_KEYS.errorFileLimit),
    invalidFileTypeMessageDetail: translateService.instant(IMPORT_TRANSLATION_KEYS.errorFileType),
    
    templateInstructionKey: translateService.instant(IMPORT_TRANSLATION_KEYS.templateInstruction),
    downloadTemplateKey: translateService.instant(IMPORT_TRANSLATION_KEYS.downloadTemplate),
    recordInstructionKey: translateService.instant(IMPORT_TRANSLATION_KEYS.recordInstruction),
    closeButtonKey: translateService.instant(IMPORT_TRANSLATION_KEYS.closeButton),
    continueButtonKey: translateService.instant(IMPORT_TRANSLATION_KEYS.continueButton),
    fileInprogressTitleKey: translateService.instant(IMPORT_TRANSLATION_KEYS.fileInprogressTitle),
    importFileSuccessTitleKey: translateService.instant(IMPORT_TRANSLATION_KEYS.fileSuccessTitle),
    chooseAnotherFileKey: translateService.instant(IMPORT_TRANSLATION_KEYS.chooseAnother),
  };
}
