import {
  ChangeDetectionStrategy,
  Component,
  computed,
  inject,
  model,
  output,
  ViewEncapsulation,
} from '@angular/core';
import { BaseComponent } from 'primeng/basecomponent';
import { UBCKPaginatorStyles } from './styles/pagination.style';
import { PaginatorState } from 'primeng/paginator';
import { PaginatorProps, UBCKPaginatorState } from './paginator.types';
import { computePropsFromModel } from './utils/compute-props';
import { reMapPaginatorState } from './utils/re-map-paginator-state';

@Component({
  selector: 'ubck-paginator',
  template: `
    @let data = computedProps();
    @if (data?.showTotalRecords) {
      <span class="ubck-paginator__report">
        {{
          'PAGINATOR.ALL_RECORDS'
            | translate: { count: (data.totalRecords | number) }
        }}
      </span>
    }
    <div class="ubck-paginator__content">
      @if (data.showCurrentPageReport) {
        <span>{{ 'PAGINATOR.SHOW' | translate }}</span>
        <p-select
          [options]="data.rowsPerPageOptions"
          [dropdownIcon]="'pi pi-sort-down-fill'"
          appendTo="body"
          optionValue="value"
          [styleClass]="'ubck-paginator__select'"
          (ngModelChange)="handleRowsPerPageChange(Number($event))"
          [(ngModel)]="data.rows"
        >
          <ng-template let-option #item>
            {{
              option.label || 'PAGINATOR.PAGE'
                | translate: { page: option.value }
            }}
          </ng-template>
          <ng-template let-option #selectedItem>
            {{
              option.label || 'PAGINATOR.PAGE'
                | translate: { page: option.value }
            }}
          </ng-template>
          <ng-template #dropdownicon>
            <svg
              width="20"
              height="20"
              viewBox="0 0 20 20"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                d="M15.8334 7.5L10.0001 12.5L4.16675 7.5"
                stroke="#0F1110"
                stroke-width="1.5"
                stroke-linecap="round"
                stroke-linejoin="round"
              />
            </svg>
          </ng-template>
        </p-select>
      }

      <p-paginator
        [rows]="data.rows"
        [totalRecords]="data.totalRecords"
        [first]="data.first!"
        [showCurrentPageReport]="data.showCurrentPageReport"
        [currentPageReportTemplate]="''"
        [alwaysShow]="data.alwaysShow"
        [showFirstLastIcon]="data.showFirstLastIcon"
        [showPageLinks]="data.showPageLinks"
        [pageLinkSize]="data.pageLinkSize"
        [style]="data.style"
        [styleClass]="data.styleClass"
        [appendTo]="data.appendTo"
        [dropdownAppendTo]="data.dropdownAppendTo"
        [showJumpToPageInput]="data.showJumpToPageInput"
        (onPageChange)="handlePageChange($event)"
      >
        <ng-template let-state #firstpagelinkicon>
          <svg
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M13 19L7 12L13 5"
              stroke="#0F1110"
              stroke-width="1.5"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
            <path
              d="M16.9998 19L10.9998 12L16.9998 5"
              stroke="#0F1110"
              stroke-width="1.5"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </ng-template>
        <ng-template let-state #previouspagelinkicon>
          <svg
            width="20"
            height="20"
            viewBox="0 0 20 20"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M12.5 4.16602L7.5 9.99935L12.5 15.8327"
              stroke="#0F1110"
              stroke-width="1.5"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </ng-template>

        <ng-template let-state #lastpagelinkicon>
          <svg
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M11 19L17 12L11 5"
              stroke="#0F1110"
              stroke-width="1.5"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
            <path
              d="M6.99976 19L12.9998 12L6.99976 5"
              stroke="#0F1110"
              stroke-width="1.5"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </ng-template>
        <ng-template let-state #nextpagelinkicon>
          <svg
            width="20"
            height="20"
            viewBox="0 0 20 20"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M7.5 4.16602L12.5 9.99935L7.5 15.8327"
              stroke="#0F1110"
              stroke-width="1.5"
              stroke-linecap="round"
              stroke-linejoin="round"
            />
          </svg>
        </ng-template>
      </p-paginator>
    </div>
  `,
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class UBCKPaginator extends BaseComponent {
  _componentStyle = inject(UBCKPaginatorStyles);
  Number = Number;

  props = model<PaginatorProps>();
  computedProps = computed(() => computePropsFromModel(this.props()!));

  // Output events
  onPageChange = output<UBCKPaginatorState>();

  handlePageChange(event: PaginatorState): void {
    const value = reMapPaginatorState(event);
    this.props.update(() => ({
      ...this.computedProps(),
      ...value,
    }));
    this.onPageChange.emit(value);
  }

  handleRowsPerPageChange(event: number): void {
    const value = {
      rows: event,
      first: 0,
      currentPage: 1,
      recordPerPage: event,
    };
    this.props.update(() => ({
      ...this.computedProps(),
      ...value,
    }));
    this.onPageChange.emit(value);
  }
}
