/**
 * Card size options
 */
export const CARD_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type CardSize = (typeof CARD_SIZES)[keyof typeof CARD_SIZES];

/**
 * Card style variants
 */
export const CARD_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export type CardVariant = (typeof CARD_VARIANTS)[keyof typeof CARD_VARIANTS];
