import { ChangeDetectionStrategy, Component, input, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ButtonGroupModule } from 'primeng/buttongroup';

@Component({
  selector: 'cmm-buttongroup',
  templateUrl: './cmm-buttongroup.component.html',
  styleUrls: ['./cmm-buttongroup.component.scss'],
  standalone: true,
  imports: [CommonModule, ButtonGroupModule],
  exportAs: 'cmmbuttongroup',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmButtongroupComponent {
  // Signal inputs - Styling
  style = input<{ [klass: string]: any } | null>(null);
  styleClass = input<string>('');

  // Custom variant and size system
  variant = input<'outlined' | 'filled'>('filled');
  customSize = input<'small' | 'default' | 'large'>('default');
  orientation = input<'horizontal' | 'vertical'>('horizontal');

  // Computed style class
  computedStyleClass = computed(() => {
    const classes = [
      'cmm-buttongroup',
      `cmm-buttongroup--${this.variant()}`,
      `cmm-buttongroup--${this.customSize()}`,
      `cmm-buttongroup--${this.orientation()}`,
      this.styleClass(),
    ];
    return classes.filter(Boolean).join(' ');
  });
}
