import { Component, input, output, model, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DrawerModule } from 'primeng/drawer';
import { DrawerPosition } from './cmm-drawer.types';
import { DRAWER_DEFAULTS } from './cmm-drawer.constants';

@Component({
  selector: 'cmm-drawer',
  standalone: true,
  imports: [CommonModule, DrawerModule],
  templateUrl: './cmm-drawer.component.html',
  styleUrl: './cmm-drawer.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmDrawerComponent {
  // Model signal for visible (two-way binding)
  visible = model<boolean>(false);

  // Core props
  header = input<string>();
  position = input<DrawerPosition>(DRAWER_DEFAULTS.POSITION);
  appendTo = input<any>(DRAWER_DEFAULTS.APPEND_TO);
  blockScroll = input<boolean>(DRAWER_DEFAULTS.BLOCK_SCROLL);
  style = input<Record<string, any>>();
  styleClass = input<string>();
  ariaCloseLabel = input<string>();
  autoZIndex = input<boolean>(DRAWER_DEFAULTS.AUTO_Z_INDEX);
  baseZIndex = input<number>(DRAWER_DEFAULTS.BASE_Z_INDEX);
  modal = input<boolean>(DRAWER_DEFAULTS.MODAL);
  closeButtonProps = input<any>();
  dismissible = input<boolean>(DRAWER_DEFAULTS.DISMISSIBLE);
  showCloseIcon = input<boolean>(DRAWER_DEFAULTS.SHOW_CLOSE_ICON);
  closeOnEscape = input<boolean>(DRAWER_DEFAULTS.CLOSE_ON_ESCAPE);
  transitionOptions = input<string>(DRAWER_DEFAULTS.TRANSITION_OPTIONS);
  fullScreen = input<boolean>();
  maskStyle = input<Record<string, any>>();
  closable = input<boolean>(DRAWER_DEFAULTS.CLOSABLE);

  // Output events
  onShow = output<any>();
  onHide = output<any>();

  // Template projections
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  contentTemplate = contentChild<TemplateRef<any>>('content');
  closeiconTemplate = contentChild<TemplateRef<any>>('closeicon');
  headlessTemplate = contentChild<TemplateRef<any>>('headless');

  // Event handlers
  handleShow(event: any): void {
    this.onShow.emit(event);
  }

  handleHide(event: any): void {
    this.onHide.emit(event);
  }
}
