import { Component, input, output, model, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { CarouselModule } from 'primeng/carousel';
import { CarouselOrientation } from './cmm-carousel.types';
import { CAROUSEL_DEFAULTS } from './cmm-carousel.constants';

@Component({
  selector: 'cmm-carousel',
  standalone: true,
  imports: [CommonModule, CarouselModule],
  template: `
    <p-carousel
      [value]="value()"
      [page]="page()"
      [numVisible]="numVisible()"
      [numScroll]="numScroll()"
      [responsiveOptions]="responsiveOptions() ?? undefined"
      [orientation]="orientation()"
      [verticalViewPortHeight]="verticalViewPortHeight()"
      [contentClass]="contentClass()"
      [indicatorsContentClass]="indicatorsContentClass()"
      [indicatorsContentStyle]="indicatorsContentStyle() ?? undefined"
      [indicatorStyleClass]="indicatorStyleClass()"
      [indicatorStyle]="indicatorStyle() ?? undefined"
      [style]="style() ?? undefined"
      [styleClass]="styleClass()"
      [circular]="circular()"
      [autoplayInterval]="autoplayInterval()"
      [showNavigators]="showNavigators()"
      [showIndicators]="showIndicators()"
      [prevButtonProps]="prevButtonProps() ?? undefined"
      [nextButtonProps]="nextButtonProps() ?? undefined"
      (onPage)="onPage.emit($event)">
      @if (itemTemplate()) {
        <ng-template pTemplate="item" let-item>
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
      @if (headerTemplate()) {
        <ng-template pTemplate="header">
          <ng-container *ngTemplateOutlet="headerTemplate()!" />
        </ng-template>
      }
      @if (footerTemplate()) {
        <ng-template pTemplate="footer">
          <ng-container *ngTemplateOutlet="footerTemplate()!" />
        </ng-template>
      }
      @if (previousIconTemplate()) {
        <ng-template pTemplate="previousicon">
          <ng-container *ngTemplateOutlet="previousIconTemplate()!" />
        </ng-template>
      }
      @if (nextIconTemplate()) {
        <ng-template pTemplate="nexticon">
          <ng-container *ngTemplateOutlet="nextIconTemplate()!" />
        </ng-template>
      }
    </p-carousel>
  `,
  styleUrl: './cmm-carousel.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmCarouselComponent {
  // Core props
  value = input<any[]>([]);
  page = model<number>(CAROUSEL_DEFAULTS.PAGE);
  numVisible = input<number>(CAROUSEL_DEFAULTS.NUM_VISIBLE);
  numScroll = input<number>(CAROUSEL_DEFAULTS.NUM_SCROLL);
  responsiveOptions = input<any[]>();
  orientation = input<CarouselOrientation>(CAROUSEL_DEFAULTS.ORIENTATION);
  verticalViewPortHeight = input<string>('300px');

  // Content styling
  contentClass = input<string>('');
  indicatorsContentClass = input<string>('');
  indicatorsContentStyle = input<Record<string, any> | null>(null);
  indicatorStyleClass = input<string>('');
  indicatorStyle = input<Record<string, any> | null>(null);

  // Component styling
  style = input<Record<string, any> | null>(null);
  styleClass = input<string>('');

  // Behavior
  circular = input<boolean>(CAROUSEL_DEFAULTS.CIRCULAR);
  autoplayInterval = input<number>(CAROUSEL_DEFAULTS.AUTOPLAY_INTERVAL);
  showNavigators = input<boolean>(CAROUSEL_DEFAULTS.SHOW_NAVIGATORS);
  showIndicators = input<boolean>(CAROUSEL_DEFAULTS.SHOW_INDICATORS);

  // Button props
  prevButtonProps = input<any>(null);
  nextButtonProps = input<any>(null);

  // Templates
  itemTemplate = contentChild<TemplateRef<any>>('item');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  previousIconTemplate = contentChild<TemplateRef<any>>('previousicon');
  nextIconTemplate = contentChild<TemplateRef<any>>('nexticon');

  // Events
  onPage = output<any>();
}
