import { CommonModule } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  inject,
  input,
  signal,
  TemplateRef,
} from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { TranslatePipe } from '@ngx-translate/core';

import { IamArrowBottomIcon } from '../../icons/arrrow-bottom';
import { IamCloseIcon } from '../../icons/close';
import { IamExcelIcon } from '../../icons/excel';
import { IamLoadingSpinnerIcon } from '../../icons/loading-spinner';
import { DownloadProgress, DownloadState } from '../../modal/download-manager.type';
import { DownloadManagerService } from '../../service/download-manager.service';
import {
  DownloadHeaderActions,
  DownloadHeaderContext,
  DownloadFileIconContext,
  DownloadItemActions,
  DownloadItemContext,
  DownloadItemVm,
  DownloadNotifyClasses,
} from './download-notify.types';

/**
 * Translation keys for the popover. Externalised so labels are i18n-driven and the
 * component stays lib-portable. Keys live under `DOWNLOAD.*` in public/translate/{vi,en}.json.
 */
export const DOWNLOAD_NOTIFY_KEYS = {
  title: 'DOWNLOAD.TITLE',
  subtitle: 'DOWNLOAD.SUBTITLE', // params: { completed, total } — kept for a future multi-slot store
  preparing: 'DOWNLOAD.PREPARING',
  cancel: 'DOWNLOAD.CANCEL',
  retry: 'DOWNLOAD.RETRY',
  pause: 'DOWNLOAD.PAUSE',
  resume: 'DOWNLOAD.RESUME',
  waiting: 'DOWNLOAD.WAITING',
} as const;

/**
 * Centralised palette for the popover. Icon directives take colours as `[props]` strings, so the
 * hex values live here (referenced from the template) — a palette change is now a single edit.
 */
export const DOWNLOAD_NOTIFY_COLORS = {
  ink: '#0F1110', // primary text / header icons
  muted: '#909090', // placeholder / disabled text
  progressTrack: '#D0DDE9',
  progressFill: '#1570EF',
  progressTrackPaused: '#FEECE6',
  progressPaused: '#F79009',
  error: '#DE3730',
  success: '#00894A',
  secondary: '#0F5A43', // pause / resume / retry button text
  divider: '#E4E7EC',
} as const;

@Component({
  selector: 'ubck-download-notify',
  standalone: true,
  imports: [CommonModule, TranslatePipe, IamArrowBottomIcon, IamCloseIcon, IamExcelIcon, IamLoadingSpinnerIcon],
  templateUrl: './download-notify.component.html',
  styleUrl: './download-notify.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DownloadNotifyComponent {
  private readonly downloadManager = inject(DownloadManagerService);

  readonly i18nKeys = DOWNLOAD_NOTIFY_KEYS;
  readonly colors = DOWNLOAD_NOTIFY_COLORS;

  // --- Consumer customization ----------------------------------------------

  /**
   * Max width (px) of the popover. The container sizes to its longest row
   * (`width: max-content`) and is capped here; longer filenames ellipsize + show a tooltip.
   */
  readonly maxWidth = input<number>(500);
  /** Min width (px) of the popover, so short filenames don't collapse it too narrow. */
  readonly minWidth = input<number>(298);

  /** Per-slot Tailwind class overrides; appended onto the component defaults. */
  readonly tailwindClass = input<DownloadNotifyClasses>({});
  /** Convenience accessor so the template can read `cls().container` etc. */
  readonly cls = computed<DownloadNotifyClasses>(() => this.tailwindClass());

  readonly headerTemplate = contentChild<TemplateRef<DownloadHeaderContext>>('headerTemplate');
  readonly itemTemplate = contentChild<TemplateRef<DownloadItemContext>>('itemTemplate');
  /** Replaces only the file icon in the default item template. */
  readonly fileIconTemplate = contentChild<TemplateRef<DownloadFileIconContext>>('fileIconTemplate');

  // --- Service-backed state -------------------------------------------------

  /** Bridge the service slot to a signal for OnPush-friendly template reads. */
  private readonly active = toSignal(this.downloadManager.activeDownload$, { initialValue: [] });

  /**
   * Single → list bridge: feeds the multi-download `@for` from the single slot.
   * Length 0 (nothing active) or 1 (one active download).
   */
  readonly downloads = computed<DownloadProgress[]>(() => this.active() || []);

  /** Template-ready view-models — all per-row logic resolved once, here. */
  readonly items = computed<DownloadItemVm[]>(() => this.downloads().map((d) => this.toVm(d)));

  // --- UI-local state -------------------------------------------------------

  /** UC-06: expanded vs minimized (mini bar). */
  readonly isExpanded = signal(true);
  /** UC-08: whether the popover is shown. Hiding it must NOT abort the download. */
  readonly isVisible = this.downloadManager.isVisible;

  // --- Header counters (for the minimized subtitle) -------------------------

  readonly completedCount = computed(() => this.items().filter((vm) => vm.isCompleted).length);
  readonly totalCount = computed(() => this.items().length);

  /** `$implicit` + actions bundle for the header template. */
  readonly headerContext = computed<DownloadHeaderContext>(() => ({
    $implicit: {
      isExpanded: this.isExpanded(),
      completedCount: this.completedCount(),
      totalCount: this.totalCount(),
    },
    actions: this.headerActions,
  }));

  readonly itemActions: DownloadItemActions = {
    cancel: (id) => this.downloadManager.cancel(id),
    pause: (id) => this.downloadManager.pause(id),
    resume: (id) => this.downloadManager.resume(id),
    retry: (id) => this.downloadManager.retry(id),
  };

  readonly headerActions: DownloadHeaderActions = {
    toggleExpand: () => this.toggleExpand(),
    close: () => this.closePanel(),
  };

  // --- Header actions -------------------------------------------------------

  toggleExpand(): void {
    this.isExpanded.update((v) => !v);
  }

  /** Manual close only hides the popover — the download keeps running in the service. */
  closePanel(): void {
    this.isVisible.set(false);
  }

  /** Collapse one {@link DownloadProgress} into the flat {@link DownloadItemVm} the template reads. */
  private toVm(d: DownloadProgress): DownloadItemVm {
    const isPreparing = d.state === DownloadState.Waiting;
    const isCompleted = d.state === DownloadState.Completed;
    const isError = d.state === DownloadState.Error;
    const hasPercent = d.percent !== undefined;
    const percent = d.percent ?? 0;

    return {
      id: d.id,
      ...this.resolveFileName(d),
      isDownloading: d.state === DownloadState.Downloading,
      isPaused: d.state === DownloadState.Paused,
      isPreparing,
      isCompleted,
      isError,
      // Excel icon shows once we leave Waiting, or as soon as the blob has arrived.
      showExcelIcon: d.state !== DownloadState.Waiting || d._blob !== undefined,
      // Progress/error row hidden when completed; hidden while preparing unless erroring.
      showProgressRow: !isCompleted && (!isPreparing || isError),
      showError: isError,
      errorMsg: d.errorMsg ?? '',
      // Actions hidden when completed or still preparing.
      showActions: !(isCompleted || isPreparing),
      hasPercent,
      percent,
      showBytes: (!isError && hasPercent && percent > 0) || isCompleted,
      loadedLabel: this.formatBytes(d.loadedBytes),
      totalLabel: this.formatBytes(d.totalBytes),
    };
  }

  /**
   * Resolve what the filename row shows. Returns a translation *key* (resolved in the template via
   * `| translate`, so it reacts to language switches) for the waiting/preparing phases, otherwise
   * the literal filename:
   * - "Đang chờ tải…" while the API is in flight,
   * - "Đang chuẩn bị…" until the real filename is resolved,
   * - then the actual filename.
   */
  private resolveFileName(d: DownloadProgress): Pick<DownloadItemVm, 'fileName' | 'fileNameKey'> {
    if (d.state === DownloadState.Waiting && d._blob === undefined) {
      return { fileName: null, fileNameKey: this.i18nKeys.waiting };
    }
    if (!d.fileName) {
      return { fileName: null, fileNameKey: this.i18nKeys.preparing };
    }
    return { fileName: d.fileName, fileNameKey: null };
  }

  /** Bytes → human-readable (e.g. "30.3 KB"). */
  private formatBytes(bytes: number | undefined, decimals = 1): string {
    if (!bytes) {
      return '0 KB';
    }
    const k = 1024;
    const dm = Math.max(decimals, 0);
    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return `${Number.parseFloat((bytes / k ** i).toFixed(dm))} ${sizes[i]}`;
  }
}
