import {
  ChangeDetectionStrategy,
  Component,
  input,
  output,
  computed,
  contentChild,
  TemplateRef,
  viewChild,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  FileUpload,
  FileBeforeUploadEvent,
  FileSendEvent,
  FileUploadEvent,
  FileUploadErrorEvent,
  FileRemoveEvent,
  FileSelectEvent,
  FileProgressEvent,
  FileUploadHandlerEvent,
  RemoveUploadedFileEvent,
} from 'primeng/fileupload';
import { HttpHeaders } from '@angular/common/http';
import { FILEUPLOAD_DEFAULTS, FileUploadMethod, FileUploadMode } from './file-upload.const';

@Component({
  selector: 'cmm-fileUpload',
  templateUrl: './cmm-file-upload.component.html',
  styleUrls: ['./cmm-file-upload.component.scss'],
  standalone: true,
  imports: [CommonModule, FileUpload],
  exportAs: 'cmmfileupload',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmFileUploadComponent {
  // Signal inputs - FileUpload properties
  name = input<string>();
  url = input<string>();
  method = input<FileUploadMethod>(FILEUPLOAD_DEFAULTS.METHOD);
  multiple = input<boolean>(FILEUPLOAD_DEFAULTS.MULTIPLE);
  accept = input<string>();
  disabled = input<boolean>(FILEUPLOAD_DEFAULTS.DISABLED);
  auto = input<boolean>(FILEUPLOAD_DEFAULTS.AUTO);
  maxFileSize = input<number | null>(null);
  fileLimit = input<number>();

  style = input<Record<string, any>>();
  styleClass = input<string>();
  previewWidth = input<number>(FILEUPLOAD_DEFAULTS.PREVIEW_WIDTH);
  chooseLabel = input<string>();
  uploadLabel = input<string>();
  cancelLabel = input<string>();
  chooseIcon = input<string>();
  uploadIcon = input<string>();
  cancelIcon = input<string>();
  showUploadButton = input<boolean>(FILEUPLOAD_DEFAULTS.SHOW_UPLOAD_BUTTON);
  showCancelButton = input<boolean>(FILEUPLOAD_DEFAULTS.SHOW_CANCEL_BUTTON);
  mode = input<FileUploadMode>(FILEUPLOAD_DEFAULTS.MODE);
  headers = input<HttpHeaders>();
  customUpload = input<boolean>(FILEUPLOAD_DEFAULTS.CUSTOM_UPLOAD);
  withCredentials = input<boolean>(FILEUPLOAD_DEFAULTS.WITH_CREDENTIALS);
  invalidFileSizeMessageSummary = input<string>('{0}: Invalid file size, ');
  invalidFileSizeMessageDetail = input<string>('maximum upload size is {0}.');
  invalidFileTypeMessageSummary = input<string>('{0}: Invalid file type, ');
  invalidFileTypeMessageDetail = input<string>('allowed file types: {0}.');
  invalidFileLimitMessageDetail = input<string>('limit is {0} at most.');
  invalidFileLimitMessageSummary = input<string>('Maximum number of files exceeded, ');
  uploadStyleClass = input<string>('');
  cancelStyleClass = input<string>('');
  removeStyleClass = input<string>('');
  chooseStyleClass = input<string>('');

  // Custom variant and size system
  variant = input<'outlined' | 'filled'>('outlined');
  customSize = input<'small' | 'default' | 'large'>('default');

  // Signal outputs
  onBeforeUpload = output<FileBeforeUploadEvent>();
  onSend = output<FileSendEvent>();
  onUpload = output<FileUploadEvent>();
  onError = output<FileUploadErrorEvent>();
  onClear = output<Event>();
  onRemove = output<FileRemoveEvent>();
  onSelect = output<FileSelectEvent>();
  onProgress = output<FileProgressEvent>();
  uploadHandler = output<FileUploadHandlerEvent>();
  onImageError = output<Event>();
  onRemoveUploadedFile = output<RemoveUploadedFileEvent>();

  // Template projections
  fileTemplate = contentChild<TemplateRef<unknown>>('file');
  headerTemplate = contentChild<TemplateRef<unknown>>('header');
  contentTemplate = contentChild<TemplateRef<unknown>>('content');
  toolbarTemplate = contentChild<TemplateRef<unknown>>('toolbar');
  chooseIconTemplate = contentChild<TemplateRef<unknown>>('chooseicon');
  fileLabelTemplate = contentChild<TemplateRef<unknown>>('filelabel');
  uploadIconTemplate = contentChild<TemplateRef<unknown>>('uploadicon');
  cancelIconTemplate = contentChild<TemplateRef<unknown>>('cancelicon');
  emptyTemplate = contentChild<TemplateRef<unknown>>('empty');

  // ViewChild reference to PrimeNG FileUpload
  fileUploadRef = viewChild<FileUpload>('fileUploadRef');

  // Computed style class
  computedStyleClass = computed(() => {
    const classes = [
      'cmm-file-upload',
      `cmm-file-upload--${this.variant()}`,
      `cmm-file-upload--${this.customSize()}`,
      this.styleClass(),
    ];
    return classes.filter(Boolean).join(' ');
  });

  // Event handlers
  handleBeforeUpload(event: FileBeforeUploadEvent): void {
    this.onBeforeUpload.emit(event);
  }

  handleSend(event: FileSendEvent): void {
    this.onSend.emit(event);
  }

  handleUpload(event: FileUploadEvent): void {
    this.onUpload.emit(event);
  }

  handleError(event: FileUploadErrorEvent): void {
    this.onError.emit(event);
  }

  handleClear(event: Event): void {
    this.onClear.emit(event);
  }

  handleRemove(event: FileRemoveEvent): void {
    this.onRemove.emit(event);
  }

  handleSelect(event: FileSelectEvent): void {
    this.onSelect.emit(event);
  }

  handleProgress(event: FileProgressEvent): void {
    this.onProgress.emit(event);
  }

  handleUploadHandler(event: FileUploadHandlerEvent): void {
    this.uploadHandler.emit(event);
  }

  handleImageError(event: Event): void {
    this.onImageError.emit(event);
  }

  handleRemoveUploadedFile(event: RemoveUploadedFileEvent): void {
    this.onRemoveUploadedFile.emit(event);
  }

  // Public methods to access FileUpload instance
  upload(): void {
    this.fileUploadRef()?.upload();
  }

  clear(): void {
    this.fileUploadRef()?.clear();
  }

  remove(event: Event, index: number): void {
    this.fileUploadRef()?.remove(event, index);
  }

  getFiles(): File[] {
    return this.fileUploadRef()?.files || [];
  }
}
