import { Component, ChangeDetectionStrategy, input, output } from '@angular/core';
import { Splitter } from 'primeng/splitter';

export interface SplitterResizeStartEvent {
  originalEvent: MouseEvent | TouchEvent;
  sizes: number[];
}

export interface SplitterResizeEndEvent {
  originalEvent: MouseEvent | TouchEvent;
  sizes: number[];
}

@Component({
  selector: 'cmm-splitter',
  standalone: true,
  imports: [Splitter],
  templateUrl: './cmm-splitter.component.html',
  styleUrl: './cmm-splitter.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmSplitterComponent {
  styleClass = input<string>('');
  panelStyleClass = input<string>('');
  style = input<Record<string, any>>();
  panelStyle = input<Record<string, any>>();
  stateStorage = input<'session' | 'local'>('session');
  stateKey = input<string>();
  layout = input<'horizontal' | 'vertical'>('horizontal');
  gutterSize = input<number>(4);
  step = input<number>(5);
  minSizes = input<number[]>([]);
  panelSizes = input<number[]>([]);

  onResizeEnd = output<any>();
  onResizeStart = output<any>();
}
