import { Component, ChangeDetectionStrategy, input, output, model, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TreeSelectModule } from 'primeng/treeselect';
import type { TreeNode, ScrollerOptions, OverlayOptions } from 'primeng/api';

export interface TreeSelectNodeExpandEvent {
  originalEvent: Event;
  node: TreeNode;
}

export interface TreeSelectNodeCollapseEvent {
  originalEvent: Event;
  node: TreeNode;
}

export interface TreeNodeSelectEvent {
  originalEvent: Event;
  node: TreeNode;
}

export interface TreeNodeUnSelectEvent {
  originalEvent: Event;
  node: TreeNode;
}

export interface TreeFilterEvent {
  filter: string;
  filteredValue?: TreeNode[] | null;
}

@Component({
  selector: 'cmm-treeselect',
  standalone: true,
  imports: [CommonModule, FormsModule, TreeSelectModule],
  templateUrl: './cmm-treeselect.component.html',
  styleUrl: './cmm-treeselect.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmTreeSelectComponent {
  value = model<any>();

  inputId = input<string>();
  scrollHeight = input<string>('400px');
  disabled = input<boolean>(false);
  metaKeySelection = input<boolean>(false);
  variant = input<'outlined' | 'filled'>('outlined');
  display = input<'chip' | 'comma'>('comma');
  selectionMode = input<'single' | 'multiple' | 'checkbox'>('single');
  tabindex = input<string>('0');
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();
  placeholder = input<string>();
  panelClass = input<string | string[] | Set<string> | Record<string, any>>();
  panelStyle = input<Record<string, any>>();
  fluid = input<boolean>(false);
  panelStyleClass = input<string>();
  containerStyle = input<Record<string, any>>();
  containerStyleClass = input<string>();
  labelStyle = input<Record<string, any>>();
  labelStyleClass = input<string>();
  overlayOptions = input<OverlayOptions>();
  emptyMessage = input<string>('');
  appendTo = input<unknown>('body');
  filter = input<boolean>(false);
  filterBy = input<string>('label');
  filterMode = input<string>('lenient');
  filterPlaceholder = input<string>();
  filterLocale = input<string>();
  filterInputAutoFocus = input<boolean>(true);
  propagateSelectionDown = input<boolean>(true);
  propagateSelectionUp = input<boolean>(true);
  showClear = input<boolean>(false);
  resetFilterOnHide = input<boolean>(true);
  virtualScroll = input<boolean>(false);
  virtualScrollItemSize = input<number>();
  size = input<'small' | 'large'>();
  virtualScrollOptions = input<ScrollerOptions>();
  autofocus = input<boolean>(false);
  options = input<TreeNode[]>([]);
  showTransitionOptions = input<string>();
  hideTransitionOptions = input<string>();
  loading = input<boolean>(false);

  onNodeExpand = output<TreeSelectNodeExpandEvent>();
  onNodeCollapse = output<TreeSelectNodeCollapseEvent>();
  onShow = output<any>();
  onHide = output<Event>();
  onClear = output<any>();
  onFilter = output<TreeFilterEvent>();
  onFocus = output<Event>();
  onBlur = output<Event>();
  onNodeUnselect = output<TreeNodeUnSelectEvent>();
  onNodeSelect = output<TreeNodeSelectEvent>();

  valueTemplate = contentChild<TemplateRef<any>>('value');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  emptyTemplate = contentChild<TemplateRef<any>>('empty');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  clearIconTemplate = contentChild<TemplateRef<any>>('clearicon');
  triggerIconTemplate = contentChild<TemplateRef<any>>('triggericon');
  dropdownIconTemplate = contentChild<TemplateRef<any>>('dropdownicon');
  filterIconTemplate = contentChild<TemplateRef<any>>('filtericon');
  closeIconTemplate = contentChild<TemplateRef<any>>('closeicon');
  itemTogglerIconTemplate = contentChild<TemplateRef<any>>('itemtogglericon');
  itemCheckboxIconTemplate = contentChild<TemplateRef<any>>('itemcheckboxicon');
  itemLoadingIconTemplate = contentChild<TemplateRef<any>>('itemloadingicon');
}
