import { ChangeDetectionStrategy, Component, inject, input, output } from '@angular/core';
import { IDialogHeader } from '../dialog.model';
import { CloseIconComponent } from '../../base/Atoms/icons/close.component';
import { NgClass } from '@angular/common';
import { DynamicDialogRef } from 'primeng/dynamicdialog';
import { TranslatePipe } from '@ngx-translate/core';
import { CmmTypepographyModule } from '../../typography/public-api';

@Component({
  selector: 'cmm-dialog-header',
  imports: [CloseIconComponent, TranslatePipe, NgClass, CmmTypepographyModule],
  templateUrl: './dialog-header.component.html',
  styleUrl: './dialog-header.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DialogHeaderComponent {
  meta = input.required<IDialogHeader>();
  eventClose = output<MouseEvent | undefined>();
  dialogRef = inject(DynamicDialogRef);
  handleClose() {
    this.meta().closeHandler(this.dialogRef);
  }
}
