import { ChangeDetectionStrategy, Component, input, output, computed, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ButtonModule } from 'primeng/button';

@Component({
  selector: 'cmm-button',
  templateUrl: './cmm-button.component.html',
  styleUrls: ['./cmm-button.component.scss'],
  standalone: true,
  imports: [CommonModule, ButtonModule],
  exportAs: 'cmmbutton',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmButtonComponent {
  // Signal inputs - Button properties (supported by pButton directive)
  label = input<string>('');
  icon = input<string>('');
  iconPos = input<'left' | 'right' | 'top' | 'bottom'>('left');
  badge = input<string>('');
  loading = input<boolean>(false);
  loadingIcon = input<string>('');
  severity = input<'success' | 'info' | 'danger' | 'help' | 'primary' | 'secondary' | 'contrast' | 'warn' | null>(null);
  raised = input<boolean>(false);
  rounded = input<boolean>(false);
  text = input<boolean>(false);
  outlined = input<boolean>(false);
  link = input<boolean>(false);
  size = input<'small' | 'large' | undefined>(undefined);
  plain = input<boolean>(false);
  variant = input<'text' | 'outlined' | undefined>(undefined);
  fluid = input<boolean>(false);
  autofocus = input<boolean>(false);
  tabindex = input<number | undefined>(undefined);
  badgeClass = input<string>('');
  badgeSeverity = input<'success' | 'info' | 'danger' | 'help' | 'primary' | 'secondary' | 'contrast' | 'warn'>(
    'secondary',
  );
  buttonProps = input<any>(undefined);

  // Signal inputs - HTML button attributes
  type = input<'button' | 'submit' | 'reset'>('button');
  disabled = input<boolean>(false);
  ariaLabel = input<string>('');

  // Signal inputs - Styling
  style = input<{ [klass: string]: any } | null>(null);
  styleClass = input<string>('');

  // Custom enhancements
  customVariant = input<'outlined' | 'filled'>('filled');
  customSize = input<'small' | 'default' | 'large'>('default');

  // Signal outputs
  onClick = output<Event>();
  onFocus = output<Event>();
  onBlur = output<Event>();

  // Template projections
  contentTemplate = contentChild<TemplateRef<any>>('content');
  loadingIconTemplate = contentChild<TemplateRef<any>>('loadingicon');
  iconTemplate = contentChild<TemplateRef<any>>('icon');

  // Computed style class
  computedStyleClass = computed(() => {
    const classes = [
      'cmm-button-directive',
      `cmm-button-directive--${this.customVariant()}`,
      `cmm-button-directive--${this.customSize()}`,
      this.styleClass(),
    ];
    return classes.filter(Boolean).join(' ');
  });

  // Event handlers
  handleClick(event: Event): void {
    if (!this.disabled()) {
      this.onClick.emit(event);
    }
  }

  handleFocus(event: Event): void {
    this.onFocus.emit(event);
  }

  handleBlur(event: Event): void {
    this.onBlur.emit(event);
  }
}
