import { Directive, input, output, HostBinding } from '@angular/core';
import { Textarea } from 'primeng/textarea';
import { TextareaVariant, TextareaSize } from './cmm-textarea.types';
import { TEXTAREA_DEFAULTS } from './cmm-textarea.constants';

@Directive({
  selector: 'textarea[cmmTextarea]',
  standalone: true,
  hostDirectives: [
    {
      directive: Textarea,
      inputs: ['autoResize', 'variant', 'fluid'],
      outputs: ['onResize'],
    },
  ],
})
export class CmmTextareaDirective {
  autoResize = input<boolean>(TEXTAREA_DEFAULTS.AUTO_RESIZE);
  variant = input<TextareaVariant>(TEXTAREA_DEFAULTS.VARIANT);
  fluid = input<boolean>(TEXTAREA_DEFAULTS.FLUID);
  size = input<TextareaSize>();

  onResize = output<Event>();

  @HostBinding('class.p-textarea')
  get textareaClass() {
    return true;
  }
}
