import {
  Component,
  inject,
  input,
  effect,
  OnDestroy, Signal,
  signal,
  viewChild,
  HostListener,
} from '@angular/core';

import { CmmDynamicFormFacade } from './dynamic-form.facade';
import { DEFAULT_MAX_LENGTH_TEXT, DynamicFieldTypes, DynamicFormItem } from './dynamic-form.types';
import {FormGroup} from '@angular/forms';
import { Popover } from 'primeng/popover';
import { CommonModule } from '@angular/common';
@Component({
  selector: 'cmm-dynamic-form',
  templateUrl: './dynamic-form.component.html',
  styleUrls: ['./dynamic-form.component.scss'],
  standalone: false,
  providers: [CmmDynamicFormFacade]
})
export class CmmDynamicFormComponent implements  OnDestroy {
  public readonly facade = inject(CmmDynamicFormFacade);
  public readonly id = signal(`dynamic-form-${Math.random().toString(36).substring(2, 9)}`);

  op = viewChild(Popover)

  DynamicFieldTypes = DynamicFieldTypes;
  DEFAULT_MAX_LENGTH_TEXT = DEFAULT_MAX_LENGTH_TEXT;

  /* ================================
   * INPUT (SIGNAL)
   * ================================ */

  readonly config = input<DynamicFormItem[]>([]);

  /* ================================
   * EXPOSE TO TEMPLATE
   * ================================ */

  readonly items = this.facade.items;
  readonly form: Signal<FormGroup> = this.facade.form;

  readonly isVisible = this.facade.isVisible.bind(this.facade);
  readonly isDisabled = this.facade.isDisabled.bind(this.facade);
  readonly isGroupVisible = this.facade.isGroupVisible.bind(this.facade);

  /* ================================
   * INIT EFFECT
   * ================================ */

  constructor() {
    effect(() => {
      const cfg = this.config();
      if (cfg?.length) {
        this.facade.init(cfg);
      }
    });

    // Effect to trigger validator updates when form values change
    effect(() => {
      const form = this.facade.form();
      if (form && Object.keys(form.controls).length > 0) {
        // Access form.value to create dependency on form changes
        form.value;
        // Trigger validator update using the exposed method
        this.facade.triggerValidatorUpdate();
      }
    });
  }

  handleBlur(event: FocusEvent) {
    const target = event.target as HTMLInputElement;
    target.scrollLeft = 0;
  }

  handleClickHint(item: DynamicFormItem) {
    this.facade.setHint(item.hint || '');
  }

  handleClearField(item: DynamicFormItem): void {
    const control = this.facade.getControl(item);
    if (!control) return;
    control.setValue('');
    control.markAsDirty();
    control.markAsTouched();
  }

  // hasExplicitOnClickOutside(item: DynamicFormItem): boolean {
  //   console.log({
  //     "item.props": item.props,
  //     "item.props['onClickOutside']": item.props['onClickOutside']
  //   })
  //   return item.props['onClickOutside'];
  // }


  ngOnDestroy(): void {
    this.facade.destroy();
  }
}
