import { 
  ComponentRef, 
  ViewContainerRef, 
  Renderer2, 
  createComponent, 
  EnvironmentInjector,
  ApplicationRef 
} from '@angular/core';
import { ValidationErrorComponent } from '../validation-error.component';

/**
 * Error Renderer Helper
 * Single Responsibility: Create and manage validation error components
 */
export class ErrorRendererHelper {
  /**
   * Create error component at custom target element
   */
  static createErrorComponent(
    renderer: Renderer2,
    targetElement: HTMLElement,
    environmentInjector: EnvironmentInjector,
    appRef: ApplicationRef,
    message: string,
    showIcon: boolean,
    position: 'bottom' | 'top' = 'bottom'
  ): ComponentRef<ValidationErrorComponent> {
    // Create component using standalone API
    const componentRef = createComponent(ValidationErrorComponent, {
      environmentInjector,
      hostElement: undefined
    });

    // Set inputs
    componentRef.setInput('message', message);
    componentRef.setInput('showIcon', showIcon);

    // Attach to application for change detection
    appRef.attachView(componentRef.hostView);

    // Get the native element from component
    const errorElement = componentRef.location.nativeElement;

    // Insert into target element at specified position
    if (position === 'top') {
      renderer.insertBefore(targetElement, errorElement, targetElement.firstChild);
    } else {
      renderer.appendChild(targetElement, errorElement);
    }

    return componentRef;
  }

  /**
   * Update error message in existing component
   */
  static updateErrorMessage(
    componentRef: ComponentRef<ValidationErrorComponent>,
    message: string
  ): void {
    componentRef.setInput('message', message);
    componentRef.changeDetectorRef.detectChanges();
  }

  /**
   * Remove error component
   */
  static removeErrorComponent(
    renderer: Renderer2,
    componentRef: ComponentRef<ValidationErrorComponent> | undefined,
    appRef: ApplicationRef
  ): void {
    if (!componentRef) return;

    // Detach from application
    appRef.detachView(componentRef.hostView);

    // Destroy component
    componentRef.destroy();
  }
}
