import { Component, input, ChangeDetectionStrategy } from '@angular/core';

import { FloatLabelModule } from 'primeng/floatlabel';
import { FloatLabelVariant } from './cmm-floatlabel.types';
import { FLOATLABEL_DEFAULTS } from './cmm-floatlabel.constants';

@Component({
  selector: 'cmm-floatlabel',
  standalone: true,
  imports: [FloatLabelModule],
  template: `
    <p-floatLabel [variant]="variant()">
      <ng-content />
    </p-floatLabel>
  `,
  styleUrl: './cmm-floatlabel.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmFloatlabelComponent {
  // Input properties
  readonly variant = input<FloatLabelVariant>(FLOATLABEL_DEFAULTS.VARIANT);
}
