import {
  FormGroup,
  FormControl,
  FormArray,
  ValidatorFn,
  AsyncValidatorFn,
} from '@angular/forms';

import { CmmDynamicFormBuilder, DynamicFieldTypes, DynamicFormItem } from './dynamic-form.types';
import { Injectable } from '@angular/core';

export interface VisibilityContext {
  isVisible: (item: DynamicFormItem) => boolean;
}

@Injectable()
export class CmmDynamicFormBuilderImpl implements CmmDynamicFormBuilder {
  build(items: DynamicFormItem[], visibilityContext?: VisibilityContext): FormGroup {
    const controls = this.buildControls(items, visibilityContext);
    const { validators, asyncValidators } = this.getValidatorsForGroup(items, visibilityContext);
    return new FormGroup(controls, {
      validators: validators.length ? validators : null,
      asyncValidators: asyncValidators.length ? asyncValidators : null,
    });
  }

  private getValidatorsForGroup(items: DynamicFormItem[], visibilityContext?: VisibilityContext): {
    validators: ValidatorFn[];
    asyncValidators: AsyncValidatorFn[];
  } {
    const validators = items
      .filter((f) => {
        // Only include validators for visible items
        const isVisible = visibilityContext?.isVisible(f) ?? true;
        return isVisible && (f.validatorsGroup || f.asyncValidatorsGroup);
      })
      .map((item) => this.filerByGroupValidators(item))
      .reduce<{
        validators: ValidatorFn[];
        asyncValidators: AsyncValidatorFn[];
      }>(
        (acc, curr) => {
          if (curr.validators) {
            acc.validators.push(...curr.validators);
          }
          if (curr.asyncValidators) {
            acc.asyncValidators.push(...curr.asyncValidators);
          }
          return acc;
        },
        { validators: [], asyncValidators: [] }
      );
    return validators;
  }
  
  private filerByGroupValidators(item: DynamicFormItem): {
    validators: ValidatorFn[] | null;
    asyncValidators: AsyncValidatorFn[] | null;
  } {
    const validators = item.validatorsGroup ?? null;
    const asyncValidators = item.asyncValidatorsGroup ?? null;
    return { validators, asyncValidators };
  }

  /* ============================
   * INTERNAL
   * ============================ */
  private buildControls(items: DynamicFormItem[], visibilityContext?: VisibilityContext): Record<string, any> {
    return items.reduce<Record<string, any>>((acc, item) => {
      // layout-only item
      if (!(item.key || item.children?.length)) {
        return acc;
      }

      if (item.children?.length) {
        acc[item.key] = this.buildGroup(item, visibilityContext);
      } else if (item.key) {
        acc[item.key] = this.buildControl(item, visibilityContext);
      }

      return acc;
    }, {});
  }

  private buildControl(item: DynamicFormItem, visibilityContext?: VisibilityContext): FormControl {
    // Check if field is visible before setting validators
    const isVisible = visibilityContext?.isVisible(item) ?? true;
    
    /**
     * Use pseudo readonly mode to show tooltip on selection since disabled mode will prevent showing tooltip (https://github.com/primefaces/primeng/issues/13797)
     */ 
    if (
      item.type === DynamicFieldTypes.SELECT && 
      item.props.showTooltipWhenDisabled &&
      item.disabled
    ) {
      console.warn(`[Dynamic Form warn]: showTooltipWhenDisabled will not work with disabled field. Please set disable to false for key:`, item.key);
    }

    const control = new FormControl(
      { value: item.value ?? null, disabled: item.disabled },
      {
        validators: isVisible ? item.validators : null,
        asyncValidators: isVisible ? item.asyncValidators : null,
      }
    );

    return control;
  }

  private buildGroup(item: DynamicFormItem, visibilityContext?: VisibilityContext): FormGroup | FormArray {
    // Simple rule: if children have numeric keys → array
    const isArray = item.children?.every(
      (c) => typeof c.key === 'number' || !isNaN(Number(c.key))
    );

    if (isArray) {
      return new FormArray(
        item.children!.map((child) => this.buildControl(child, visibilityContext))
      );
    }

    return new FormGroup(this.buildControls(item.children!, visibilityContext));
  }
}
