import {afterNextRender, DestroyRef, ElementRef, inject, Injector, signal, WritableSignal} from "@angular/core";
import { NgControl } from "@angular/forms";
import {Subscription} from 'rxjs';

export function useElementWidth(
    elementRefFn: () => ElementRef<HTMLElement> | undefined,
    onResize?: (width: number) => void,
): WritableSignal<number> {
    const width = signal<number>(0);
    const destroyRef = inject(DestroyRef);
    let resizeObserver: ResizeObserver | undefined;
    let isDestroyed = false;

    destroyRef.onDestroy(() => {
      isDestroyed = true;
      resizeObserver?.disconnect();
    })

    afterNextRender({
        read: () => {
          if (isDestroyed) {
            // Prevent early destroyed component causing memory leak in afterNextRender
            return;
          }
            const elementRef = elementRefFn();
            if (!elementRef) {
                return;
            }
            const initialWidth = Math.round(elementRef.nativeElement.clientWidth);
            width.set(initialWidth);

            if (onResize) {
                onResize(initialWidth);
            }

            // Setup Obs for subsequent resizes
            if (typeof ResizeObserver !== 'undefined') {
                resizeObserver = new ResizeObserver((entries) => {
                    const entry = entries[0]
                    if (entry) {
                        const newWidth = Math.round(entry.contentRect.width);
                        if (newWidth !== width()) {
                            width.set(newWidth);

                            if (onResize) {
                                onResize(newWidth);
                            }
                        }
                    }
                })

                resizeObserver.observe(elementRef.nativeElement);
            }
        }
    })

    return width;
}

// Handle grabbing NgControl dynamically using Injector
export function useFormControlReset(onReset: (value: any) => void) {
  const injector = inject(Injector);
  const destroyRef = inject(DestroyRef);
  let subscription: Subscription | undefined;

  destroyRef.onDestroy(() => {
    subscription?.unsubscribe();
  })

  // Schedule control lookup after instantiation completes to prevent circular dependency (NG0200)
  queueMicrotask(() => {
    const ngControl = injector.get(NgControl, null);
    if (ngControl && ngControl.control) {
      subscription = ngControl.control.statusChanges?.subscribe(() => {
        if (ngControl.control?.pristine && ngControl.control?.untouched) {
          const value = ngControl.control.value;
          onReset(value);
        }
      });
    }
  });
}
