import { UBCK_PAGINATOR_DEFAULTS } from "../paginator.const";
import { PaginatorProps } from "../paginator.types";



export function computePropsFromModel(props: PaginatorProps): PaginatorProps {
    const p = props;
    const rows = p.recordPerPage || UBCK_PAGINATOR_DEFAULTS.ROWS;
    const currentPage = p.currentPage ?? UBCK_PAGINATOR_DEFAULTS.FIRST;
    // Calculate first from currentPage if currentPage is provided, otherwise use first
    const first = p.currentPage !== undefined ? (currentPage - 1) * rows : (p.first ?? UBCK_PAGINATOR_DEFAULTS.FIRST);
    
    return {
        ...p,
        first,
        rows,
        recordPerPage: rows,
        alwaysShow: p.alwaysShow ?? UBCK_PAGINATOR_DEFAULTS.ALWAYS_SHOW,
        showCurrentPageReport: p.showCurrentPageReport ?? UBCK_PAGINATOR_DEFAULTS.SHOW_CURRENT_PAGE_REPORT,
        showFirstLastIcon: p.showFirstLastIcon ?? UBCK_PAGINATOR_DEFAULTS.SHOW_FIRST_LAST_ICON,
        showPageLinks: p.showPageLinks ?? UBCK_PAGINATOR_DEFAULTS.SHOW_PAGE_LINKS,
        currentPage,
        appendTo: p.appendTo ?? UBCK_PAGINATOR_DEFAULTS.APPEND_TO,
        dropdownAppendTo: p.dropdownAppendTo ?? UBCK_PAGINATOR_DEFAULTS.DROPDOWN_APPEND_TO,
        showJumpToPageInput: p.showJumpToPageInput ?? UBCK_PAGINATOR_DEFAULTS.SHOW_JUMP_TO_PAGE_INPUT,
        pageLinkSize: p.pageLinkSize ?? UBCK_PAGINATOR_DEFAULTS.PAGE_LINK_SIZE,
        showTotalRecords: p.showTotalRecords ?? UBCK_PAGINATOR_DEFAULTS.SHOW_TOTAL_RECORDS,
        rowsPerPageOptions: p.rowsPerPageOptions ?? UBCK_PAGINATOR_DEFAULTS.ROWS_PER_PAGE_OPTIONS,
    };    

}