import { Component, input, ChangeDetectionStrategy } from '@angular/core';

import { InputGroupModule } from 'primeng/inputgroup';

@Component({
  selector: 'cmm-inputgroup',
  standalone: true,
  imports: [InputGroupModule],
  template: `
    <p-inputGroup [style]="style() ?? undefined" [styleClass]="styleClass() || ''">
      <ng-content />
    </p-inputGroup>
  `,
  styleUrl: './cmm-inputgroup.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmInputgroupComponent {
  // Input properties
  readonly style = input<Record<string, any>>();
  readonly styleClass = input<string>();
}
