/**
 * Custom events for PickList component
 */

export interface PickListMoveToSourceEvent {
  /** Moved items */
  items: any[];
}

export interface PickListMoveAllToSourceEvent {
  /** Moved items */
  items: any[];
}

export interface PickListMoveAllToTargetEvent {
  /** Moved items */
  items: any[];
}

export interface PickListMoveToTargetEvent {
  /** Moved items */
  items: any[];
}

export interface PickListSourceReorderEvent {
  /** Moved items */
  items: any[];
}

export interface PickListTargetReorderEvent {
  /** Moved items */
  items: any[];
}

export interface PickListSourceSelectEvent {
  /** Browser event */
  originalEvent: Event;
  /** Selected items */
  items: any[];
}

export interface PickListTargetSelectEvent {
  /** Browser event */
  originalEvent: Event;
  /** Selected items */
  items: any[];
}

export interface PickListSourceFilterEvent {
  /** Filter value */
  query: string | null | undefined;
  /** Filtered items */
  value: any[] | null | undefined;
}

export interface PickListTargetFilterEvent {
  /** Filter value */
  query: string | null | undefined;
  /** Filtered items */
  value: any[] | null | undefined;
}

/**
 * Filter options for PickList component
 */
export interface PickListFilterOptions {
  /** Callback to filter items */
  filter?: (value?: any) => void;
  /** Callback to reset the filter */
  reset?: () => void;
}
