import { Component, input, output, viewChild, ChangeDetectionStrategy } from '@angular/core';

import { UIChart, ChartModule } from 'primeng/chart';
import { ChartType } from './cmm-chart.types';
import { CHART_DEFAULTS } from './cmm-chart.constants';

@Component({
  selector: 'cmm-chart',
  standalone: true,
  imports: [ChartModule],
  template: `
    <p-chart
      #chart
      [type]="type()"
      [data]="data()"
      [options]="options() ?? undefined"
      [plugins]="plugins() || []"
      [width]="width()"
      [height]="height()"
      [style]="style() ?? undefined"
      [responsive]="responsive()"
      (onDataSelect)="onDataSelect.emit($event)" />
  `,
  styleUrl: './cmm-chart.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmChartComponent {
  chart = viewChild<UIChart>('chart');

  // Core props
  type = input<ChartType>(CHART_DEFAULTS.TYPE);
  data = input<any>();
  options = input<any>();
  plugins = input<any[]>();
  width = input<string>(CHART_DEFAULTS.WIDTH);
  height = input<string>(CHART_DEFAULTS.HEIGHT);
  style = input<Record<string, any>>();
  styleClass = input<string>();
  responsive = input<boolean>(CHART_DEFAULTS.RESPONSIVE);

  // Events
  onDataSelect = output<any>();

  // Public methods
  refresh(): void {
    this.chart()?.refresh();
  }

  reinit(): void {
    this.chart()?.reinit();
  }

  generateLegend(): any {
    return this.chart()?.generateLegend();
  }
}
