import {
  ChangeDetectionStrategy,
  Component,
  input,
  output,
  TemplateRef,
  ViewEncapsulation,
} from '@angular/core';
export type BodyTableProps = {
  isShowCheckBox: boolean;
  isShowOrder: boolean;
  isClickRecord: boolean;
  dataKey: string;
  rowData: any;
  active: boolean;
  rowIndex: number;
  currentPage: number;
  itemPerPage: number;
  cols: any;
  orderTemplate?: TemplateRef<any> | null;
};
@Component({
  selector: 'tr[ubck-table-body]',
  encapsulation: ViewEncapsulation.None,
  standalone: false,
  template: `
    @let data = props(); @if (data.isShowCheckBox) {
    <td class="text-center">
      <p-tableCheckbox
         #checkItem
        [pTooltip]="getTooltipCheckbox(checkItem)"
        tooltipPosition="top"
        [value]="data.rowData"
        [disabled]="data.rowData.disabled"
        [class.disabled]="data.rowData.disabled"
      />
    </td>
    } @if (data.isShowOrder) {
    <td
      class="text-center"
      [class.cursor-pointer]="data.isClickRecord"
      [class.active]="data.active"
    >
      @if (data.orderTemplate) {
      <ng-container
        [ngTemplateOutlet]="data.orderTemplate"
        [ngTemplateOutletContext]="{ $implicit: getCurrentPage(), rowData: data.rowData }"
      ></ng-container>
      } @else {
      {{ getCurrentPage() }}
      }
    </td>
    }
    <ng-container
      [ngTemplateOutlet]="defaultRow"
      [ngTemplateOutletContext]="{
              $implicit: data.rowData,
              cols: data.cols,
            }"
    ></ng-container>

    <ng-template #defaultRow let-rowData let-cols="cols">
      @for (col of cols; track $index) { @if (col.customTemplate) {
      @if(col['isFrozen']) {
      <td
        pFrozenColumn
        (click)="handleClickRow(rowData)"
        [class.cursor-pointer]="data.isClickRecord"
        [class.active]="data.active"
        class="{{ col.tdClassName }} {{
          rowData.tdCustomClasses
        }} "
        [ngStyle]="{
          'min-width': col['minWidth'] || 'unset',
          'max-width': col['maxWidth'] || 'unset',
          width: col['width'] || 'unset',
        }"
        [attr.colSpan]="col.tdColSpan || 1"
        [attr.rowSpan]="col.tdRowSpan || 1"
      >
        <ng-container
          [ngTemplateOutlet]="col.customTemplate"
          [ngTemplateOutletContext]="{
            $implicit: rowData[col.field],
            rowData,
            col: col
          }"
        ></ng-container>
      </td>
      } @else {
      <td
        (click)="handleClickRow(rowData)"
        [class.cursor-pointer]="data.isClickRecord"
        [class.active]="data.active"
        class="{{ col.tdClassName }} {{
          rowData.tdCustomClasses
        }} "
        [ngStyle]="{
          'min-width': col['minWidth'] || 'unset',
          'max-width': col['maxWidth'] || 'unset',
          width: col['width'] || 'unset',
        }"
        [attr.colSpan]="col.tdColSpan || 1"
        [attr.rowSpan]="col.tdRowSpan || 1"
      >
        <ng-container
          [ngTemplateOutlet]="col.customTemplate"
          [ngTemplateOutletContext]="{
            $implicit: rowData[col.field],
            rowData,
            col: col
          }"
        ></ng-container>
      </td>
      } } @else { @if(col['isFrozen']) {
      <td
        pFrozenColumn
        (click)="handleClickRow(rowData)"
        [class.cursor-pointer]="data.isClickRecord"
        [class.active]="data.active"
        class="{{ col.tdClassName }} {{
          rowData.tdCustomClasses
        }} "
        [ngStyle]="{
          'min-width': col['minWidth'] || 'unset',
          'max-width': col['maxWidth'] || 'unset',
          width: col['width'] || 'unset',
        }"
        [attr.colSpan]="col.tdColSpan || 1"
        [attr.rowSpan]="col.tdRowSpan || 1"
      >
        
          <span  cmmEllipsis [appEllipsis]="true" [ellipsisRows]="col.row || 1" [style.maxWidth]="col.maxWidth" >{{ rowData[col.field] }}</span>
      
      </td>
      } @else {
      <td
        (click)="handleClickRow(rowData)"
        [class.cursor-pointer]="data.isClickRecord"
        [class.active]="data.active"
        class="{{ col.tdClassName }} {{
          rowData.tdCustomClasses
        }} "
        [ngStyle]="{
          'min-width': col['minWidth'] || 'unset',
          'max-width': col['maxWidth'] || 'unset',
          width: col['width'] || 'unset',
        }"
        [attr.colSpan]="col.tdColSpan || 1"
        [attr.rowSpan]="col.tdRowSpan || 1"
      >
        <span  cmmEllipsis [appEllipsis]="true" [ellipsisRows]="col.ellipsisRows || 1" [style.maxWidth]="col.maxWidth" >{{ rowData[col.field] }}</span>
      </td>
      } } }
    </ng-template>
  `,
  changeDetection: ChangeDetectionStrategy.Default,
})
export class UBCKTableBody {
  props = input.required<BodyTableProps>();
  onClickRow = output<any>();
  getCurrentPage() {
    return (
      this.props().rowIndex +
      1 +
      this.props().currentPage * this.props().itemPerPage
    );
  }
  handleClickRow(rowData: any) {
    this.onClickRow.emit(rowData);
  }
  getTooltipCheckbox(checkItem: any) {
    if(checkItem.checked) {
      return 'Bỏ chọn'
    } else {
      return 'Chọn'
    }
  }
}
