
import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { HeaderComponent, IUserActionHeader, UserActionHeaderComponent } from '../../Organisms/public-api';
import { BtnHeaderComponent } from '../../Atoms/public-api';
import { IBtnHeader } from '../../Atoms/btn-header/btn-header.model';

@Component({
  selector: 'cmm-header-management',
  imports: [HeaderComponent, BtnHeaderComponent, UserActionHeaderComponent],
  templateUrl: './header-management.component.html',
  styleUrl: './header-management.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class HeaderManagementComponent {
  headersConfig = input.required<IBtnHeader[]>();
  userActionMeta = input<IUserActionHeader>();
  eventClickAvatar = output<MouseEvent>();
  eventClickNotification = output<MouseEvent>();
  onAvatarClick(evt: MouseEvent) {
    this.eventClickAvatar.emit(evt);
  }
  onNotificationClick(evt: MouseEvent) {
    this.eventClickNotification.emit(evt);
  }
}
