import { Component, input, inject, output } from '@angular/core';

import { UbckImportProps } from './import-file.types';
import { computedUploadProps } from './computed/props';
import { UploadComponent } from '../public-api';
import { UbckImportSuccess } from './components/import-success/import-success';
import { TranslatePipe } from '@ngx-translate/core';
import { Button } from 'primeng/button';
import { Importing } from './components/importing/importing';
import { UbckImportReport } from './components/import-report/import-report';
import { ImportFileService, ImportConfig, ImportResult } from './services/import-file.service';
import { computed } from '@angular/core';

@Component({
  selector: 'ubck-import',
  template: `
    @let data = computedProps();
    @switch (importService.computedStep()) {
      @case ('select-file') {
        <app-upload
          [props]="data"
          (fileSelect)="handleFileSelected($event)"
          
      (validationError)="handleError($event)"
      (dragValidationError)="handleError($event)"
        ></app-upload>
        <ul class="upload-instructions">
          <li>
            {{ (props().templateInstructionKey || 'Để có kết quả nhập khẩu chính xác, hãy sử dụng tệp mẫu') | translate }}
            <a class="link" (click)="downloadTemplate()">{{ (props().downloadTemplateKey || 'Tải tệp mẫu') | translate }}</a>
          </li>
          <li>
            {{ (props().recordInstructionKey || 'Mỗi dòng dữ liệu trong tệp nhập khẩu tương ứng với 1 bản ghi.') | translate }}
          </li>
        </ul>
      }
      @case ('show-success-info') {
        <ubck-import-success
          [file]="importService.file()!"
          (onBackToPreviousStep)="handleBackToPreviousStep()"
          (onRemoveFile)="handleRemoveFile()"
          [importFileSuccessTitleKey]="props().importFileSuccessTitleKey || 'Tải file thành công'"
          [chooseAnotherFileKey]="props().chooseAnotherFileKey || 'Chọn tệp khác'"
        >
        </ubck-import-success>
        <div class="upload-footer">
          <p-button
            size="small"
            [label]="(props().closeButtonKey || 'Đóng') | translate"
            variant="outlined"
            (onClick)="handleClose()"
          ></p-button>
          <p-button
            size="small"
            [label]="(props().continueButtonKey || 'Tiếp tục') | translate"
            (onClick)="handleUpload()"
          ></p-button>
        </div>
      }
      @case ('upload-in-progress') {
        <ubck-importing
          [file]="importService.file()!"
          [progress]="importService.progress()"
          [fileInprogressTitleKey]="props().fileInprogressTitleKey || 'Đang tải file...'"
        ></ubck-importing>
      }
      @case ('show-result') {
        @if (importReportData()) {
          <ubck-import-report 
            [reportData]="importReportData()!"
            (onDownloadFile)="handleDownloadReport($event)"
            >
          </ubck-import-report>
        }
      }
    }
  `,
  imports: [
    UploadComponent,
    UbckImportSuccess,
    TranslatePipe,
    Button,
    Importing,
    UbckImportReport
],
  providers: [ImportFileService],
  styleUrls: ['./styles/upload-styles.scss'],
  standalone: true,
})
export class UbckImport {
  // Inject the service
  importService = inject(ImportFileService);
  
  uploadErrorEvent = output();
  
  // Props
  props = input.required<UbckImportProps>();
  config = input.required<ImportConfig>();

  uploadSuccessEvent = output<ImportResult>();

  // Computed props
  computedProps = computed(() => {
    return computedUploadProps(this.props());
  });

  // Computed import report data
  importReportData = computed(() => {
    const result = this.importService.result();
    if (!result) return null;

    return result
  });

  handleError(event: any) {
    this.uploadErrorEvent.emit(event);
  }

  // Event handlers
  handleFileSelected(event: File[]) {
    const file = event[0];
    this.importService.selectFile(file);
  }

  handleBackToPreviousStep() {
    this.importService.removeFile();
  }

  handleRemoveFile() {
    this.importService.removeFile();
  }

  handleUpload() {
    this.importService.startImport(this.config()).subscribe({
      next: (result) => {
        console.log('Import Result:', result);
        if(result.errorCount === 0) {
          this.uploadSuccessEvent.emit(result);
        }
        // Service already handles state updates
      },
      error: (error) => {
        console.error('Import failed:', error);
        // Error is already handled by service
      }
    });
  }

  downloadTemplate() {
    this.importService.downloadTemplate(this.config(), this.config()?.templateUrl || '');
  }

  handleClose() {
    this.importService.reset();
  }


  handleDownloadReport(event: { fileName?: string | null }) {
    if (event.fileName) {
      this.importService.downloadErrorReport(this.config(),  event.fileName);
    }
  }
}