/**
 * Default base z-index values for different overlay types
 */
export const ZINDEX_BASE_VALUES = {
  MODAL: 1100,
  OVERLAY: 1000,
  MENU: 1000,
  TOOLTIP: 1100,
  TOAST: 1200,
  SIDEBAR: 1050,
} as const;

export type ZIndexBaseValue = (typeof ZINDEX_BASE_VALUES)[keyof typeof ZINDEX_BASE_VALUES];

/**
 * Z-Index layer types for semantic usage
 */
export const ZINDEX_LAYERS = {
  BASE: 0,
  DROPDOWN: 1000,
  STICKY: 1020,
  FIXED: 1030,
  MODAL_BACKDROP: 1040,
  MODAL: 1050,
  POPOVER: 1060,
  TOOLTIP: 1070,
  NOTIFICATION: 1080,
} as const;

export type ZIndexLayer = (typeof ZINDEX_LAYERS)[keyof typeof ZINDEX_LAYERS];
