import { Component, input, ChangeDetectionStrategy } from '@angular/core';

import { TerminalModule } from 'primeng/terminal';
import { CmmTerminalProps } from './cmm-terminal.types';
import { TERMINAL_DEFAULTS } from './cmm-terminal.constants';

/**
 * Terminal is a text based user interface.
 * Wraps PrimeNG Terminal component.
 */
@Component({
  selector: 'cmm-terminal',
  standalone: true,
  imports: [TerminalModule],
  templateUrl: './cmm-terminal.component.html',
  styleUrl: './cmm-terminal.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmTerminalComponent {
  /**
   * Initial text to display on terminal
   */
  welcomeMessage = input<string>(TERMINAL_DEFAULTS.WELCOME_MESSAGE);

  /**
   * Prompt text for each command
   */
  prompt = input<string>(TERMINAL_DEFAULTS.PROMPT);

  /**
   * Inline style of the component
   */
  style = input<Record<string, any>>();

  /**
   * Style class of the component
   */
  styleClass = input<string>();
}
