import { AbstractControl, FormControl, FormGroup, ValidationErrors, ValidatorFn } from '@angular/forms';

/**
 * Custom Validators Utility Class
 * 
 * Provides reusable custom validators for Angular forms
 * 
 * Usage:
 * ```typescript
 * this.form = this.fb.group({
 *   phone: ['', [ValidationUtils.phoneValidator()]],
 *   url: ['', [ValidationUtils.urlValidator()]],
 *   password: ['', [ValidationUtils.strongPassword()]],
 * });
 * ```
 */
export class ValidationUtils {
  
  /**
   * Vietnamese phone number validator (10-11 digits, starts with 0)
   */
  static phoneValidator(): ValidatorFn {
    return (control: AbstractControl): ValidationErrors | null => {
      if (!control.value) {
        return null;
      }
      
      const phoneRegex = /^0[0-9]{9,10}$/;
      const valid = phoneRegex.test(control.value);
      
      return valid ? null : { invalidPhone: { value: control.value } };
    };
  }

  /**
   * URL validator
   */
  static urlValidator(): ValidatorFn {
    return (control: AbstractControl): ValidationErrors | null => {
      if (!control.value) {
        return null;
      }
      
      const urlRegex = /^(https?:\/\/)?([\da-z.-]+)\.([a-z.]{2,6})([/\w .-]*)*\/?$/;
      const valid = urlRegex.test(control.value);
      
      return valid ? null : { invalidUrl: { value: control.value } };
    };
  }

  /**
   * No whitespace validator - prevents input with only spaces
   */
  static noWhitespaceValidator(): ValidatorFn {
    return (control: AbstractControl): ValidationErrors | null => {
      if (!control.value) {
        return null;
      }
      
      const isWhitespace = (control.value || '').trim().length === 0;
      return isWhitespace ? { whitespace: { value: control.value } } : null;
    };
  }

  /**
   * Strong password validator
   * - At least 8 characters
   * - Contains uppercase and lowercase
   * - Contains number
   * - Contains special character
   */
  static strongPassword(): ValidatorFn {
    return (control: AbstractControl): ValidationErrors | null => {
      if (!control.value) {
        return null;
      }
      
      const hasUpperCase = /[A-Z]/.test(control.value);
      const hasLowerCase = /[a-z]/.test(control.value);
      const hasNumber = /[0-9]/.test(control.value);
      const hasSpecialChar = /[!@#$%^&*(),.?":{}|<>]/.test(control.value);
      const isLengthValid = control.value.length >= 8;
      
      const passwordValid = hasUpperCase && hasLowerCase && hasNumber && hasSpecialChar && isLengthValid;
      
      return passwordValid ? null : {
        strongPassword: {
          hasUpperCase,
          hasLowerCase,
          hasNumber,
          hasSpecialChar,
          isLengthValid,
          minLength: 8
        }
      };
    };
  }

  /**
   * Match validator - ensures two fields have the same value
   * 
   * Usage:
   * ```typescript
   * this.form = this.fb.group({
   *   password: ['', Validators.required],
   *   confirmPassword: ['', Validators.required]
   * }, {
   *   validators: ValidationUtils.matchValidator('password', 'confirmPassword')
   * });
   * ```
   */
  static matchValidator(controlName: string, matchingControlName: string): ValidatorFn {
    return (formGroup: AbstractControl): ValidationErrors | null => {
      const control = formGroup.get(controlName);
      const matchingControl = formGroup.get(matchingControlName);

      if (!(control && matchingControl)) {
        return null;
      }

      // Return if another validator has already found an error
      if (matchingControl.errors && !matchingControl.errors['passwordMismatch']) {
        return null;
      }

      // Set error on matchingControl if validation fails
      if (control.value !== matchingControl.value) {
        matchingControl.setErrors({ passwordMismatch: true });
        return { passwordMismatch: true };
      }
        matchingControl.setErrors(null);
        return null;
    };
  }

  /**
   * Date range validator
   */
  static dateRangeValidator(minDate: Date, maxDate: Date): ValidatorFn {
    return (control: AbstractControl): ValidationErrors | null => {
      if (!control.value) {
        return null;
      }
      
      const date = new Date(control.value);
      
      if (isNaN(date.getTime())) {
        return { invalidDate: true };
      }
      
      if (date < minDate) {
        return { dateMin: { minDate: minDate.toLocaleDateString() } };
      }
      
      if (date > maxDate) {
        return { dateMax: { maxDate: maxDate.toLocaleDateString() } };
      }
      
      return null;
    };
  }

  /**
   * File type validator
   * 
   * Usage:
   * ```typescript
   * ValidationUtils.fileTypeValidator(['image/png', 'image/jpeg'])
   * ```
   */
  static fileTypeValidator(allowedTypes: string[]): ValidatorFn {
    return (control: AbstractControl): ValidationErrors | null => {
      const file = control.value;
      
      if (!file) {
        return null;
      }
      
      const fileType = file.type;
      
      if (allowedTypes.indexOf(fileType) === -1) {
        return {
          invalidFileType: {
            actualType: fileType,
            allowedTypes: allowedTypes.join(', ')
          }
        };
      }
      
      return null;
    };
  }

  /**
   * File size validator (in MB)
   * 
   * Usage:
   * ```typescript
   * ValidationUtils.fileSizeValidator(5) // Max 5MB
   * ```
   */
  static fileSizeValidator(maxSizeMB: number): ValidatorFn {
    return (control: AbstractControl): ValidationErrors | null => {
      const file = control.value;
      
      if (!file) {
        return null;
      }
      
      const fileSizeMB = file.size / 1024 / 1024;
      
      if (fileSizeMB > maxSizeMB) {
        return {
          fileSizeExceeded: {
            actualSize: fileSizeMB.toFixed(2),
            maxSize: maxSizeMB
          }
        };
      }
      
      return null;
    };
  }

  /**
   * Number range validator
   */
  static numberRangeValidator(min: number, max: number): ValidatorFn {
    return (control: AbstractControl): ValidationErrors | null => {
      if (!control.value && control.value !== 0) {
        return null;
      }
      
      const value = Number(control.value);
      
      if (isNaN(value)) {
        return { invalidNumber: true };
      }
      
      if (value < min || value > max) {
        return {
          invalidRange: {
            min,
            max,
            actual: value
          }
        };
      }
      
      return null;
    };
  }

  /**
   * Async validator example - check if value exists in database
   * 
   * Usage:
   * ```typescript
   * this.form = this.fb.group({
   *   username: ['', [Validators.required], [ValidationUtils.asyncDuplicateValidator(this.userService)]]
   * });
   * ```
   */
  static asyncDuplicateValidator(checkService: any) {
    return (control: AbstractControl): Promise<ValidationErrors | null> => {
      if (!control.value) {
        return Promise.resolve(null);
      }
      
      // Simulated async check - replace with actual service call
      return new Promise((resolve) => {
        setTimeout(() => {
          // Replace this with actual API call
          // checkService.checkDuplicate(control.value).subscribe(...)
          const isDuplicate = false; // Your logic here
          
          resolve(isDuplicate ? { duplicateValue: true } : null);
        }, 500);
      });
    };
  }

  /**
   * Get all error messages from a form group
   */
  static getAllFormErrors(form: FormGroup): { [key: string]: any } | null {
    if (form instanceof AbstractControl) {
      const errors: { [key: string]: any } = {};
      
      Object.keys(form.controls || {}).forEach(key => {
        const control = (form as any).get(key);
        const controlErrors = control.errors;
        
        if (controlErrors) {
          errors[key] = controlErrors;
        }
        
        // Recursive for nested form groups
        if (control instanceof FormGroup) {
          const nestedErrors = ValidationUtils.getAllFormErrors(control);
          if (nestedErrors) {
            errors[key] = { ...errors[key], ...nestedErrors };
          }
        }
      });
      
      return Object.keys(errors).length > 0 ? errors : null;
    }
    
    return null;
  }
}