import {
  Component,
  input,
  output,
  model,
  viewChild,
  contentChild,
  TemplateRef,
  ChangeDetectionStrategy,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { ContextMenu, ContextMenuModule } from 'primeng/contextmenu';
import type { MenuItem } from 'primeng/api';
import { ContextMenuAppendTo } from './cmm-contextmenu.types';
import { CONTEXTMENU_DEFAULTS } from './cmm-contextmenu.constants';

@Component({
  selector: 'cmm-contextmenu',
  standalone: true,
  imports: [CommonModule, ContextMenuModule],
  template: `
    <p-contextMenu
      #contextMenu
      [id]="id() ?? undefined"
      [model]="model()"
      [triggerEvent]="triggerEvent()"
      [target]="target()"
      [global]="global()"
      [appendTo]="appendTo()"
      [autoZIndex]="autoZIndex()"
      [baseZIndex]="baseZIndex()"
      [breakpoint]="breakpoint()"
      [ariaLabel]="ariaLabel() ?? undefined"
      [ariaLabelledBy]="ariaLabelledBy() ?? undefined"
      [pressDelay]="pressDelay()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined"
      (onShow)="onShow.emit($event)"
      (onHide)="onHide.emit()">
      @if (itemTemplate()) {
        <ng-template pTemplate="item" let-item>
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
      @if (submenuIconTemplate()) {
        <ng-template pTemplate="submenuicon" let-class="class">
          <ng-container *ngTemplateOutlet="submenuIconTemplate()!; context: { class: class }" />
        </ng-template>
      }
    </p-contextMenu>
  `,
  styleUrl: './cmm-contextmenu.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmContextmenuComponent {
  contextMenu = viewChild<ContextMenu>('contextMenu');

  // Core props
  id = input<string>();
  model = input<MenuItem[]>([]);
  triggerEvent = input<string>('contextmenu');
  target = input<any>();
  global = input<boolean>(false);
  appendTo = input<ContextMenuAppendTo>(CONTEXTMENU_DEFAULTS.APPEND_TO);
  autoZIndex = input<boolean>(CONTEXTMENU_DEFAULTS.AUTO_Z_INDEX);
  baseZIndex = input<number>(CONTEXTMENU_DEFAULTS.BASE_Z_INDEX);
  breakpoint = input<string>('960px');
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();
  pressDelay = input<number>(500);
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Templates
  itemTemplate = contentChild<TemplateRef<any>>('item');
  submenuIconTemplate = contentChild<TemplateRef<any>>('submenuicon');

  // Events
  onShow = output<any>();
  onHide = output<void>();

  // Public methods
  show(event: Event): void {
    this.contextMenu()?.show(event);
  }

  hide(): void {
    this.contextMenu()?.hide();
  }

  toggle(event: Event): void {
    this.contextMenu()?.toggle(event);
  }
}
