import {  Injectable, Signal, computed } from '@angular/core';
import { FormGroup } from '@angular/forms';
import { DynamicFormItem } from './dynamic-form.types';
@Injectable()
export class CmmDynamicFormService {


 
  isVisible(item: DynamicFormItem, form: FormGroup): boolean {
    if (item.hidden) return false;
    if (!item.visibleWhen) return true;
    return item.visibleWhen(form.value, form);
  }

  isDisabled(item: DynamicFormItem, form: FormGroup): boolean {
    if (item.disabled) return true;
    if (!item.disabledWhen) return false;
    return item.disabledWhen(form.value, form);
  }

  isVisibleSignal(item: DynamicFormItem, form: FormGroup): Signal<boolean> {
    return computed(() =>
      item.visibleWhen ? item.visibleWhen(form.value, form) : true
    );
  }
  isDiabledSignal(item: DynamicFormItem, form: FormGroup): Signal<boolean> {
    return computed(() =>
      item.disabledWhen ? item.disabledWhen(form.value, form) : false
    );
  }

  getControl(item: DynamicFormItem, form: FormGroup) {
    return form.get(item.key);
  }
}
