/**
 * Constants for OrderList component
 */

/** Controls position options */
export const ORDERLIST_CONTROLS_POSITION = {
  LEFT: 'left' as const,
  RIGHT: 'right' as const,
};

/** Filter match mode options */
export const ORDERLIST_FILTER_MATCH_MODE = {
  CONTAINS: 'contains' as const,
  STARTS_WITH: 'startsWith' as const,
  ENDS_WITH: 'endsWith' as const,
  EQUALS: 'equals' as const,
  NOT_EQUALS: 'notEquals' as const,
  IN: 'in' as const,
  LT: 'lt' as const,
  LTE: 'lte' as const,
  GT: 'gt' as const,
  GTE: 'gte' as const,
};

export type OrderListControlsPosition = (typeof ORDERLIST_CONTROLS_POSITION)[keyof typeof ORDERLIST_CONTROLS_POSITION];
export type OrderListFilterMatchMode = (typeof ORDERLIST_FILTER_MATCH_MODE)[keyof typeof ORDERLIST_FILTER_MATCH_MODE];
