import { ChangeDetectionStrategy, Component, input, output, computed, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Breadcrumb } from 'primeng/breadcrumb';
import { MenuItem } from 'primeng/api';

@Component({
  selector: 'cmm-breadcrumb',
  templateUrl: './cmm-breadcrumb.component.html',
  styleUrls: ['./cmm-breadcrumb.component.scss'],
  standalone: true,
  imports: [CommonModule, Breadcrumb],
  exportAs: 'cmmbreadcrumb',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmBreadcrumbComponent {
  // Signal inputs - Breadcrumb properties
  model = input<MenuItem[]>([]);
  home = input<MenuItem | undefined>(undefined);
  homeAriaLabel = input<string>('');

  // Signal inputs - Styling
  style = input<{ [klass: string]: any } | null>(null);
  styleClass = input<string>('');

  // Custom variant and size system
  variant = input<'default' | 'compact' | 'spacious'>('default');
  customSize = input<'small' | 'default' | 'large'>('default');

  // Signal outputs
  onItemClick = output<{ originalEvent: Event; item: MenuItem }>();

  // Template projections
  itemTemplate = contentChild<TemplateRef<any>>('item');
  separatorTemplate = contentChild<TemplateRef<any>>('separator');

  // Computed style class
  computedStyleClass = computed(() => {
    const classes = [
      'cmm-breadcrumb',
      `cmm-breadcrumb--${this.variant()}`,
      `cmm-breadcrumb--${this.customSize()}`,
      this.styleClass(),
    ];
    return classes.filter(Boolean).join(' ');
  });

  // Event handlers
  handleItemClick(event: { originalEvent: Event; item: MenuItem }): void {
    this.onItemClick.emit(event);
  }
}
