import { CommonModule } from '@angular/common';
import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { IBtnActionsModel } from './btn-actions.model';

@Component({
  selector: 'cmm-btn-actions',
  imports: [CommonModule],
  templateUrl: './btn-actions.component.html',
  styleUrls: ['./btn-actions.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class BtnActionsComponent {
  meta = input.required<IBtnActionsModel>();
  eventClick = output<MouseEvent>();

  handleClick(event: MouseEvent) {
    this.eventClick.emit(event);
  }
}
