import {
  ChangeDetectionStrategy,
  Component,
  forwardRef,
  input,
  model,
  output,
  contentChild,
  TemplateRef,
  computed,
} from '@angular/core';
import { ControlValueAccessor, FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { AutoComplete, AutoCompleteCompleteEvent, AutoCompleteSelectEvent } from 'primeng/autocomplete';

@Component({
  selector: 'cmm-auto-complete',
  templateUrl: './cmm-auto-complete.component.html',
  styleUrls: ['./cmm-auto-complete.component.scss'],
  standalone: true,
  imports: [CommonModule, AutoComplete, FormsModule],
  exportAs: 'cmmautocomplete',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmAutoCompleteComponent),
      multi: true,
    },
  ],
  host: {
    '[attr.name]': 'serializeId',
  },
})
export class CmmAutoCompleteComponent implements ControlValueAccessor {
  public readonly serializeId = `cmm-ac-${Math.random().toString(36).substring(2)}`;
  private _value: any;
  onTouched: () => void = () => {};
  onChange: (_: any) => void = () => {};

  // Core value binding
  value: any;

  // Signal inputs - Core functionality
  suggestions = model<any[]>([]);
  field = input<string>();
  dropdown = input<boolean>(false);
  multiple = input<boolean>(false);
  disabled = model<boolean>(false);
  readonly = input<boolean>(false);

  // Signal inputs - Data handling
  optionLabel = input<string | ((item: any) => string)>();
  optionValue = input<string | ((item: any) => string)>();
  optionDisabled = input<string>();
  optionGroupLabel = input<string>('label');
  optionGroupChildren = input<string>('items');
  dataKey = input<string>();

  // Signal inputs - Search & Filtering
  minLength = input<number>(1);
  delay = input<number>(300);
  completeOnFocus = input<boolean>(false);
  forceSelection = input<boolean>(false);
  unique = input<boolean>(true);
  autoHighlight = input<boolean>(false);
  selectOnFocus = input<boolean>(false);
  autoOptionFocus = input<boolean>(false);
  searchLocale = input<string>();
  focusOnHover = input<boolean>(true);
  typeahead = input<boolean>(true);

  // Signal inputs - Display & UI
  placeholder = input<string>('');
  emptyMessage = input<string>();
  dropdownIcon = input<string>();
  showClear = input<boolean>(false);
  autofocus = input<boolean>(false);
  virtualScroll = input<boolean>(false);
  virtualScrollItemSize = input<number>();
  virtualScrollOptions = input<any>();
  scrollHeight = input<string>('200px');
  showEmptyMessage = input<boolean>(true);
  group = input<boolean>(false);
  dropdownMode = input<string>('blank');

  // Signal inputs - Input attributes
  name = input<string>();
  required = input<boolean>(false);
  maxlength = input<number>();
  tabindex = input<number>();
  type = input<string>('text');
  autoComplete = input<string>('off');

  // Signal inputs - Styling
  styleClass = input<string>('');
  style = input<Record<string, any>>({});
  panelStyleClass = input<string>('');
  panelStyle = input<Record<string, any>>({});
  inputStyleClass = input<string>('');
  inputStyle = input<Record<string, any>>({});
  inputId = input<string>();
  size = input<'small' | 'large'>();
  variant = input<'filled' | 'outlined'>('outlined');
  fluid = input<boolean>(false);

  // Signal inputs - Overlay
  appendTo = input<unknown>('body');
  overlayOptions = input<any>();
  autoZIndex = input<boolean>(true);
  baseZIndex = input<number>(0);
  showTransitionOptions = input<string>('.12s cubic-bezier(0, 0, 0.2, 1)');
  hideTransitionOptions = input<string>('.1s linear');

  // Signal inputs - Accessibility
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();
  dropdownAriaLabel = input<string>();
  searchMessage = input<string>();
  emptySelectionMessage = input<string>();
  selectionMessage = input<string>();

  // Signal inputs - Advanced
  lazy = input<boolean>(false);
  id = input<string>();

  // Signal outputs
  onComplete = output<AutoCompleteCompleteEvent>();
  onSelect = output<AutoCompleteSelectEvent>();
  onUnselect = output<any>();
  onFocus = output<Event>();
  onBlur = output<Event>();
  onClear = output<void>();
  onKeyUp = output<KeyboardEvent>();
  onDropdownClick = output<any>();
  onShow = output<void>();
  onHide = output<void>();
  onLazyLoad = output<any>();

  // Content projection using contentChild for templates
  itemTemplate = contentChild<TemplateRef<any>>('item');
  emptyTemplate = contentChild<TemplateRef<any>>('empty');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  selectedItemTemplate = contentChild<TemplateRef<any>>('selecteditem');
  groupTemplate = contentChild<TemplateRef<any>>('group');
  loaderTemplate = contentChild<TemplateRef<any>>('loader');
  removeIconTemplate = contentChild<TemplateRef<any>>('removeicon');
  loadingIconTemplate = contentChild<TemplateRef<any>>('loadingicon');
  clearIconTemplate = contentChild<TemplateRef<any>>('clearicon');
  dropdownIconTemplate = contentChild<TemplateRef<any>>('dropdownicon');

  // Computed state for dynamic classes
  computedStyleClass = computed(() => {
    const classes = [this.styleClass()];

    if (this.size()) {
      classes.push(`cmm-autocomplete-${this.size()}`);
    }

    if (this.variant()) {
      classes.push(`cmm-autocomplete-${this.variant()}`);
    }

    return classes.filter(Boolean).join(' ');
  });

  // ControlValueAccessor implementation
  writeValue(value: any): void {
    this.value = value;
    this._value = value;
  }

  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled.set(isDisabled);
  }

  // Event handlers
  handleComplete(event: AutoCompleteCompleteEvent): void {
    this.onComplete.emit(event);
  }

  handleSelect(event: AutoCompleteSelectEvent): void {
    this.onChange(this.value);
    this.onSelect.emit(event);
  }

  handleUnselect(event: any): void {
    this.onChange(this.value);
    this.onUnselect.emit(event);
  }

  handleFocus(event: Event): void {
    this.onFocus.emit(event);
  }

  handleBlur(event: Event): void {
    this.onTouched();
    this.onBlur.emit(event);
  }

  handleClear(): void {
    this.value = null;
    this.onChange(null);
    this.onClear.emit();
  }

  handleKeyUp(event: KeyboardEvent): void {
    this.onKeyUp.emit(event);
  }

  handleDropdownClick(event: any): void {
    this.onDropdownClick.emit(event);
  }

  handleShow(): void {
    this.onShow.emit();
  }

  handleHide(): void {
    this.onHide.emit();
  }

  handleLazyLoad(event: any): void {
    this.onLazyLoad.emit(event);
  }

  handleModelChange(value: any): void {
    this.value = value;
    this.onChange(value);
  }
}
