// ============================================
// 4. HEADING DIRECTIVE (extends base)

import { Directive, inject, Input, OnInit } from "@angular/core";
import { CmmTypographyDirective } from "./typography.directive";
import { CmmTypographyConfigService } from "../services/typography-config.service";
import { UBCKCustomTypographyStyles } from "../styles/typography.style";
import { BaseComponent } from "primeng/basecomponent";
// ============================================
// 4. HEADING DIRECTIVE (extends base)
// ============================================

@Directive({
  selector: 'h1[cmmHeading], h2[cmmHeading], h3[cmmHeading], h4[cmmHeading], h5[cmmHeading], h6[cmmHeading]',
  standalone: true,
  hostDirectives: [{
    directive: CmmTypographyDirective,
    inputs: ['copyable', 'editable', 'disabled', 'ellipsis', 'type'],
    outputs: ['contentChange', 'copy']
  }],
  host: {
    '[class.cmm-heading]': 'true',
    '[class.cmm-heading-1]': 'level === 1',
    '[class.cmm-heading-2]': 'level === 2',
    '[class.cmm-heading-3]': 'level === 3',
    '[class.cmm-heading-4]': 'level === 4',
    '[class.cmm-heading-5]': 'level === 5',
    '[class.cmm-heading-6]': 'level === 6'
  },
  providers: [UBCKCustomTypographyStyles]
})
export class CmmHeadingDirective extends BaseComponent implements OnInit {
  _componentStyle = inject(UBCKCustomTypographyStyles)

  private configService = inject(CmmTypographyConfigService);

  @Input() level?: 1 | 2 | 3 | 4 | 5 | 6;
  @Input() weight?: 'normal' | 'medium' | 'semibold' | 'bold';
  @Input() fontSize?: string; // Allow override per element

  override  ngOnInit(): void {
    super.ngOnInit();
    // Auto-detect level from tag name if not provided
    if (!this.level) {
      const tagName = this.el.nativeElement.tagName.toLowerCase();
      this.level = Number.parseInt(tagName.charAt(1)) as 1 | 2 | 3 | 4 | 5 | 6;
    }

    // Apply font-size: priority is fontSize input > config service > default
    const size = this.fontSize || this.configService.getHeadingSize(this.level);
    this.renderer.setStyle(this.el.nativeElement, 'font-size', size);

    // Apply font-weight if specified
    if (this.weight) {
      const weightMap = {
        'normal': '400',
        'medium': '500',
        'semibold': '600',
        'bold': '700'
      };
      this.renderer.setStyle(this.el.nativeElement, 'font-weight', weightMap[this.weight]);
    } else {
      // Default weight for headings
      this.renderer.setStyle(this.el.nativeElement, 'font-weight', '600');
    }
  }
}