import { Component, input, output, model, ChangeDetectionStrategy, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { SidebarPosition } from './cmm-sidebar.types';
import { SIDEBAR_DEFAULTS } from './cmm-sidebar.constants';

@Component({
  selector: 'cmm-sidebar',
  standalone: true,
  imports: [CommonModule],
  template: `
    <!-- <p-sidebar
      [(visible)]="visible"
      [position]="position()"
      [modal]="modal()"
      [closeOnEscape]="dismissable()"
      [showCloseIcon]="showCloseIcon()"
      [closeOnEscape]="closeOnEscape()"
      [autoZIndex]="autoZIndex()"
      [baseZIndex]="baseZIndex()"
      [transitionOptions]="transitionOptions()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass()!"
      (onShow)="onShow.emit()"
      (onHide)="onHide.emit()"
    >
      @if (headerTemplate()) {
        <ng-template pTemplate="header">
          <ng-container *ngTemplateOutlet="headerTemplate()!" />
        </ng-template>
      }
      <ng-content />
      @if (footerTemplate()) {
        <ng-template pTemplate="footer">
          <ng-container *ngTemplateOutlet="footerTemplate()!" />
        </ng-template>
      }
    </p-sidebar> -->
  `,
  styleUrl: './cmm-sidebar.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmSidebarComponent {
  // Model
  visible = model<boolean>(SIDEBAR_DEFAULTS.VISIBLE);

  // Content children templates
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');

  // Core props
  position = input<SidebarPosition>(SIDEBAR_DEFAULTS.POSITION);
  modal = input<boolean>(SIDEBAR_DEFAULTS.MODAL);
  dismissable = input<boolean>(SIDEBAR_DEFAULTS.DISMISSABLE);
  showCloseIcon = input<boolean>(SIDEBAR_DEFAULTS.SHOW_CLOSE_ICON);
  closeOnEscape = input<boolean>(SIDEBAR_DEFAULTS.CLOSE_ON_ESCAPE);
  autoZIndex = input<boolean>(SIDEBAR_DEFAULTS.AUTO_Z_INDEX);
  baseZIndex = input<number>(SIDEBAR_DEFAULTS.BASE_Z_INDEX);
  transitionOptions = input<string>(SIDEBAR_DEFAULTS.TRANSITION_OPTIONS);
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Output events
  onShow = output<void>();
  onHide = output<void>();
}
