import { Component, input, output, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DockModule } from 'primeng/dock';
import { DockItem, DockPosition } from './cmm-dock.types';
import { DOCK_DEFAULTS } from './cmm-dock.constants';

@Component({
  selector: 'cmm-dock',
  standalone: true,
  imports: [CommonModule, DockModule],
  template: `
    <p-dock
      [id]="id() ?? undefined"
      [model]="model()"
      [position]="position()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined"
      [ariaLabel]="ariaLabel() ?? undefined"
      [ariaLabelledBy]="ariaLabelledBy() ?? undefined"
      (onFocus)="onFocus.emit($event)"
      (onBlur)="onBlur.emit($event)">
      @if (itemTemplate()) {
        <ng-template pTemplate="item" let-item>
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
    </p-dock>
  `,
  styleUrl: './cmm-dock.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmDockComponent {
  // Core props
  id = input<string>();
  model = input<DockItem[]>([]);
  position = input<DockPosition>(DOCK_DEFAULTS.POSITION);
  style = input<Record<string, any>>();
  styleClass = input<string>();
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();

  // Templates
  itemTemplate = contentChild<TemplateRef<any>>('item');

  // Events
  onFocus = output<FocusEvent>();
  onBlur = output<FocusEvent>();
}
