import { ChangeDetectionStrategy, Component, input, computed, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { CardModule } from 'primeng/card';

@Component({
  selector: 'cmm-card',
  templateUrl: './cmm-card.component.html',
  styleUrls: ['./cmm-card.component.scss'],
  standalone: true,
  imports: [CommonModule, CardModule],
  exportAs: 'cmmcard',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmCardComponent {
  // Signal inputs - Card properties
  header = input<string>('');
  subheader = input<string>('');

  // Signal inputs - Styling
  style = input<{ [klass: string]: any } | null>(null);
  styleClass = input<string>('');

  // Custom variant and size system
  variant = input<'outlined' | 'filled'>('outlined');
  customSize = input<'small' | 'default' | 'large'>('default');

  // Template projections
  headerTemplate = contentChild<TemplateRef<any>>('header');
  titleTemplate = contentChild<TemplateRef<any>>('title');
  subtitleTemplate = contentChild<TemplateRef<any>>('subtitle');
  contentTemplate = contentChild<TemplateRef<any>>('content');
  footerTemplate = contentChild<TemplateRef<any>>('footer');

  // Computed style class
  computedStyleClass = computed(() => {
    const classes = ['cmm-card', `cmm-card--${this.variant()}`, `cmm-card--${this.customSize()}`, this.styleClass()];
    return classes.filter(Boolean).join(' ');
  });
}
