export const ACCORDION_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export const ACCORDION_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export const ACCORDION_ICON_POSITIONS = {
  START: 'start',
  END: 'end',
} as const;

export const DEFAULT_TRANSITION_OPTIONS = '400ms cubic-bezier(0.86, 0, 0.07, 1)';

export type AccordionSize = (typeof ACCORDION_SIZES)[keyof typeof ACCORDION_SIZES];
export type AccordionVariant = (typeof ACCORDION_VARIANTS)[keyof typeof ACCORDION_VARIANTS];
export type AccordionIconPosition = (typeof ACCORDION_ICON_POSITIONS)[keyof typeof ACCORDION_ICON_POSITIONS];
