import { ElementRef } from '@angular/core';

/**
 * PrimeNG Component Detector
 * Single Responsibility: Auto-detect and configure PrimeNG components
 */
export class PrimeNGDetectorHelper {
  /**
   * Auto-detect PrimeNG component by checking parent elements
   */
  static autoDetect(el: ElementRef): string | undefined {
    const element = el.nativeElement;
    let current = element.parentElement;

    while (current) {
      const tagName = current.tagName.toLowerCase();
      if (tagName.startsWith('p-')) {
        return tagName.substring(2);
      }
      // Check for cmm- wrapper components
      if (tagName.startsWith('cmm-')) {
        const cmmType = tagName.substring(4); // Remove 'cmm-' prefix
        // Map cmm components to their PrimeNG equivalents
        if (cmmType === 'datepicker') return 'datepicker';
        if (cmmType === 'select') return 'select';
        if (cmmType === 'multiselect') return 'multiselect';
      }
      current = current.parentElement;
      if (current === document.body) break;
    }

    return undefined;
  }

  /**
   * Get PrimeNG tag name from component name
   */
  static getTagName(component: string): string {
    const normalized = component.toLowerCase();

    const tagMap: Record<string, string> = {
      select: 'p-select, p-dropdown',
      dropdown: 'p-select, p-dropdown',
      calendar: 'p-calendar',
      datepicker: 'p-datepicker, cmm-datepicker',
      inputnumber: 'p-inputNumber, p-inputnumber',
      multiselect: 'p-multiSelect, p-multiselect',
      autocomplete: 'p-autoComplete, p-autocomplete',
      chips: 'p-chips',
      inputmask: 'p-inputMask, p-inputmask',
      password: 'p-password',
      inputtextarea: 'p-inputTextarea, p-inputtextarea',
      textarea: 'p-inputTextarea, p-inputtextarea',
      checkbox: 'p-checkbox',
      radiobutton: 'p-radioButton, p-radiobutton',
      radio: 'p-radioButton, p-radiobutton',
      inputswitch: 'p-inputSwitch, p-inputswitch',
      switch: 'p-inputSwitch, p-inputswitch',
    };

    return tagMap[normalized] || component;
  }

  /**
   * Get PrimeNG inner element selectors for styling
   */
  static getInnerSelectors(component: string): string[] {
    const normalized = component.toLowerCase();

    const selectorMap: Record<string, string[]> = {
      select: ['.p-select', '.p-dropdown', '.p-element'],
      dropdown: ['.p-select', '.p-dropdown', '.p-element'],
      datepicker: [
        '.p-datepicker-input',
        'input.p-datepicker-input',
        '.p-inputtext',
      ],
      calendar: ['.p-inputtext', 'input.p-inputtext'],
      inputnumber: ['.p-inputnumber-input', 'input.p-inputtext'],
      multiselect: ['.p-multiselect', '.p-element'],
      autocomplete: ['.p-autocomplete input', 'input.p-inputtext'],
      chips: ['.p-chips', '.p-chips-multiple-container'],
      inputmask: ['.p-inputtext', 'input'],
      password: ['.p-inputtext', 'input'],
      inputtextarea: ['.p-inputtextarea', 'textarea'],
      textarea: ['.p-inputtextarea', 'textarea'],
      checkbox: ['.p-checkbox-box'],
      radiobutton: ['.p-radiobutton-box'],
      radio: ['.p-radiobutton-box'],
      inputswitch: ['.p-inputswitch'],
      switch: ['.p-inputswitch'],
    };

    return selectorMap[normalized] || ['input', 'select', 'textarea'];
  }
  // In isCustomCmmComponent()
  static isCustomCmmComponent(component: string): boolean {
    return (
      component === 'cmm-dropdown-lazy' ||
      component === 'cmm-dropdown-checkbox' ||
      component === 'cmm-password'
    ); // Add here
  }
}
