

// ============================================
// 2. TEXT MEASURE SERVICE (Complete)
// ============================================
import { Injectable } from '@angular/core';
@Injectable({ providedIn: 'root' })
export class CmmTextEllipsisService {

  private static canvas: HTMLCanvasElement | null = null;
  private static context: CanvasRenderingContext2D | null = null;

  /**
   * Check if element content is clamped/truncated
   */
  isElementClamped(element: HTMLElement, rows: number): boolean {
    const lineHeight = this.getLineHeight(element);
    const maxHeight = lineHeight * rows;
    return element.scrollHeight > maxHeight;
  }

  /**
   * Check if element has text ellipsis (single line)
   * Works for CSS-based text-overflow: ellipsis
   */
  isTextEllipsisActive(element: HTMLElement): boolean {
    return element.scrollWidth > element.clientWidth;
  }

  /**
   * Check if element has ellipsis (single or multi-line)
   * Universal check for both CSS and JS implementations
   */
  hasEllipsis(element: HTMLElement, rows = 1): boolean {
    // Multi-line: check vertical overflow
    const lineHeight = this.getLineHeight(element);
    const maxHeight = lineHeight * rows;
    return element.scrollHeight > maxHeight;
  }

  /**
   * Measure and truncate text to fit within specified rows
   */
  measureText(
    element: HTMLElement,
    rows: number,
    content: string,
    suffix = ''
  ): { isClamped: boolean; clampedText: string } {
    const lineHeight = this.getLineHeight(element);
    const maxHeight = lineHeight * rows;

    // Create temporary element for measurement
    const temp = this.createTempElement(element);
    temp.textContent = content + suffix;
    document.body.appendChild(temp);

    const isClamped = temp.scrollHeight > maxHeight;
    let clampedText = content;

    if (isClamped) {
      // Binary search for optimal text length
      clampedText = this.binarySearchText(temp, content, maxHeight, suffix);
    }

    document.body.removeChild(temp);

    return { isClamped, clampedText };
  }

  /**
   * Get computed line height
   */
  private getLineHeight(element: HTMLElement): number {
    const computed = window.getComputedStyle(element);
    const lineHeight = computed.lineHeight;

    if (lineHeight === 'normal') {
      // Normal is typically 1.2 times the font size
      return Number.parseFloat(computed.fontSize) * 1.2;
    }

    return Number.parseFloat(lineHeight);
  }

  /**
   * Create temporary element with same styles for measurement
   */
  private createTempElement(source: HTMLElement): HTMLElement {
    const temp = document.createElement('div');
    const computed = window.getComputedStyle(source);

    // Copy relevant styles
    temp.style.cssText = `
      position: absolute;
      visibility: hidden;
      width: ${source.offsetWidth}px;
      font-family: ${computed.fontFamily};
      font-size: ${computed.fontSize};
      font-weight: ${computed.fontWeight};
      line-height: ${computed.lineHeight};
      letter-spacing: ${computed.letterSpacing};
      word-spacing: ${computed.wordSpacing};
      white-space: normal;
      word-wrap: break-word;
      overflow-wrap: break-word;
    `;

    return temp;
  }

  /**
   * Binary search to find optimal text length that fits
   */
  private binarySearchText(
    element: HTMLElement,
    text: string,
    maxHeight: number,
    suffix = ''
  ): string {
    let start = 0;
    let end = text.length;
    let result = text;
    const ellipsis = '...';

    while (start <= end) {
      const mid = Math.floor((start + end) / 2);
      const testText = text.slice(0, mid) + ellipsis + suffix;
      element.textContent = testText;

      if (element.scrollHeight <= maxHeight) {
        result = text.slice(0, mid);
        start = mid + 1;
      } else {
        end = mid - 1;
      }
    }

    return result;
  }
  /**
   * Check if text width exceeds the maximum width
   * @param text - The text to measure
   * @param maxWidth - Maximum width in pixels
   * @param font - Font style (default: '14px Arial')
   * @returns true if text width exceeds maxWidth, false otherwise
   */
  static isEllipses(text: string, maxWidth: number, font = '14px Roboto'): boolean {
    if (!text || maxWidth <= 0) {
      return false;
    }

    // Create canvas context if not exists (singleton pattern)
    if (!CmmTextEllipsisService.context) {
      CmmTextEllipsisService.canvas = document.createElement('canvas');
      CmmTextEllipsisService.context = CmmTextEllipsisService.canvas.getContext('2d');
    }

    if (!CmmTextEllipsisService.context) {
      return false;
    }

    // Set font and measure text
    CmmTextEllipsisService.context.font = font;
    const metrics = CmmTextEllipsisService.context.measureText(text);

    return metrics.width > maxWidth;
  }

  /**
   * Get the actual width of text in pixels
   * @param text - The text to measure
   * @param font - Font style (default: '14px Arial')
   * @returns Width in pixels
   */
  static getTextWidth(text: string, font = '14px Roboto'): number {
    if (!text) {
      return 0;
    }

    if (!CmmTextEllipsisService.context) {
      CmmTextEllipsisService.canvas = document.createElement('canvas');
      CmmTextEllipsisService.context = CmmTextEllipsisService.canvas.getContext('2d');
    }

    if (!CmmTextEllipsisService.context) {
      return 0;
    }

    CmmTextEllipsisService.context.font = font;
    const metrics = CmmTextEllipsisService.context.measureText(text);

    return metrics.width;
  }
}
