import {
  Component,
  input,
  output,
  model,
  contentChild,
  TemplateRef,
  viewChild,
  inject,
  computed,
  ChangeDetectionStrategy,
  ViewEncapsulation,
} from '@angular/core';
import { Table } from 'primeng/table';
import {
  TablePageEvent,
  TableFilterEvent,
  TableRowSelectEvent,
  TableRowReorderEvent,
  TableRowExpandEvent,
  TableRowCollapseEvent,
} from 'primeng/table';
import {
  ColumnDefinition,
  TableProps,
} from './table.types';
import { BaseComponent } from 'primeng/basecomponent';
import { computedColumn } from './utils/compute-column';
import { computedTableProps } from './utils/compute-table-props';
import { computeTotalCols } from './utils/compute-total-col';
import { UBCK_DEFAULT_PAGE, UBCK_DEFAULT_RESULT_COUNT } from './table.const';
import { UbckTableStyle } from './styles/table.style';
@Component({
  selector: 'ubck-table',
  templateUrl: './table.component.html',
  standalone: false,
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None
})
export class UbckTable extends BaseComponent {
  _componentStyle = inject(UbckTableStyle)

  currentPage = model<number>(UBCK_DEFAULT_PAGE);
  itemPerPage = model<number>(UBCK_DEFAULT_RESULT_COUNT);


  tbl = viewChild<Table>('dt');

  ObjectAssign = Object.assign;

  columns = input.required<ColumnDefinition[][]>();
  // Computed signals for derived state
  cols = computed(() => computedColumn(this.columns()));

  captionTemplate = contentChild<TemplateRef<any>>('caption');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  headergroupedTemplate = contentChild<TemplateRef<any>>('headergrouped');
  bodyTemplate = contentChild<TemplateRef<any>>('body');
  loadingbodyTemplate = contentChild<TemplateRef<any>>('loadingbody');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  footergroupedTemplate = contentChild<TemplateRef<any>>('footergrouped');
  summaryTemplate = contentChild<TemplateRef<any>>('summary');
  colgroupTemplate = contentChild<TemplateRef<any>>('colgroup');
  expandedrowTemplate = contentChild<TemplateRef<any>>('expandedrow');
  groupheaderTemplate = contentChild<TemplateRef<any>>('groupheader');
  groupfooterTemplate = contentChild<TemplateRef<any>>('groupfooter');
  frozenheaderTemplate = contentChild<TemplateRef<any>>('frozenheader');
  frozenbodyTemplate = contentChild<TemplateRef<any>>('frozenbody');
  frozenfooterTemplate = contentChild<TemplateRef<any>>('frozenfooter');
  frozencolgroupTemplate = contentChild<TemplateRef<any>>('frozencolgroup');
  frozenexpandedrowTemplate = contentChild<TemplateRef<any>>('frozenexpandedrow');
  emptymessageTemplate = contentChild<TemplateRef<any>>('emptymessage');
  paginatorleftTemplate = contentChild<TemplateRef<any>>('paginatorleft');
  paginatorrightTemplate = contentChild<TemplateRef<any>>('paginatorright');
  paginatordropdowniconTemplate = contentChild<TemplateRef<any>>('paginatordropdownicon');
  paginatordropdownitemTemplate = contentChild<TemplateRef<any>>('paginatordropdownitem');
  paginatorfirstpagelinkiconTemplate = contentChild<TemplateRef<any>>('paginatorfirstpagelinkicon');
  paginatorlastpagelinkiconTemplate = contentChild<TemplateRef<any>>('paginatorlastpagelinkicon');
  paginatorpreviouspagelinkiconTemplate = contentChild<TemplateRef<any>>('paginatorpreviouspagelinkicon');
  paginatornextpagelinkiconTemplate = contentChild<TemplateRef<any>>('paginatornextpagelinkicon');
  loadingiconTemplate = contentChild<TemplateRef<any>>('loadingicon');
  reorderindicatorupiconTemplate = contentChild<TemplateRef<any>>('reorderindicatorupicon');
  reorderindicatordowniconTemplate = contentChild<TemplateRef<any>>('reorderindicatordownicon');
  sorticonTemplate = contentChild<TemplateRef<any>>('sorticon');
  checkboxiconTemplate = contentChild<TemplateRef<any>>('checkboxicon');
  headercheckboxiconTemplate = contentChild<TemplateRef<any>>('headercheckboxicon');
  customItem = contentChild<TemplateRef<any>>('customItem');
  orderTemplate = contentChild<TemplateRef<any>>('orderColumn');

  onClickRecord = output<Record<string, unknown>>();

  // Model
  dataSources = input.required<Record<string, any>[]>();
  selection = model<any | any[]>();

  _currentSelectedRow: any = null;


  // Single props input
  props = input<TableProps>({});

  // Output events
  onPage = output<TablePageEvent>();
  onSort = output<any>();
  onFilter = output<TableFilterEvent>();
  onRowSelect = output<TableRowSelectEvent>();
  onRowUnselect = output<any>();
  onSelectAllChange = output<any>();
  onRowReorder = output<TableRowReorderEvent>();
  onRowExpand = output<TableRowExpandEvent>();
  onRowCollapse = output<TableRowCollapseEvent>();
  onContextMenuSelect = output<any>();
  onColReorder = output<any>();
  onColResize = output<any>();
  onEditInit = output<any>();
  onEditComplete = output<any>();
  onEditCancel = output<any>();
  onHeaderCheckboxToggle = output<any>();
  onStateSave = output<any>();
  onStateRestore = output<any>();

  // Computed properties with defaults merged from TABLE_DEFAULTS
  computedProps = computed(() => {
    return computedTableProps(this.props());
  });
  getTotalColumns() {
    return computeTotalCols(this.computedProps(), this.cols());
  }


  handleClickRow(rowData: any) {
    this._currentSelectedRow = rowData;
    this.computedProps().isClickRecord && this.onClickRecord.emit(this._currentSelectedRow);
  }

  getTableActiveRowClass(rowData: any) {
    return (this._currentSelectedRow && this._currentSelectedRow === rowData ||
      (this._currentSelectedRow && this._currentSelectedRow[this.computedProps().dataKey] === rowData?.[this.computedProps().dataKey])) &&
      this.computedProps().isClickRecord;
  }
}
