import { Component, input, output, model, forwardRef, ChangeDetectionStrategy } from '@angular/core';

import { FormsModule, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import { InputMaskModule } from 'primeng/inputmask';
import { InputMaskVariant, InputMaskSize } from './cmm-inputmask.types';
import { INPUTMASK_DEFAULTS } from './cmm-inputmask.constants';

@Component({
  selector: 'cmm-inputmask',
  standalone: true,
  imports: [FormsModule, InputMaskModule],
  template: `
    <p-inputMask
      [(ngModel)]="value"
      [mask]="mask()"
      [slotChar]="slotChar()"
      [autoClear]="autoClear()"
      [unmask]="unmask()"
      [disabled]="disabled()"
      [readonly]="readonly()"
      [variant]="variant()"
      [placeholder]="placeholder()!"
      [style]="style() ?? undefined"
      [styleClass]="styleClass()!"
      [ariaLabel]="ariaLabel()!"
      [ariaLabelledBy]="ariaLabelledBy()!"
      [autofocus]="autofocus()"
      (onComplete)="handleComplete($event)"
      (onFocus)="onFocus.emit($event)"
      (onBlur)="handleBlur($event)"
      (onInput)="handleInput($event)"
    />
  `,
  styleUrl: './cmm-inputmask.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmInputmaskComponent),
      multi: true,
    },
  ],
})
export class CmmInputmaskComponent implements ControlValueAccessor {
  // Model
  value = model<string>('');

  // Core props
  mask = input.required<string>();
  slotChar = input<string>(INPUTMASK_DEFAULTS.SLOT_CHAR);
  autoClear = input<boolean>(INPUTMASK_DEFAULTS.AUTOCLR);
  unmask = input<boolean>(INPUTMASK_DEFAULTS.UNMASK);
  disabled = input<boolean>(INPUTMASK_DEFAULTS.DISABLED);
  readonly = input<boolean>(INPUTMASK_DEFAULTS.READONLY);
  variant = input<InputMaskVariant>(INPUTMASK_DEFAULTS.VARIANT);
  size = input<InputMaskSize>();
  placeholder = input<string>();
  style = input<Record<string, any>>();
  styleClass = input<string>();
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();
  autofocus = input<boolean>(INPUTMASK_DEFAULTS.AUTOFOCUS);

  // Output events
  onComplete = output<Event>();
  onFocus = output<Event>();
  onBlur = output<Event>();
  onInput = output<Event>();

  // ControlValueAccessor
  private onChangeFn: (value: string) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: string): void {
    this.value.set(value || '');
  }

  registerOnChange(fn: (value: string) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handle if needed
  }

  handleComplete(event: Event): void {
    this.onComplete.emit(event);
    this.onChangeFn(this.value());
  }

  handleInput(event: Event): void {
    this.onInput.emit(event);
    this.onChangeFn(this.value());
  }

  handleBlur(event: Event): void {
    this.onBlur.emit(event);
    this.onTouchedFn();
  }
}
