import { inject, Injectable } from '@angular/core';
import { HttpClient, HttpErrorResponse, HttpEvent, HttpEventType } from '@angular/common/http';
import {
  BehaviorSubject, catchError,
  concat, delay, filter, finalize, from, map, mergeMap, Observable, of, switchMap, takeWhile, tap, timer
} from 'rxjs';
import {resolveFileName} from '../utils/file-name-resolver';
import {DownloadProgress, DownloadRequest, DownloadState} from '../modal/download-manager.type';
import {DOWNLOAD_MANAGER_CONFIG} from '../config/download-manager.config';
import {DownloadTransportInterface} from '../download-transport.interface';


@Injectable()
export class SyncBlobTransportService extends DownloadTransportInterface {
  // Raw HttpClient — NOT the AppHttpApiService wrapper.
  private readonly http = inject(HttpClient);

  private readonly config = inject(DOWNLOAD_MANAGER_CONFIG);

  // A map of BehaviorSubject to control pause/resume for each active download
  private readonly pausedSubjects = new Map<string, BehaviorSubject<boolean>>();

  private getOrCreatePausedSubject(id: string): BehaviorSubject<boolean> {
    let subject = this.pausedSubjects.get(id);
    if (!subject) {
      subject = new BehaviorSubject<boolean>(false);
      this.pausedSubjects.set(id, subject);
    }
    return subject;
  }

  override pause(id: string): void {
    const subject = this.pausedSubjects.get(id);
    if (subject) {
      subject.next(true);
    }
  }


  override resume(id: string): void {
    const subject = this.pausedSubjects.get(id);
    if (subject) {
      subject.next(false);
    }
  }

  override cancel(id: string): void {
    const subject = this.pausedSubjects.get(id);
    if (subject) {
      subject.complete();
      this.pausedSubjects.delete(id);
    }
  }

  start(id: string, req: DownloadRequest): Observable<DownloadProgress> {
    const { method, url, body, fileNameFallback } = req;

    // `req.url` is already the full, resolved endpoint.
    return this.http
      .request(method, url, {
        body,
        responseType: 'blob', // export is octet-stream, not JSON
        observe: 'events', // stream EVERY event, not just the final body
        reportProgress: true, // include the DownloadProgress ticks
        context: this.config.httpContext,
      })
      .pipe(
        // 1:1 transform. Events we don't care about become `null` and are filtered out.
        map((event: HttpEvent<Blob>): DownloadProgress | null => {
          switch (event.type) {
            // Request dispatched, no bytes yet → the "load icon" moment.
            case HttpEventType.Sent:
              // Emit waiting state immediately when request is dispatched
              return { id, fileName: fileNameFallback, state: DownloadState.Waiting };

            // Final response → resolve the real filename, SAVE the blob, emit Completed.
            case HttpEventType.Response: {
              const fileName = resolveFileName(event.headers.get('Content-Disposition'), fileNameFallback);
              const totalHeader = event.headers.get('Content-Length');
              const totalBytes = totalHeader ? Number.parseInt(totalHeader, 10) : event.body?.size || 0;
              const blob = event.body || undefined;
              return {
                id,
                fileName,
                state: DownloadState.Waiting,
                percent: 0,
                loadedBytes: 0,
                totalBytes,
                _blob: blob,
              };
            }

            // Other events (including HttpEventType.DownloadProgress) are ignored during the API call
            default:
              return null;
          }
        }),
        mergeMap((p: DownloadProgress | null): Observable<DownloadProgress | null> => {
          if (!p) {
            return of(p);
          }

          // Start simulated progress when we receive the waiting state (after the response).
          if (p.state === DownloadState.Waiting && p._blob) {
            const totalBytes = p.totalBytes ?? 0;
            const fileName = p.fileName;

            const initial: Observable<DownloadProgress> = of(p);

            const tickIntervalMs = this.config.progressDurationMs / 100;

            const simulation: Observable<DownloadProgress> = of(null).pipe(
              delay(this.config.delayBeforeDownloadMs),
              switchMap(() => {
                const paused = this.getOrCreatePausedSubject(id);
                // `step` lives in this closure so it survives pause/resume cycles:
                // pausing freezes it, resuming keeps ticking from where it stopped.
                let step = 0;

                return paused.pipe(
                  // Paused → emit ONE frozen snapshot (no ticking). Resumed → resume the
                  // 1%-per-tick timer. switchMap tears down the previous branch on toggle.
                  switchMap((isPaused) =>
                    isPaused ? of('paused' as const) : timer(0, tickIntervalMs).pipe(map(() => 'tick' as const)),
                  ),
                  map((kind): DownloadProgress => {
                    if (kind === 'tick') {
                      step += 1;
                    }
                    const state =
                      kind === 'paused'
                        ? DownloadState.Paused
                        : step >= 100
                          ? DownloadState.Completed
                          : DownloadState.Downloading;
                    return {
                      id,
                      fileName,
                      state,
                      percent: step,
                      loadedBytes: Math.round((totalBytes * step) / 100),
                      totalBytes,
                      _blob: p._blob,
                    };
                  }),
                  // Emit the Completed event (inclusive), then end the stream — this also
                  // tears down the timer so no further ticks fire past 100%.
                  takeWhile((progress) => progress.state !== DownloadState.Completed, true),
                );
              }),
            );

            return concat(initial, simulation);
          }
          // Pass through initial Sent event
          return of(p);
        }),
        filter((p: DownloadProgress | null): p is DownloadProgress => p !== null),
        // download when progress is 100% completed
        tap((p: DownloadProgress) => {
          if (p.state === DownloadState.Completed && p._blob) {
            this.triggerExportFile(p._blob, p.fileName);
          }
        }),
        catchError((err: HttpErrorResponse) => this.toErrorProgress(err, id, fileNameFallback)),
        finalize(() => {
          this.pausedSubjects.delete(id);
        }),
      );
  }

  /**
   * Chuyển đổi lỗi HTTP nhận được thành luồng thông tin lỗi DownloadProgress để giao diện hiển thị.
   * - Nếu lỗi kết nối (status = 0), trả về thông báo lỗi "Internet error".
   * - Nếu lỗi từ Server, trích xuất thông điệp lỗi JSON từ Blob/Text để hiển thị cụ thể lỗi cho người dùng.
   */
  private toErrorProgress(err: HttpErrorResponse, id: string, fileName: string): Observable<DownloadProgress> {
    if (err.status === 0) {
      return of({ id, fileName, state: DownloadState.Error, errorMsg: 'Internet error' });
    }

    const read =
      err.error instanceof Blob ? from(err.error.text()) : of(typeof err.error === 'string' ? err.error : '');

    return read.pipe(
      map((text): DownloadProgress => {
        let errorMsg = err.message;
        let resolvedFileName = fileName;
        let fileType: string | undefined;
        try {
          const json = JSON.parse(text);
          errorMsg = json?.message ?? json?.error ?? errorMsg;
          if (json?.fileName) {
            resolvedFileName = json.fileName;
          }
          if (json?.fileType) {
            fileType = json.fileType;
          }
        } catch {
          if (text) {
            errorMsg = text;
          }
        }
        return { id, fileName: resolvedFileName, state: DownloadState.Error, errorMsg, fileType };
      }),
    );
  }
}
