import { Component, input, ChangeDetectionStrategy } from '@angular/core';

import { TooltipModule } from 'primeng/tooltip';
import { TooltipPosition, TooltipEvent } from './cmm-tooltip.types';
import { CMM_TOOLTIP_DEFAULTS } from './cmm-tooltip.constants';

@Component({
  selector: 'cmm-tooltip',
  standalone: true,
  imports: [TooltipModule],
  template: `
    <div
      [pTooltip]="text()"
      [tooltipPosition]="position()"
      [tooltipEvent]="event()"
      [showDelay]="showDelay()"
      [hideDelay]="hideDelay()"
      [autoHide]="autoHide()"
      [escape]="escape()"
      [hideOnEscape]="hideOnEscape()"
      [fitContent]="fitContent()"
      [tooltipStyleClass]="tooltipStyleClass()!"
      [tooltipDisabled]="disabled()"
    >
      <ng-content />
    </div>
  `,
  styleUrl: './cmm-tooltip.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmTooltipComponent {
  // Core props
  text = input.required<string>();
  position = input<TooltipPosition>('top');
  event = input<TooltipEvent>('hover');
  showDelay = input<number>(0);
  hideDelay = input<number>(0);
  autoHide = input<boolean>(CMM_TOOLTIP_DEFAULTS.AUTO_HIDE);
  escape = input<boolean>(CMM_TOOLTIP_DEFAULTS.ESCAPE);
  hideOnEscape = input<boolean>(CMM_TOOLTIP_DEFAULTS.HIDE_ON_ESCAPE);
  fitContent = input<boolean>(CMM_TOOLTIP_DEFAULTS.FIT_CONTENT);
  tooltipStyleClass = input<string>();
  disabled = input<boolean>(false);
}
