/**
 * Validation Library - Public API
 * 
 * Import directives with auto-loaded styles (like PrimeNG)
 * 
 * @example Standalone Component
 * ```typescript
 * import { ValidationDirective, InputRestrictDirective } from '@validations';
 * 
 * @Component({
 *   standalone: true,
 *   imports: [ValidationDirective, InputRestrictDirective]
 * })
 * export class MyComponent {}
 * ```
 * 
 * @example Module-based
 * ```typescript
 * import { ValidationModule } from '@validations';
 * 
 * @NgModule({
 *   imports: [ValidationModule]
 * })
 * export class MyModule {}
 * ```
 */

export * from './styles/validation.style'
export {InputRestrictBaseDirective} from './core/input-restrict.directive';
export {ValidationBaseDirective} from './core/validation.directive';
export {InputRestrictDirective} from './directives/input-restrict.directive.wrapper';
// Directive exports (standalone) - export wrappers, not core
export { ValidationDirective } from './directives/validation.directive';
export { ValidationErrorComponent } from './components/validation-error.component';

// Core service & utilities
export { ValidationService } from './core/validation.service';
export { ValidationUtils } from './core/validation.util';
export { CharPatterns, InputPatterns, InputValidators } from './core/input-patterns.const';
export { InputFormatters, FormatPatterns } from './core/input-formatters.const';
export * from './core/utils/validation-field.util';

// Messages - constants, tokens, and providers
export * from './core/messages/public-api';



// Module export
export { ValidationModule } from './validation.module';
