import {
  Component,
  input,
  output,
  model,
  forwardRef,
  ChangeDetectionStrategy,
  contentChild,
  TemplateRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import {
  ListboxModule,
  ListboxChangeEvent,
  ListboxFilterEvent,
  ListboxClickEvent,
  ListboxDoubleClickEvent,
} from 'primeng/listbox';
import { ListboxVariant, ListboxFilterMatchMode } from './cmm-listbox.types';
import { LISTBOX_DEFAULTS } from './cmm-listbox.constants';

@Component({
  selector: 'cmm-listbox',
  standalone: true,
  imports: [CommonModule, FormsModule, ListboxModule],
  template: `
    <p-listbox
      [(ngModel)]="value"
      [options]="options()"
      [optionLabel]="optionLabel()"
      [optionValue]="optionValue()"
      [optionDisabled]="optionDisabled()"
      [optionGroupLabel]="optionGroupLabel()"
      [optionGroupChildren]="optionGroupChildren()"
      [group]="group()"
      [disabled]="disabled()"
      [readonly]="readonly()"
      [multiple]="multiple()"
      [checkbox]="checkbox()"
      [filter]="filter()"
      [filterMatchMode]="filterMatchMode()"
      [filterPlaceHolder]="filterPlaceHolder()!"
      [filterLocale]="filterLocale()!"
      [listStyle]="listStyle() ?? undefined"
      [listStyleClass]="listStyleClass()!"
      [style]="style() ?? undefined"
      [styleClass]="styleClass()!"
      [ariaLabel]="ariaLabel()!"
      [emptyMessage]="emptyMessage()!"
      [emptyFilterMessage]="emptyFilterMessage()!"
      [striped]="striped()"
      [showToggleAll]="showToggleAll()"
      [filterBy]="filterBy()!"
      [dataKey]="dataKey()!"
      (onChange)="handleChange($event)"
      (onFilter)="handleFilter($event)"
      (onClick)="handleClick($event)"
      (onDblClick)="handleDoubleClick($event)"
      (onFocus)="onFocus.emit($event)"
      (onBlur)="onBlur.emit($event)"
    >
      @if (itemTemplate()) {
        <ng-template pTemplate="item" let-item let-index="index">
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item, index: index }" />
        </ng-template>
      }
      @if (groupTemplate()) {
        <ng-template pTemplate="group" let-group>
          <ng-container *ngTemplateOutlet="groupTemplate()!; context: { $implicit: group }" />
        </ng-template>
      }
      @if (headerTemplate()) {
        <ng-template pTemplate="header">
          <ng-container *ngTemplateOutlet="headerTemplate()!" />
        </ng-template>
      }
      @if (footerTemplate()) {
        <ng-template pTemplate="footer">
          <ng-container *ngTemplateOutlet="footerTemplate()!" />
        </ng-template>
      }
      @if (emptyTemplate()) {
        <ng-template pTemplate="empty">
          <ng-container *ngTemplateOutlet="emptyTemplate()!" />
        </ng-template>
      }
      @if (emptyFilterTemplate()) {
        <ng-template pTemplate="emptyfilter">
          <ng-container *ngTemplateOutlet="emptyFilterTemplate()!" />
        </ng-template>
      }
    </p-listbox>
  `,
  styleUrl: './cmm-listbox.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmListboxComponent),
      multi: true,
    },
  ],
})
export class CmmListboxComponent implements ControlValueAccessor {
  // Model
  value = model<any | any[]>();

  // Content children templates
  itemTemplate = contentChild<TemplateRef<any>>('item');
  groupTemplate = contentChild<TemplateRef<any>>('group');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  emptyTemplate = contentChild<TemplateRef<any>>('empty');
  emptyFilterTemplate = contentChild<TemplateRef<any>>('emptyFilter');

  // Core props
  options = input<any[]>([]);
  optionLabel = input<string>(LISTBOX_DEFAULTS.OPTION_LABEL);
  optionValue = input<string>(LISTBOX_DEFAULTS.OPTION_VALUE);
  optionDisabled = input<string>(LISTBOX_DEFAULTS.OPTION_DISABLED);
  optionGroupLabel = input<string>(LISTBOX_DEFAULTS.OPTION_GROUP_LABEL);
  optionGroupChildren = input<string>(LISTBOX_DEFAULTS.OPTION_GROUP_CHILDREN);
  group = input<boolean>(false);
  disabled = input<boolean>(LISTBOX_DEFAULTS.DISABLED);
  readonly = input<boolean>(LISTBOX_DEFAULTS.READONLY);
  multiple = input<boolean>(LISTBOX_DEFAULTS.MULTIPLE);
  checkbox = input<boolean>(LISTBOX_DEFAULTS.CHECKBOX);
  filter = input<boolean>(LISTBOX_DEFAULTS.FILTER);
  filterMatchMode = input<ListboxFilterMatchMode>(LISTBOX_DEFAULTS.FILTER_MATCH_MODE);
  filterPlaceHolder = input<string>();
  filterLocale = input<string>();
  variant = input<ListboxVariant>(LISTBOX_DEFAULTS.VARIANT);
  listStyle = input<Record<string, any>>();
  listStyleClass = input<string>();
  style = input<Record<string, any>>();
  styleClass = input<string>();
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();
  emptyMessage = input<string>();
  emptyFilterMessage = input<string>();
  striped = input<boolean>(LISTBOX_DEFAULTS.STRIPED);
  showToggleAll = input<boolean>(LISTBOX_DEFAULTS.SHOW_TOGGLE_ALL);
  filterBy = input<string>();
  dataKey = input<string>();

  // Output events
  onChange = output<ListboxChangeEvent>();
  onFilter = output<ListboxFilterEvent>();
  onClick = output<ListboxClickEvent>();
  onDblClick = output<ListboxDoubleClickEvent>();
  onFocus = output<Event>();
  onBlur = output<Event>();

  // ControlValueAccessor
  private onChangeFn: (value: any) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: any): void {
    this.value.set(value);
  }

  registerOnChange(fn: (value: any) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handle if needed
  }

  handleChange(event: ListboxChangeEvent): void {
    this.onChange.emit(event);
    this.onChangeFn(event.value);
  }

  handleFilter(event: ListboxFilterEvent): void {
    this.onFilter.emit(event);
  }

  handleClick(event: ListboxClickEvent): void {
    this.onClick.emit(event);
  }

  handleDoubleClick(event: ListboxDoubleClickEvent): void {
    this.onDblClick.emit(event);
  }
}
