import { Renderer2 } from '@angular/core';
import { AbstractControl } from '@angular/forms';
import { ValidationDisplayMode } from '../validation.directive';

/**
 * Validation Styler Helper
 * Single Responsibility: Handle CSS classes and inline styles for validation states
 */
export class ValidationStylerHelper {
  /**
   * Update CSS classes based on validation state
   */
  static updateClasses(
    renderer: Renderer2,
    inputElement: HTMLElement,
    wrapperElement: HTMLElement | undefined,
    control: AbstractControl,
    displayMode: ValidationDisplayMode,
    showValidation: boolean | undefined,
    errorClass: string
  ): void {
    // Remove all validation classes
    ValidationStylerHelper.removeClasses(renderer, inputElement, wrapperElement, errorClass);
    
    if (!control) return;

    const shouldApplyClasses = ValidationStylerHelper.shouldApplyValidation(
      control,
      displayMode,
      showValidation
    );

    if (shouldApplyClasses) {
      if (control.valid) {
        ValidationStylerHelper.applyValidClasses(renderer, inputElement, wrapperElement);
      } else {
        ValidationStylerHelper.applyInvalidClasses(renderer, inputElement, wrapperElement, errorClass);
      }
    }
  }

  /**
   * Update inline styles for PrimeNG components
   */
  static updateInlineStyles(
    renderer: Renderer2,
    nativeElement: HTMLElement,
    primengInnerElement: HTMLElement | undefined,
    control: AbstractControl | undefined | null,
    displayMode: ValidationDisplayMode,
    showValidation: boolean | undefined
  ): void {
    // Remove existing styles
    ValidationStylerHelper.removeInlineStyles(renderer, nativeElement, primengInnerElement);
    
    if (!control) return;

    const shouldStyle = ValidationStylerHelper.shouldApplyValidation(
      control,
      displayMode,
      showValidation
    );

    if (shouldStyle) {
      const targetElement = primengInnerElement || nativeElement;
      
      if (control.valid) {
        // renderer.setStyle(targetElement, 'border-color', validBorderColor);
        renderer.removeStyle(targetElement, 'box-shadow');
      } else {
        /**
         * TODO: Fix box-shadow for PrimeNG components
         */
        // renderer.setStyle(targetElement, 'border-color', invalidBorderColor);
        // renderer.setStyle(
        //   targetElement,
        //   'box-shadow',
        //   `0 0 0 0.2rem ${invalidBorderColor}25`
        // );
      }
    }
  }

  /**
   * Remove inline styles
   */
  static removeInlineStyles(
    renderer: Renderer2,
    nativeElement: HTMLElement,
    primengInnerElement: HTMLElement | undefined
  ): void {
    if (primengInnerElement) {
      renderer.removeStyle(primengInnerElement, 'border-color');
      renderer.removeStyle(primengInnerElement, 'box-shadow');
    }
    
    renderer.removeStyle(nativeElement, 'border-color');
    renderer.removeStyle(nativeElement, 'box-shadow');
  }

  /**
   * Determine if validation should be applied based on display mode
   */
  private static shouldApplyValidation(
    control: AbstractControl,
    displayMode: ValidationDisplayMode,
    showValidation: boolean | undefined
  ): boolean {
    switch (displayMode) {
      case 'touched':
        return control.touched;
      case 'dirty':
        return control.dirty;
      case 'always':
        return true;
      case 'submit':
      case 'custom':
        return !!showValidation;
      default:
        return control.touched;
    }
  }

  /**
   * Remove all validation classes
   */
  private static removeClasses(
    renderer: Renderer2,
    inputElement: HTMLElement,
    wrapperElement: HTMLElement | undefined,
    errorClass: string
  ): void {
    // Only remove custom classes, not Angular's native classes
    // Angular manages ng-invalid, ng-valid, ng-touched, ng-dirty automatically
    const classesToRemove = [
      'is-valid',
      'is-invalid',
      errorClass,
    ];

    classesToRemove.forEach(cls => {
      renderer.removeClass(inputElement, cls);
      if (wrapperElement) {
        renderer.removeClass(wrapperElement, cls);
      }
    });
  }

  /**
   * Apply valid state classes
   */
  private static applyValidClasses(
    renderer: Renderer2,
    inputElement: HTMLElement,
    wrapperElement: HTMLElement | undefined
  ): void {
    // Only add custom classes - Angular already manages ng-valid
    renderer.addClass(inputElement, 'is-valid');
    if (wrapperElement) {
      renderer.addClass(wrapperElement, 'is-valid');
    }
  }

  /**
   * Apply invalid state classes
   */
  private static applyInvalidClasses(
    renderer: Renderer2,
    inputElement: HTMLElement,
    wrapperElement: HTMLElement | undefined,
    errorClass: string
  ): void {
    // Only add custom classes - Angular already manages ng-invalid, ng-touched, ng-dirty
    renderer.addClass(inputElement, 'is-invalid');
    renderer.addClass(inputElement, errorClass);
    
    // Add classes to PrimeNG wrapper (p-select, p-datepicker, etc.) for CSS selectors to work
    if (wrapperElement) {
      renderer.addClass(wrapperElement, 'is-invalid');
    }
  }
}
