import {
  Component,
  input,
  output,
  model,
  viewChild,
  contentChild,
  TemplateRef,
  ChangeDetectionStrategy,
  forwardRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { Editor, EditorModule } from 'primeng/editor';
import { NG_VALUE_ACCESSOR, ControlValueAccessor, FormsModule } from '@angular/forms';
import { EDITOR_DEFAULTS } from './cmm-editor.constants';

@Component({
  selector: 'cmm-editor',
  standalone: true,
  imports: [CommonModule, EditorModule, FormsModule],
  template: `
    <p-editor
      #editor
      [(ngModel)]="value"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined"
      [placeholder]="placeholder()"
      [formats]="formats() ?? undefined"
      [modules]="modules() ?? undefined"
      [bounds]="bounds() ?? undefined"
      [scrollingContainer]="scrollingContainer() ?? undefined"
      [debug]="debug() ?? undefined"
      [readonly]="readonly()"
      (onTextChange)="handleTextChange($event)"
      (onSelectionChange)="onSelectionChange.emit($event)"
      (onInit)="onInit.emit($event)">
      @if (headerTemplate()) {
        <ng-template pTemplate="header">
          <ng-container *ngTemplateOutlet="headerTemplate()!" />
        </ng-template>
      }
    </p-editor>
  `,
  styleUrl: './cmm-editor.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmEditorComponent),
      multi: true,
    },
  ],
})
export class CmmEditorComponent implements ControlValueAccessor {
  editor = viewChild<Editor>('editor');

  // Core props
  value = model<any>();
  style = input<Record<string, any>>();
  styleClass = input<string>();
  placeholder = input<string>(EDITOR_DEFAULTS.PLACEHOLDER);
  formats = input<string[]>();
  modules = input<any>();
  bounds = input<HTMLElement>();
  scrollingContainer = input<HTMLElement | string>();
  debug = input<string>();
  readonly = input<boolean>(EDITOR_DEFAULTS.READONLY);
  showHeader = input<boolean>(EDITOR_DEFAULTS.SHOW_HEADER);

  // Templates
  headerTemplate = contentChild<TemplateRef<any>>('header');

  // Events
  onTextChange = output<any>();
  onSelectionChange = output<any>();
  onInit = output<any>();

  // CVA implementation
  private onChangeFn: (value: any) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: any): void {
    this.value.set(value);
  }

  registerOnChange(fn: (value: any) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handled by readonly input
  }

  handleTextChange(event: any): void {
    this.onChangeFn(event.htmlValue);
    this.onTextChange.emit(event);
  }

  // Public methods
  getQuill(): any {
    return this.editor()?.getQuill();
  }
}
