import { Component, ChangeDetectionStrategy, input, output, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Image } from 'primeng/image';
import type { SafeUrl } from '@angular/platform-browser';

@Component({
  selector: 'cmm-image',
  standalone: true,
  imports: [CommonModule, Image],
  templateUrl: './cmm-image.component.html',
  styleUrl: './cmm-image.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmImageComponent {
  // Input properties
  readonly imageClass = input<string>();
  readonly imageStyle = input<Record<string, any>>();
  readonly styleClass = input<string>('');
  readonly style = input<Record<string, any>>();
  readonly src = input<string | SafeUrl>();
  readonly srcSet = input<string | SafeUrl>();
  readonly sizes = input<string>();
  readonly previewImageSrc = input<string | SafeUrl>();
  readonly previewImageSrcSet = input<string | SafeUrl>();
  readonly previewImageSizes = input<string>();
  readonly alt = input<string>();
  readonly imageWidth = input<string>(undefined, { alias: 'width' });
  readonly imageHeight = input<string>(undefined, { alias: 'height' });
  readonly imageLoading = input<'lazy' | 'eager'>(undefined, { alias: 'loading' });
  readonly appendTo = input<unknown>('body');
  readonly preview = input<boolean>(false);
  readonly showTransitionOptions = input<string>('150ms cubic-bezier(0, 0, 0.2, 1)');
  readonly hideTransitionOptions = input<string>('150ms cubic-bezier(0, 0, 0.2, 1)');

  // Output events
  readonly onShow = output<any>();
  readonly onHide = output<any>();
  readonly onImageError = output<Event>();

  // Template references
  readonly indicatorTemplate = contentChild<TemplateRef<any>>('indicator');
  readonly rotateRightIconTemplate = contentChild<TemplateRef<any>>('rotaterighticon');
  readonly rotateLeftIconTemplate = contentChild<TemplateRef<any>>('rotatelefticon');
  readonly zoomOutIconTemplate = contentChild<TemplateRef<any>>('zoomouticon');
  readonly zoomInIconTemplate = contentChild<TemplateRef<any>>('zoominicon');
  readonly closeIconTemplate = contentChild<TemplateRef<any>>('closeicon');
  readonly previewTemplate = contentChild<TemplateRef<any>>('preview');
  readonly imageTemplate = contentChild<TemplateRef<any>>('image');
}
