
import {
  Directive,
  ElementRef,
  Input,
  Output,
  EventEmitter,
  OnInit,
  OnDestroy,
  AfterViewInit,
  Renderer2,
  inject,
  ChangeDetectorRef,
  booleanAttribute,
  numberAttribute,
  afterNextRender
} from '@angular/core';
import { fromEvent, Subject, debounceTime, takeUntil } from 'rxjs';

import { CmmTextEllipsisService } from '../services/text-ellipsis.service';
import { UBCKCustomTypographyStyles } from '../styles/typography.style';
import { BaseComponent } from 'primeng/basecomponent';
@Directive({
  selector: '[cmmEllipsis]',
  standalone: true,
  host: {
    '[class.ellipsis-container]': 'true',
    '[class.ellipsis-active]': 'isEllipsis',
    '[class.ellipsis-expanded]': 'expanded'
  },
  providers: [UBCKCustomTypographyStyles],
  exportAs: 'cmmEllipsis'
})
export class CmmEllipsisDirective extends BaseComponent implements OnInit, OnDestroy {
  _componentStyle = inject(UBCKCustomTypographyStyles)

  private measureService = inject(CmmTextEllipsisService);
  private cdr = inject(ChangeDetectorRef);
  private destroy$ = new Subject<void>();

  // Inputs
  @Input({ transform: booleanAttribute }) appEllipsis = false;
  @Input({ transform: numberAttribute }) ellipsisRows = 1;
  @Input({ transform: booleanAttribute }) ellipsisExpandable = false;
  @Input() ellipsisSuffix = '';
  @Input() ellipsisSymbol = '...';

  // Outputs
  @Output() ellipsisChange = new EventEmitter<boolean>();

  // State
  isEllipsis = false;
  expanded = false;
  originalContent = '';
  clampedContent = '';
  expandButton: HTMLElement | null = null;

  // CSS-based ellipsis support
  private supportsCssEllipsis = false;

  constructor() {
    super();
    afterNextRender({
      read: () => {
        // Store original content
        this.originalContent = this.el.nativeElement.textContent || '';
        if (!this.appEllipsis) return;

        // Initial check
        this.checkAndApplyEllipsis();

        // Watch for resize events
        fromEvent(window, 'resize')
          .pipe(
            debounceTime(200),
            takeUntil(this.destroy$)
          )
          .subscribe(() => {
            if (!this.expanded) {
              this.checkAndApplyEllipsis();
            }
          });
      }
    });
  }

  override ngOnInit(): void {
    super.ngOnInit();
    // Check if browser supports CSS ellipsis
    this.supportsCssEllipsis = this.checkCssEllipsisSupport();
  }



  override ngOnDestroy(): void {
    super.ngOnDestroy();
    this.destroy$.next();
    this.destroy$.complete();
    this.removeExpandButton();
  }

  /**
   * Check if CSS-based ellipsis is supported and can be used
   */
  private checkCssEllipsisSupport(): boolean {
    if (this.ellipsisExpandable) {
      // Can't use CSS ellipsis if expandable (need JS control)
      return false;
    }

    if (this.ellipsisRows === 1) {
      // Single line: text-overflow: ellipsis
      return 'textOverflow' in document.documentElement.style;
    }
    // Multi-line: -webkit-line-clamp
    return 'webkitLineClamp' in document.documentElement.style;
  }

  /**
   * Main logic: check if text is clamped and apply ellipsis
   */
  private checkAndApplyEllipsis(): void {
    const element = this.el.nativeElement;

    // Use CSS-based ellipsis if possible (more performant)
    if (this.supportsCssEllipsis && !this.ellipsisExpandable) {
      this.applyCssEllipsis();
      return;
    }

    // Use JS-based ellipsis for complex cases
    this.applyJsEllipsis();
  }

  /**
   * Apply CSS-based ellipsis (most performant)
   */
  private applyCssEllipsis(): void {
    const element = this.el.nativeElement as HTMLDivElement; 
    if (this.ellipsisRows) {
      element.style.display = '-webkit-box';
      element.style.webkitBoxOrient = 'vertical';
      element.style.webkitLineClamp = this.ellipsisRows.toString();
      // Add Mozilla prefix for Firefox compatibility
      (element.style as any).MozBoxOrient = 'vertical';
      // Add Microsoft prefix for older Edge versions
      (element.style as any).msBoxOrient = 'vertical';
      element.style.overflow = 'hidden';
      element.style.wordBreak = 'break-word';
      element.style.textOverflow = 'ellipsis';
      element.style.whiteSpace = 'pre-wrap';
    }

    // Check if actually clamped (for callback)
    // Use the correct method that checks element dimensions, not text width
    const isClamped = this.measureService.hasEllipsis(element, this.ellipsisRows);
    if (isClamped !== this.isEllipsis) {
      this.isEllipsis = isClamped;
      this.ellipsisChange.emit(this.isEllipsis);
    }
    // Set title tooltip only if text is actually ellipsized
    if(isClamped) {
        this.renderer.setProperty(element, 'title',  this.originalContent);
    }
   
  }

  /**
   * Apply JS-based ellipsis (for expandable or complex cases)
   */
  private applyJsEllipsis(): void {
    const element = this.el.nativeElement;
    const { isClamped, clampedText } = this.measureService.measureText(
      element,
      this.ellipsisRows,
      this.originalContent,
      this.ellipsisSuffix
    );

    if (isClamped) {
      this.isEllipsis = true;
      this.clampedContent = clampedText;

      // Apply clamped text
      element.textContent = clampedText + this.ellipsisSymbol + this.ellipsisSuffix;

      // Add expand button if needed
      if (this.ellipsisExpandable) {
        this.addExpandButton();
      }
    } else {
      this.isEllipsis = false;
      element.textContent = this.originalContent + this.ellipsisSuffix;
    }

    this.ellipsisChange.emit(this.isEllipsis);
    this.cdr.markForCheck();
  }

  /**
   * Add "Expand" button
   */
  private addExpandButton(): void {
    if (this.expandButton) return;

    this.expandButton = this.renderer.createElement('a');
    this.renderer.addClass(this.expandButton, 'ellipsis-expand-btn');
    this.renderer.setProperty(this.expandButton, 'textContent', ' Expand');
    this.renderer.setStyle(this.expandButton, 'color', '#1890ff');
    this.renderer.setStyle(this.expandButton, 'cursor', 'pointer');
    this.renderer.setStyle(this.expandButton, 'margin-left', '4px');

    this.renderer.listen(this.expandButton, 'click', (e: Event) => {
      e.preventDefault();
      this.expand();
    });

    this.renderer.appendChild(this.el.nativeElement, this.expandButton);
  }

  /**
   * Remove expand button
   */
  private removeExpandButton(): void {
    if (this.expandButton && this.expandButton.parentNode) {
      this.renderer.removeChild(this.expandButton.parentNode, this.expandButton);
      this.expandButton = null;
    }
  }

  /**
   * Expand to show full content
   */
  expand(): void {
    this.expanded = true;
    const element = this.el.nativeElement;

    // Remove ellipsis styles
    this.renderer.removeStyle(element, 'overflow');
    this.renderer.removeStyle(element, 'text-overflow');
    this.renderer.removeStyle(element, 'white-space');
    this.renderer.removeStyle(element, 'display');
    this.renderer.removeStyle(element, '-webkit-box-orient');
    this.renderer.removeStyle(element, '-webkit-line-clamp');

    // Show full content
    element.textContent = this.originalContent + this.ellipsisSuffix;

    // Remove expand button
    this.removeExpandButton();

    // Optionally add "Collapse" button
    if (this.ellipsisExpandable) {
      this.addCollapseButton();
    }

    this.cdr.markForCheck();
  }

  /**
   * Add "Collapse" button
   */
  private addCollapseButton(): void {
    const collapseBtn = this.renderer.createElement('a');
    this.renderer.addClass(collapseBtn, 'ellipsis-collapse-btn');
    this.renderer.setProperty(collapseBtn, 'textContent', ' Collapse');
    this.renderer.setStyle(collapseBtn, 'color', '#1890ff');
    this.renderer.setStyle(collapseBtn, 'cursor', 'pointer');
    this.renderer.setStyle(collapseBtn, 'margin-left', '4px');

    this.renderer.listen(collapseBtn, 'click', (e: Event) => {
      e.preventDefault();
      this.collapse();
    });

    this.renderer.appendChild(this.el.nativeElement, collapseBtn);
    this.expandButton = collapseBtn; // Reuse variable for cleanup
  }

  /**
   * Collapse back to ellipsis
   */
  collapse(): void {
    this.expanded = false;
    this.removeExpandButton();
    this.checkAndApplyEllipsis();
  }
}