import { Component, input, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ScrollTopModule } from 'primeng/scrolltop';
import { ScrollTopTarget, ScrollTopBehavior } from './cmm-scrolltop.types';
import { SCROLLTOP_DEFAULTS } from './cmm-scrolltop.constants';

@Component({
  selector: 'cmm-scrolltop',
  standalone: true,
  imports: [CommonModule, ScrollTopModule],
  template: `
    <p-scrollTop
      [target]="target()"
      [threshold]="threshold()"
      [icon]="icon() ?? undefined"
      [behavior]="behavior()"
      [showTransitionOptions]="showTransitionOptions()"
      [hideTransitionOptions]="hideTransitionOptions()"
      [buttonAriaLabel]="buttonAriaLabel() ?? undefined"
      [buttonProps]="buttonProps() ?? undefined"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined">
      @if (iconTemplate()) {
        <ng-template pTemplate="icon" let-styleClass="styleClass">
          <ng-container *ngTemplateOutlet="iconTemplate()!; context: { styleClass: styleClass }" />
        </ng-template>
      }
    </p-scrollTop>
  `,
  styleUrl: './cmm-scrolltop.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmScrolltopComponent {
  // Core props
  target = input<ScrollTopTarget>(SCROLLTOP_DEFAULTS.TARGET);
  threshold = input<number>(SCROLLTOP_DEFAULTS.THRESHOLD);
  icon = input<string>();
  behavior = input<ScrollTopBehavior>(SCROLLTOP_DEFAULTS.BEHAVIOR);
  showTransitionOptions = input<string>(SCROLLTOP_DEFAULTS.SHOW_TRANSITION);
  hideTransitionOptions = input<string>(SCROLLTOP_DEFAULTS.HIDE_TRANSITION);
  buttonAriaLabel = input<string>();
  buttonProps = input<any>();
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Templates
  iconTemplate = contentChild<TemplateRef<any>>('icon');
}
