
import { CmmTypographyConfigService } from '../services/typography-config.service';
import {
  Directive,
  Input,
  Output,
  EventEmitter,
  HostBinding,
  OnInit,
  OnDestroy,
  booleanAttribute,
  inject,
} from '@angular/core';
import { CmmEllipsisDirective } from './text-ellipsis.directive';
import { CmmCopyableDirective } from './copyable.directive';
import { CmmEditableDirective } from './editable.directive';
import { BaseComponent } from 'primeng/basecomponent';
import { UBCKCustomTypographyStyles } from '../styles/typography.style';

@Directive({
  selector: '[cmmTypography]',
  standalone: true,
  hostDirectives: [
    {
      directive: CmmEllipsisDirective,
      inputs: [
        'appEllipsis: ellipsis',
        'ellipsisRows',
        'ellipsisExpandable',
        'ellipsisSuffix',
        'ellipsisSymbol',
      ],
      outputs: ['ellipsisChange'],
    },
    {
      directive: CmmCopyableDirective,
      inputs: ['appCopyable: copyable'],
      outputs: ['copy'],
    },
    {
      directive: CmmEditableDirective,
      inputs: ['appEditable: editable', 'disabled'],
      outputs: ['contentChange'],
    },
  ],
  host: {
    '[class.cmm-typography]': 'true',
    '[class.cmm-typography-copyable]': 'copyable',
    '[class.cmm-typography-ellipsis]': 'ellipsis',
    '[class.cmm-typography-disabled]': 'disabled',
  },
  providers: [UBCKCustomTypographyStyles],
  exportAs: 'cmmTypography'
})
export class CmmTypographyDirective extends BaseComponent implements OnInit, OnDestroy {

  protected configService = inject(CmmTypographyConfigService);
  _componentStyle = inject(UBCKCustomTypographyStyles);

  // Inputs
  @Input({ transform: booleanAttribute }) copyable = false;
  @Input({ transform: booleanAttribute }) editable = false;
  @Input({ transform: booleanAttribute }) disabled = false;
  @Input({ transform: booleanAttribute }) ellipsis = false;
  @Input() type:
    | 'default'
    | 'secondary'
    | 'success'
    | 'warning'
    | 'danger'
    | 'muted'
    | 'form-required' = 'default';

  // Outputs
  @Output() contentChange = new EventEmitter<string>();
  @Output() copy = new EventEmitter<string>();

  // Host bindings for type styling
  @HostBinding('class.cmm-typography-secondary') get isSecondary() {
    return this.type === 'secondary';
  }
  @HostBinding('class.cmm-typography-success') get isSuccess() {
    return this.type === 'success';
  }
  @HostBinding('class.cmm-typography-warning') get isWarning() {
    return this.type === 'warning';
  }
  @HostBinding('class.cmm-typography-danger') get isDanger() {
    return this.type === 'danger';
  }
  @HostBinding('class.cmm-typography-muted') get isMuted() {
    return this.type === 'muted';
  }
  @HostBinding('class.cmm-typography-form-required') get isFormRequired() {
    return this.type === 'form-required';
  }

  override ngOnInit(): void {
    super.ngOnInit();
    
    // Apply global config if not explicitly set
    const globalConfig = this.configService.getConfig();
    if (this.copyable === false && globalConfig.copyable) {
      this.copyable = globalConfig.copyable;
    }
  }

  override ngOnDestroy(): void {
    super.ngOnDestroy();
  }



  protected getTextContent(): string {
    return this.el.nativeElement.textContent || '';
  }
}
