import { inject, Injectable, Injector } from '@angular/core';
import { MessageService } from 'primeng/api';
import { ToastMessage, ToastOptions } from './toast.types';
import { ToastSeverity } from '../base/public-api';

@Injectable({
  providedIn: 'root',
})
export class ToastService {
  readonly injector = inject(Injector);
  /**
   * Show a success toast
   */
  success(summary: string, detail?: string, options?: ToastOptions): void {
    this.show({
      severity: 'success',
      summary,
      detail,
      ...options,
    });
  }

  /**
   * Show an info toast
   */
  info(summary: string, detail?: string, options?: ToastOptions): void {
    this.show({
      severity: 'info',
      summary,
      detail,
      ...options,
    });
  }

  /**
   * Show a warning toast
   */
  warn(summary: string, detail?: string, options?: ToastOptions): void {
    this.show({
      severity: 'warn',
      summary,
      detail,
      ...options,
    });
  }

  /**
   * Show an error toast
   */
  error(summary: string, detail?: string, options?: ToastOptions): void {
    this.show({
      severity: 'error',
      summary,
      detail,
      ...options,
    });
  }

  /**
   * Show a toast with avatar
   */
  withAvatar(severity: ToastSeverity, summary: string, detail: string, avatar: string, options?: ToastOptions): void {
    this.show({
      severity,
      summary,
      detail,
      data: {
        avatar,
        ...options?.data,
      },
      ...options,
    });
  }

  /**
   * Show a toast with custom icon
   */
  withIcon(severity: ToastSeverity, summary: string, detail: string, icon: string, options?: ToastOptions): void {
    this.show({
      severity,
      summary,
      detail,
      data: {
        customIcon: icon,
        ...options?.data,
      },
      ...options,
    });
  }

  /**
   * Show a toast with action button
   */
  withAction(
    severity: ToastSeverity,
    summary: string,
    detail: string,
    actionLabel: string,
    actionCallback: () => void,
    options?: ToastOptions,
  ): void {
    this.show({
      severity,
      summary,
      detail,
      data: {
        actionLabel,
        actionCallback,
        ...options?.data,
      },
      ...options,
    });
  }

  /**
   * Success toast with action button
   */
  successWithAction(
    summary: string,
    detail: string,
    actionLabel: string,
    actionCallback: () => void,
    options?: ToastOptions,
  ): void {
    this.withAction('success', summary, detail, actionLabel, actionCallback, options);
  }

  /**
   * Info toast with action button
   */
  infoWithAction(
    summary: string,
    detail: string,
    actionLabel: string,
    actionCallback: () => void,
    options?: ToastOptions,
  ): void {
    this.withAction('info', summary, detail, actionLabel, actionCallback, options);
  }

  /**
   * Error toast with action button
   */
  errorWithAction(
    summary: string,
    detail: string,
    actionLabel: string,
    actionCallback: () => void,
    options?: ToastOptions,
  ): void {
    this.withAction('error', summary, detail, actionLabel, actionCallback, options);
  }

  /**
   * Show a custom toast message with avatar and action
   */
  avatarWithAction(
    severity: ToastSeverity,
    summary: string,
    detail: string,
    avatar: string,
    actionLabel: string,
    actionCallback: () => void,
    options?: ToastOptions,
  ): void {
    this.show({
      severity,
      summary,
      detail,
      data: {
        avatar,
        actionLabel,
        actionCallback,
        ...options?.data,
      },
      ...options,
    });
  }

  /**
   * Generic show method
   */
  show(message: ToastMessage): void {
    const toastMessage: ToastMessage = {
      ...message,
      severity: message.severity,
      summary: message.summary,
      detail: message.detail,
      life: message.life,
      sticky: message.sticky,
      closable: message.closable ?? true,
      key: message.key,
      styleClass: message.styleClass,
      contentStyleClass: message.contentStyleClass,
      data: message.data,
      icon: message.icon,
    };

    this.injector.get(MessageService).add(toastMessage);
  }

  /**
   * Show multiple toasts
   */
  showAll(messages: ToastMessage[]): void {
    messages.forEach((message) => {
      this.show(message);
    });
  }

  /**
   * Clear all toasts or toasts with specific key
   */
  clear(key?: string): void {
    this.injector.get(MessageService).clear(key);
  }
}
