import { Component, ChangeDetectionStrategy, input } from '@angular/core';
import { ProgressSpinner } from 'primeng/progressspinner';

@Component({
  selector: 'cmm-progressspinner',
  standalone: true,
  imports: [ProgressSpinner],
  templateUrl: './cmm-progressspinner.component.html',
  styleUrl: './cmm-progressspinner.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmProgressSpinnerComponent {
  styleClass = input<string>('');
  style = input<Record<string, any>>();
  strokeWidth = input<string>('2');
  fill = input<string>('none');
  animationDuration = input<string>('2s');
  ariaLabel = input<string>();
}
