import { Component, ChangeDetectionStrategy, input, output, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Message } from 'primeng/message';

@Component({
  selector: 'cmm-message',
  standalone: true,
  imports: [CommonModule, Message],
  templateUrl: './cmm-message.component.html',
  styleUrl: './cmm-message.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmMessageComponent {
  severity = input<any>('info');
  text = input<string>();
  escape = input<boolean>(true);
  style = input<Record<string, any>>();
  styleClass = input<string>('');
  closable = input<boolean>(false);
  icon = input<string>();
  closeIcon = input<string>();
  showTransitionOptions = input<string>('300ms ease-out');
  hideTransitionOptions = input<string>('200ms cubic-bezier(0.86, 0, 0.07, 1)');
  size = input<'small' | 'large'>();
  variant = input<'text' | 'outlined' | 'simple'>();

  onClose = output<void>();

  iconTemplate = contentChild<TemplateRef<any>>('icon');
  closeIconTemplate = contentChild<TemplateRef<any>>('closeicon');
}
