import { Directive, ElementRef, Renderer2, afterNextRender, Injector, inject } from '@angular/core';

/**
 * CmmLayoutDirective - Main layout container
 *
 * Takes 100vh of viewport height and sets up flexbox container.
 * Should be the root container for the layout system.
 *
 * @example
 * ```html
 * <div cmmLayout>
 *   <div cmmHeader>Header content</div>
 *   <div cmmContent>
 *     <div cmmLeftContent>Left panel</div>
 *     <div cmmRightContent>Right panel</div>
 *   </div>
 * </div>
 * ```
 */
@Directive({
  selector: '[cmmLayout]',
  standalone: true,
})
export class CmmLayoutDirective {
  private el = inject(ElementRef);
  private renderer = inject(Renderer2);
  private injector = inject(Injector);

  private static stylesInjected = false;
  private static readonly minifiedCss = '.cmm-layout{box-sizing:border-box}';

  constructor() {
    afterNextRender(
      () => {
        this.injectStyles();
        this.applyStyles();
      },
      { injector: this.injector },
    );
  }

  private injectStyles(): void {
    if (!CmmLayoutDirective.stylesInjected && typeof document !== 'undefined') {
      const style = this.renderer.createElement('style');
      this.renderer.setAttribute(style, 'data-cmm-layout', '');
      const text = this.renderer.createText(CmmLayoutDirective.minifiedCss);
      this.renderer.appendChild(style, text);
      this.renderer.appendChild(document.head, style);
      CmmLayoutDirective.stylesInjected = true;
    }
  }

  private applyStyles(): void {
    const element = this.el.nativeElement;

    // Set up the main layout container
    this.renderer.addClass(element, 'cmm-layout');
    this.renderer.setStyle(element, 'display', 'flex');
    this.renderer.setStyle(element, 'flex-direction', 'column');
    this.renderer.setStyle(element, 'height', '100vh');
    this.renderer.setStyle(element, 'overflow', 'hidden');
    this.renderer.setStyle(element, 'width', '100%');
  }
}
