import { ChangeDetectionStrategy, Component, input, output, contentChild, TemplateRef, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Avatar } from 'primeng/avatar';

@Component({
  selector: 'cmm-avatar',
  templateUrl: './cmm-avatar.component.html',
  styleUrls: ['./cmm-avatar.component.scss'],
  standalone: true,
  imports: [CommonModule, Avatar],
  exportAs: 'cmmavatar',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmAvatarComponent {
  // Signal inputs - Core functionality
  label = input<string>('');
  icon = input<string>('');
  image = input<string>('');
  size = input<'normal' | 'large' | 'xlarge'>('normal');
  shape = input<'square' | 'circle'>('square');

  // Styling
  style = input<{ [klass: string]: any } | null>(null);
  styleClass = input<string>('');
  imageAlt = input<string>('avatar');

  // Accessibility
  ariaLabel = input<string>('');
  ariaLabelledBy = input<string>('');

  // Custom variant and size system
  variant = input<'outlined' | 'filled'>('filled');
  customSize = input<'small' | 'default' | 'large'>('default');

  // Events
  onImageError = output<Event>();

  // Template projections
  contentTemplate = contentChild<TemplateRef<any>>('content');

  // Computed style class
  computedStyleClass = computed(() => {
    const classes = [
      'cmm-avatar',
      `cmm-avatar--${this.variant()}`,
      `cmm-avatar--${this.customSize()}`,
      this.styleClass(),
    ];
    return classes.filter(Boolean).join(' ');
  });

  // Event handlers
  handleImageError(event: Event): void {
    this.onImageError.emit(event);
  }
}
