import {
  Directive,
  ElementRef,
  HostListener,
  Input,
  OnInit,
  Renderer2,
} from '@angular/core';
import { NgControl } from '@angular/forms';

/**
 * Input Restriction Directive
 * 
 * Restricts user input based on pattern and length constraints.
 * Prevents invalid characters from being entered (not just validation after input).
 * 
 * Features:
 * - Pattern-based character restriction (block invalid input in real-time)
 * - Auto-trim when exceeding maxLength
 * - Optional trim whitespace on blur
 * - Optional uppercase/lowercase transformation
 * - Paste event handling
 * 
 * @example
 * ```html
 * <!-- Only allow numbers -->
 * <input cmmInputRestrict [pattern]="'[0-9]'" maxlength="10" />
 * 
 * <!-- Only alphanumeric -->
 * <input cmmInputRestrict [pattern]="'[a-zA-Z0-9]'" />
 * 
 * <!-- Phone number (digits only) -->
 * <input cmmInputRestrict [pattern]="'\\d'" maxlength="10" [trimOnBlur]="true" />
 * 
 * <!-- Username (alphanumeric + underscore) -->
 * <input cmmInputRestrict [pattern]="'[a-zA-Z0-9_]'" [maxLength]="20" [transform]="'lowercase'" />
 * 
 * <!-- Decimal numbers -->
 * <input cmmInputRestrict [pattern]="'[0-9.]'" [customValidator]="decimalValidator" />
 * ```
 */
@Directive({
  selector: '[cmmInputRestrict]',
  standalone: true,
})
export class InputRestrictBaseDirective implements OnInit {
  /**
   * Regular expression pattern for allowed characters
   * Can be string or RegExp object
   * 
   * Common patterns:
   * - '[0-9]' or '\\d' - digits only
   * - '[a-zA-Z]' - letters only
   * - '[a-zA-Z0-9]' - alphanumeric
   * - '[a-zA-Z0-9_-]' - alphanumeric with underscore and hyphen
   * - '[0-9.]' - decimal numbers
   * - '[\\w]' - word characters (alphanumeric + underscore)
   */
  @Input() pattern?: string | RegExp;

  /**
   * Maximum length of input
   * Will auto-trim if user tries to exceed this length
   */
  @Input() maxLength?: number;

  /**
   * Trim whitespace on blur event
   * Default: false
   */
  @Input() trimOnBlur = true;

  /**
   * Transform input text
   * Options: 'uppercase' | 'lowercase' | 'none'
   * Default: 'none'
   */
  @Input() transform: 'uppercase' | 'lowercase' | 'none' = 'none';

  /**
   * Allow spaces in input
   * Default: true
   */
  @Input() allowSpaces = true;

  /**
   * Custom validator function for complex validation
   * Return true if valid, false if invalid
   */
  @Input() customValidator?: (value: string) => boolean;

  /**
   * Block paste event if content doesn't match pattern
   * Default: true
   */
  @Input() blockInvalidPaste = true;

  /**
   * Format function to apply on blur
   * Receives raw value, returns formatted value
   * 
   * @example
   * ```typescript
   * // Credit card: 1234-5678-9012-3456
   * formatOnBlur = (value: string) => {
   *   const cleaned = value.replace(/\D/g, '');
   *   return cleaned.match(/.{1,4}/g)?.join('-') || cleaned;
   * }
   * 
   * // Phone: (012) 345-6789
   * formatOnBlur = InputFormatters.phoneFormat('xxx-xxx-xxxx', '-')
   * ```
   */
  @Input() formatOnBlur?: (value: string) => string;



  regex?: RegExp;

  /**
   * True if host element is a single-line <input> (not a <textarea>).
   * Single-line inputs must never contain line breaks.
   */
  isSingleLine = false;

  constructor(
    public el: ElementRef<HTMLInputElement>,
    public renderer: Renderer2,
    public ngControl: NgControl
  ) { }

  ngOnInit(): void {
    // Detect single-line input (line breaks are stripped only for <input>, not <textarea>)
    this.isSingleLine = this.el.nativeElement.tagName === 'INPUT';

    // Compile regex pattern
    if (this.pattern) {
      if (typeof this.pattern === 'string') {
        // If pattern doesn't have ^ and $, wrap it
        const patternStr = this.pattern.startsWith('^')
          ? this.pattern
          : `^${this.pattern}+$`;
        this.regex = new RegExp(patternStr);
      } else {
        this.regex = this.pattern;
      }
    }

    // Set maxlength attribute if provided
    if (this.maxLength !== undefined) {
      this.renderer.setAttribute(this.el.nativeElement, 'maxlength', String(this.maxLength));
    }
  }

  /**
   * Handle keyboard input
   * Prevent invalid characters from being entered
   */
  @HostListener('input', ['$event'])
  onInput(event: Event): void {
    const input = event.target as HTMLInputElement;
    let value = input.value;

    // Store cursor position
    const cursorPosition = input.selectionStart || 0;

    // Strip line breaks for single-line inputs (e.g. pasted multi-line text)
    if (this.isSingleLine) {
      value = value.replace(/[\r\n]+/g, '');
    }

    // Apply pattern restriction
    if (this.regex) {
      value = this.filterByPattern(value);
    }

    // Remove spaces if not allowed
    if (!this.allowSpaces) {
      value = value.replace(/\s/g, '');
    }

    // Apply max length (trim excess)
    if (this.maxLength !== undefined && value.length > this.maxLength) {
      value = value.substring(0, this.maxLength);
    }

    // Apply custom validator
    if (this.customValidator && !this.customValidator(value)) {
      // Revert to previous valid value
      value = input.value.substring(0, input.value.length - 1);
    }

    // Apply text transformation
    value = this.applyTransform(value);

    // Update input value if changed
    if (input.value !== value) {
      input.value = value;

      // Update form control value
      if (this.ngControl?.control) {
        this.ngControl.control.setValue(value, { emitEvent: false });
      }

      // Restore cursor position (adjust if text was removed)
      const newPosition = Math.min(cursorPosition, value.length);
      input.setSelectionRange(newPosition, newPosition);
    }
  }

  /**
   * Handle paste event
   * Validate pasted content against pattern
   */
  @HostListener('paste', ['$event'])
  onPaste(event: ClipboardEvent): void {
    if(this.ngControl.control?.disabled) {
      return;
    }
    if (!this.blockInvalidPaste) return;

    event.preventDefault();

    let pastedText = event.clipboardData?.getData('text') || '';
    const input = this.el.nativeElement;
    let currentValue = input.value;
    if (this.trimOnBlur) {
      pastedText = pastedText.trim();
    }
    const cursorPosition = input.selectionStart || 0;

    // Filter pasted text
    let filteredText = pastedText;

    // Strip line breaks for single-line inputs
    if (this.isSingleLine) {
      filteredText = filteredText.replace(/[\r\n]+/g, '');
    }

    if (this.regex) {
      filteredText = this.filterByPattern(filteredText);
    }

    if (!this.allowSpaces) {
      filteredText = filteredText.replace(/\s/g, '');
    }

    filteredText = this.applyTransform(filteredText);

    // Build new value
    const beforeCursor = currentValue.substring(0, cursorPosition);
    const afterCursor = currentValue.substring(input.selectionEnd || cursorPosition);
    let newValue = beforeCursor + filteredText + afterCursor;

    // Apply max length
    if (this.maxLength !== undefined && newValue.length > this.maxLength) {
      newValue = newValue.substring(0, this.maxLength);
    }

    // Update input
    input.value = newValue;

    if (this.ngControl?.control) {
      this.ngControl.control.setValue(newValue);
    }

    // Set cursor position after pasted text
    const newPosition = Math.min(cursorPosition + filteredText.length, newValue.length);
    input.setSelectionRange(newPosition, newPosition);
  }

  /**
   * Handle blur event
   * Apply trim and formatting
   */
  @HostListener('blur', ['$event'])
  onBlur(event: Event): void {
    const input = event.target as HTMLInputElement;
    let value = input.value;

    // Trim whitespace if enabled
    if (this.trimOnBlur) {
      value = value.trim();
    }

    // Apply custom format function
    if (this.formatOnBlur) {
      value = this.formatOnBlur(value);
    }

    // Update if value changed
    if (input.value !== value) {
      input.value = value;

      if (this.ngControl?.control) {
        this.ngControl.control.setValue(value);
      }
    }
  }

  /**
   * Filter value by pattern
   * Remove characters that don't match the pattern
   */
  filterByPattern(value: string): string {
    if (!this.regex) return value;

    // Create character-matching regex
    const charPattern = new RegExp(
      this.pattern!.toString().replace(/^\^|\$$/g, '').replace(/\+/g, '')
    );

    // Filter each character
    return value
      .split('')
      .filter(char => charPattern.test(char))
      .join('');
  }

  /**
   * Apply text transformation
   */
  applyTransform(value: string): string {
    switch (this.transform) {
      case 'uppercase':
        return value.toUpperCase();
      case 'lowercase':
        return value.toLowerCase();
      default:
        return value;
    }
  }
}
