import {
  ChangeDetectionStrategy,
  Component,
  forwardRef,
  input,
  model,
  output,
  contentChild,
  TemplateRef,
  computed,
  effect,
  ViewEncapsulation,
} from '@angular/core';
import {
  AbstractControl,
  ControlValueAccessor,
  FormsModule,
  NG_VALIDATORS,
  NG_VALUE_ACCESSOR,
  ValidationErrors,
  Validator,
} from '@angular/forms';
import { NgTemplateOutlet } from '@angular/common';
import { DatePicker, DatePickerMonthChangeEvent, DatePickerYearChangeEvent } from 'primeng/datepicker';
import { DatepickerProps } from './date-picker.types';
import { CMM_DATEPICKER_FORMAT } from './date-picker.const';


export type DateValue = Date | Date[] | undefined;

@Component({
  selector: 'cmm-datepicker',
  imports: [DatePicker, FormsModule, NgTemplateOutlet],
  templateUrl: './datepicker.component.html',
  styleUrl: './datepicker.component.scss',
  changeDetection: ChangeDetectionStrategy.Default,
  exportAs: 'cmmDatepicker',
  encapsulation: ViewEncapsulation.None,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmDatepickerComponent),
      multi: true,
    },
    {
      provide: NG_VALIDATORS,
      useExisting: forwardRef(() => CmmDatepickerComponent),
      multi: true,
    },
  ]
})
export class CmmDatepickerComponent implements ControlValueAccessor, Validator {
  public readonly serializeId = `cmm-dpk-${Math.random().toString(36).substring(2)}`;
  private _value: any;
  onTouched: () => void = () => {};
  onChange: (_: any) => void = () => {};

  // Core date binding
  date: Date | Date[] | undefined;

  // Component props
  disabled = model<boolean>(false);
  props = input<DatepickerProps>();
  propsComputed = computed(() => ({
    ...this.props(),
    dateFormat: this.props()?.dateFormat ??  CMM_DATEPICKER_FORMAT.DDMMYYYY,
    viewMode: this.props()?.viewMode ??  'date',
    selectionMode: this.props()?.selectionMode ??  'single',
    showIcon: this.props()?.showIcon ?? true,
    rangeSeparator: this.props()?.rangeSeparator ??  '\u2192',
    iconDisplay: this.props()?.iconDisplay ??  'input',
    showTime: this.props()?.showTime ??  false,
    hourFormat: this.props()?.hourFormat ??  '24',
    showButtonBar: this.props()?.showButtonBar ??  true,
    tabindex: this.props()?.tabindex ?? 0,
    fluid: this.props()?.fluid ?? true,
    isStrictRangeValidate: this.props()?.isStrictRangeValidate ?? false,
  }))

  private onValidatorChange: () => void = () => {};
  // Check xem có cần validate select thiếu ngày ở chế độ "Range" hay không
  private rangeValidationRequested = false;
  private readonly selectionModeValidatorEffect = effect(() => {
    if (this.propsComputed().selectionMode !== 'range') {
      this.rangeValidationRequested = false;
    }
    this.onValidatorChange();
  });

  // Inputs
  hasExplicitOnClickOutside = input<boolean>(false);

  // Outputs
  eventDateChange = output<Date | Date[] | undefined>();
  onSelect = output<Date | Date[]>();
  onClear = output<void>();
  onMonthChange = output<DatePickerMonthChangeEvent>();
  onYearChange = output<DatePickerYearChangeEvent>();
  onFocus = output<Event>();
  onBlur = output<Event>();
  onShow = output<void>();
  onHide = output<void>();
  onClickOutside = output<Date | Date[] | undefined>();

  // Template projections
  dateTemplate = contentChild<TemplateRef<any>>('date');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  decadeTemplate = contentChild<TemplateRef<any>>('decade');
  previousIconTemplate = contentChild<TemplateRef<any>>('previousicon');
  nextIconTemplate = contentChild<TemplateRef<any>>('nexticon');
  triggerIconTemplate = contentChild<TemplateRef<any>>('triggericon');
  clearIconTemplate = contentChild<TemplateRef<any>>('clearicon');
  decrementIconTemplate = contentChild<TemplateRef<any>>('decrementicon');
  incrementIconTemplate = contentChild<TemplateRef<any>>('incrementicon');
  inputIconTemplate = contentChild<TemplateRef<any>>('inputicon');

  handleDateChange() {
    this.eventDateChange.emit(this.date);
  }

  handleSelect(event: Date | Date[]): void {
    if (this.props()?.selectionMode === 'range') {
      const date = this.date as Date[];
      if (date && date.length > 2) {
        this.date = [date[1], event as Date];
      }
      this.updateValue(this.date);
    } else {
      this.updateValue(event);
    }
    this.onSelect.emit(event);
  }

  handleInput(event: any): void {
    this.updateValue(this.date);
  }

  handleClickOutside(): void {
    if (
      this.propsComputed().selectionMode === 'range' &&
      this.propsComputed().isStrictRangeValidate &&
      !this.hasExplicitOnClickOutside()
    ) {
      // Incomplete-range validation is intentionally delayed until the user
      // finishes interacting with the picker and clicks outside.
      this.rangeValidationRequested = true;
      this.onValidatorChange();
      this.onTouched();
      return;
    }
    this.onClickOutside.emit(this.date);
  }

  handleClear(): void {
    this.updateValue(null);
    this.onClear.emit();
  }

  handleMonthChange(event: DatePickerMonthChangeEvent): void {
    this.onMonthChange.emit(event);
  }

  handleYearChange(event: DatePickerYearChangeEvent): void {
    this.onYearChange.emit(event);
  }

  handleFocus(event: Event): void {
    this.onFocus.emit(event);
  }

  handleBlur(event: Event): void {
    this.onTouched();
    // Handle select gọi updateValue rồi
    // this.updateValue(this.date);
    this.onBlur.emit(event);
  }

  handleShow(): void {
    this.onShow.emit();
  }

  handleHide(): void {
    this.onHide.emit();
  }

  updateValue(value: any): void {
    this.rangeValidationRequested = false;
    // Tránh update value liên tục khi touched
    // this.onTouched();
    this.onChange(value);
    this._value = value;
    this.date = value;
    this.handleDateChange();
  }

  // ControlValueAccessor implementation
  writeValue(obj: any): void {
    this.rangeValidationRequested = false;
    this.date = obj;
    this._value = obj;
    if (this.onChange) {
      this.onChange(this._value);
    }
  }

  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  validate(control: AbstractControl): ValidationErrors | null {
    if (
      this.propsComputed().selectionMode !== 'range' ||
      !this.rangeValidationRequested
    ) {
      return null;
    }

    const value: unknown = control.value;

    // Let Validators.required own the empty-value case so an empty range and
    // an incomplete range can display different validation messages.
    if (value == null || (Array.isArray(value) && value.length === 0)) {
      return null;
    }

    if (!Array.isArray(value)) {
      return { incompleteDateRange: true };
    }

    const [startDate, endDate] = value;
    return this.isValidDate(startDate) && this.isValidDate(endDate)
      ? null
      : { incompleteDateRange: true };
  }

  registerOnValidatorChange(fn: () => void): void {
    this.onValidatorChange = fn;
  }

  private isValidDate(value: unknown): value is Date {
    return value instanceof Date && !Number.isNaN(value.getTime());
  }

  setDisabledState?(isDisabled: boolean): void {
    this.disabled.set(isDisabled);
  }
}
