
import { ChangeDetectionStrategy, Component, input, model, output } from '@angular/core';
import { System, SCREEN_STATUS, SCREEN_STATUS_ENUM } from '../permission.types';
import { CmmCheckboxComponent, CmmToggleswitchComponent } from '../../base/public-api';
import { ToggleSwitchChangeEvent } from 'primeng/toggleswitch';
import { FormsModule } from '@angular/forms';

export type PermissionProps = System;
@Component({
  selector: 'app-permission',
  imports: [CmmToggleswitchComponent, CmmCheckboxComponent, FormsModule],
  templateUrl: './permission.component.html',
  styleUrl: './permission.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class PermissionComponent {
  // Input props
  props = model.required<PermissionProps>();
  screenMode = input.required<SCREEN_STATUS>();
  fullPermissionsLabel = input<string>('Full Permissions');

  // output events
  checkAllEvent = output<boolean>();
  checkItemEvent = output<System>();

  // INTERNAL
  readonly inputId = Math.random().toString(36).substring(2);

  readonly SCREEN_STATUS_ENUM = SCREEN_STATUS_ENUM;

  // helper functions
  handleToggleFullPermissions(evt: ToggleSwitchChangeEvent): void {
    this.checkAllEvent.emit(evt.checked);
  }
  handleCheckChange(): void {
    this.checkItemEvent.emit(this.props());
  }

  isCheckedAllPermissions(): boolean {
    return !!(
      this.props().permissions &&
      this.props().permissions.length > 0 &&
      this.props().permissions.every((permission) => permission.active)
    );
  }
}
