//     animate('200ms ease-out', style({ opacity: 1 }))
//   ])
// ]);
/**
 * Validation Error Component
 *
 * Displays validation error messages with optional icon
 *
 * This component is automatically created by ValidationDirective
 * You don't need to use it directly in templates
 */
@Component({
  selector: 'app-validation-error',
  standalone: true,
  template: `
    @if(message) {
    <div class="validation-error">
      @if(showIcon) {
      <svg
        class="validation-error-icon"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        stroke-width="2"
        stroke-linecap="round"
        stroke-linejoin="round"
      >
        <circle cx="12" cy="12" r="10"></circle>
        <line x1="12" y1="8" x2="12" y2="12"></line>
        <line x1="12" y1="16" x2="12.01" y2="16"></line>
      </svg>
      }

      <span class="validation-error-message">{{ message }}</span>
    </div>
    }
  `,
  styles: [
    `
      :host {
        display: block;
        width: 100%;
      }
    `,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  animations: [
    // fadeIn
  ],
  providers: [UbckValidationStyles],
})
export class ValidationErrorComponent extends BaseComponent{
  @Input() message = '';
  @Input() showIcon = false;
  _componentStyle = inject(UbckValidationStyles);
}
