import { Component, ChangeDetectionStrategy, input } from '@angular/core';
import { Skeleton } from 'primeng/skeleton';

/**
 * Skeleton is a placeholder to display instead of the actual content.
 * Wraps PrimeNG Skeleton component.
 */
@Component({
  selector: 'cmm-skeleton',
  standalone: true,
  imports: [Skeleton],
  templateUrl: './cmm-skeleton.component.html',
  styleUrl: './cmm-skeleton.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmSkeletonComponent {
  // Input properties
  /**
   * Class of the element
   */
  readonly styleClass = input<string>('');

  /**
   * Inline style of the element
   */
  readonly style = input<Record<string, any>>();

  /**
   * Shape of the element
   */
  readonly shape = input<string>('rectangle');

  /**
   * Border radius of the element, defaults to value from theme
   */
  readonly borderRadius = input<string>();

  /**
   * Size of the skeleton
   */
  readonly size = input<string>();

  /**
   * Width of the element
   */
  readonly width = input<string>('100%');

  /**
   * Height of the element
   */
  readonly height = input<string>('1rem');
}
