import { Component, input, viewChild, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { PanelMenu, PanelMenuModule } from 'primeng/panelmenu';
import type { MenuItem } from 'primeng/api';
import { PANELMENU_DEFAULTS } from './cmm-panelmenu.constants';

@Component({
  selector: 'cmm-panelmenu',
  standalone: true,
  imports: [CommonModule, PanelMenuModule],
  template: `
    <p-panelMenu
      #panelMenu
      [id]="id() ?? undefined"
      [model]="model()"
      [multiple]="multiple()"
      [transitionOptions]="transitionOptions()"
      [tabindex]="tabindex()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined">
      @if (itemTemplate()) {
        <ng-template pTemplate="item" let-item>
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
      @if (submenuIconTemplate()) {
        <ng-template pTemplate="submenuicon">
          <ng-container *ngTemplateOutlet="submenuIconTemplate()!" />
        </ng-template>
      }
    </p-panelMenu>
  `,
  styleUrl: './cmm-panelmenu.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmPanelmenuComponent {
  panelMenu = viewChild<PanelMenu>('panelMenu');

  // Core props
  id = input<string>();
  model = input<MenuItem[]>([]);
  multiple = input<boolean>(PANELMENU_DEFAULTS.MULTIPLE);
  transitionOptions = input<string>('400ms cubic-bezier(0.86, 0, 0.07, 1)');
  tabindex = input<number>(0);
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Templates
  itemTemplate = contentChild<TemplateRef<any>>('item');
  submenuIconTemplate = contentChild<TemplateRef<any>>('submenuicon');

  // Public methods
  collapseAll(): void {
    this.panelMenu()?.collapseAll();
  }
}
