import { ColumnDefinition } from "../table.types";


export function computedColumn(columns: ColumnDefinition[] | ColumnDefinition[][]): ColumnDefinition[] {
    return columns
      ?.flat()
      ?.filter((item) => item?.index)
      ?.sort((pre: any, next: any) => (pre?.index || 1) - (next?.index || 1)) ?? [];
  }