import {
  Component,
  input,
  output,
  model,
  forwardRef,
  ChangeDetectionStrategy,
  signal,
} from '@angular/core';

import {
  FormsModule,
  NG_VALUE_ACCESSOR,
  ControlValueAccessor,
} from '@angular/forms';
import { CheckboxModule, CheckboxChangeEvent } from 'primeng/checkbox';
import { CheckboxVariant, CheckboxSize } from './cmm-checkbox.types';
import { CHECKBOX_DEFAULTS } from './cmm-checkbox.constants';

@Component({
  selector: 'cmm-checkbox',
  standalone: true,
  imports: [FormsModule, CheckboxModule],
  template: `
    <p-checkbox
      [(ngModel)]="value"
      (onChange)="handleChange($event)"
      [name]="name()"
      [disabled]="disabled() || cvaDisabled()"
      [binary]="binary()"
      [readonly]="readonly()"
      [required]="required()"
      [trueValue]="trueValue()"
      [falseValue]="falseValue()"
      [tabindex]="tabindex()"
      [inputId]="inputId()"
      [ariaLabelledBy]="ariaLabelledBy() ?? undefined"
      [ariaLabel]="ariaLabel() ?? undefined"
      [style]="style() ?? undefined"
      [inputStyle]="inputStyle() ?? undefined"
      [styleClass]="styleClass() ?? undefined"
      [inputClass]="inputClass() ?? undefined"
      [checkboxIcon]="checkboxIcon() ?? undefined"
      [variant]="variant()"
      [indeterminate]="indeterminate()"
      [autofocus]="autofocus()"
      (onFocus)="handleFocus($event)"
      (onBlur)="handleBlur($event)"
    />
  `,
  styleUrl: './cmm-checkbox.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmCheckboxComponent),
      multi: true,
    },
  ],
})
export class CmmCheckboxComponent implements ControlValueAccessor {
  // Model
  value = model<any>();

  // Core props
  name = input<string>('');
  disabled = input<boolean>(CHECKBOX_DEFAULTS.DISABLED);
  cvaDisabled = signal(false);
  binary = input<boolean>(CHECKBOX_DEFAULTS.BINARY);
  readonly = input<boolean>(CHECKBOX_DEFAULTS.READONLY);
  required = input<boolean>(CHECKBOX_DEFAULTS.REQUIRED);
  trueValue = input<any>(CHECKBOX_DEFAULTS.TRUE_VALUE);
  falseValue = input<any>(CHECKBOX_DEFAULTS.FALSE_VALUE);
  tabindex = input<number>(CHECKBOX_DEFAULTS.TABINDEX);
  inputId = input<string>('');
  ariaLabelledBy = input<string>();
  ariaLabel = input<string>();
  style = input<Record<string, any>>();
  inputStyle = input<Record<string, any>>();
  styleClass = input<string>();
  inputClass = input<string>();
  label = input<string>();
  checkboxIcon = input<string>();
  variant = input<CheckboxVariant>(CHECKBOX_DEFAULTS.VARIANT);
  size = input<CheckboxSize>('small');
  indeterminate = input<boolean>(false);
  autofocus = input<boolean>(false);

  // Output events
  onChange = output<CheckboxChangeEvent>();
  onFocus = output<Event>();
  onBlur = output<Event>();

  // ControlValueAccessor implementation
  private onChangeFn: (value: any) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: any): void {
    this.value.set(value);
  }

  registerOnChange(fn: (value: any) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.cvaDisabled.set(isDisabled);
  }

  handleChange(event: CheckboxChangeEvent): void {
    this.value.set(event.checked);
    this.onChange.emit(event);
    this.onChangeFn(event.checked);
    this.onTouchedFn();
  }

  handleFocus(event: Event): void {
    this.onFocus.emit(event);
  }

  handleBlur(event: Event): void {
    this.onBlur.emit(event);
    this.onTouchedFn();
  }
}
