import { Component, input, output, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ScrollerModule } from 'primeng/scroller';
import {
  
  ScrollerOrientation,
  ScrollerLazyLoadEvent,
  ScrollerScrollEvent,
  ScrollerScrollIndexChangeEvent,
  
} from './cmm-scroller.types';
import { SCROLLER_DEFAULTS } from './cmm-scroller.constants';
import { ScrollerOptions } from 'primeng/api';

/**
 * Scroller is a performance-approach to handle huge data efficiently with virtual scrolling.
 * Wraps PrimeNG Scroller component.
 */
@Component({
  selector: 'cmm-scroller',
  standalone: true,
  imports: [CommonModule, ScrollerModule],
  templateUrl: './cmm-scroller.component.html',
  styleUrl: './cmm-scroller.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmScrollerComponent {
  // Input properties
  /**
   * Unique identifier of the element
   */
  readonly id = input<string>();

  /**
   * Inline style of the component
   */
  readonly style = input<any>();

  /**
   * Style class of the element
   */
  readonly styleClass = input<string>();

  /**
   * Index of the element in tabbing order
   */
  readonly tabindex = input<number>();

  /**
   * An array of objects to display
   */
  readonly items = input<any[]>();

  /**
   * The height/width of item according to orientation
   */
  readonly itemSize = input<number | number[]>(50);

  /**
   * Height of the scroll viewport
   */
  readonly scrollHeight = input<string>();

  /**
   * Width of the scroll viewport
   */
  readonly scrollWidth = input<string>();

  /**
   * The orientation of scrollbar
   */
  readonly orientation = input<ScrollerOrientation>(SCROLLER_DEFAULTS.ORIENTATION);

  /**
   * Used to specify how many items to load in each load method in lazy mode
   */
  readonly step = input<number>(SCROLLER_DEFAULTS.STEP);

  /**
   * Delay in scroll before new data is loaded
   */
  readonly delay = input<number>(SCROLLER_DEFAULTS.DELAY);

  /**
   * Delay after window's resize finishes
   */
  readonly resizeDelay = input<number>(SCROLLER_DEFAULTS.RESIZE_DELAY);

  /**
   * Used to append each loaded item to top without removing any items from the DOM
   */
  readonly appendOnly = input<boolean>(SCROLLER_DEFAULTS.APPEND_ONLY);

  /**
   * Specifies whether the scroller should be displayed inline or not
   */
  readonly inline = input<boolean>(SCROLLER_DEFAULTS.INLINE);

  /**
   * Defines if data is loaded and interacted with in lazy manner
   */
  readonly lazy = input<boolean>(SCROLLER_DEFAULTS.LAZY);

  /**
   * If disabled, the scroller feature is eliminated and the content is displayed directly
   */
  readonly disabled = input<boolean>(SCROLLER_DEFAULTS.DISABLED);

  /**
   * Used to implement a custom loader instead of using the loader feature in the scroller
   */
  readonly loaderDisabled = input<boolean>(SCROLLER_DEFAULTS.LOADER_DISABLED);

  /**
   * Columns to display
   */
  readonly columns = input<any[]>();

  /**
   * Used to implement a custom spacer instead of using the spacer feature in the scroller
   */
  readonly showSpacer = input<boolean>(SCROLLER_DEFAULTS.SHOW_SPACER);

  /**
   * Defines whether to show loader
   */
  readonly showLoader = input<boolean>(SCROLLER_DEFAULTS.SHOW_LOADER);

  /**
   * Determines how many additional elements to add to the DOM outside of the view
   */
  readonly numToleratedItems = input<number>();

  /**
   * Defines whether the data is loaded
   */
  readonly loading = input<boolean>(SCROLLER_DEFAULTS.LOADING);

  /**
   * Defines whether to dynamically change the height or width of scrollable container
   */
  readonly autoSize = input<boolean>(SCROLLER_DEFAULTS.AUTO_SIZE);

  /**
   * Function to optimize the dom operations by delegating to ngForTrackBy
   */
  readonly trackBy = input<Function>();

  /**
   * Defines whether to use the scroller feature
   */
  readonly options = input<ScrollerOptions>();

  // Template references
  /**
   * Custom content template
   */
  readonly contentTemplate = contentChild<TemplateRef<any>>('content');

  /**
   * Custom item template
   */
  readonly itemTemplate = contentChild<TemplateRef<any>>('item');

  /**
   * Custom loader template
   */
  readonly loaderTemplate = contentChild<TemplateRef<any>>('loader');

  /**
   * Custom loader icon template
   */
  readonly loadericonTemplate = contentChild<TemplateRef<any>>('loadericon');

  // Output events
  /**
   * Callback to invoke in lazy mode to load new data
   */
  readonly onLazyLoad = output<ScrollerLazyLoadEvent>();

  /**
   * Callback to invoke when scroll position changes
   */
  readonly onScroll = output<ScrollerScrollEvent>();

  /**
   * Callback to invoke when scroll position and item's range in view changes
   */
  readonly onScrollIndexChange = output<ScrollerScrollIndexChangeEvent>();
}
