import { Component, ChangeDetectionStrategy, input, computed } from '@angular/core';
import { CommonModule } from '@angular/common';
import { AnimateOnScroll, AnimateOnScrollModule } from 'primeng/animateonscroll';

@Component({
  selector: 'cmm-animate-on-scroll',
  templateUrl: './cmm-animate-on-scroll.component.html',
  styleUrls: ['./cmm-animate-on-scroll.component.scss'],
  standalone: true,
  imports: [CommonModule, AnimateOnScrollModule],
  exportAs: 'cmmanimateonscroll',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmAnimateOnScrollComponent {
  // ====================================================
  // PROPS (from schema)
  // ====================================================

  // Animation classes
  readonly enterClass = input<string>('fadein');
  readonly leaveClass = input<string>('fadeout');

  // IntersectionObserver configuration
  readonly root = input<HTMLElement | undefined>(undefined);
  readonly rootMargin = input<string>('0px');
  readonly threshold = input<number>(0.5);
  readonly once = input<boolean>(true);

  // ====================================================
  // CUSTOM STYLING PROPS (not in schema)
  // ====================================================

  readonly styleClass = input<string>('');
  readonly style = input<Record<string, any>>({});

  // Custom size/variant props for theming
  readonly size = input<'small' | 'default' | 'large'>('default');
  readonly variant = input<'outlined' | 'filled'>('outlined');
  readonly animationSpeed = input<'fast' | 'normal' | 'slow'>('normal');

  // ====================================================
  // COMPUTED PROPERTIES
  // ====================================================

  readonly computedStyleClass = computed(() => {
    const classes = [this.styleClass()];

    if (this.size() !== 'default') {
      classes.push(`cmm-animate-${this.size()}`);
    }

    if (this.variant()) {
      classes.push(`cmm-animate-${this.variant()}`);
    }

    if (this.animationSpeed() !== 'normal') {
      classes.push(`cmm-animate-speed-${this.animationSpeed()}`);
    }

    return classes.filter(Boolean).join(' ');
  });
}
