import { Component, input, ChangeDetectionStrategy, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TimelineModule } from 'primeng/timeline';
import { TimelineAlign, TimelineLayout } from './cmm-timeline.types';
import { TIMELINE_DEFAULTS } from './cmm-timeline.constants';

@Component({
  selector: 'cmm-timeline',
  standalone: true,
  imports: [CommonModule, TimelineModule],
  template: `
    <p-timeline
      [value]="value()"
      [layout]="layout()"
      [align]="align()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass()!"
    >
      @if (contentTemplate()) {
        <ng-template pTemplate="content" let-event>
          <ng-container *ngTemplateOutlet="contentTemplate()!; context: { $implicit: event }" />
        </ng-template>
      }
      @if (oppositeTemplate()) {
        <ng-template pTemplate="opposite" let-event>
          <ng-container *ngTemplateOutlet="oppositeTemplate()!; context: { $implicit: event }" />
        </ng-template>
      }
      @if (markerTemplate()) {
        <ng-template pTemplate="marker" let-event>
          <ng-container *ngTemplateOutlet="markerTemplate()!; context: { $implicit: event }" />
        </ng-template>
      }
      @if (connectorTemplate()) {
        <ng-template pTemplate="connector" let-event>
          <ng-container *ngTemplateOutlet="connectorTemplate()!; context: { $implicit: event }" />
        </ng-template>
      }
    </p-timeline>
  `,
  styleUrl: './cmm-timeline.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmTimelineComponent {
  // Core props
  value = input.required<any[]>();
  layout = input<TimelineLayout>(TIMELINE_DEFAULTS.LAYOUT);
  align = input<TimelineAlign>(TIMELINE_DEFAULTS.ALIGN);
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Content children templates
  contentTemplate = contentChild<TemplateRef<any>>('content');
  oppositeTemplate = contentChild<TemplateRef<any>>('opposite');
  markerTemplate = contentChild<TemplateRef<any>>('marker');
  connectorTemplate = contentChild<TemplateRef<any>>('connector');
}
