// ============================================
// 2. CONFIG SERVICE (Global Configuration)
// ============================================
import { Injectable } from '@angular/core';
import { TypographyConfig, HeadingFontSizes, TextFontSizes } from '../types/typography.types';

@Injectable({ providedIn: 'root' })
export class CmmTypographyConfigService {
  private config: Partial<TypographyConfig> = {
    ellipsis: false,
    copyable: false,
    editable: false
  };

  // Default heading font sizes
  private headingSizes: HeadingFontSizes = {
    h1: '32px',
    h2: '28px',
    h3: '24px',
    h4: '20px',
    h5: '18px',
    h6: '16px'
  };

  // Default text/paragraph sizes
  private textSizes: TextFontSizes = {
    base: '16px',
    small: '14px',
    large: '18px'
  };

  setConfig(config: Partial<TypographyConfig>): void {
    this.config = { ...this.config, ...config };
  }

  getConfig(): Partial<TypographyConfig> {
    return { ...this.config };
  }

  setHeadingSizes(sizes: Partial<HeadingFontSizes>): void {
    this.headingSizes = { ...this.headingSizes, ...sizes };
  }

  getHeadingSize(level: 1 | 2 | 3 | 4 | 5 | 6): string {
    const key = `h${level}` as keyof HeadingFontSizes;
    return this.headingSizes[key] || '16px';
  }

  setTextSizes(sizes: Partial<TextFontSizes>): void {
    this.textSizes = { ...this.textSizes, ...sizes };
  }

  getTextSize(size: 'base' | 'small' | 'large' = 'base'): string {
    return this.textSizes[size] || '16px';
  }
}
