import {
  Component,
  input,
  output,
  model,
  contentChild,
  TemplateRef,
  ChangeDetectionStrategy,
  forwardRef,
  computed,
  signal,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { ToggleSwitchChangeEvent, ToggleSwitchModule } from 'primeng/toggleswitch';
import { NG_VALUE_ACCESSOR, ControlValueAccessor, FormsModule } from '@angular/forms';
import { TOGGLESWITCH_DEFAULTS } from './cmm-toggleswitch.constants';
import { CmmToggleswitchProps } from './cmm-toggleswitch.types';

@Component({
  selector: 'cmm-toggleswitch',
  standalone: true,
  imports: [CommonModule, ToggleSwitchModule, FormsModule],
  template: `
    <p-toggleSwitch
      [(ngModel)]="value"
      [style]="computedProps().style"
      [styleClass]="computedProps().styleClass"
      [tabindex]="computedProps().tabindex"
      [inputId]="computedProps().inputId"
      [name]="computedProps().name"
      [disabled]="computedProps().disabled"
      [readonly]="computedProps().readonly"
      [trueValue]="computedProps().trueValue"
      [falseValue]="computedProps().falseValue"
      [ariaLabel]="computedProps().ariaLabel"
      [ariaLabelledBy]="computedProps().ariaLabelledBy"
      [autofocus]="computedProps().autofocus"
      (onChange)="handleChange($event)">
      @if (handleTemplate()) {
        <ng-template pTemplate="handle">
          <ng-container *ngTemplateOutlet="handleTemplate()!" />
        </ng-template>
      }
    </p-toggleSwitch>
  `,
  styleUrl: './cmm-toggleswitch.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmToggleswitchComponent),
      multi: true,
    },
  ],
})
export class CmmToggleswitchComponent implements ControlValueAccessor {
  /**
   * Value of the toggleswitch
   */
  value = model<any>();

  /**
   * Component props
   */
  props = input.required<CmmToggleswitchProps>();

  cvaDisabled = signal(false);

  computedProps = computed(() => {
    const p = this.props();
    return {
      ...p,
      tabindex: p.tabindex ?? TOGGLESWITCH_DEFAULTS.TABINDEX,
      disabled: (p.disabled ?? TOGGLESWITCH_DEFAULTS.DISABLED) || this.cvaDisabled(),
      readonly: p.readonly ?? TOGGLESWITCH_DEFAULTS.READONLY,
      trueValue: p.trueValue ?? TOGGLESWITCH_DEFAULTS.TRUE_VALUE,
      falseValue: p.falseValue ?? TOGGLESWITCH_DEFAULTS.FALSE_VALUE,
      autofocus: p.autofocus ?? TOGGLESWITCH_DEFAULTS.AUTOFOCUS,
      styleClass: p.styleClass ?? '',
      name: p.name ?? '',
    };
  });

  /**
   * Custom handle template
   */
  handleTemplate = contentChild<TemplateRef<any>>('handle');

  /**
   * Callback to invoke when toggleswitch value changes
   */
  onChange = output<any>();

  // CVA implementation
  private onChangeFn: (value: any) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: any): void {
    this.value.set(value);
  }

  registerOnChange(fn: (value: any) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.cvaDisabled.set(isDisabled);
  }

  handleChange(event: ToggleSwitchChangeEvent): void {
    this.onChangeFn(event.checked);
    this.onChange.emit(event);
  }
}
