import { Component, input, output, model, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DialogModule } from 'primeng/dialog';
import { DialogPosition, DialogMaximizeEvent } from './cmm-dialog.types';
import { DIALOG_DEFAULTS } from './cmm-dialog.constants';

@Component({
  selector: 'cmm-dialog',
  standalone: true,
  imports: [CommonModule, DialogModule],
  templateUrl: './cmm-dialog.component.html',
  styleUrl: './cmm-dialog.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmDialogComponent {
  // Model signal for visible (two-way binding)
  visible = model<boolean>(false);

  // Core props
  header = input<string>();
  draggable = input<boolean>(DIALOG_DEFAULTS.DRAGGABLE);
  resizable = input<boolean>(DIALOG_DEFAULTS.RESIZABLE);
  contentStyle = input<any>();
  contentStyleClass = input<string>();
  modal = input<boolean>(DIALOG_DEFAULTS.MODAL);
  closeOnEscape = input<boolean>(DIALOG_DEFAULTS.CLOSE_ON_ESCAPE);
  dismissableMask = input<boolean>(DIALOG_DEFAULTS.DISMISSABLE_MASK);
  rtl = input<boolean>(DIALOG_DEFAULTS.RTL);
  closable = input<boolean>(DIALOG_DEFAULTS.CLOSABLE);
  appendTo = input<unknown>('body');
  breakpoints = input<any>();
  styleClass = input<string>();
  maskStyleClass = input<string>();
  maskStyle = input<Record<string, any>>();
  showHeader = input<boolean>(DIALOG_DEFAULTS.SHOW_HEADER);
  blockScroll = input<boolean>(DIALOG_DEFAULTS.BLOCK_SCROLL);
  autoZIndex = input<boolean>(DIALOG_DEFAULTS.AUTO_Z_INDEX);
  baseZIndex = input<number>(DIALOG_DEFAULTS.BASE_Z_INDEX);
  minX = input<number>(DIALOG_DEFAULTS.MIN_X);
  minY = input<number>(DIALOG_DEFAULTS.MIN_Y);
  focusOnShow = input<boolean>(DIALOG_DEFAULTS.FOCUS_ON_SHOW);
  maximizable = input<boolean>(DIALOG_DEFAULTS.MAXIMIZABLE);
  keepInViewport = input<boolean>(DIALOG_DEFAULTS.KEEP_IN_VIEWPORT);
  focusTrap = input<boolean>(DIALOG_DEFAULTS.FOCUS_TRAP);
  transitionOptions = input<string>(DIALOG_DEFAULTS.TRANSITION_OPTIONS);
  closeIcon = input<string>();
  closeAriaLabel = input<string>();
  closeTabindex = input<string>(DIALOG_DEFAULTS.CLOSE_TABINDEX);
  minimizeIcon = input<string>();
  maximizeIcon = input<string>();
  closeButtonProps = input<any>();
  maximizeButtonProps = input<any>();
  style = input<any>();
  position = input<DialogPosition>();

  // Deprecated props (kept for compatibility)
  positionLeft = input<number>();
  positionTop = input<number>();
  responsive = input<boolean>();
  breakpoint = input<number>();

  // Output events
  onShow = output<any>();
  onHide = output<any>();
  onResizeInit = output<MouseEvent>();
  onResizeEnd = output<MouseEvent>();
  onDragEnd = output<DragEvent>();
  onMaximize = output<DialogMaximizeEvent>();

  // Template projections
  headerTemplate = contentChild<TemplateRef<any>>('header');
  contentTemplate = contentChild<TemplateRef<any>>('content');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  closeiconTemplate = contentChild<TemplateRef<any>>('closeicon');
  maximizeiconTemplate = contentChild<TemplateRef<any>>('maximizeicon');
  minimizeiconTemplate = contentChild<TemplateRef<any>>('minimizeicon');
  headlessTemplate = contentChild<TemplateRef<any>>('headless');

  // Event handlers
  handleShow(event: any): void {
    this.onShow.emit(event);
  }

  handleHide(event: any): void {
    this.onHide.emit(event);
  }

  handleResizeInit(event: MouseEvent): void {
    this.onResizeInit.emit(event);
  }

  handleResizeEnd(event: MouseEvent): void {
    this.onResizeEnd.emit(event);
  }

  handleDragEnd(event: DragEvent): void {
    this.onDragEnd.emit(event);
  }

  handleMaximize(event: any): void {
    this.onMaximize.emit({ value: event });
  }
}
