

import { Directive, ElementRef, inject, Input, OnInit, Renderer2 } from "@angular/core";
import { CmmTypographyDirective } from "./typography.directive";
import { CmmTypographyConfigService } from "../services/typography-config.service";
import { BaseComponent } from "primeng/basecomponent";
import { UBCKCustomTypographyStyles } from "../styles/typography.style";

// ============================================
// 5. TEXT/PARAGRAPH DIRECTIVES
// ============================================
@Directive({
  selector: 'p[cmmParagraph], span[cmmText]',
  standalone: true,
  hostDirectives: [{
    directive: CmmTypographyDirective,
    inputs: ['copyable', 'editable', 'disabled', 'ellipsis', 'type'],
    outputs: ['contentChange', 'copy']
  }],
  host: {
    '[class.cmm-text]': 'true',
    '[class.cmm-text-paragraph]': 'isParagraph',
    '[class.cmm-text-inline]': '!isParagraph'
  }
})
export class CmmTextDirective extends BaseComponent implements OnInit {
   _componentStyle = inject(UBCKCustomTypographyStyles)

  private configService = inject(CmmTypographyConfigService);
  
  @Input() size?: 'small' | 'base' | 'large';
  @Input() fontSize?: string; // Allow override per element

  get isParagraph(): boolean {
    return this.el.nativeElement.tagName.toLowerCase() === 'p';
  }

  override ngOnInit(): void {
    super.ngOnInit();
    // Apply font-size: priority is fontSize input > size > config service > default
    let finalSize: string;
    
    if (this.fontSize) {
      finalSize = this.fontSize;
    } else if (this.size) {
      finalSize = this.configService.getTextSize(this.size);
    } else {
      // Default to base size
      finalSize = this.configService.getTextSize('base');
    }
    
    this.renderer.setStyle(this.el.nativeElement, 'font-size', '14px');
  
  }
}