import { Component, input, ChangeDetectionStrategy } from '@angular/core';

import { InputGroupAddonModule } from 'primeng/inputgroupaddon';

@Component({
  selector: 'cmm-inputgroupaddon',
  standalone: true,
  imports: [InputGroupAddonModule],
  template: `
    <p-inputGroupAddon [style]="style() ?? undefined" [styleClass]="styleClass() || ''">
      <ng-content />
    </p-inputGroupAddon>
  `,
  styleUrl: './cmm-inputgroupaddon.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmInputgroupaddonComponent {
  // Input properties
  readonly style = input<Record<string, any>>();
  readonly styleClass = input<string>();
}
