import { computed, Directive, input, output } from '@angular/core';
import { IamBaseIconsProps } from './icon-base';

@Directive({
  host: {
    '(click)': 'onClick($event)',
  },
})
export abstract class IamBasIcon {
  props = input<IamBaseIconsProps>({});
  abstract computedProps: ReturnType<typeof computed>;
  eventClick = output<MouseEvent>({ alias: 'onClick' });
  onClick(event: MouseEvent) {
    this.eventClick.emit(event);
  }
}
