import { Injectable } from "@angular/core";
import { BaseStyle } from "primeng/base";

export const UBCK_VALIDATION_THEME = ({dt}: any)=> `
/* Validation Styles */
:root {
    --cmm-validation-error-color: ${dt('validation.error.color')};
    --cmm-validation-error-bg-alpha: ${dt('validation.error.bgAlpha')};
    --cmm-validation-success-color: ${dt('validation.success.color')};
    --cmm-validation-success-bg-alpha: ${dt('validation.success.bgAlpha')};
    --cmm-form-control-text-color: ${dt('validation.formControl.textColor')};
    --cmm-form-control-bg-color: ${dt('validation.formControl.backgroundColor')};
    --cmm-form-control-border-color: ${dt('validation.formControl.borderColor')};
    --cmm-form-control-border-radius: ${dt('validation.formControl.borderRadius')};
    --cmm-form-control-focus-border-color: ${dt('validation.formControl.focus.borderColor')};
    --cmm-form-control-focus-shadow-color: ${dt('validation.formControl.focus.shadowColor')};
    --cmm-form-control-focus-shadow-alpha: ${dt('validation.formControl.focus.shadowAlpha')};
    --cmm-form-control-disabled-bg-color: ${dt('validation.formControl.disabledBackground')};
    --cmm-validation-error-font-size: ${dt('validation.error.fontSize')};
    --cmm-validation-error-gap: ${dt('validation.error.gap')};
    --cmm-validation-error-margin-top: ${dt('validation.error.marginTop')};
    --cmm-validation-error-icon-size: ${dt('validation.error.icon.size')};
}

.cmm-form-control {
    display: block;
    width: 100%;
    padding: .375rem .75rem;
    font-size: 1rem;
    font-weight: 400;
    line-height: 1.5;
    color: var(--cmm-form-control-text-color);
    background-color: var(--cmm-form-control-bg-color);
    background-clip: padding-box;
    border: 1px solid var(--cmm-form-control-border-color);
    border-radius: var(--cmm-form-control-border-radius);
    transition: border-color .15s ease-in-out, box-shadow .15s ease-in-out;
}

.cmm-form-control:focus {
    color: var(--cmm-form-control-text-color);
    background-color: var(--cmm-form-control-bg-color);
    border-color: var(--cmm-form-control-focus-border-color);
    outline: 0;
    box-shadow: 0 0 0 .25rem rgba(var(--cmm-form-control-focus-shadow-color), var(--cmm-form-control-focus-shadow-alpha));
}

.cmm-form-control:disabled,
.cmm-form-control[readonly] {
    background-color: var(--cmm-form-control-disabled-bg-color);
    opacity: 1;
}

.cmm-form-control.is-valid:focus {
    box-shadow: 0 0 0 .25rem rgba(25, 135, 84, var(--cmm-validation-success-bg-alpha));
}

// .cmm-form-control.is-invalid:focus,
// .cmm-form-control.cmm-form-control-error:focus {
//     border-color: var(--cmm-validation-error-color);
//     box-shadow: 0 0 0 .25rem rgba(220, 53, 69, var(--cmm-validation-error-bg-alpha));
// }

// input.is-invalid,
// textarea.is-invalid,
// select.is-invalid {
//     border-color: var(--cmm-validation-error-color);
//     padding-right: calc(1.5em + .75rem);
//     background-repeat: no-repeat;
//     background-position: right calc(.375em + .1875rem) center;
//     background-size: calc(.75em + .375rem) calc(.75em + .375rem);
// }

// input.is-invalid:focus,
// textarea.is-invalid:focus,
// select.is-invalid:focus {
//     border-color: var(--cmm-validation-error-color);
//     box-shadow: 0 0 0 .2rem rgba(220, 53, 69, var(--cmm-validation-error-bg-alpha));
// }

input.ng-invalid.ng-touched,
textarea.ng-invalid.ng-touched,
select.ng-invalid.ng-touched {
    border-color: var(--cmm-validation-error-color);
}

input.ng-invalid.ng-touched:focus,
textarea.ng-invalid.ng-touched:focus,
select.ng-invalid.ng-touched:focus {
    border-color: var(--cmm-validation-error-color);
    box-shadow: 0 0 0 .2rem rgba(220, 53, 69, var(--cmm-validation-error-bg-alpha));
}

/* Override default styles for submit mode - only show when explicitly enabled */
.cmm-validation-submit-mode.ng-invalid.ng-touched:not(.cmm-validation-show-errors),
.cmm-validation-submit-mode.ng-invalid.ng-touched:not(.cmm-validation-show-errors):focus {
    border-color: var(--cmm-form-control-border-color) !important;
    box-shadow: none !important;
}

/* Show validation styles only when explicitly enabled for submit mode */
.cmm-validation-submit-mode.cmm-validation-show-errors.ng-invalid.ng-touched,
.cmm-validation-submit-mode.cmm-validation-show-errors.ng-invalid.ng-touched:focus {
    border-color: var(--cmm-validation-error-color) !important;
}

input.cmm-form-control-error,
textarea.cmm-form-control-error,
select.cmm-form-control-error {
    border-color: var(--cmm-validation-error-color);
}

input.is-valid,
textarea.is-valid,
select.is-valid {
    background-repeat: no-repeat;
    background-position: right calc(.375em + .1875rem) center;
    background-size: calc(.75em + .375rem) calc(.75em + .375rem);
}

input.is-valid:focus,
textarea.is-valid:focus,
select.is-valid:focus {
    box-shadow: 0 0 0 .2rem rgba(40, 167, 69, var(--cmm-validation-success-bg-alpha));
}

/* PrimeNG Input Text */
// input.p-inputtext.is-invalid,
input.p-inputtext.ng-invalid.ng-touched {
    border-color: var(--cmm-validation-error-color);
}

// input.p-inputtext.is-invalid:focus,
input.p-inputtext.ng-invalid.ng-touched:enabled:focus {
    border-color: var(--cmm-validation-error-color);
    box-shadow: 0 0 0 .2rem rgba(220, 53, 69, var(--cmm-validation-error-bg-alpha));
}

/* PrimeNG Dropdown & Select */
p-dropdown.ng-invalid.ng-touched .p-dropdown,
p-select.ng-invalid.ng-touched .p-select,
cmm-select.ng-invalid.ng-touched p-select {
    border-color: var(--cmm-validation-error-color);
}

p-dropdown.ng-invalid.ng-touched .p-dropdown:focus,
p-select.ng-invalid.ng-touched .p-select:focus,
cmm-select.ng-invalid.ng-touched p-select:focus {
    border-color: var(--cmm-validation-error-color);
    box-shadow: 0 0 0 .2rem rgba(220, 53, 69, var(--cmm-validation-error-bg-alpha));
}

cmm-select.ng-invalid.ng-touched .p-select-label.p-placeholder,
p-select.ng-invalid.ng-touched .p-select-label.p-placeholder {
    color: var(--cmm-validation-error-color);
}

/* PrimeNG Calendar / DatePicker */
p-calendar.ng-invalid.ng-touched .p-inputtext,
cmm-datepicker.ng-invalid.ng-touched .p-datepicker-input {
    border-color: var(--cmm-validation-error-color);
}

p-calendar.ng-invalid.ng-touched .p-inputtext:enabled:focus,
cmm-datepicker.ng-invalid.ng-touched .p-datepicker-input:enabled:focus {
    border-color: var(--cmm-validation-error-color);
    box-shadow: 0 0 0 .2rem rgba(220, 53, 69, var(--cmm-validation-error-bg-alpha));
}

cmm-datepicker.ng-invalid.ng-touched .p-datepicker-input::placeholder,
cmm-datepicker.ng-invalid.ng-touched .p-datepicker-input::-webkit-input-placeholder,
cmm-datepicker.ng-invalid.ng-touched .p-datepicker-input::-moz-placeholder,
cmm-datepicker.ng-invalid.ng-touched .p-datepicker-input:-ms-input-placeholder {
    color: var(--cmm-validation-error-color);
}

/* PrimeNG Password */
cmm-password.ng-invalid.ng-touched .p-inputtext,
p-password.ng-invalid.ng-touched .p-inputtext {
    border-color: var(--cmm-validation-error-color);
}

cmm-password.ng-invalid.ng-touched .p-inputtext::placeholder,
p-password.ng-invalid.ng-touched .p-inputtext::placeholder,
cmm-password.ng-invalid.ng-touched .p-inputtext::-webkit-input-placeholder,
p-password.ng-invalid.ng-touched .p-inputtext::-webkit-input-placeholder,
cmm-password.ng-invalid.ng-touched .p-inputtext::-moz-placeholder,
p-password.ng-invalid.ng-touched .p-inputtext::-moz-placeholder,
cmm-password.ng-invalid.ng-touched .p-inputtext:-ms-input-placeholder,
p-password.ng-invalid.ng-touched .p-inputtext:-ms-input-placeholder {
    color: var(--cmm-validation-error-color);
}

p-password.ng-invalid.ng-touched .p-inputtext:enabled:focus {
    border-color: var(--cmm-validation-error-color);
    box-shadow: 0 0 0 .2rem rgba(220, 53, 69, var(--cmm-validation-error-bg-alpha));
}

/* PrimeNG MultiSelect */
p-multiselect.ng-invalid.ng-touched .p-multiselect,
cmm-multiselect.ng-invalid.ng-touched p-multiselect {
    border-color: var(--cmm-validation-error-color);
}

p-multiselect.ng-invalid.ng-touched .p-multiselect:not(.p-disabled).p-focus,
cmm-multiselect.ng-invalid.ng-touched p-multiselect:not(.p-disabled).p-focus {
    border-color: var(--cmm-validation-error-color);
    box-shadow: 0 0 0 .2rem rgba(220, 53, 69, var(--cmm-validation-error-bg-alpha));
}

cmm-multiselect.ng-invalid.ng-touched .p-multiselect-label.p-placeholder,
p-multiselect.ng-invalid.ng-touched .p-multiselect-label.p-placeholder {
    color: var(--cmm-validation-error-color);
}

/* PrimeNG InputNumber */
p-inputnumber.ng-invalid.ng-touched .p-inputnumber-input {
    border-color: var(--cmm-validation-error-color);
}

p-inputnumber.ng-invalid.ng-touched .p-inputnumber-input:enabled:focus {
    border-color: var(--cmm-validation-error-color);
    box-shadow: 0 0 0 .2rem rgba(220, 53, 69, var(--cmm-validation-error-bg-alpha));
}

/* Custom Dropdowns */
cmm-dropdown-lazy.ng-invalid.ng-touched .title,
cmm-dropdown-checkbox.ng-invalid.ng-touched .title {
    border-color: var(--cmm-validation-error-color);
}

cmm-dropdown-lazy.ng-invalid.ng-touched .title:focus,
cmm-dropdown-checkbox.ng-invalid.ng-touched .title:focus {
    border-color: var(--cmm-validation-error-color);
    box-shadow: 0 0 0 .2rem rgba(220, 53, 69, var(--cmm-validation-error-bg-alpha));
}

cmm-dropdown-lazy.ng-invalid.ng-touched .title-content.placeholder,
cmm-dropdown-checkbox.ng-invalid.ng-touched .placeholder {
    color: var(--cmm-validation-error-color);
}

/* Validation Component */
:host {
    display: block;
    width: 100%;
}

/* Validation Error Message */
.validation-error {
    display: flex;
    align-items: flex-start;
    gap: var(--cmm-validation-error-gap);
    margin-top: var(--cmm-validation-error-margin-top);
    font-size: var(--cmm-validation-error-font-size);
    color: var(--cmm-validation-error-color);
    animation: fadeIn .2s ease-in;
}

.validation-error-icon {
    width: var(--cmm-validation-error-icon-size);
    height: var(--cmm-validation-error-icon-size);
    min-width: var(--cmm-validation-error-icon-size);
    margin-top: 2px;
}

.validation-error-message {
    line-height: 1.4;
}


@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(-4px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@media (max-width: 576px) {
    .cmm-form-control {
        font-size: 16px;
    }
}
`;

export const  UBCK_VALIDATION_CLASSES = {

}
@Injectable()
export class UbckValidationStyles extends BaseStyle {
   override name = 'validation';
   override style = UBCK_VALIDATION_THEME;
   override classes = UBCK_VALIDATION_CLASSES;
}