/**
 * Button size options
 */
export const BUTTON_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type ButtonSize = (typeof BUTTON_SIZES)[keyof typeof BUTTON_SIZES];

/**
 * Button style variants
 */
export const BUTTON_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export type ButtonVariant = (typeof BUTTON_VARIANTS)[keyof typeof BUTTON_VARIANTS];

/**
 * Button severities
 */
export const BUTTON_SEVERITIES = {
  PRIMARY: 'primary',
  SECONDARY: 'secondary',
  SUCCESS: 'success',
  INFO: 'info',
  WARNING: 'warning',
  DANGER: 'danger',
  HELP: 'help',
  CONTRAST: 'contrast',
} as const;

export type ButtonSeverity = (typeof BUTTON_SEVERITIES)[keyof typeof BUTTON_SEVERITIES];

/**
 * Button icon positions
 */
export const BUTTON_ICON_POSITIONS = {
  LEFT: 'left',
  RIGHT: 'right',
  TOP: 'top',
  BOTTOM: 'bottom',
} as const;

export type ButtonIconPosition = (typeof BUTTON_ICON_POSITIONS)[keyof typeof BUTTON_ICON_POSITIONS];

/**
 * Button types
 */
export const BUTTON_TYPES = {
  BUTTON: 'button',
  SUBMIT: 'submit',
  RESET: 'reset',
} as const;

export type ButtonType = (typeof BUTTON_TYPES)[keyof typeof BUTTON_TYPES];
