import { Directive, input, computed } from '@angular/core';
import { BadgeDirective } from 'primeng/badge';

@Directive({
  selector: '[cmmBadge]',
  standalone: true,
  hostDirectives: [BadgeDirective],
  exportAs: 'cmmbadge',
  host: {
    '[attr.pBadge]': 'cmmBadge() || value()',
    '[attr.badgeClass]': 'computedBadgeClass()',
    '[attr.badgeSize]': 'badgeSize()',
    '[attr.severity]': 'severity()',
    '[attr.badgeDisabled]': 'disabled()',
  },
})
export class CmmBadgeDirective {
  // Signal inputs - Schema props
  cmmBadge = input<string | number>(''); // Main directive input (shorthand for value)
  value = input<string | number>(''); // Schema: value to display (alternative to cmmBadge)
  disabled = input<boolean>(false); // Schema: disabled state
  badgeSize = input<'small' | 'large' | 'xlarge'>(); // Schema: size
  severity = input<'primary' | 'secondary' | 'success' | 'info' | 'warn' | 'danger' | 'contrast' | 'help'>(); // Schema: severity type

  // Custom enhancements
  badgeClass = input<string>('');
  variant = input<'outlined' | 'filled'>('filled');
  customSize = input<'small' | 'default' | 'large'>('default');

  // Computed badge class with variants
  computedBadgeClass = computed(() => {
    const classes = ['cmm-badge', `cmm-badge--${this.variant()}`, `cmm-badge--${this.customSize()}`, this.badgeClass()];
    return classes.filter(Boolean).join(' ');
  });
}
