import { Component, ChangeDetectionStrategy, input, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Tag } from 'primeng/tag';

@Component({
  selector: 'cmm-tag',
  standalone: true,
  imports: [CommonModule, Tag],
  templateUrl: './cmm-tag.component.html',
  styleUrl: './cmm-tag.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmTagComponent {
  style = input<Record<string, any>>();
  styleClass = input<string>('');
  severity = input<'secondary' | 'success' | 'info' | 'warn' | 'danger' | 'contrast'>();
  value = input<string>();
  icon = input<string>();
  rounded = input<boolean>(false);

  iconTemplate = contentChild<TemplateRef<any>>('icon');
}
