/**
 * Common Input Patterns
 * 
 * Pre-defined regex patterns for common input restrictions.
 * Use with cmmInputRestrict directive.
 * 
 * @example
 * ```html
 * <input cmmInputRestrict [pattern]="InputPatterns.DIGITS_ONLY" />
 * <input cmmInputRestrict [pattern]="InputPatterns.ALPHANUMERIC" />
 * ```
 */
export const InputPatterns = {
  /**
   * Digits only (0-9)
   */
  DIGITS_ONLY: /^\d+$/,

  /**
   * Letters only (a-z, A-Z)
   */
  LETTERS_ONLY: /^[a-zA-Z]+$/,

  /**
   * Alphanumeric (a-z, A-Z, 0-9)
   */
  ALPHANUMERIC: /^[a-zA-Z0-9]+$/,

  /**
   * Alphanumeric with underscore and hyphen
   * Useful for usernames, slugs
   */
  ALPHANUMERIC_DASH: /^[a-zA-Z0-9_-]+$/,

  /**
   * Decimal number (digits and single dot)
   */
  DECIMAL: /^[0-9.]+$/,

  /**
   * Integer (positive or negative)
   */
  INTEGER: /^-?\d+$/,

  /**
   * Vietnamese characters with diacritics
   */
  VIETNAMESE: /^[a-zA-ZàáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴÈÉẸẺẼÊỀẾỆỂỄÌÍỊỈĨÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠÙÚỤỦŨƯỪỨỰỬỮỲÝỴỶỸĐ\s]+$/,

  /**
   * Vietnamese alphanumeric
   */
  VIETNAMESE_ALPHANUMERIC: /^[a-zA-Z0-9àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴÈÉẸẺẼÊỀẾỆỂỄÌÍỊỈĨÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠÙÚỤỦŨƯỪỨỰỬỮỲÝỴỶỸĐ\s]+$/,

  /**
   * Email characters (basic)
   */
  EMAIL_CHARS: /^[a-zA-Z0-9@._-]+$/,

  /**
   * URL safe characters
   */
  URL_SAFE: /^[a-zA-Z0-9-._~:/?#[\]@!$&'()*+,;=]+$/,

  /**
   * Hex color code
   */
  HEX_COLOR: /^[0-9A-Fa-f]+$/,

  /**
   * Credit card number (digits and spaces)
   */
  CREDIT_CARD: /^[0-9\s]+$/,

  /**
   * Vietnamese phone number (digits, +, spaces, hyphens)
   */
  PHONE_NUMBER: /^[0-9+\s-]+$/,
} as const;

/**
 * Character patterns for filterByPattern
 * These match individual characters (not full strings)
 */
export const CharPatterns = {
  DIGIT: '[0-9]',
  LETTER: '[a-zA-Z]',
  ALPHANUMERIC: '[a-zA-Z0-9]',
  ALPHANUMERIC_DASH: '[a-zA-Z0-9_-]',
  DECIMAL: '[0-9.]',
  VIETNAMESE: '[a-zA-ZàáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđÀÁẠẢÃÂẦẤẬẨẪĂẰẮẶẲẴÈÉẸẺẼÊỀẾỆỂỄÌÍỊỈĨÒÓỌỎÕÔỒỐỘỔỖƠỜỚỢỞỠÙÚỤỦŨƯỪỨỰỬỮỲÝỴỶỸĐ\\s]',
  WORD: '[\\w]',
  HEX: '[0-9A-Fa-f]',
} as const;

/**
 * Custom validator functions for complex restrictions
 */
export const InputValidators = {
  /**
   * Validate decimal number (only one dot allowed)
   */
  decimal: (value: string): boolean => {
    const dotCount = (value.match(/\./g) || []).length;
    return dotCount <= 1;
  },

  /**
   * Validate Vietnamese phone number format
   * Accepts: 0xxxxxxxxx, +84xxxxxxxxx, 84xxxxxxxxx
   */
  vietnamesePhone: (value: string): boolean => {
    const cleaned = value.replace(/[\s-]/g, '');
    return /^(0|\+?84)[0-9]{9}$/.test(cleaned);
  },

  /**
   * Validate credit card number (Luhn algorithm)
   */
  creditCard: (value: string): boolean => {
    const cleaned = value.replace(/\s/g, '');
    if (!/^\d+$/.test(cleaned)) return false;

    let sum = 0;
    let shouldDouble = false;

    for (let i = cleaned.length - 1; i >= 0; i--) {
      let digit = Number.parseInt(cleaned[i]);

      if (shouldDouble) {
        digit *= 2;
        if (digit > 9) digit -= 9;
      }

      sum += digit;
      shouldDouble = !shouldDouble;
    }

    return sum % 10 === 0;
  },

  /**
   * No consecutive spaces
   */
  noConsecutiveSpaces: (value: string): boolean => {
    return !/\s{2,}/.test(value);
  },

  /**
   * No leading/trailing spaces
   */
  noLeadingTrailingSpaces: (value: string): boolean => {
    return value === value.trim();
  },
} as const;
