import { Directive, input, output, HostListener } from '@angular/core';
import { DropEffect } from './cmm-dragdrop.types';
import { DRAGDROP_DEFAULTS } from './cmm-dragdrop.constants';

@Directive({
  selector: '[cmmDroppable]',
  standalone: true,
})
export class CmmDroppableDirective {
  // Core props
  disabled = input<boolean>(DRAGDROP_DEFAULTS.DROPPABLE_DISABLED);
  dropEffect = input<DropEffect>(DRAGDROP_DEFAULTS.DROP_EFFECT);

  // Output events
  onDragEnter = output<DragEvent>();
  onDragLeave = output<DragEvent>();
  onDrop = output<DragEvent>();

  @HostListener('dragenter', ['$event'])
  handleDragEnter(event: DragEvent): void {
    if (this.disabled()) {
      return;
    }
    event.preventDefault();
    this.onDragEnter.emit(event);
  }

  @HostListener('dragover', ['$event'])
  handleDragOver(event: DragEvent): void {
    if (this.disabled()) {
      return;
    }
    event.preventDefault();
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = this.dropEffect();
    }
  }

  @HostListener('dragleave', ['$event'])
  handleDragLeave(event: DragEvent): void {
    if (this.disabled()) {
      return;
    }
    this.onDragLeave.emit(event);
  }

  @HostListener('drop', ['$event'])
  handleDrop(event: DragEvent): void {
    if (this.disabled()) {
      return;
    }
    event.preventDefault();
    this.onDrop.emit(event);
  }
}
