import { Component, input, output, model, ChangeDetectionStrategy, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FieldsetModule } from 'primeng/fieldset';
import { FIELDSET_DEFAULTS } from './cmm-fieldset.constants';
import { FieldsetAfterToggleEvent, FieldsetBeforeToggleEvent } from './cmm-fieldset.types';

@Component({
  selector: 'cmm-fieldset',
  standalone: true,
  imports: [CommonModule, FieldsetModule],
  template: `
    <p-fieldset
      [legend]="legend()"
      [toggleable]="toggleable()"
      [(collapsed)]="collapsed"
      [style]="style()"
      [styleClass]="styleClass()"
      [transitionOptions]="transitionOptions()"
      (onBeforeToggle)="onBeforeToggle.emit($event)"
      (onAfterToggle)="onAfterToggle.emit($event)"
    >
      @if (headerTemplate()) {
        <ng-template pTemplate="header">
          <ng-container *ngTemplateOutlet="headerTemplate()!" />
        </ng-template>
      }
      @if (expandiconTemplate()) {
        <ng-template pTemplate="expandicon">
          <ng-container *ngTemplateOutlet="expandiconTemplate()!" />
        </ng-template>
      }
      @if (collapseiconTemplate()) {
        <ng-template pTemplate="collapseicon">
          <ng-container *ngTemplateOutlet="collapseiconTemplate()!" />
        </ng-template>
      }
      @if (contentTemplate()) {
        <ng-template pTemplate="content">
          <ng-container *ngTemplateOutlet="contentTemplate()!" />
        </ng-template>
      } @else {
        <ng-content />
      }
    </p-fieldset>
  `,
  styleUrl: './cmm-fieldset.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmFieldsetComponent {
  // Model for two-way binding
  collapsed = model<boolean>(FIELDSET_DEFAULTS.COLLAPSED);

  // Template references
  readonly headerTemplate = contentChild<TemplateRef<any>>('header');
  readonly expandiconTemplate = contentChild<TemplateRef<any>>('expandicon');
  readonly collapseiconTemplate = contentChild<TemplateRef<any>>('collapseicon');
  readonly contentTemplate = contentChild<TemplateRef<any>>('content');

  // Input properties
  readonly legend = input<string>('');
  readonly toggleable = input<boolean>(FIELDSET_DEFAULTS.TOGGLEABLE);
  readonly style = input<Record<string, any>>();
  readonly styleClass = input<string>('');
  readonly transitionOptions = input<string>('400ms cubic-bezier(0.86, 0, 0.07, 1)');

  // Output events
  readonly onBeforeToggle = output<FieldsetBeforeToggleEvent>();
  readonly onAfterToggle = output<FieldsetAfterToggleEvent>();
}
