

import { CommonModule } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  effect,
  forwardRef,
  inject,
  input,
  output,
  signal,
  TemplateRef,
  viewChild,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { CmmButtonComponent } from '../base/primeng/button/cmm-button.component';
import { FILEUPLOAD_DEFAULTS } from '../base/primeng/file-upload/file-upload.const';
import { CmmTypepographyModule } from '../typography/public-api';
import { FileRemoveEvent, FileSelectEvent, FileUpload, FileUploadErrorEvent, FileUploadEvent } from 'primeng/fileupload';
// Facade & Services
import { UploadFacade } from './upload.facade';
import { FileValidationService } from './upload.service';
import { FileValidationError, UploadProps } from './upload.types';
import { extractFilesFromDragEvent, FileType, formatFileSize, getFileType } from './upload.utils';
import { Button } from 'primeng/button';
import { TranslatePipe } from '@ngx-translate/core';
import { ProgressBar } from 'primeng/progressbar';

@Component({
  selector: 'app-upload',
  imports: [CmmButtonComponent, CommonModule, CmmTypepographyModule, Button, TranslatePipe, ProgressBar, FileUpload],
  templateUrl: './upload.component.html',
  styleUrl: './upload.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => UploadComponent),
      multi: true,
    },
    // Provide facade and its dependencies
    UploadFacade,
    FileValidationService,
  ],
})
export class UploadComponent implements ControlValueAccessor {
  // ========================================
  // FACADE INJECTION
  // ========================================
  private readonly facade = inject(UploadFacade);

  // ========================================
  // INPUTS - Single Props Configuration
  // ========================================
  props = input<UploadProps>({});
  cvaDisabled = signal(false);

  readonly uploadComponent = viewChild<FileUpload>('upload');



  // Computed props with defaults
  computedProps = computed(() => {
    const p = this.props();
    return {

      ...p,
      // Behavior Configuration
      name: p.name ?? 'files[]',
      url: p.url ?? '',
      method: p.method ?? FILEUPLOAD_DEFAULTS.METHOD,
      multiple: p.multiple ?? false,
      disabled: (p.disabled ?? false) || this.cvaDisabled(),
      auto: p.auto ?? false,

      // Validation Configuration
      maxFileSize: p.maxFileSize ?? FILEUPLOAD_DEFAULTS.MAX_FILE_SIZE,
      maxFiles: p.maxFiles ?? 10,
      minFiles: p.minFiles ?? 0,
      accept: p.accept ?? '.xls,.xlsx,.ods',

      // UI Labels
      title: p.title ?? 'Thêm tài sản theo tệp',
      chooseLabel: p.chooseLabel ?? 'Chọn tệp',
      dropZoneLabel: p.dropZoneLabel ?? 'Kéo thả tệp vào đây',
      orLabel: p.orLabel ?? 'Hoặc',
      acceptInfoLabel: p.acceptInfoLabel ?? 'Chấp nhận file .xls, .xlsx và .ods có dung lượng tối đa 5mb.',
      primaryButtonLabel: p.primaryButtonLabel ?? 'Thêm mới',
      secondaryButtonLabel: p.secondaryButtonLabel ?? 'Đóng',
      importNoteLabel: p.importNoteLabel ?? 'Để có kết quả nhập khẩu chính xác, hãy sử dụng tệp mẫu',
      templateLinkLabel: p.templateLinkLabel ?? 'Tải tệp mẫu',
      importWarningLabel: p.importWarningLabel ?? 'Mỗi dòng dữ liệu trong tệp nhập khẩu tương ứng với 1 bản ghi.',

      // UI Visibility
      showTemplateLink: p.showTemplateLink ?? false,
      showImportNotes: p.showImportNotes ?? false,
      showFooter: p.showFooter ?? false,
      uploading: p.uploading ?? false,
      showProgressBar: p.showProgressBar ?? false,
      uploadPercent: p.uploadPercent ?? 0,
      fileItemTemplate: p.fileItemTemplate ?? null,
      invalidFileSizeMessageDetail: p.invalidFileSizeMessageDetail ?? 'File quá lớn. Giới hạn tối đa 5MB.',
      invalidFileLimitMessageDetail: p.invalidFileLimitMessageDetail ?? '',
      invalidFileTypeMessageDetail: p.invalidFileTypeMessageDetail ?? '',
      invalidFileSizeMessageSummary: p.invalidFileSizeMessageSummary ?? '',
      invalidFileTypeMessageSummary: p.invalidFileTypeMessageSummary ?? '',
      invalidFileLimitMessageSummary: p.invalidFileLimitMessageSummary ?? '',
      summary: p.summary ?? 'Lỗi',
      fileNameClass: p.fileNameClass ?? ''
    };
  });

  // ========================================
  // OUTPUTS - Events
  // ========================================
  fileSelect = output<File[]>();
  fileRemove = output<File>();
  validationError = output<FileValidationError>();
  dragValidationError = output<FileValidationError[]>();
  primaryAction = output<File[]>();
  secondaryAction = output<void>();
  templateDownload = output<void>();

  // ========================================
  // CONTENT PROJECTION - Template Overrides (Fallback Pattern)
  // ========================================
  headerTemplate = contentChild<TemplateRef<any>>('headerTemplate');
  contentTemplate = contentChild<TemplateRef<any>>('contentTemplate');
  emptyTemplate = contentChild<TemplateRef<any>>('emptyTemplate');
  infoTemplate = contentChild<TemplateRef<any>>('infoTemplate');
  footerTemplate = contentChild<TemplateRef<any>>('footerTemplate');
  fileItemTemplate = contentChild<TemplateRef<any>>('fileItemTemplate');

  // ========================================
  // READONLY SIGNALS FROM FACADE
  // ========================================
  readonly selectedFiles = this.facade.files;
  readonly validationErrors = this.facade.errors;
  readonly isUploading = this.facade.isUploading;
  readonly isDragOver = this.facade.isDragOver;
  readonly isDragInvalid = this.facade.isDragInvalid;
  readonly dragErrors = this.facade.dragErrors;
  readonly hasFiles = this.facade.hasFiles;
  readonly fileCount = this.facade.fileCount;
  readonly isValid = this.facade.isValid;
  readonly canSubmit = this.facade.canSubmit;

  isDragError = computed(() => this.isDragInvalid());

  // ========================================
  // ControlValueAccessor
  // ========================================
  private onChange: (value: File[] | null) => void = () => { };
  private onTouched: () => void = () => { };

  writeValue(value: File[] | null): void {
    this.facade.setFiles(value);
  }

  registerOnChange(fn: (value: File[] | null) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.cvaDisabled.set(isDisabled);
  }

  // ========================================
  // EFFECTS - Sync facade to form control
  // ========================================
  constructor() {
    // Update validation config when props change
    effect(() => {
      const props = this.computedProps();
      this.facade.updateConfig({
        maxFileSize: props.maxFileSize,
        maxFiles: props.maxFiles,
        minFiles: props.minFiles,
        accept: props.accept,
        invalidFileSizeMessageDetail: props.invalidFileSizeMessageDetail ?? '',
        invalidFileLimitMessageDetail: props.invalidFileLimitMessageDetail ?? '',
        invalidFileTypeMessageDetail: props.invalidFileTypeMessageDetail ?? '',
        invalidFileSizeMessageSummary: props.invalidFileSizeMessageSummary ?? '',
        invalidFileTypeMessageSummary: props.invalidFileTypeMessageSummary ?? '',
        invalidFileLimitMessageSummary: props.invalidFileLimitMessageSummary ?? '',
      });
    });

    // Update multiple flag
    effect(() => {
      this.facade.setMultiple(this.computedProps().multiple);
    });

    // Sync files to form control
    effect(() => {
      const files = this.facade.files();
      this.onChange(files.length > 0 ? files : null);
    });
  }

  // ========================================
  // EVENT HANDLERS - Forward to Facade
  // ========================================
  onSelect(event: FileSelectEvent, msgs: { severity: string, text: string }[] | undefined): void {
    msgs && msgs.forEach(ms => {
      this.validationError.emit({
        type: 'custom',
        message: ms.text,
      })
    });

    this.facade.selectFiles(event.currentFiles);
    this.fileSelect.emit(event.currentFiles);
    this.onTouched();
  }
  onRemove(event: FileRemoveEvent): void {
    const file = event.file;
    const index = this.facade.getFiles().indexOf(file);
    this.facade.removeFile(index);
    this.fileRemove.emit(file);
    this.onTouched();
  }

  onUpload(_: FileUploadEvent): void {
    this.facade.setUploading(false);

  }

  onError(event: FileUploadErrorEvent): void {
    this.facade.setUploading(false);
    this.validationError.emit({
      type: 'custom',
      message: 'Lỗi tải lên tệp',
    });
    console.error('Upload error:', event);
  }

  onClear(_event: Event): void {
    this.facade.clearFiles();
    this.onTouched();
  }

  onRemoveFile(file: File, index: number): void {
    this.facade.removeFile(index);
    this.fileRemove.emit(file);
    this.onTouched();
  }

  onRemoveFileUploadWithTemplate(event: Event, index: number,): void {
    this.uploadComponent()?.remove(event, index);
    this.onTouched();
  }

  onChoose(_event: Event, chooseCallback: () => void): void {
    chooseCallback();
    this.onTouched();

  }

  // Drag and drop handlers - Forward to Facade
  onDragOver(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    this.facade.setDragOver(true);


    // Validate dragged files to show visual feedback
    // Note: Full file access only on drop, but we can check MIME types
    this.facade.validateOnDragOver(event);
  }

  onDragLeave(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    // Check if we're actually leaving the drop zone
    const target = event.target as HTMLElement;
    const relatedTarget = event.relatedTarget as HTMLElement;
    if (!target.contains(relatedTarget)) {
      this.facade.setDragOver(false);
      this.facade.setDragInvalid(false);
    }
  }

  onDrop(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();

    // Extract files and forward to facade
    const files = extractFilesFromDragEvent(event);
    const errors = this.facade.handleDrop(files);


    // Emit validation errors if any
    if (errors.length > 0) {
      errors.forEach((error) => {
        console.log(error);

        this.validationError.emit(error);
      });
    } else {
      this.fileSelect.emit(this.facade.getFiles());
    }

    this.onTouched();
  }

  onPrimaryAction(): void {
    if (this.facade.canSubmit()) {
      this.primaryAction.emit(this.facade.getFiles());
    }
  }

  onSecondaryAction(): void {
    this.secondaryAction.emit();
  }

  onTemplateDownload(): void {
    this.templateDownload.emit();
  }

  // ========================================
  // UTILITY METHODS - Delegated to Utils
  // ========================================
  formatFileSize(bytes: number): string {
    return formatFileSize(bytes);
  }

  // File type detection - delegated to utils
  getFileType(file: File): FileType {
    return getFileType(file);
  }

  // Total size - delegated to facade
  getTotalSize(): string {
    return this.facade.totalSizeFormatted();
  }

  // ========================================
  // PUBLIC API - For programmatic control
  // ========================================
  public clearFiles(): void {
    this.facade.clearFiles();
  }

  public addFiles(files: File[]): void {
    this.facade.selectFiles(files);
  }

  public getFiles(): File[] {
    return this.facade.getFiles();
  }

  public getErrors(): FileValidationError[] {
    return this.facade.getErrors();
  }

  public totalSizeFormatted(): string {
    return formatFileSize(this.facade.totalSize());
  }
}
