import { PaginatorState } from 'primeng/paginator';
import { UBCKPaginatorState } from '../paginator.types';
import { UBCK_PAGINATOR_DEFAULTS } from '../paginator.const';

export function reMapPaginatorState(event: PaginatorState): UBCKPaginatorState {
  return {
    ...event,
    currentPage:
      event?.page && !isNaN(event.page) ? Math.max(event.page + 1, 0) : UBCK_PAGINATOR_DEFAULTS.CURRENT_PAGE,
    recordPerPage: event.rows || UBCK_PAGINATOR_DEFAULTS.ROWS,
  };
}
