import {
  afterRenderEffect,
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  DestroyRef,
  ElementRef,
  EventEmitter,
  inject,
  input,
  Output,
  signal,
  TemplateRef,
  viewChild,
  viewChildren,
} from '@angular/core';
import { NgTemplateOutlet } from '@angular/common';
import { ChipItem, ChipListProps } from './chip-list.types';

/**
 * Debounce window (ms) for the resize-driven recompute. A window/container drag
 * fires the `ResizeObserver` on every frame; coalescing that burst into a single
 * recompute once the size settles stops the visible-count flip-flop near a row
 * boundary that otherwise reads as flickering chips.
 */
const RESIZE_DEBOUNCE_MS = 500;

/**
 * Renders a horizontal list of chips and collapses the ones that don't fit
 * within `maxRows` into a single `+N` badge.
 *
 * - `maxRows` (default 2): how many rows of chips are visible before collapsing.
 * - `maxVisible` (default `2`): hard cap on how many chips are shown. When set
 *   to a positive number `X`, at most `X` chips render and the rest collapse into
 *   `+(items.length - X)`. It only ever *lowers* the visible count — the layout
 *   measurement can still hide more chips if they don't physically fit. Pass
 *   `0` to opt out of the cap so the count is driven purely by the width/row
 *   measurement (e.g. to let `maxRows` alone decide how many chips fit).
 * - `chipsPerRow` (default `2`): "grid mode". When set to a positive number `N`,
 *   the list renders a deterministic `N`-per-row grid over at most `maxRows` rows
 *   instead of measuring pixel widths — so a 2x2 grid always shows up to 4 chips.
 *   The `+N` badge is appended as an *extra* on the last row (it does not take a
 *   chip slot). Chips too wide to sit `N`-per-row shrink + ellipsize rather than
 *   wrapping. `maxVisible` is ignored while grid mode is active. Pass `0` to fall
 *   back to width-measured mode. See {@link ChipListProps}.
 * - The `+N` badge always shows the tooltip (full, comma-joined name list).
 * - `orderChipBy` (default `'text-shortest-to-longest'`): sorts chips by `name`
 *   length before rendering/measuring. `'none'` keeps the `items` order as-is.
 */
@Component({
  selector: 'ubck-chip-list',
  imports: [NgTemplateOutlet],
  templateUrl: './chip-list.component.html',
  styleUrl: './chip-list.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class UbckChipList {
  /** All inputs are bundled here; see {@link ChipListProps} for per-field defaults. */
  readonly props = input<ChipListProps>({});
  readonly items = input.required<ChipItem[]>();

  // Internal accessors that unpack `props` and apply per-field defaults, so the
  // template and layout code can keep reading individual signals.
  protected readonly maxRows = computed<number>(() => this.props().maxRows ?? 2);
  protected readonly maxVisible = computed<number | undefined>(() => this.props().maxVisible ?? 0);
  /** Chips per row for the deterministic grid; `2` (default) = width-measured mode. */
  protected readonly chipsPerRow = computed<number>(() => this.props().chipsPerRow ?? 2);
  /** True when `chipsPerRow` is set — switches rendering to the fixed grid layout. */
  protected readonly gridMode = computed<boolean>(() => this.chipsPerRow() > 0);
  protected readonly maxWidth = computed<string | undefined>(() => this.props().maxWidth);
  protected readonly chipMaxLines = computed<number | undefined>(() => this.props().chipMaxLines ?? 1);
  protected readonly chipMaxWidth = computed<string>(() => this.props().chipMaxWidth ?? '10rem');
  protected readonly emptyText = computed<string>(() => this.props().emptyText ?? '-');
  protected readonly chipClass = computed<string>(() => this.props().chipClass ?? '');
  protected readonly chipBadgeClass = computed<string>(() => this.props().chipBadgeClass ?? '');
  protected readonly emptyClass = computed<string>(() => this.props().emptyClass ?? '');
  protected readonly orderChipBy = computed<NonNullable<ChipListProps['orderChipBy']>>(
    () => this.props().orderChipBy ?? 'text-shortest-to-longest',
  );
  protected readonly chipTemplate = contentChild<TemplateRef<unknown>>('chipTemplate');
  protected readonly emptyTemplate = contentChild<TemplateRef<unknown>>('emptyTemplate');

  /**
   * Legacy `@Output()`/`EventEmitter` on purpose: `EventEmitter.observed` is the
   * only reliable way to tell whether a consumer bound the handler, which we use
   * to drive the badge cursor (pointer when bound, default otherwise). The signal
   * `output()` API exposes no equivalent. Emits the hidden chips.
   */
  @Output() badgeClick = new EventEmitter<ChipItem[]>();

  private readonly container = viewChild<ElementRef<HTMLElement>>('container');
  private readonly measureContainer = viewChild<ElementRef<HTMLElement>>('measureContainer');
  private readonly measureChips = viewChildren<ElementRef<HTMLElement>>('measureChip');
  private readonly badgeRef = viewChild<ElementRef<HTMLElement>>('measureBadge');

  /** Number of chips kept visible; the rest are collapsed into the `+N` badge. */
  readonly visibleCount = signal<number>(0);
  /** Becomes true after the first measurement, so the badge isn't flashed early. */
  readonly measured = signal<boolean>(false);

  /** `items()` sorted per `orderChipBy`; drives rendering, measurement and the tooltip/badge. */
  readonly orderedItems = computed<ChipItem[]>(() => {
    const orderBy = this.orderChipBy();
    if (orderBy === 'none') {
      return this.items();
    }
    const direction = orderBy === 'text-longest-to-shortest' ? -1 : 1;
    return [...this.items()].sort((a, b) => direction * (a.name.length - b.name.length));
  });

  readonly tooltip = computed(() =>
    this.orderedItems()
      .map((i) => i.name)
      .join(', '),
  );
  readonly badgeCount = computed(() => Math.max(0, this.orderedItems().length - this.visibleCount()));

  /**
   * Grid mode only: the visible chips chunked into rows of `chipsPerRow`, e.g.
   * `[[c0, c1], [c2, c3]]` for a 2x2 grid. Each row renders as its own
   * `flex-wrap: nowrap` container so the chips shrink to fit rather than wrapping
   * onto extra rows (plain `flex-wrap: wrap` wraps *before* it shrinks, which is
   * what pushed a 2-per-row layout onto 3 lines). Empty in measured mode.
   */
  readonly visibleRows = computed<ChipItem[][]>(() => {
    if (!this.gridMode()) {
      return [];
    }
    const perRow = Math.max(1, this.chipsPerRow());
    const chips = this.orderedItems().slice(0, this.visibleCount());
    const rows: ChipItem[][] = [];
    for (let i = 0; i < chips.length; i += perRow) {
      rows.push(chips.slice(i, i + perRow));
    }
    return rows;
  });

  private resizeObserver?: ResizeObserver;
  private resizeDebounceTimer?: ReturnType<typeof setTimeout>;
  private lastWidth?: number;

  constructor() {
    // Recompute whenever the rendered chips, maxRows or maxVisible change.
    afterRenderEffect(() => {
      // Touch the signals that should trigger a recompute.
      this.measureChips();
      this.chipTemplate();
      this.maxRows();
      this.maxVisible();
      this.chipsPerRow();
      this.orderedItems();
      this.observeContainer();
      this.recompute(true);
    });

    inject(DestroyRef).onDestroy(() => {
      this.resizeObserver?.disconnect();
      clearTimeout(this.resizeDebounceTimer);
    });
  }

  onBadgeClick(): void {
    if (!this.badgeClick.observed) {
      return;
    }
    this.badgeClick.emit(this.orderedItems().slice(this.visibleCount()));
  }


  private observeContainer(): void {
    const host = this.container()?.nativeElement;
    if (!host || this.resizeObserver) {
      return;
    }
    this.resizeObserver = new ResizeObserver(() => this.scheduleRecompute());
    this.resizeObserver.observe(host);
  }

  /**
   * Debounces the resize-driven recompute. The `ResizeObserver` fires on every
   * frame while the container is being dragged/resized; running the layout-reading
   * measurement each time makes the visible count oscillate near a row boundary,
   * which shows up as flickering chips. We instead wait for the size to settle for
   * {@link RESIZE_DEBOUNCE_MS} and recompute once. Data/config changes still go
   * through the (forced, immediate) `afterRenderEffect`, so they never feel laggy.
   */
  private scheduleRecompute(): void {
    clearTimeout(this.resizeDebounceTimer);
    this.resizeDebounceTimer = setTimeout(() => this.recompute(), RESIZE_DEBOUNCE_MS);
  }

  /**
   * Measures the chips by row (via `offsetTop`) and collapses the overflow into
   * the `+N` badge. Measurement runs on a hidden off-flow container so the visible
   * layout is never disturbed, completely eliminating resize-observer layout loops.
   */
  private recompute(force = false): void {
    // Grid mode: the visible count is deterministic (chipsPerRow * maxRows), so
    // skip all pixel measurement. Every slot holds a real chip; the `+N` badge is
    // appended as an extra on the last row (it does NOT consume a chip slot), so a
    // full 2x2 grid shows 4 chips + the badge. CSS shrinks chips to fit the row.
    if (this.gridMode()) {
      const total = this.orderedItems().length;
      const slots = Math.max(1, this.chipsPerRow()) * Math.max(1, this.maxRows());
      this.visibleCount.set(Math.min(total, slots));
      this.measured.set(true);
      return;
    }

    const containerEl = this.container()?.nativeElement;
    const measureEl = this.measureContainer()?.nativeElement;
    if (!containerEl || !measureEl) {
      return;
    }

    const currentWidth = containerEl.clientWidth;
    if (!force && this.lastWidth !== undefined && currentWidth === this.lastWidth) {
      return;
    }

    // Match the measurement container's width to the visible container
    measureEl.style.width = `${currentWidth}px`;

    const chipEls = this.measureChips().map((ref) => ref.nativeElement);
    const total = chipEls.length;

    if (total === 0) {
      this.visibleCount.set(0);
      this.measured.set(true);
      this.lastWidth = currentWidth;
      return;
    }

    const maxRows = Math.max(1, this.maxRows());
    const rowTops = this.rowTops(chipEls);
    const lastAllowedTop = rowTops[Math.min(maxRows, rowTops.length) - 1];

    // Chips that naturally fit within the allowed rows.
    let fit = chipEls.filter((c) => c.offsetTop <= lastAllowedTop).length;

    // Hard cap: never show more than `maxVisible` chips. Unset or 0 leaves the
    // count driven purely by the layout measurement above.
    const maxVisible = this.maxVisible();
    if (maxVisible && maxVisible > 0) {
      fit = Math.min(fit, maxVisible);
    }

    if (total - fit > 0) {
      // The badge will be shown: ensure it fits on the last allowed row,
      // dropping trailing chips until it does.
      const badgeWidth = this.badgeRef()?.nativeElement.offsetWidth ?? 0;
      while (fit > 0 && !this.badgeFits(chipEls, fit, lastAllowedTop, badgeWidth)) {
        fit--;
      }
    }

    this.visibleCount.set(fit);
    this.measured.set(true);
    this.lastWidth = containerEl.clientWidth;
  }

  /** Distinct row offsets (top -> bottom), one per visual row. */
  private rowTops(chips: HTMLElement[]): number[] {
    const tops: number[] = [];
    for (const chip of chips) {
      if (!tops.includes(chip.offsetTop)) {
        tops.push(chip.offsetTop);
      }
    }
    return tops.sort((a, b) => a - b);
  }

  /**
   * Whether the badge placed right after the first `fit` chips would sit on the
   * last allowed row (i.e. not wrap past `lastAllowedTop`).
   */
  private badgeFits(chips: HTMLElement[], fit: number, lastAllowedTop: number, badgeWidth: number): boolean {
    if (fit === 0) {
      return true;
    }
    const container = this.measureContainer()?.nativeElement;
    if (!container) {
      return true;
    }
    const last = chips[fit - 1];
    // Room left of the last visible chip on its row, accounting for the gap.
    const roomOnRow = container.clientWidth - (last.offsetLeft + last.offsetWidth);
    const onAllowedRow = last.offsetTop <= lastAllowedTop;
    return onAllowedRow && roomOnRow >= badgeWidth;
  }
}
