import {
  Component,
  ChangeDetectionStrategy,
  input,
  output,
  contentChild,
  TemplateRef,
  computed,
  model,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { Accordion, AccordionModule, AccordionPanel } from 'primeng/accordion';
import type { AccordionTabOpenEvent, AccordionTabCloseEvent } from 'primeng/accordion';

@Component({
  selector: 'cmm-accordion-panel',
  templateUrl: './cmm-accordion-panel.component.html',
  styleUrls: ['./cmm-accordion-panel.component.scss'],
  standalone: true,
  imports: [CommonModule, AccordionModule],
  exportAs: 'cmmaccordionpanel',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmAccordionPanelComponent {
  // ====================================================
  // ACCORDION COMPONENT PROPS (from schema)
  // ====================================================

  // Value binding (ModelSignal)
  readonly value = model<any>();

  // Multiple mode
  readonly multiple = input<boolean>(false);

  // Styling
  readonly style = input<Record<string, any>>();
  readonly styleClass = input<string>();

  // Icons
  readonly expandIcon = input<string>();
  readonly collapseIcon = input<string>('pi pi-chevron-down');

  // Focus behavior
  readonly selectOnFocus = input<boolean>(false);

  // Animation
  readonly transitionOptions = input<string>('400ms cubic-bezier(0.86, 0, 0.07, 1)');

  // Accessibility
  readonly headerAriaLevel = input<number>(2);

  // Deprecated (keeping for backward compatibility)
  readonly activeIndex = input<number | number[]>();

  // ====================================================
  // ACCORDION TAB/PANEL PROPS (from schema)
  // ====================================================

  // Identity
  readonly id = input<string>();

  // Header
  readonly header = input<string>();
  readonly headerStyle = input<Record<string, any>>();
  readonly headerStyleClass = input<string>();

  // Tab styling
  readonly tabStyle = input<Record<string, any>>();
  readonly tabStyleClass = input<string>();

  // Content styling
  readonly contentStyle = input<Record<string, any>>();
  readonly contentStyleClass = input<string>();

  // Behavior
  readonly disabled = input<boolean>(false);
  readonly cache = input<boolean>(true);
  readonly iconPos = input<'start' | 'end'>('start');
  readonly selected = input<boolean>();

  // Custom props (not in schema)
  readonly size = input<'small' | 'default' | 'large'>('default');
  readonly variant = input<'outlined' | 'filled'>('outlined');

  // ====================================================
  // OUTPUTS (from schema)
  // ====================================================

  // Accordion events
  readonly onClose = output<AccordionTabCloseEvent>();
  readonly onOpen = output<AccordionTabOpenEvent>();

  // Tab events
  readonly selectedChange = output<boolean>();

  // Deprecated
  readonly activeIndexChange = output<number | number[]>();

  // ====================================================
  // TEMPLATES (from schema)
  // ====================================================

  // AccordionHeader templates
  readonly toggleIconTemplate = contentChild<TemplateRef<any>>('toggleicon');

  // AccordionTab templates
  readonly headerTemplate = contentChild<TemplateRef<any>>('header');
  readonly footerTemplate = contentChild<TemplateRef<any>>('footer');
  readonly iconTemplate = contentChild<TemplateRef<any>>('icon');
  readonly contentTemplate = contentChild<TemplateRef<any>>('content');

  // ====================================================
  // COMPUTED PROPERTIES
  // ====================================================

  readonly computedStyleClass = computed(() => {
    const classes = [this.styleClass()];

    if (this.size() !== 'default') {
      classes.push(`cmm-accordion-${this.size()}`);
    }

    if (this.variant()) {
      classes.push(`cmm-accordion-${this.variant()}`);
    }

    return classes.filter(Boolean).join(' ');
  });

  // ====================================================
  // EVENT HANDLERS
  // ====================================================

  handleOpen(event: AccordionTabOpenEvent): void {
    this.onOpen.emit(event);
  }

  handleClose(event: AccordionTabCloseEvent): void {
    this.onClose.emit(event);
  }

  handleSelectedChange(value: boolean): void {
    this.selectedChange.emit(value);
  }

  handleActiveIndexChange(value: number | number[]): void {
    this.activeIndexChange.emit(value);
  }
}
