import {
  Component,
  input,
  output,
  model,
  contentChild,
  viewChild,
  TemplateRef,
  ChangeDetectionStrategy,
  forwardRef,
  computed, HostListener, ElementRef, inject, signal, effect,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import { Select, SelectModule } from 'primeng/select';
import {
  CmmSelectProps,
  SelectChangeEvent,
  SelectFilterEvent,
  SelectLazyLoadEvent,
} from './cmm-select.types';
import { CmmTypepographyModule } from '../../../../custom/typography/public-api';
import {handleOutsideClick} from '../../../../utils/document-event.utils';
import { FloatLabelModule } from 'primeng/floatlabel';
/**
 * Select is a form component to choose a value from a collection of options with virtual scrolling support.
 * Wraps PrimeNG Select component.
 */
@Component({
  selector: 'cmm-select',
  standalone: true,
  imports: [CommonModule, SelectModule, FormsModule, CmmTypepographyModule, FloatLabelModule],
  templateUrl: './cmm-select.component.html',
  styleUrl: './cmm-select.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmSelectComponent),
      multi: true,
    },
  ],
  host: {
  }
})
export class CmmSelectComponent implements ControlValueAccessor {
  private readonly hostElement = inject(ElementRef<HTMLElement>)

  private getDefaultScrollHeight(p?: CmmSelectProps): string {
    const maxVisibleSearchItems = p?.maxVisibleSearchItems ?? 5;
    const itemHeight = p?.virtualScrollItemSize ?? 40;
    const defaultPadding = 8;

    return `${maxVisibleSearchItems * itemHeight + defaultPadding}px`;
  }

  getEmptyStateHeight(): string {
    return this.computedProps().scrollHeight || this.getDefaultScrollHeight(this.props());
  }

  /**
   * Value of the select
   */
   value = model<any>();


  /**
   * Component props
   */
   props = input.required<CmmSelectProps>();

   /** Reactive-forms disabled state (set via setDisabledState) */
   cvaDisabled = signal(false);

   computedProps = computed(() => {
    const p = this.props();
    const isPseudoDisabled = !!p.showTooltipWhenDisabled;

    return {
      ...p,
      scrollHeight: p.scrollHeight ?? this.getDefaultScrollHeight(p),
      filterMatchMode: p.filterMatchMode ?? 'contains',
      variant: p.variant ?? 'outlined',
      appendTo: p.appendTo ?? 'body',
      tooltipPosition: p.tooltipPosition ?? 'top',
      tooltipPositionStyle: p.tooltipPositionStyle ?? '',
      name: p.name ?? '',
      required: p.required ?? false,
      disabled: isPseudoDisabled ? false : (!!p.disabled || this.cvaDisabled()),
      readonly: isPseudoDisabled ? true : !!p.readonly,
      style: this.getStyle(),
      optionGroupChildren: p.optionGroupChildren ?? '',
      tabindex: p.tabindex ?? 0,
      width: p.width ?? '100%',
      dropdownIcon: p.dropdownIcon ?? 'pi pi-chevron-down',
      showTooltipWhenDisabled: isPseudoDisabled,
      styleClass: `${p.styleClass} ${isPseudoDisabled ? 'showTooltipWhenDisabled-item' : ''}`,
      floatLabel: p.floatLabel,
    };
   });

   getPlaceholder(): string {
     if (this.computedProps().floatLabel) {
       // When floatLabel is enabled, the placeholder is used as the floating label text.
       // In this case, we don't want to show the placeholder in the input field itself.
       return '';
     }
     return this.computedProps().placeholder || '';
   }

   getStyle() {
    if (this.props().showTooltipWhenDisabled) {
      return {
        ...this.props().style,
        pointerEvents: 'auto',
        backgroundColor: '#F3F4F6', // Simulate disabled field
      };
    }
    return this.props().style;
   }

  /**
   * Callback to invoke when value of select changes
   */
  onChange = output<SelectChangeEvent>();

  /**
   * Callback to invoke when data is filtered
   */
  onFilter = output<SelectFilterEvent>();

  /**
   * Callback to invoke when select gets focus
   */
  onFocus = output<Event>();

  /**
   * Callback to invoke when select loses focus
   */
  onBlur = output<Event>();

  /**
   * Callback to invoke when component is clicked
   */
  onClick = output<MouseEvent>();

  /**
   * Callback to invoke when select overlay gets visible
   */
  onShow = output<any>();

  handleShow(event: any): void {
    this.onShow.emit(event);
    const maxLength = this.computedProps().maxLength;
    if (maxLength == null) return;
    queueMicrotask(() => {
      const filterEl = this.selectRef()?.filterViewChild?.nativeElement;
      if (filterEl) {
        filterEl.setAttribute('maxlength', String(maxLength));
      }
    });
  }

  /**
   * Callback to invoke when select overlay gets hidden
   */
  onHide = output<any>();

  /**
   * Callback to invoke when select clears the value
   */
  onClear = output<Event>();

  /**
   * Callback to invoke in lazy mode to load new data
   */
  onLazyLoad = output<SelectLazyLoadEvent>();

  /**
   * Custom item template
   */
  itemTemplate = contentChild<TemplateRef<any>>('item');

  /**
   * Custom group template
   */
  groupTemplate = contentChild<TemplateRef<any>>('group');

  /**
   * Custom loader template
   */
  loaderTemplate = contentChild<TemplateRef<any>>('loader');

  /**
   * Custom selected item template
   */
  selecteditemTemplate = contentChild<TemplateRef<any>>('selecteditem');

  /**
   * Custom header template
   */
  headerTemplate = contentChild<TemplateRef<any>>('header');

  /**
   * Custom filter template
   */
  filterTemplate = contentChild<TemplateRef<any>>('filter');

  /**
   * Custom footer template
   */
  footerTemplate = contentChild<TemplateRef<any>>('footer');

  /**
   * Custom empty filter template
   */
  emptyfilterTemplate = contentChild<TemplateRef<any>>('emptyfilter');

  /**
   * Custom empty template
   */
  emptyTemplate = contentChild<TemplateRef<any>>('empty');

  /**
   * Custom dropdown icon template
   */
  dropdowniconTemplate = contentChild<TemplateRef<any>>('dropdownicon');

  /**
   * Custom loading icon template
   */
  loadingiconTemplate = contentChild<TemplateRef<any>>('loadingicon');

  /**
   * Custom clear icon template
   */
  cleariconTemplate = contentChild<TemplateRef<any>>('clearicon');

  /**
   * Custom filter icon template
   */
  filtericonTemplate = contentChild<TemplateRef<any>>('filtericon');

  /**
   * Reference to the PrimeNG Select component
   */
  selectRef = viewChild<Select>('select');

  private onChangeFn: any = () => {};
  private onTouchedFn: any = () => {};

  /**
   * Handles change event
   */
  handleChange(event: any): void {
    this.onChange.emit(event);
    this.onChangeFn(event.value);
  }
  handleClear($event: Event): void {
    this.onClear.emit($event);
    this.onChangeFn(null);
    this.onTouchedFn();
  }

  /**
   * Handles blur event
   */
  handleBlur(event: Event): void {
    this.onBlur.emit(event);
    // Mirrors PrimeNG Select's own `!overlayVisible` guard in onInputBlur().
    if (!this.selectRef()?.overlayVisible) {
      this.onTouchedFn();
    }
  }

  /**
   * Commit the touched state when the overlay closes, mirroring PrimeNG Select's
   * onModelTouched() call in onOverlayAfterLeave(). This covers the filter flow
   * where the combobox input already blurred (while the panel was open) when
   * focus moved into the filter, so handleBlur is skipped on close.
   */
  handleHide(event: any): void {
    this.onHide.emit(event);
    this.onTouchedFn();
  }

  // ControlValueAccessor methods
  writeValue(value: any): void {
    this.value.set(value);
    if (value === null || value === undefined) {
      this.resetFilter();
    }
  }

   registerOnChange(fn: any): void {
    this.onChangeFn = fn;
  }

   registerOnTouched(fn: any): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.cvaDisabled.set(isDisabled);
  }

  /**
   * Callback to invoke on filter reset
   */
  resetFilter(): void {
    this.selectRef()?.resetFilter();
  }

  /**
   * Displays the panel
   */
  show(isFocus?: boolean): void {
    this.selectRef()?.show(isFocus);
  }

  /**
   * Hides the panel
   */
  hide(isFocus?: boolean): void {
    this.selectRef()?.hide(isFocus);
  }

  /**
   * Applies focus
   */
  focus(): void {
    this.selectRef()?.focus();
  }

  /**
   * Clears the model
   */
  clear(event?: Event): void {
    this.selectRef()?.clear(event);
  }

  /**
   * Handle document mouse down event
   * @param event Mouse event
   */
  @HostListener('document:mousedown', ['$event'])
  handleDocumentMouseDown(event: MouseEvent): void {
    const select = this.selectRef();

    if (!select) {
      return;
    }

    const triggerElement = this.hostElement.nativeElement;
    const overlayElement = select?.overlayViewChild?.overlayEl as HTMLElement | undefined;

    handleOutsideClick(
      event,
      [triggerElement, overlayElement],
      () => { select.hide() },
      !!select.overlayVisible
    )
  }
}
