import { Directive, ElementRef, Renderer2, input, afterNextRender, Injector, inject } from '@angular/core';

/**
 * CmmLeftContentDirective - Left panel in the content area
 *
 * Can optionally enable scrolling. Takes up specified width or flex proportion.
 * Must be used inside cmmContent directive.
 *
 * @input enableScroll - Enable scrolling for this panel (default: false)
 * @input width - CSS width value (e.g., '300px', '30%', or flex value like '1')
 *
 * @example
 * ```html
 * <div cmmContent>
 *   <div cmmLeftContent [enableScroll]="true" width="300px">
 *     Long content that can scroll...
 *   </div>
 *   <div cmmRightContent>Right panel</div>
 * </div>
 * ```
 */
@Directive({
  selector: '[cmmLeftContent]',
  standalone: true,
})
export class CmmLeftContentDirective {
  enableScroll = input<boolean>(false);
  width = input<string>('1'); // Default flex: 1

  private el = inject(ElementRef);
  private renderer = inject(Renderer2);
  private injector = inject(Injector);

  private static stylesInjected = false;
  private static readonly minifiedCss =
    '.cmm-left-content{box-sizing:border-box;scroll-behavior:smooth}.cmm-left-content::-webkit-scrollbar{width:8px}.cmm-left-content::-webkit-scrollbar-track{background:#f1f1f1}.cmm-left-content::-webkit-scrollbar-thumb{background:#888;border-radius:4px}.cmm-left-content::-webkit-scrollbar-thumb:hover{background:#555}.cmm-panel-padded{padding:1rem}.cmm-panel-bordered{border:1px solid #e2e8f0}.cmm-panel-shadow{box-shadow:0 2px 8px rgba(0,0,0,.08)}.cmm-panel-bg-white{background:#fff}.cmm-panel-bg-gray{background:#f9fafb}';

  constructor() {
    afterNextRender(
      () => {
        this.injectStyles();
        this.applyStyles();
      },
      { injector: this.injector },
    );
  }

  private injectStyles(): void {
    if (!CmmLeftContentDirective.stylesInjected && typeof document !== 'undefined') {
      const style = this.renderer.createElement('style');
      this.renderer.setAttribute(style, 'data-cmm-left-content', '');
      const text = this.renderer.createText(CmmLeftContentDirective.minifiedCss);
      this.renderer.appendChild(style, text);
      this.renderer.appendChild(document.head, style);
      CmmLeftContentDirective.stylesInjected = true;
    }
  }

  private applyStyles(): void {
    const element = this.el.nativeElement;
    const width = this.width();
    const enableScroll = this.enableScroll();

    this.renderer.addClass(element, 'cmm-left-content');

    // Determine if width is a flex value or absolute value
    if (this.isFlexValue(width)) {
      this.renderer.setStyle(element, 'flex', `${width} 1 0`);
    } else {
      this.renderer.setStyle(element, 'flex', '0 0 auto');
      this.renderer.setStyle(element, 'width', width);
    }

    this.renderer.setStyle(element, 'min-height', '0');
    this.renderer.setStyle(element, 'min-width', '0');

    // Set overflow based on scroll option
    if (enableScroll) {
      this.renderer.setStyle(element, 'overflow-y', 'auto');
      this.renderer.setStyle(element, 'overflow-x', 'hidden');
    } else {
      this.renderer.setStyle(element, 'overflow', 'hidden');
    }
  }

  private isFlexValue(value: string): boolean {
    // Check if it's a simple number (flex value)
    return /^\d+(\.\d+)?$/.test(value);
  }
}
