/**
 * Input Formatters
 * 
 * Pre-built formatter functions for common formatting scenarios.
 * Use with cmmInputRestrict directive's formatOnBlur input.
 * 
 * @example
 * ```html
 * <input 
 *   cmmInputRestrict 
 *   [formatOnBlur]="InputFormatters.creditCard()"
 * />
 * ```
 */
export class InputFormatters {
  /**
   * Credit card formatter: 1234-5678-9012-3456
   * Groups of 4 digits
   */
  static creditCard(separator = '-'): (value: string) => string {
    return (value: string) => {
      const cleaned = value.replace(/\D/g, '');
      const groups = cleaned.match(/.{1,4}/g);
      return groups ? groups.join(separator) : cleaned;
    };
  }

  /**
   * Phone number formatter with custom pattern
   * 
   * @param pattern - Pattern with 'x' for digits (e.g., 'xxx-xxx-xxxx')
   * @param separator - Separator character (default: '-')
   * 
   * @example
   * ```typescript
   * // US: (123) 456-7890
   * InputFormatters.phoneFormat('(xxx) xxx-xxxx')
   * 
   * // Vietnam: 012-345-6789
   * InputFormatters.phoneFormat('xxx-xxx-xxxx')
   * ```
   */
  static phoneFormat(pattern: string, separator?: string): (value: string) => string {
    return (value: string) => {
      const cleaned = value.replace(/\D/g, '');
      let formatted = '';
      let digitIndex = 0;

      for (let i = 0; i < pattern.length && digitIndex < cleaned.length; i++) {
        const char = pattern[i];
        if (char.toLowerCase() === 'x') {
          formatted += cleaned[digitIndex];
          digitIndex++;
        } else {
          formatted += char;
        }
      }

      return formatted;
    };
  }

  /**
   * Vietnamese phone formatter: 0123-456-789
   * Pattern: xxx-xxx-xxx or xxxx-xxx-xxx
   */
  static vietnamesePhone(): (value: string) => string {
    return (value: string) => {
      const cleaned = value.replace(/\D/g, '');
      
      if (cleaned.length <= 3) {
        return cleaned;
      }if (cleaned.length <= 6) {
        return `${cleaned.slice(0, 3)}-${cleaned.slice(3)}`;
      }if (cleaned.length <= 9) {
        return `${cleaned.slice(0, 3)}-${cleaned.slice(3, 6)}-${cleaned.slice(6)}`;
      }
        return `${cleaned.slice(0, 4)}-${cleaned.slice(4, 7)}-${cleaned.slice(7, 10)}`;
    };
  }

  /**
   * Date formatter: DD/MM/YYYY
   */
  static dateFormat(separator = '/'): (value: string) => string {
    return (value: string) => {
      const cleaned = value.replace(/\D/g, '');
      
      if (cleaned.length <= 2) {
        return cleaned;
      }if (cleaned.length <= 4) {
        return `${cleaned.slice(0, 2)}${separator}${cleaned.slice(2)}`;
      }
        return `${cleaned.slice(0, 2)}${separator}${cleaned.slice(2, 4)}${separator}${cleaned.slice(4, 8)}`;
    };
  }

  /**
   * Time formatter: HH:MM
   */
  static timeFormat(separator = ':'): (value: string) => string {
    return (value: string) => {
      const cleaned = value.replace(/\D/g, '');
      
      if (cleaned.length <= 2) {
        return cleaned;
      }
        return `${cleaned.slice(0, 2)}${separator}${cleaned.slice(2, 4)}`;
    };
  }

  /**
   * Currency formatter: 1,234,567
   * Add thousand separators
   */
  static currency(separator = ','): (value: string) => string {
    return (value: string) => {
      const cleaned = value.replace(/\D/g, '');
      if (!cleaned) return '';
      
      return cleaned.replace(/\B(?=(\d{3})+(?!\d))/g, separator);
    };
  }

  /**
   * Decimal formatter: 1,234.56
   * With thousand separator and decimal places
   * 
   * @param decimalPlaces - Number of decimal places (default: 2)
   * @param thousandSep - Thousand separator (default: ',')
   * @param decimalSep - Decimal separator (default: '.')
   */
  static decimal(
    decimalPlaces = 2,
    thousandSep = ',',
    decimalSep = '.'
  ): (value: string) => string {
    return (value: string) => {
      // Split by decimal separator
      const parts = value.split(decimalSep);
      let integerPart = parts[0].replace(/\D/g, '');
      const decimalPart = parts[1] ? parts[1].replace(/\D/g, '').slice(0, decimalPlaces) : '';

      // Add thousand separators to integer part
      if (integerPart) {
        integerPart = integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, thousandSep);
      }

      // Combine parts
      return decimalPart ? `${integerPart}${decimalSep}${decimalPart}` : integerPart;
    };
  }

  /**
   * Uppercase words: "hello world" => "Hello World"
   */
  static titleCase(): (value: string) => string {
    return (value: string) => {
      return value.toLowerCase().replace(/\b\w/g, char => char.toUpperCase());
    };
  }

  /**
   * Remove consecutive spaces and trim
   */
  static cleanSpaces(): (value: string) => string {
    return (value: string) => {
      return value.replace(/\s+/g, ' ').trim();
    };
  }

  /**
   * Custom pattern formatter
   * Replace digits in pattern with input digits
   * 
   * @param pattern - Pattern string (e.g., 'xx-xx-xx', 'xxxx xxxx xxxx')
   * @param separator - Will be preserved from pattern
   * 
   * @example
   * ```typescript
   * // Input: "123456" with pattern "xx-xx-xx"
   * // Output: "12-34-56"
   * InputFormatters.customPattern('xx-xx-xx')
   * 
   * // Input: "1234567890" with pattern "xxxx xxxx xx"
   * // Output: "1234 5678 90"
   * InputFormatters.customPattern('xxxx xxxx xx')
   * ```
   */
  static customPattern(pattern: string): (value: string) => string {
    return (value: string) => {
      const cleaned = value.replace(/\D/g, '');
      let formatted = '';
      let digitIndex = 0;

      for (let i = 0; i < pattern.length && digitIndex < cleaned.length; i++) {
        const char = pattern[i];
        if (char.toLowerCase() === 'x') {
          formatted += cleaned[digitIndex];
          digitIndex++;
        } else {
          formatted += char;
        }
      }

      return formatted;
    };
  }

  /**
   * Group digits with custom grouping
   * 
   * @param groups - Array of group sizes (e.g., [4, 4, 4] for credit card)
   * @param separator - Separator between groups (default: '-')
   * 
   * @example
   * ```typescript
   * // Credit card: 1234-5678-9012-3456
   * InputFormatters.groupDigits([4, 4, 4, 4], '-')
   * 
   * // Vietnamese ID: 012345-678901
   * InputFormatters.groupDigits([6, 6], '-')
   * 
   * // Custom: 123-4567-89
   * InputFormatters.groupDigits([3, 4, 2], '-')
   * ```
   */
  static groupDigits(groups: number[], separator = '-'): (value: string) => string {
    return (value: string) => {
      const cleaned = value.replace(/\D/g, '');
      let formatted = '';
      let position = 0;

      for (let i = 0; i < groups.length && position < cleaned.length; i++) {
        const groupSize = groups[i];
        const chunk = cleaned.substring(position, position + groupSize);
        
        if (chunk) {
          formatted += chunk;
          position += groupSize;
          
          // Add separator if not last group and there's more input
          if (i < groups.length - 1 && position < cleaned.length) {
            formatted += separator;
          }
        }
      }

      return formatted;
    };
  }
}

/**
 * Format pattern presets for common use cases
 */
export const FormatPatterns = {
  /**
   * Credit card: xxxx-xxxx-xxxx-xxxx
   */
  CREDIT_CARD: 'xxxx-xxxx-xxxx-xxxx',

  /**
   * US Phone: (xxx) xxx-xxxx
   */
  US_PHONE: '(xxx) xxx-xxxx',

  /**
   * Vietnam Phone: xxx-xxx-xxxx
   */
  VN_PHONE: 'xxx-xxx-xxxx',

  /**
   * Date: dd/mm/yyyy
   */
  DATE_DDMMYYYY: 'xx/xx/xxxx',

  /**
   * Date: mm/dd/yyyy
   */
  DATE_MMDDYYYY: 'xx/xx/xxxx',

  /**
   * Time: hh:mm
   */
  TIME_HHMM: 'xx:xx',

  /**
   * Time: hh:mm:ss
   */
  TIME_HHMMSS: 'xx:xx:xx',

  /**
   * Vietnamese ID: xxxxxx-xxxxxx
   */
  VN_ID: 'xxxxxx-xxxxxx',

  /**
   * Social Security: xxx-xx-xxxx
   */
  SSN: 'xxx-xx-xxxx',
} as const;
