import { Component, input, computed, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TooltipModule } from 'primeng/tooltip';
import { CmmTextDirective } from '../../../typography/directives/text.directive';
import { CmmReadonlyProps } from './cmm-readonly.types';

@Component({
  selector: 'cmm-readonly',
  imports: [CommonModule, TooltipModule, CmmTextDirective],
  template: `
    <p cmmParagraph
       [ellipsis]="computedEllipsis()"
       [ellipsisRows]="computedEllipsisRows()"
       [class]="computedClass()"
       [pTooltip]="computedTooltipValue()"
       [tooltipPosition]="computedTooltipPosition()"
       [tooltipStyleClass]="computedTooltipStyleClass()"
       [textContent]="value() ?? ''"
    ></p>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmReadonlyComponent {
  value = input<any>('');
  styleClass = input<string>('');
  props = input<CmmReadonlyProps>({});

  computedEllipsis = computed(() => {
    const propVal = this.props()?.ellipsis;
    return propVal !== undefined ? propVal : true;
  });

  computedEllipsisRows = computed(() => {
    const propVal = this.props()?.ellipsisRows;
    return propVal !== undefined ? propVal : 1;
  });

  computedTooltipValue = computed(() => {
    return (!this.props().disableTooltip && this.value()) ? this.value() : ''
  })

  computedTooltipPosition = computed(() => {
    return this.props()?.tooltipPosition ?? 'top';
  });

  computedClass = computed(() => {
    return 'readonly-field text-gray-800 font-medium max-w-[400px] whitespace-pre ' + this.styleClass()
  })

  computedTooltipStyleClass = computed(() => {
    return this.props()?.tooltipStyleClass ?? 'custom-tooltip-view-user-detail';
  });
}
