import {
  Component,
  input,
  output,
  model,
  forwardRef,
  ChangeDetectionStrategy,
  contentChild,
  TemplateRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import { InputOtpModule } from 'primeng/inputotp';
import { InputOtpVariant } from './cmm-inputotp.types';
import { INPUTOTP_DEFAULTS } from './cmm-inputotp.constants';

@Component({
  selector: 'cmm-inputotp',
  standalone: true,
  imports: [CommonModule, FormsModule, InputOtpModule],
  template: `
    <p-inputOtp
      [(ngModel)]="value"
      [length]="length()"
      [mask]="mask()"
      [integerOnly]="integerOnly()"
      [disabled]="disabled()"
      [readonly]="readonly()"
      [variant]="variant()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass()!"
      (onChange)="handleChange($event)"
      (onFocus)="onFocus.emit($event)"
      (onBlur)="handleBlur($event)"
    >
      @if (inputTemplate()) {
        <ng-template pTemplate="input" let-token let-events="events">
          <ng-container *ngTemplateOutlet="inputTemplate()!; context: { $implicit: token, events: events }" />
        </ng-template>
      }
    </p-inputOtp>
  `,
  styleUrl: './cmm-inputotp.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmInputotpComponent),
      multi: true,
    },
  ],
})
export class CmmInputotpComponent implements ControlValueAccessor {
  // Model
  value = model<string | number | null>(null);

  // Content children templates
  inputTemplate = contentChild<TemplateRef<any>>('input');

  // Core props
  length = input<number>(INPUTOTP_DEFAULTS.LENGTH);
  mask = input<boolean>(INPUTOTP_DEFAULTS.MASK);
  integerOnly = input<boolean>(INPUTOTP_DEFAULTS.INTEGER_ONLY);
  disabled = input<boolean>(INPUTOTP_DEFAULTS.DISABLED);
  readonly = input<boolean>(INPUTOTP_DEFAULTS.READONLY);
  variant = input<InputOtpVariant>(INPUTOTP_DEFAULTS.VARIANT);
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Output events
  onChange = output<any>();
  onFocus = output<Event>();
  onBlur = output<Event>();

  // ControlValueAccessor
  private onChangeFn: (value: string | number | null) => void = () => {};
  private onTouchedFn: () => void = () => {};

  writeValue(value: string | number | null): void {
    this.value.set(value);
  }

  registerOnChange(fn: (value: string | number | null) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    // Handle if needed
  }

  handleChange(event: any): void {
    this.onChange.emit(event);
    this.onChangeFn(this.value());
  }

  handleBlur(event: Event): void {
    this.onBlur.emit(event);
    this.onTouchedFn();
  }
}
