import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ValidationDirective } from './directives/validation.directive';
import { InputRestrictDirective } from './directives/input-restrict.directive';
import { ValidationErrorComponent } from './components/validation-error.component';
import { UbckValidationStyles } from './styles/validation.style';

/**
 * Validation Module
 * 
 * Import this module to get validation directives with auto-loaded styles
 * Styles are injected automatically - no need for global imports!
 * 
 * @example
 * ```typescript
 * import { ValidationModule } from '@validations';
 * 
 * @Component({
 *   standalone: true,
 *   imports: [ValidationModule]
 * })
 * export class MyComponent {}
 * ```
 */
@NgModule({
  imports: [
    CommonModule,
    ValidationDirective,        // Wrapper with auto-inject
    InputRestrictDirective,     // Wrapper with auto-inject
    ValidationErrorComponent,   // Standalone component
  ],
  exports: [
    ValidationDirective,
    InputRestrictDirective,
    ValidationErrorComponent,
  ]
})
export class ValidationModule {}
