import { Component, ChangeDetectionStrategy, input, output, contentChild, viewChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Menu } from 'primeng/menu';
import type { MenuItem } from 'primeng/api';

@Component({
  selector: 'cmm-menu',
  standalone: true,
  imports: [CommonModule, Menu],
  templateUrl: './cmm-menu.component.html',
  styleUrl: './cmm-menu.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmMenuComponent {
  model = input<MenuItem[]>([]);
  popup = input<boolean>(false);
  style = input<Record<string, any>>();
  styleClass = input<string>('');
  appendTo = input<unknown>('body');
  autoZIndex = input<boolean>(true);
  baseZIndex = input<number>(0);
  showTransitionOptions = input<string>('.12s cubic-bezier(0, 0, 0.2, 1)');
  hideTransitionOptions = input<string>('.1s linear');
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();
  id = input<string>();
  tabindex = input<number>(0);

  onShow = output<any>();
  onHide = output<any>();
  onBlur = output<Event>();
  onFocus = output<Event>();

  startTemplate = contentChild<TemplateRef<any>>('start');
  endTemplate = contentChild<TemplateRef<any>>('end');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  itemTemplate = contentChild<TemplateRef<any>>('item');
  submenuHeaderTemplate = contentChild<TemplateRef<any>>('submenuheader');

  menuRef = viewChild<Menu>('menuRef');

  toggle(event: Event) {
    this.menuRef()?.toggle(event);
  }

  show(event: any) {
    this.menuRef()?.show(event);
  }

  hide() {
    this.menuRef()?.hide();
  }
}
