import { Directive, ChangeDetectorRef, input, ElementRef, inject, afterNextRender } from '@angular/core';
import { AutoFocus } from 'primeng/autofocus';

@Directive({
  selector: '[cmmAutoFocus]',
  standalone: true,
  hostDirectives: [
    {
      directive: AutoFocus,
      // inputs: ['autofocus'],
    },
  ],
  exportAs: 'cmmautofocus',
})
export class CmmAutoFocusDirective {
  private el = inject(ElementRef);
  private cdr = inject(ChangeDetectorRef);

  // // Signal input for controlling autofocus behavior
  cmmAutoFocus = input<boolean>(true);

  // // Additional configuration
  focusDelay = input<number>(0);
  selectOnFocus = input<boolean>(false);

  constructor() {
    afterNextRender(() => {
      if (this.cmmAutoFocus()) {
        const delay = this.focusDelay();
        if (delay > 0) {
          setTimeout(() => this.applyFocus(), delay);
        } else {
          this.applyFocus();
        }
      }
    });
  }

  private applyFocus(): void {
    const element = this.el.nativeElement;

    if (element) {
      element.focus();

      // Select text if input/textarea and selectOnFocus is enabled
      if (this.selectOnFocus() && (element.tagName === 'INPUT' || element.tagName === 'TEXTAREA')) {
        element.select();
      }
    }
  }
}
