import { Component, input, output, model, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { SpeedDialModule } from 'primeng/speeddial';
import type { MenuItem } from 'primeng/api';
import { SpeedDialDirection, SpeedDialType } from './cmm-speeddial.types';
import { SPEEDDIAL_DEFAULTS } from './cmm-speeddial.constants';

@Component({
  selector: 'cmm-speeddial',
  standalone: true,
  imports: [CommonModule, SpeedDialModule],
  template: `
    <p-speedDial
      [id]="id() ?? undefined"
      [model]="model()"
      [(visible)]="visible"
      [direction]="direction()"
      [type]="type()"
      [radius]="radius()"
      [mask]="mask()"
      [disabled]="disabled()"
      [hideOnClickOutside]="hideOnClickOutside()"
      [transitionDelay]="transitionDelay()"
      [buttonStyle]="buttonStyle() ?? undefined"
      [buttonClassName]="buttonClass()"
      [maskStyle]="maskStyle() ?? undefined"
      [maskClassName]="maskClass()"
      [showIcon]="showIcon()"
      [hideIcon]="hideIcon()"
      [rotateAnimation]="rotateAnimation()"
      [ariaLabel]="ariaLabel() ?? undefined"
      [ariaLabelledBy]="ariaLabelledBy() ?? undefined"
      [tooltipOptions]="tooltipOptions() ?? undefined"
      [buttonProps]="buttonProps() ?? undefined"
      [style]="style() ?? undefined"
      [className]="styleClass() ?? undefined"
      (onClick)="onClick.emit($event)"
      (onShow)="onShow.emit($event)"
      (onHide)="onHide.emit($event)"
      (onVisibleChange)="onVisibleChange.emit($event)">
      @if (buttonTemplate()) {
        <ng-template pTemplate="button" let-toggleCallback="toggleCallback">
          <ng-container *ngTemplateOutlet="buttonTemplate()!; context: { toggleCallback: toggleCallback }" />
        </ng-template>
      }
      @if (itemTemplate()) {
        <ng-template pTemplate="item" let-item let-index="index" let-toggleCallback="toggleCallback">
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item, index: index, toggleCallback: toggleCallback }" />
        </ng-template>
      }
      @if (iconTemplate()) {
        <ng-template pTemplate="icon">
          <ng-container *ngTemplateOutlet="iconTemplate()!" />
        </ng-template>
      }
    </p-speedDial>
  `,
  styleUrl: './cmm-speeddial.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmSpeeddialComponent {
  // Core props
  id = input<string>();
  model = input<MenuItem[]>([]);
  visible = model<boolean>(false);
  direction = input<SpeedDialDirection>(SPEEDDIAL_DEFAULTS.DIRECTION);
  type = input<SpeedDialType>(SPEEDDIAL_DEFAULTS.TYPE);
  radius = input<number>(SPEEDDIAL_DEFAULTS.RADIUS);
  mask = input<boolean>(SPEEDDIAL_DEFAULTS.MASK);
  disabled = input<boolean>(SPEEDDIAL_DEFAULTS.DISABLED);
  hideOnClickOutside = input<boolean>(SPEEDDIAL_DEFAULTS.HIDE_ON_CLICK_OUTSIDE);
  transitionDelay = input<number>(30);
  buttonStyle = input<Record<string, any>>();
  buttonClass = input<string>(SPEEDDIAL_DEFAULTS.BUTTON_CLASS);
  maskStyle = input<Record<string, any>>();
  maskClass = input<string>(SPEEDDIAL_DEFAULTS.MASK_CLASS);
  showIcon = input<string>(SPEEDDIAL_DEFAULTS.SHOW_ICON);
  hideIcon = input<string>(SPEEDDIAL_DEFAULTS.HIDE_ICON);
  rotateAnimation = input<boolean>(SPEEDDIAL_DEFAULTS.ROTATE_ANIMATION);
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();
  tooltipOptions = input<any>();
  buttonProps = input<any>();
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Templates
  buttonTemplate = contentChild<TemplateRef<any>>('button');
  itemTemplate = contentChild<TemplateRef<any>>('item');
  iconTemplate = contentChild<TemplateRef<any>>('icon');

  // Events
  onClick = output<MouseEvent>();
  onShow = output<Event>();
  onHide = output<Event>();
  onVisibleChange = output<boolean>();
}
