import { CommonModule } from '@angular/common';
import {
  afterNextRender,
  ChangeDetectionStrategy,
  Component,
  contentChild,
  DestroyRef,
  ElementRef,
  inject,
  output,
  signal,
  TemplateRef
} from '@angular/core';

@Component({
  selector: 'ubck-deferered-section',
  imports: [CommonModule],
  templateUrl: './deferered-section.component.html',
  styleUrl: './deferered-section.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class UBCKDefereredSectionComponent {
  public readonly el = inject(ElementRef);
  private observer!: IntersectionObserver;
  isVisible = signal(false);

  private destroyRef = inject(DestroyRef);

  public readonly loadContent = output<void>();
  private timeout: unknown;

  loadingContent = contentChild<TemplateRef<any>>('loadingContent', {
    descendants: false,
  });

  constructor() {
    afterNextRender({
      read: () => {
        this.handleImplementWhenDomStable();
      },
    });
    this.destroyRef.onDestroy(() => {
      this.handleComponentDestroy();
    });
  }
  handleImplementWhenDomStable() {
    this.observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          this.timeout = setTimeout(() => {
            this.loadContent.emit();
            this.isVisible.set(true);
          }, 300);
          this.observer.unobserve(entry.target);
        }
      });
    });
    if (this.el?.nativeElement) {
      this.observer.observe(this.el.nativeElement);
    }
  }

  handleComponentDestroy() {
    if (this.observer && this.el?.nativeElement) {
      this.observer.unobserve(this.el.nativeElement);
    }
    if (this.timeout) {
      clearTimeout(this.timeout as number);
    }
  }
}
