export const ANIMATION_CLASSES = {
  // Fade animations
  FADE_IN: 'fadein',
  FADE_OUT: 'fadeout',

  // Slide animations
  SLIDE_UP: 'slideup',
  SLIDE_DOWN: 'slidedown',
  SLIDE_LEFT: 'slideleft',
  SLIDE_RIGHT: 'slideright',

  // Zoom animations
  ZOOM_IN: 'zoomin',
  ZOOM_OUT: 'zoomout',

  // Flip animations
  FLIP_UP: 'flipup',
  FLIP_DOWN: 'flipdown',
} as const;

export const ANIMATE_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export const ANIMATE_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export const ANIMATION_SPEEDS = {
  FAST: 'fast',
  NORMAL: 'normal',
  SLOW: 'slow',
} as const;

export const DEFAULT_THRESHOLD = 0.5;
export const DEFAULT_ROOT_MARGIN = '0px';

export type AnimationClass = (typeof ANIMATION_CLASSES)[keyof typeof ANIMATION_CLASSES];
export type AnimateSize = (typeof ANIMATE_SIZES)[keyof typeof ANIMATE_SIZES];
export type AnimateVariant = (typeof ANIMATE_VARIANTS)[keyof typeof ANIMATE_VARIANTS];
export type AnimationSpeed = (typeof ANIMATION_SPEEDS)[keyof typeof ANIMATION_SPEEDS];
