/**
 * this model from server response
 */

export type RoleModel = {
  id: string;
  code: string;
  name: string;
  description: string;
  status: string;
  system: string; //  system like MO, EDM...
  createdAt: string;
  updatedAt: string;
  createdByName: string | null;
  updatedByName: string | null;
  totalPermissions: number;
  permissionGroups: PermissionModelGroup[];
  userIds: string[];
  users: any[] | null;
};

export type PermissionModelGroup = {
  id: string;
  code: string;
  name: string;
  description: string;
  displayOrder: number;
  permissions: PermissionModel[];
};

export type PermissionModel = {
  id: string;
  code: string;
  name: string;
  description: string;
  endpoint: string;
  method: string;
};
