import { ChangeDetectionStrategy, Component, inject, input, viewChild, ViewEncapsulation } from '@angular/core';
import { ColumnDefinition } from '../table.types';
import { Table, TableHeaderCheckbox } from 'primeng/table';
import { CheckboxChangeEvent, CheckboxPassThrough } from 'primeng/types/checkbox';
export type HeaderTableProps = {
  cols: ColumnDefinition[];
  isShowCheckBox: boolean;
  showIndeterminateCheckAll: boolean;
  indeterminateCheckAllClass?: string;
  isShowOrder: boolean;
  colOrderName: string;
  isSortColumn: boolean;
  colIndex: number;
  totalCols: number;
  ellipsisRows?: number;
};
@Component({
  selector: 'tr[ubck-table-header]',
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.Default,
  template: `
    @let data = props(); 
    @if (!!data.isShowCheckBox && data.colIndex === 0) {
    <th
      id="th1{{ data.colIndex }}"
      class="text-center"
      [attr.colSpan]="1"
      [attr.rowSpan]="data.totalCols > 1 ? data.totalCols : 1"
      [ngStyle]="{ width: '48px' }"
    >
     @if (data.showIndeterminateCheckAll) {
       <span [pTooltip]="tooltipCheckboxAll()" tooltipPosition="top">
         <p-checkbox
           [binary]="true"
           [ngModel]="isAllSelected()"
           [indeterminate]="isIndeterminate()"
           [pt]="indeterminateCheckAllPassThrough()"
           [disabled]="isCheckAllDisabled()"
           (onChange)="toggleAllRows($event)"
         />
       </span>
     } @else {
       <p-tableHeaderCheckbox #checkAll [pTooltip]="tooltipCheckboxAll()" tooltipPosition="top"/>
     }
    </th>
    } @if (data.isShowOrder && data.colIndex === 0) {
    <th
      id="th1{{ data.colIndex }}"
      [attr.colSpan]="1"
      [attr.rowSpan]="data.totalCols > 1 ? data.totalCols : 1"
      [ngStyle]="{ width: '48px' }"
      class="text-center"
    >
      {{ data.colOrderName | translate}}
    </th>
    } @for (col of data.cols ; track $index) { @if (col['isShowSort'] &&
    !!data.isSortColumn) { @if(col['isFrozen']) {
    <th
      pFrozenColumn
      [pSortableColumn]="col['field'] || ''"
      id="th2{{ $index }}"
      [ngStyle]="{
                    'min-width': col['minWidth'] || 'unset',
                    'max-width': col['maxWidth'] || 'unset',
                    width: col['width'],
                  }"
      class="{{ col.thClassName }} text-ellipsis"
      [attr.colSpan]="col.thColSpan || 1"
      [attr.rowSpan]="col.thRowSpan || 1"
    >
      <div class="flex justify-content-between align-items-center">
        @if(col.headerTemplate) {
          <ng-container [ngTemplateOutlet]="col.headerTemplate"></ng-container>
        } @else {
          <span cmmEllipsis [appEllipsis]="true" [ellipsisRows]="data.ellipsisRows || 1" [style.maxWidth]="col['maxWidth']">{{ col.header | translate}}</span>
        }
        <p-sortIcon [field]="col['field'] || ''" />
      </div>
    </th>
    } @else {
    <th
      [pSortableColumn]="col['field'] || ''"
      id="th2{{ $index }}"
      [ngStyle]="{
                    'min-width': col['minWidth'] || 'unset',
                    'max-width': col['maxWidth'] || 'unset',
                    width: col['width'],
                  }"
      class="{{ col.thClassName }} "
      [attr.colSpan]="col.thColSpan || 1"
      [attr.rowSpan]="col.thRowSpan || 1"
    >
      <div class="flex justify-content-between align-items-center">
         @if(col.headerTemplate) {
          <ng-container [ngTemplateOutlet]="col.headerTemplate"></ng-container>
        } @else {
          <span cmmEllipsis [appEllipsis]="true" [ellipsisRows]="data.ellipsisRows || 1" [style.maxWidth]="col['maxWidth']">{{ col.header | translate}}</span>
        }
        <p-sortIcon [field]="col['field'] || ''" />
      </div>
    </th>
    } } @else { @if(col['isFrozen']) {
    <th
      pFrozenColumn
      id="th2{{ $index }}"
      [ngStyle]="{
                    'min-width': col['minWidth'] || 'unset',
                    'max-width': col['maxWidth'] || 'unset',
                    width: col['width'],
                  }"
      class="{{ col.thClassName }} text-ellipsis"
      [attr.colSpan]="col.thColSpan || 1"
      [attr.rowSpan]="col.thRowSpan || 1"
    >
       @if(col.headerTemplate) {
          <ng-container [ngTemplateOutlet]="col.headerTemplate"></ng-container>
        } @else {
          <span cmmEllipsis [appEllipsis]="true" [ellipsisRows]="data.ellipsisRows || 1" [style.maxWidth]="col['maxWidth']">{{ col.header | translate}}</span>
        }
    </th>
    } @else {
    <th
      id="th2{{ $index }}"
      [ngStyle]="{
                    'min-width': col['minWidth'] || 'unset',
                    'max-width': col['maxWidth'] || 'unset',
                    width: col['width'],
                  }"
      class="{{ col.thClassName }} "
      [attr.colSpan]="col.thColSpan || 1"
      [attr.rowSpan]="col.thRowSpan || 1"
    >
       @if(col.headerTemplate) {
          <ng-container [ngTemplateOutlet]="col.headerTemplate"></ng-container>
        } @else {
          <span cmmEllipsis [appEllipsis]="true" [ellipsisRows]="data.ellipsisRows || 1" [style.maxWidth]="col['maxWidth']">{{ col.header | translate}}</span>
        }
    </th>
    } } }
  `,
})
export class UbckTableHeader {
  props = input.required<HeaderTableProps>();
  checkAllRef = viewChild<TableHeaderCheckbox>('checkAll');
  private readonly dataTable = inject(Table);

  isAllSelected(): boolean {
    if (this.dataTable._selectAll !== null) {
      return this.dataTable._selectAll;
    }

    const selectableRows = this.getSelectableRows();
    const selection = this.getSelection();

    return selectableRows.length > 0 && selectableRows.every((row) =>
      selection.some((selectedRow) => this.dataTable.equals(row, selectedRow)),
    );
  }

  isIndeterminate(): boolean {
    if (!this.props().showIndeterminateCheckAll || this.isAllSelected()) {
      return false;
    }

    const selection = this.getSelection();

    return this.getSelectableRows().some((row) =>
      selection.some((selectedRow) => this.dataTable.equals(row, selectedRow)),
    );
  }

  isCheckAllDisabled(): boolean {
    return !this.dataTable.value?.length;
  }

  toggleAllRows(event: CheckboxChangeEvent): void {
    if (!event.originalEvent || this.isCheckAllDisabled()) {
      return;
    }

    this.dataTable.toggleRowsWithCheckbox(
      { ...event, originalEvent: event.originalEvent },
      !this.isAllSelected(),
    );
  }

  tooltipCheckboxAll(): string {
    return this.isAllSelected() || this.checkAllRef()?.checked
      ? 'Bỏ chọn tất cả'
      : 'Chọn tất cả';
  }

  indeterminateCheckAllPassThrough(): CheckboxPassThrough | undefined {
    if (!this.isIndeterminate()) {
      return undefined;
    }

    const customClass = this.props().indeterminateCheckAllClass;

    return {
      box: {
        class: customClass
          ? `ubck-table__header-checkbox--indeterminate-box ubck-table__header-checkbox--custom-color ${customClass}`
          : 'ubck-table__header-checkbox--indeterminate-box',
      },
    };
  }

  private getSelectableRows(): unknown[] {
    const data: unknown[] = this.dataTable.selectionPageOnly
      ? this.dataTable.dataToRender(this.dataTable.processedData)
      : this.dataTable.processedData;
    const rows: unknown[] = this.dataTable.frozenValue ? [...this.dataTable.frozenValue, ...data] : data;

    return this.dataTable.rowSelectable
      ? rows.filter((row, index) => this.dataTable.rowSelectable({ data: row, index }))
      : rows;
  }

  private getSelection(): unknown[] {
    return Array.isArray(this.dataTable.selection) ? this.dataTable.selection : [];
  }
}
