/**
 * Resolve a download filename from a Content-Disposition header.
 *
 * RFC 5987 aware: prefers the `filename*=UTF-8''<pct-encoded>` form (which carries
 * the correct UTF-8 name, e.g. Vietnamese diacritics) over the plain ASCII
 * `filename="…"` form, then falls back to the provided fallback name.
 *
 * Resolution order:
 *   1. `filename*=<charset>''<pct-encoded>` → split on `''`, `decodeURIComponent` the value.
 *   2. `filename="…"` (ASCII form, quotes stripped).
 *   3. `fallbackName`.
 *
 * @param contentDisposition Content-Disposition header value (may be empty/null).
 * @param fallbackName Fallback filename when the header has no usable name.
 * @returns The resolved filename, or `fallbackName` when none is found.
 */
export function resolveFileName(contentDisposition: string | null | undefined, fallbackName: string): string {
  if (contentDisposition) {
    // 1. RFC 5987 extended form: filename*=UTF-8''<pct-encoded>
    const extendedMatch = contentDisposition.match(/filename\*\s*=\s*([^;\n]+)/i);
    if (extendedMatch && extendedMatch[1]) {
      const raw = extendedMatch[1].trim();
      // <charset>'<lang>'<pct-encoded-value> — value is the part after the second quote.
      const parts = raw.split("''");
      const encodedValue = parts.length > 1 ? parts[1] : raw;
      try {
        return decodeURIComponent(encodedValue);
      } catch {
        // Malformed percent-encoding — fall through to the ASCII form.
      }
    }

    // 2. Plain ASCII form: filename="…" or filename=…
    const fileNameMatch = contentDisposition.match(/filename[^*;=\n]*=((['"]).*?\2|[^;\n]*)/i);
    if (fileNameMatch && fileNameMatch[1]) {
      const name = fileNameMatch[1].replace(/["']/g, '').trim();
      if (name) {
        return name;
      }
    }
  }

  return fallbackName;
}
