import {
  ChangeDetectionStrategy,
  Component,
  input,
  model,
  output,
  computed,
  contentChild,
  TemplateRef,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { BlockUI } from 'primeng/blockui';

@Component({
  selector: 'cmm-block-ui',
  templateUrl: './cmm-block-ui.component.html',
  styleUrls: ['./cmm-block-ui.component.scss'],
  standalone: true,
  imports: [CommonModule, BlockUI],
  exportAs: 'cmmblockui',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmBlockUIComponent {
  // Signal inputs - BlockUI properties
  target = input<any>('document');
  blocked = model<boolean>(false);
  autoZIndex = input<boolean>(true);
  baseZIndex = input<number>(0);

  // Signal inputs - Styling
  style = input<{ [klass: string]: any } | null>(null);
  styleClass = input<string>('');

  // Custom variant and size system
  variant = input<'outlined' | 'filled'>('filled');
  customSize = input<'small' | 'default' | 'large'>('default');

  // Signal outputs
  onBlocked = output<void>();
  onUnblocked = output<void>();

  // Template projections
  contentTemplate = contentChild<TemplateRef<any>>('content');

  // Computed style class
  computedStyleClass = computed(() => {
    const classes = [
      'cmm-block-ui',
      `cmm-block-ui--${this.variant()}`,
      `cmm-block-ui--${this.customSize()}`,
      this.styleClass(),
    ];
    return classes.filter(Boolean).join(' ');
  });

  // Event handlers
  handleBlocked(): void {
    this.onBlocked.emit();
  }

  handleUnblocked(): void {
    this.onUnblocked.emit();
  }
}
