import { inject, Injectable, signal, Signal, computed } from '@angular/core';
import { FormGroup } from '@angular/forms';
import { Subscription } from 'rxjs';

import {
  DynamicFieldTypes,
  DynamicFormFacade,
  DynamicFormItem,
  PropsEnricher,
} from './dynamic-form.types';
import { CmmDynamicFormBuilderImpl, VisibilityContext } from './form-builder.detail';
import { CmmDynamicFormService } from './dynamic-form.service';
@Injectable()
export class CmmDynamicFormFacade implements DynamicFormFacade {
  private readonly fb = inject(CmmDynamicFormBuilderImpl);
  private readonly service = inject(CmmDynamicFormService);

  readonly currentHint = signal<string>('');
  private disabledSyncSub?: Subscription;

  /* ================================
   * SOURCE SIGNALS
   * ================================ */

  private readonly _config = signal<DynamicFormItem[]>([]);
  private readonly _form = signal<FormGroup>(this.fb.build([]));

  /* ================================
   * PUBLIC SIGNALS
   * ================================ */

  readonly items: Signal<DynamicFormItem[]> = computed(() =>
   {
    return  this._config()
      .slice()
      .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
   }
  );

  /**
   * Group items by row
   */
  readonly groupedItems = computed(() => {

    return this.groupItemsByRow(this.items());
  });

  readonly form: Signal<FormGroup> = this._form.asReadonly();

  /**
   * Computed signal to automatically update validators when visibility changes
   */
  private readonly validatorUpdater = computed(() => {
    const form = this._form();
    const config = this._config();

    // This computed runs whenever form or config changes
    config.forEach(item => {
      const control = form.get(item.key);
      if (control) {
        const isVisible = this.isVisible(item);

        const currentValidator = control.validator;
        const expectedValidators = isVisible ? item.validators : null;

        // Only update if validators actually changed to avoid unnecessary updates
        const hasValidators = expectedValidators && expectedValidators.length > 0;
        const shouldUpdate = (hasValidators && !currentValidator) || (!hasValidators && currentValidator);

        if (shouldUpdate) {
          if (isVisible) {
            control.setValidators(item.validators || null);
            control.setAsyncValidators(item.asyncValidators || null);
          } else {
            control.setValidators(null);
            control.setAsyncValidators(null);
            // Clear any existing validation errors
            control.setErrors(null);
          }

          // Update validity after changing validators
          control.updateValueAndValidity({ emitEvent: false });
        }
      }
    });

    return true; // Return something to satisfy computed requirements
  });

  /**
   * Getter to trigger validator updater - used in component effect
   */
  triggerValidatorUpdate(): boolean {
    return this.validatorUpdater();
  }

  /* ================================
   * INIT
   * ================================ */

  init(config: DynamicFormItem[]): void {
    const currentForm = this._form();
    const isInitialBuild = !currentForm || Object.keys(currentForm.controls).length === 0;

    if (isInitialBuild) {
      // Warning for floatLabel conflicts. Which helps devs save time debugging.
      this.warnFloatLabel(config);
      // First time: build form normally
      this._config.set(config);

      // Create visibility context for form building
      const visibilityContext = {
        isVisible: (item: DynamicFormItem) => {
          // For initial build, we need to create a temporary form to check visibility
          // Since we don't have form value yet, we'll assume visible for initial build
          // and rely on runtime visibility checks in template
          if (item.hidden) return false;
          if (!item.visibleWhen) return true;
          // For initial build, create empty form value to check visibility
          const emptyFormValue = config.reduce<Record<string, any>>((acc, c) => {
            acc[c.key] = c.value ?? null;
            return acc;
          }, {});
          const tempForm = this.fb.build(config);
          tempForm.patchValue(emptyFormValue);
          return item.visibleWhen(emptyFormValue, tempForm);
        }
      };

      this._form.set(this.fb.build(config, visibilityContext));
    } else {
      // Subsequent calls (load more items): only update config
      // Keep existing FormGroup to preserve validation state & control references
      this._config.set(config);
      // FormGroup and controls remain unchanged → validation directive keeps working
    }
    this.setupDisabledSync(this._form());
  }

  private warnFloatLabel(config: DynamicFormItem[]): void {
    for (const item of config) {
      const floatLabel = item.props?.['floatLabel'] ?? item.floatLabel;

      if (!floatLabel) {
        continue;
      }

      // Case 1: Cảnh báo nếu floatLabel được bật nhưng không có label → label sẽ trống
      if (!item.label || item.label.trim() === '') {
        console.warn(
          `🎨 [dynamic-form] Trường "${item.key}": \`floatLabel\` được bật nhưng không có \`label\`. ` +
             `Vui lòng cung cấp \`label\` để tránh tình trạng label trống.`,
        );
      }

      // Case 2: Cảnh báo nếu floatLabel được bật nhưng vẫn có placeholder → placeholder sẽ bị bỏ qua
      if (floatLabel && item.placeholder && item.placeholder.trim() !== '') {
        console.warn(
          `🎨 [dynamic-form] Trường "${item.key}": \`placeholder\` bị bỏ qua vì \`floatLabel\` được bật. ` +
            `Khi \`floatLabel\` được bật, \`label\` sẽ được sử dụng làm floating label và \`placeholder\` sẽ không hiển thị. ` +
            `Vui lòng xóa \`placeholder\` để tránh nhầm lẫn.`,
        );
      }

      // Case 3: Cảnh báo rằng tùy biến style label sẽ bị bỏ qua khi floatLabel được bật
      if (floatLabel && item.classes?.label) {
        console.warn(
          `🎨 [dynamic-form] Trường "${item.key}": \`classes.label\` bị bỏ qua vì \`floatLabel\` được bật. ` +
            `Float Label sẽ không thể tùy chỉnh thông qua \`classes.label\`. Vui lòng xóa class.label để tránh nhầm lẫn.`,
        );
      }
    }
  }

  /* ================================
   * RUNTIME LOGIC
   * ================================ */

  isVisible(item: DynamicFormItem): boolean {
    return this.service.isVisible(item, this.form());
  }

  isDisabled(item: DynamicFormItem): boolean {
    return this.service.isDisabled(item, this.form());
  }

  /**
   * Check if all items in a group are visible
   */
  isGroupVisible(items: DynamicFormItem[]): boolean {
    return items.some(item => this.isVisible(item));
  }

  isVisibleSignal(item: DynamicFormItem): Signal<boolean> {
    return this.service.isVisibleSignal(item, this.form());
  }

  getControl(item: DynamicFormItem) {
    return this.service.getControl(item, this.form());
  }

  // helper to use Object methods in templates
  public readonly ObjectAssign = Object.assign;
  public readonly ObjectKeys = Object.keys;
  public readonly ObjectValues = Object.values;
  public readonly ObjectEntries = Object.entries;

  private readonly propEnrichers: PropsEnricher[] = [
    // (item) => ({ readonly: this.isReadonly(item) }),
    // (item) => ({ hidden: this.isHidden(item) }),
    // (item) => ({ required: this.isRequired(item) }),
    // (item) => ({ options: this.getOptions(item) }),
  ];
  private enrichProps(item: DynamicFormItem) {
    return this.propEnrichers.reduce(
      (acc, enrich) => ({ ...acc, ...enrich(item) }),
      { ...item.props }
    );
  }
  groupItemsByRow(
    items: DynamicFormItem[]
  ): Array<{ group: string | number; groupLabel: string | undefined; groupClasses: string | undefined; items: DynamicFormItem[] }> {
    const map = new Map<string | number, DynamicFormItem[]>();

    for (const item of items) {
      const key = item.group ?? item.key;

      const normalizedItem: DynamicFormItem = {
        ...item,
        props: { ...this.enrichProps(item) },
      };

      if (!map.has(key)) map.set(key, []);
      map.get(key)!.push(normalizedItem);
    }

    return Array.from(map.entries()).map(([group, items]) => ({
      group,
      groupLabel: items[0].groupLabel,
      groupClasses: items[0].classes?.group,
      items,
    }));
  }
  isDiabledSignal(item: DynamicFormItem): Signal<boolean> {
    return this.service.isDiabledSignal(item, this.form());
  }

  /**
   * Submit form with validation check
   * @returns FormGroup value if valid, null if invalid
   */
  submitForm(): any | null {
    const formGroup = this.form();
    if (formGroup.valid) {
      return formGroup.value;
    }
    // Mark all fields as touched to show validation errors
    formGroup.markAllAsTouched();
    return null;
  }

  /**
   * Get all validation errors from the form
   */
  getFormErrors(): Record<string, any> {
    const formGroup = this.form();
    const errors: Record<string, any> = {};

    Object.keys(formGroup.controls).forEach(key => {
      const control = formGroup.get(key);
      if (control && control.errors) {
        errors[key] = control.errors;
      }
    });

    return errors;
  }

  /**
   * Check if form has any errors
   */
  hasErrors(): boolean {
    return !this.form().valid;
  }

  /**
   * Update validators for all form controls based on current visibility
   */
  updateValidatorsBasedOnVisibility(): void {
    const form = this.form();
    const config = this._config();

    config.forEach(item => {
      const control = form.get(item.key);
      if (control) {
        const isVisible = this.isVisible(item);

        if (isVisible) {
          // Set validators if field is visible
          control.setValidators(item.validators || null);
          control.setAsyncValidators(item.asyncValidators || null);
        } else {
          // Remove validators if field is not visible
          control.setValidators(null);
          control.setAsyncValidators(null);
          // Clear any existing validation errors
          control.setErrors(null);
        }

        // Update validity after changing validators
        control.updateValueAndValidity({ emitEvent: false });
      }
    });
  }
  /** Re-evaluate isDisabled for every control and reflect it on the FormControl. */
  private syncDisabledState(form: FormGroup): void {
    for (const item of this._config()) {
      const control = form.get(item.key);
      if (!control) continue;
      const shouldDisable = this.service.isDisabled(item, form);
      if (shouldDisable && control.enabled) {
        control.disable({ emitEvent: false });
      } else if (!shouldDisable && control.disabled) {
        control.enable({ emitEvent: false });
      }
    }
  }

  /** (Re)subscribe the disabled sync to the given form's value changes. */
  private setupDisabledSync(form: FormGroup): void {
    this.disabledSyncSub?.unsubscribe();
    this.syncDisabledState(form);
    this.disabledSyncSub = form.valueChanges.subscribe(() => this.syncDisabledState(form));
  }

  public getViewFormValue(formItem: DynamicFormItem): any {
    return this.form().get(formItem.key)?.value ?? formItem.value ?? "-";
  }

  setHint(hint: string): void {
    this.currentHint.set(hint);
  }

  destroy(): void {
    this.disabledSyncSub?.unsubscribe();
    this._config.set([]);
    this._form.set(this.fb.build([]));
  }
}
