import { Component, ChangeDetectionStrategy, input, output, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Menubar } from 'primeng/menubar';
import type { MenuItem } from 'primeng/api';

@Component({
  selector: 'cmm-menubar',
  standalone: true,
  imports: [CommonModule, Menubar],
  templateUrl: './cmm-menubar.component.html',
  styleUrl: './cmm-menubar.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmMenubarComponent {
  model = input<MenuItem[]>([]);
  style = input<Record<string, any>>();
  styleClass = input<string>('');
  autoZIndex = input<boolean>(true);
  baseZIndex = input<number>(0);
  autoDisplay = input<boolean>(true);
  autoHide = input<boolean>(false);
  breakpoint = input<string>('960px');
  autoHideDelay = input<number>(100);
  id = input<string>();
  ariaLabel = input<string>();
  ariaLabelledBy = input<string>();

  onFocus = output<FocusEvent>();
  onBlur = output<FocusEvent>();

  startTemplate = contentChild<TemplateRef<any>>('start');
  endTemplate = contentChild<TemplateRef<any>>('end');
  itemTemplate = contentChild<TemplateRef<any>>('item');
  menuIconTemplate = contentChild<TemplateRef<any>>('menuicon');
  submenuIconTemplate = contentChild<TemplateRef<any>>('submenuicon');
}
