import { Component, ChangeDetectionStrategy, input, model, output } from '@angular/core';
import { MenuItem } from 'primeng/api';
import { Steps } from 'primeng/steps';

/**
 * Steps components is an indicator for the steps in a wizard workflow.
 * Wraps PrimeNG Steps component.
 */
@Component({
  selector: 'cmm-steps',
  standalone: true,
  imports: [Steps],
  templateUrl: './cmm-steps.component.html',
  styleUrl: './cmm-steps.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmStepsComponent {
  // Model
  /**
   * Index of the active item
   */
  readonly activeIndex = model<number>(0);

  // Input properties
  /**
   * An array of menu items
   */
  readonly model = input.required<MenuItem[]>();

  /**
   * Whether the items are clickable or not
   */
  readonly readonly = input<boolean>(true);

  /**
   * Inline style of the component
   */
  readonly style = input<Record<string, any>>();

  /**
   * Style class of the component
   */
  readonly styleClass = input<string>('');

  /**
   * Whether to apply 'router-link-active-exact' class if route exactly matches the item path
   */
  readonly exact = input<boolean>(true);

  // Output events
  /**
   * Callback to invoke when the new step is selected
   */
  readonly activeIndexChange = output<number>();
}
