import { Component, input, output, ChangeDetectionStrategy } from '@angular/core';

import { ConfirmPopupModule } from 'primeng/confirmpopup';
import { ConfirmationService, Confirmation } from 'primeng/api';
import { CONFIRMPOPUP_DEFAULTS } from './cmm-confirmpopup.constants';

@Component({
  selector: 'cmm-confirmpopup',
  standalone: true,
  imports: [ConfirmPopupModule],
  providers: [ConfirmationService],
  template: `
    <!-- <p-confirmPopup
      [style]="style() ?? undefined"
      [class]="styleClass()!"
    /> -->
  `,
  styleUrl: './cmm-confirmpopup.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmConfirmpopupComponent {
  // Core props
  key = input<string>();
  defaultFocus = input<'accept' | 'reject' | 'none'>('accept');
  acceptButtonStyleClass = input<string>(CONFIRMPOPUP_DEFAULTS.ACCEPT_BUTTON_STYLE_CLASS);
  rejectButtonStyleClass = input<string>(CONFIRMPOPUP_DEFAULTS.REJECT_BUTTON_STYLE_CLASS);
  acceptIcon = input<string>(CONFIRMPOPUP_DEFAULTS.ACCEPT_ICON);
  rejectIcon = input<string>(CONFIRMPOPUP_DEFAULTS.REJECT_ICON);
  acceptLabel = input<string>(CONFIRMPOPUP_DEFAULTS.ACCEPT_LABEL);
  rejectLabel = input<string>(CONFIRMPOPUP_DEFAULTS.REJECT_LABEL);
  style = input<Record<string, any>>();
  styleClass = input<string>();
  autoZIndex = input<boolean>(CONFIRMPOPUP_DEFAULTS.AUTO_Z_INDEX);
  baseZIndex = input<number>(CONFIRMPOPUP_DEFAULTS.BASE_Z_INDEX);

  constructor(public confirmationService: ConfirmationService) {}
}
