/**
 * Constants for PickList component
 */

/** Filter match mode options */
export const PICKLIST_FILTER_MATCH_MODE = {
  CONTAINS: 'contains' as const,
  STARTS_WITH: 'startsWith' as const,
  ENDS_WITH: 'endsWith' as const,
  EQUALS: 'equals' as const,
  NOT_EQUALS: 'notEquals' as const,
  IN: 'in' as const,
  LT: 'lt' as const,
  LTE: 'lte' as const,
  GT: 'gt' as const,
  GTE: 'gte' as const,
};

export type PickListFilterMatchMode = (typeof PICKLIST_FILTER_MATCH_MODE)[keyof typeof PICKLIST_FILTER_MATCH_MODE];
