import {
  Component,
  input,
  output,
  model,
  contentChild,
  viewChild,
  TemplateRef,
  ChangeDetectionStrategy,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { TreeTable, TreeTableModule } from 'primeng/treetable';
import type { TreeNode, SortMeta, ScrollerOptions } from 'primeng/api';
import type {
  TreeTableNode,
  TreeTableLazyLoadEvent,
  TreeTableColumnReorderEvent,
  TreeTableFilterEvent,
  TreeTableNodeExpandEvent,
  TreeTableNodeCollapseEvent,
  TreeTableSortEvent,
  TreeTableColResizeEvent,
  TreeTableNodeSelectEvent,
  TreeTableNodeUnSelectEvent,
  TreeTableContextMenuSelectEvent,
  TreeTableHeaderCheckboxToggleEvent,
  TreeTableEditEvent,
  TreeTablePaginatorState,
} from './cmm-treetable.types';

/**
 * TreeTable is used to display hierarchical data in tabular format.
 * Wraps PrimeNG TreeTable component.
 */
@Component({
  selector: 'cmm-treetable',
  standalone: true,
  imports: [CommonModule, TreeTableModule],
  templateUrl: './cmm-treetable.component.html',
  styleUrl: './cmm-treetable.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmTreeTableComponent {
  // Core Properties
  /**
   * An array of objects to represent dynamic columns
   */
  readonly columns = input<any[]>([]);

  /**
   * An array of objects to display
   */
  readonly treeTableValue = input<TreeNode[]>([], { alias: 'value' });

  /**
   * Inline style of the component
   */
  readonly style = input<any>();

  /**
   * Style class of the component
   */
  readonly styleClass = input<string>();

  /**
   * Inline style of the table
   */
  readonly tableStyle = input<any>();

  /**
   * Style class of the table
   */
  readonly tableStyleClass = input<string>();

  // Layout
  /**
   * Whether the cell widths scale according to their content or not
   */
  readonly autoLayout = input<boolean>(false);

  /**
   * When specifies, enables horizontal and/or vertical scrolling
   */
  readonly scrollable = input<boolean>(false);

  /**
   * Height of the scroll viewport in fixed pixels or the "flex" keyword for a dynamic size
   */
  readonly scrollHeight = input<string>();

  /**
   * Width of the frozen columns container
   */
  readonly frozenWidth = input<string>();

  /**
   * An array of objects to represent dynamic columns that are frozen
   */
  readonly frozenColumns = input<any>();

  /**
   * Whether to show grid lines between cells
   */
  readonly showGridlines = input<boolean>(false);

  // Pagination
  /**
   * When specified as true, enables the pagination
   */
  readonly paginator = input<boolean>(false);

  /**
   * Number of rows to display per page
   */
  readonly rows = input<number>();

  /**
   * Index of the first row to be displayed
   */
  readonly first = input<number>(0);

  /**
   * Number of page links to display in paginator
   */
  readonly pageLinks = input<number>(5);

  /**
   * Array of integer/object values to display inside rows per page dropdown of paginator
   */
  readonly rowsPerPageOptions = input<any[]>();

  /**
   * Whether to show it even there is only one page
   */
  readonly alwaysShowPaginator = input<boolean>(true);

  /**
   * Position of the paginator
   */
  readonly paginatorPosition = input<'top' | 'bottom' | 'both'>('bottom');

  /**
   * Custom style class for paginator
   */
  readonly paginatorStyleClass = input<string>();

  /**
   * Target element to attach the paginator dropdown overlay
   */
  readonly paginatorDropdownAppendTo = input<any>();

  /**
   * Template of the current page report element
   */
  readonly currentPageReportTemplate = input<string>('{currentPage} of {totalPages}');

  /**
   * Whether to display current page report
   */
  readonly showCurrentPageReport = input<boolean>(false);

  /**
   * Whether to display a dropdown to navigate to any page
   */
  readonly showJumpToPageDropdown = input<boolean>(false);

  /**
   * When enabled, icons are displayed on paginator to go first and last page
   */
  readonly showFirstLastIcon = input<boolean>(true);

  /**
   * Whether to show page links
   */
  readonly showPageLinks = input<boolean>(true);

  /**
   * Locale to be used in paginator formatting
   */
  readonly paginatorLocale = input<string>();

  // Sorting
  /**
   * Sort order to use when an unsorted column gets sorted by user interaction
   */
  readonly defaultSortOrder = input<number>(1);

  /**
   * Defines whether sorting works on single column or on multiple columns
   */
  readonly sortMode = input<'single' | 'multiple'>('single');

  /**
   * When true, resets paginator to first page after sorting
   */
  readonly resetPageOnSort = input<boolean>(true);

  /**
   * Whether to use the default sorting or a custom one using sortFunction
   */
  readonly customSort = input<boolean>(false);

  /**
   * Name of the field to sort data by default
   */
  readonly sortField = input<string>();

  /**
   * Order to sort when default sorting is enabled
   */
  readonly sortOrder = input<number>();

  /**
   * An array of SortMeta objects to sort the data by default in multiple sort mode
   */
  readonly multiSortMeta = input<SortMeta[]>();

  // Selection
  /**
   * Specifies the selection mode, valid values are "single" and "multiple"
   */
  readonly selectionMode = input<string>();

  /**
   * Selected row in single mode or an array of values in multiple mode
   */
  readonly selection = model<any>();

  /**
   * A map of keys to control the selection state
   */
  readonly selectionKeys = model<any>();

  /**
   * Selected row with a context menu
   */
  readonly contextMenuSelection = input<any>();

  /**
   * Mode of the contet menu selection
   */
  readonly contextMenuSelectionMode = input<string>('separate');

  /**
   * A property to uniquely identify a record in data
   */
  readonly dataKey = input<string>();

  /**
   * Defines whether metaKey is should be considered for the selection
   */
  readonly metaKeySelection = input<boolean>(false);

  /**
   * Algorithm to define if a row is selected
   */
  readonly compareSelectionBy = input<string>('deepEquals');

  /**
   * Adds hover effect to rows without the need for selectionMode
   */
  readonly rowHover = input<boolean>(false);

  // Filtering
  /**
   * An array of FilterMetadata objects to provide external filters
   */
  readonly filters = input<any>({});

  /**
   * An array of fields as string to use in global filtering
   */
  readonly globalFilterFields = input<string[]>();

  /**
   * Delay in milliseconds before filtering the data
   */
  readonly filterDelay = input<number>(300);

  /**
   * Mode for filtering valid values are "lenient" and "strict"
   */
  readonly filterMode = input<string>('lenient');

  /**
   * Locale to use in filtering
   */
  readonly filterLocale = input<string>();

  // Virtual Scrolling
  /**
   * Whether the data should be loaded on demand during scroll
   */
  readonly virtualScroll = input<boolean>(false);

  /**
   * Height of a row to use in calculations of virtual scrolling
   */
  readonly virtualScrollItemSize = input<number>();

  /**
   * Whether to use the scroller feature
   */
  readonly virtualScrollOptions = input<ScrollerOptions>();

  /**
   * The delay (in milliseconds) before triggering the virtual scroll
   */
  readonly virtualScrollDelay = input<number>(150);

  // Column Features
  /**
   * When enabled, columns can be resized using drag and drop
   */
  readonly resizableColumns = input<boolean>(false);

  /**
   * Defines whether the overall table width should change on column resize
   */
  readonly columnResizeMode = input<string>('fit');

  /**
   * When enabled, columns can be reordered using drag and drop
   */
  readonly reorderableColumns = input<boolean>(false);

  // Lazy Loading
  /**
   * Defines if data is loaded and interacted with in lazy manner
   */
  readonly lazy = input<boolean>(false);

  /**
   * Whether to call lazy loading on initialization
   */
  readonly lazyLoadOnInit = input<boolean>(true);

  /**
   * Number of total records, defaults to length of value when not defined
   */
  readonly totalRecords = input<number>();

  // Loading
  /**
   * Displays a loader to indicate data load is in progress
   */
  readonly loading = input<boolean>(false);

  /**
   * The icon to show while indicating data load is in progress
   */
  readonly loadingIcon = input<string>();

  /**
   * Whether to show the loading mask when loading property is true
   */
  readonly showLoader = input<boolean>(true);

  // Context Menu
  /**
   * Local ng-template varilable of a ContextMenu
   */
  readonly contextMenu = input<any>();

  // Other
  /**
   * Function to optimize the dom operations by delegating to ngForTrackBy
   */
  readonly rowTrackBy = input<Function>();

  // Output events
  /**
   * Callback to invoke on selected node change
   */
  readonly selectionChange = output<any>();

  /**
   * Callback to invoke when selectionKeys are changed
   */
  readonly selectionKeysChange = output<any>();

  /**
   * Callback to invoke on context menu selection change
   */
  readonly contextMenuSelectionChange = output<any>();

  /**
   * Callback to invoke when data is filtered
   */
  readonly onFilter = output<TreeTableFilterEvent>();

  /**
   * Callback to invoke when a node is expanded
   */
  readonly onNodeExpand = output<TreeTableNodeExpandEvent>();

  /**
   * Callback to invoke when a node is collapsed
   */
  readonly onNodeCollapse = output<TreeTableNodeCollapseEvent>();

  /**
   * Callback to invoke when pagination occurs
   */
  readonly onPage = output<TreeTablePaginatorState>();

  /**
   * Callback to invoke when a column gets sorted
   */
  readonly onSort = output<any>();

  /**
   * Callback to invoke when paging, sorting or filtering happens in lazy mode
   */
  readonly onLazyLoad = output<TreeTableLazyLoadEvent>();

  /**
   * An event emitter to invoke on custom sorting
   */
  readonly sortFunction = output<TreeTableSortEvent>();

  /**
   * Callback to invoke when a column is resized
   */
  readonly onColResize = output<TreeTableColResizeEvent>();

  /**
   * Callback to invoke when a column is reordered
   */
  readonly onColReorder = output<TreeTableColumnReorderEvent>();

  /**
   * Callback to invoke when a node is selected
   */
  readonly onNodeSelect = output<TreeTableNodeSelectEvent>();

  /**
   * Callback to invoke when a node is unselected
   */
  readonly onNodeUnselect = output<TreeTableNodeUnSelectEvent>();

  /**
   * Callback to invoke when a node is selected with right click
   */
  readonly onContextMenuSelect = output<TreeTableContextMenuSelectEvent>();

  /**
   * Callback to invoke when state of header checkbox changes
   */
  readonly onHeaderCheckboxToggle = output<TreeTableHeaderCheckboxToggleEvent>();

  /**
   * Callback to invoke when a cell switches to edit mode
   */
  readonly onEditInit = output<TreeTableEditEvent>();

  /**
   * Callback to invoke when cell edit is completed
   */
  readonly onEditComplete = output<TreeTableEditEvent>();

  /**
   * Callback to invoke when cell edit is cancelled with escape key
   */
  readonly onEditCancel = output<TreeTableEditEvent>();

  // Template references
  readonly caption = contentChild<TemplateRef<any>>('caption');
  readonly header = contentChild<TemplateRef<any>>('header');
  readonly body = contentChild<TemplateRef<any>>('body');
  readonly footer = contentChild<TemplateRef<any>>('footer');
  readonly summary = contentChild<TemplateRef<any>>('summary');
  readonly colgroup = contentChild<TemplateRef<any>>('colgroup');
  readonly emptymessage = contentChild<TemplateRef<any>>('emptymessage');
  readonly paginatorleft = contentChild<TemplateRef<any>>('paginatorleft');
  readonly paginatorright = contentChild<TemplateRef<any>>('paginatorright');
  readonly paginatordropdownitem = contentChild<TemplateRef<any>>('paginatordropdownitem');
  readonly frozenheader = contentChild<TemplateRef<any>>('frozenheader');
  readonly frozenbody = contentChild<TemplateRef<any>>('frozenbody');
  readonly frozenfooter = contentChild<TemplateRef<any>>('frozenfooter');
  readonly frozencolgroup = contentChild<TemplateRef<any>>('frozencolgroup');
  readonly loadingicon = contentChild<TemplateRef<any>>('loadingicon');
  readonly reorderindicatorupicon = contentChild<TemplateRef<any>>('reorderindicatorupicon');
  readonly reorderindicatordownicon = contentChild<TemplateRef<any>>('reorderindicatordownicon');
  readonly sorticon = contentChild<TemplateRef<any>>('sorticon');
  readonly checkboxicon = contentChild<TemplateRef<any>>('checkboxicon');
  readonly headercheckboxicon = contentChild<TemplateRef<any>>('headercheckboxicon');
  readonly togglericon = contentChild<TemplateRef<any>>('togglericon');
  readonly paginatorfirstpagelinkicon = contentChild<TemplateRef<any>>('paginatorfirstpagelinkicon');
  readonly paginatorlastpagelinkicon = contentChild<TemplateRef<any>>('paginatorlastpagelinkicon');
  readonly paginatorpreviouspagelinkicon = contentChild<TemplateRef<any>>('paginatorpreviouspagelinkicon');
  readonly paginatornextpagelinkicon = contentChild<TemplateRef<any>>('paginatornextpagelinkicon');

  // ViewChild for methods
  readonly treeTable = viewChild.required<TreeTable>('treeTable');

  // Public methods
  /**
   * Resets scroll to top
   */
  resetScrollTop(): void {
    this.treeTable()?.resetScrollTop();
  }

  /**
   * Scrolls to given index when using virtual scroll
   */
  scrollToVirtualIndex(index: number): void {
    this.treeTable()?.scrollToVirtualIndex(index);
  }

  /**
   * Scrolls to given index
   */
  scrollTo(options: ScrollToOptions): void {
    this.treeTable()?.scrollTo(options);
  }

  /**
   * Clears the sort and paginator state
   */
  reset(): void {
    this.treeTable()?.reset();
  }
}
