import {
  Component,
  ElementRef,
  HostListener,
  inject,
  input,
  output,
  model,
  forwardRef,
  ChangeDetectionStrategy,
  contentChild,
  TemplateRef,
  computed,
  viewChild,
  signal,
  effect,
  untracked,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, NG_VALUE_ACCESSOR, ControlValueAccessor } from '@angular/forms';
import {
  MultiSelectModule,
  MultiSelect,
  MultiSelectChangeEvent,
  MultiSelectFilterEvent,
  MultiSelectFocusEvent,
  MultiSelectBlurEvent,
  MultiSelectLazyLoadEvent,
  MultiSelectRemoveEvent,
  MultiSelectSelectAllChangeEvent,
} from 'primeng/multiselect';

import { FloatLabelModule } from 'primeng/floatlabel';

import { MULTISELECT_DEFAULTS } from './cmm-multiselect.constants';
import { MultiselectProps } from './cmm-multiselect.types';
import { handleOutsideClick } from '../../../../utils/document-event.utils';
import { useElementWidth } from '../../../../utils/dropdown-helpers';


@Component({
  selector: 'cmm-multiselect',
  standalone: true,
  imports: [CommonModule, FormsModule, MultiSelectModule, FloatLabelModule],
  template: `
    <div #dropdownWrapper class="w-full" [style.--max-chip-width.px]="computedProps().maxChipWidth">
      @if (computedProps().floatLabel) {
        <p-floatlabel class="cmm-multiselect-floatlabel" variant="on">
          <ng-container *ngTemplateOutlet="multiselectTpl" />
          <label [for]="computedProps().inputId">{{ computedProps().label }}</label>
        </p-floatlabel>
      } @else {
        <ng-container *ngTemplateOutlet="multiselectTpl" />
      }

    <ng-template #multiselectTpl>
    <p-multiselect
      [inputId]="computedProps().inputId"
      #multiselect
      [(ngModel)]="value"
      [options]="computedProps().options"
      [optionLabel]="computedProps().optionLabel"
      [optionValue]="computedProps().optionValue"
      [optionDisabled]="computedProps().optionDisabled"
      [optionGroupLabel]="computedProps().optionGroupLabel"
      [optionGroupChildren]="computedProps().optionGroupChildren"
      [group]="computedProps().group"
      [disabled]="computedProps().disabled"
      [filter]="computedProps().filter"
      [filterMatchMode]="computedProps().filterMatchMode"
      [filterPlaceHolder]="computedProps().filterPlaceHolder"
      [filterLocale]="computedProps().filterLocale"
      [display]="doesSelectionOverflow() ? 'comma' : computedProps().display"
      [variant]="computedProps().variant"
      [placeholder]="getPlaceholder()"
      [maxSelectedLabels]="doesSelectionOverflow() ? 0 : computedProps().maxSelectedLabels"
      [selectedItemsLabel]="computedProps().selectedItemsLabel || 'Đã chọn {0} mục'"
      [showToggleAll]="computedProps().showToggleAll"
      [showClear]="computedProps().showClear"
      [emptyMessage]="computedProps().emptyMessage!"
      [emptyFilterMessage]="computedProps().emptyFilterMessage!"
      [scrollHeight]="computedProps().scrollHeight!"
      [lazy]="computedProps().lazy"
      [virtualScroll]="computedProps().virtualScroll"
      [virtualScrollItemSize]="computedProps().virtualScrollItemSize"
      [virtualScrollOptions]="computedProps().virtualScrollOptions"
      [overlayVisible]="computedProps().overlayVisible"
      [appendTo]="computedProps().appendTo"
      [dataKey]="computedProps().dataKey"
      [autofocusFilter]="computedProps().autofocusFilter"
      [resetFilterOnHide]="computedProps().resetFilterOnHide"
      [dropdownIcon]="computedProps().dropdownIcon"
      [showHeader]="computedProps().showHeader"
      [panelStyle]="computedProps().panelStyle"
      [panelStyleClass]="computedProps().panelStyleClass"
      [styleClass]="computedProps().styleClass"
      [style]="computedProps().style"
      [filterBy]="computedProps().filterBy"
      [selectionLimit]="computedProps().selectionLimit"
      [loading]="computedProps().loading"
      [loadingIcon]="computedProps().loadingIcon"
      [ariaLabel]="computedProps().ariaLabel"
      [ariaLabelledBy]="computedProps().ariaLabelledBy"
      [autofocus]="computedProps().autofocus"
      (onChange)="handleChange($event)"
      (onFilter)="handleFilter($event)"
      (onFocus)="handleFocus($event)"
      (onBlur)="handleBlur($event)"
      (onClick)="onClick.emit($event)"
      (onClear)="handleClear()"
      (onPanelShow)="handlePanelShow()"
      (onPanelHide)="handlePanelHide()"
      (onLazyLoad)="onLazyLoad.emit($event)"
      (onRemove)="onRemove.emit($event)"
      (onSelectAllChange)="onSelectAllChange.emit($event)"
      [tabindex]="computedProps().tabindex"
    >
      <ng-template pTemplate="selectedItems" let-value>
        @if (doesSelectionOverflow()) {
          <span>{{ getSelectedItemsLabel(value) }}</span>
        } @else if (selectedItemsTemplate()) {
          <ng-container *ngTemplateOutlet="selectedItemsTemplate()!; context: { $implicit: value }" />
        } @else if (computedProps().display === 'chip') {
          @for (item of value; track item) {
            @let option = findOption(item);
            @let label = getOptionLabel(option);
            @let val = getChipValue(item);
            <div class="p-multiselect-chip" [attr.title]="label">
              <span class="p-chip-label">{{ label }}</span>
              <span class="p-chip-remove-icon pi pi-times cmm-multiselect-chip-remove" (click)="$event.stopPropagation(); removeChipItem(val)"></span>
            </div>
          }
        } @else {
          {{ getCommaSeperatedLabels(value) }}
        }
      </ng-template>

      @if (itemTemplate()) {
        <ng-template pTemplate="item" let-item>
          <ng-container *ngTemplateOutlet="itemTemplate()!; context: { $implicit: item }" />
        </ng-template>
      }
      @if (headerTemplate()) {
        <ng-template pTemplate="header">
          <ng-container *ngTemplateOutlet="headerTemplate()!" />
        </ng-template>
      }
      @if (footerTemplate()) {
        <ng-template pTemplate="footer">
          <ng-container *ngTemplateOutlet="footerTemplate()!" />
        </ng-template>
      }
      @if (emptyTemplate()) {
        <ng-template pTemplate="empty">
          <ng-container *ngTemplateOutlet="emptyTemplate()!" />
        </ng-template>
      } @else {
        <ng-template pTemplate="empty">
          <div [style.height]="getEmptyStateHeight()" class="flex flex-column align-items-center justify-content-center text-center p-3 gap-2">
            <svg width="120" height="120" viewBox="0 0 160 160" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M130.4 88.8C130.4 103 124.6 115.8 115.3 125C106.2 134.1 93.6 139.6 79.7 139.6C65.9 139.6 53.3 134 44.1 125C34.8 115.8 29 103 29 88.8C29 60.7 51.7 38 79.7 38C107.7 38 130.4 60.8 130.4 88.8Z" fill="#F1FAF7" stroke="#D5E5E0" stroke-width="2" stroke-miterlimit="10"/>
            <path d="M72.6691 43.2109L68.9083 56.4761L77.9107 62.7153L77.2776 77.9569L88.6404 57.1032L83.3626 52.8865L89.3987 43.2109H96.175L116.675 65.5109L117.475 129.911C117.475 132.111 115.675 133.811 113.475 133.811H50.675C48.4749 133.811 46.6749 132.011 46.6749 129.911V47.111C46.6749 44.9109 48.4749 43.2109 50.675 43.2109H72.6691Z" fill="white" stroke="#D5E5E0" stroke-width="2" stroke-miterlimit="10" stroke-linejoin="round"/>
            <path d="M68.5292 56.711H56.4292C55.7292 56.711 55.1292 56.111 55.1292 55.411C55.1292 54.711 55.7292 54.111 56.4292 54.111H68.5292C69.2292 54.111 69.8292 54.711 69.8292 55.411C69.8292 56.111 69.2292 56.711 68.5292 56.711Z" fill="#D5E5E0"/>
            <path d="M68.0292 63.9109H56.4292C55.7292 63.9109 55.1292 63.3109 55.1292 62.6109C55.1292 61.9109 55.7292 61.3109 56.4292 61.3109H67.9292C68.6292 61.3109 69.2292 61.9109 69.2292 62.6109C69.2292 63.3109 68.6292 63.9109 68.0292 63.9109Z" fill="#D5E5E0"/>
            <path d="M95.3293 43.2109V61.0109C95.3293 63.5109 97.5293 65.5109 100.029 65.5109H115.829" fill="#D5E5E0"/>
            </svg>

            <span class="text-color-secondary">{{ computedProps().emptyMessage || 'Không có bản ghi nào' }}</span>
          </div>
        </ng-template>
      }
      @if (emptyFilterTemplate()) {
        <ng-template pTemplate="emptyfilter">
          <ng-container *ngTemplateOutlet="emptyFilterTemplate()!" />
        </ng-template>
      } @else {
        <ng-template pTemplate="emptyfilter">
          <div [style.height]="getEmptyStateHeight()" class="flex flex-column align-items-center justify-content-center text-center p-3 gap-2">
             <svg width="120" height="120" viewBox="0 0 160 160" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M130.4 88.8C130.4 103 124.6 115.8 115.3 125C106.2 134.1 93.6 139.6 79.7 139.6C65.9 139.6 53.3 134 44.1 125C34.8 115.8 29 103 29 88.8C29 60.7 51.7 38 79.7 38C107.7 38 130.4 60.8 130.4 88.8Z" fill="#F1FAF7" stroke="#D5E5E0" stroke-width="2" stroke-miterlimit="10"/>
            <path d="M72.6691 43.2109L68.9083 56.4761L77.9107 62.7153L77.2776 77.9569L88.6404 57.1032L83.3626 52.8865L89.3987 43.2109H96.175L116.675 65.5109L117.475 129.911C117.475 132.111 115.675 133.811 113.475 133.811H50.675C48.4749 133.811 46.6749 132.011 46.6749 129.911V47.111C46.6749 44.9109 48.4749 43.2109 50.675 43.2109H72.6691Z" fill="white" stroke="#D5E5E0" stroke-width="2" stroke-miterlimit="10" stroke-linejoin="round"/>
            <path d="M68.5292 56.711H56.4292C55.7292 56.711 55.1292 56.111 55.1292 55.411C55.1292 54.711 55.7292 54.111 56.4292 54.111H68.5292C69.2292 54.111 69.8292 54.711 69.8292 55.411C69.8292 56.111 69.2292 56.711 68.5292 56.711Z" fill="#D5E5E0"/>
            <path d="M68.0292 63.9109H56.4292C55.7292 63.9109 55.1292 63.3109 55.1292 62.6109C55.1292 61.9109 55.7292 61.3109 56.4292 61.3109H67.9292C68.6292 61.3109 69.2292 61.9109 69.2292 62.6109C69.2292 63.3109 68.6292 63.9109 68.0292 63.9109Z" fill="#D5E5E0"/>
            <path d="M95.3293 43.2109V61.0109C95.3293 63.5109 97.5293 65.5109 100.029 65.5109H115.829" fill="#D5E5E0"/>
            </svg>

            <span class="text-color-secondary">{{ computedProps().emptyFilterMessage || computedProps().emptyMessage || 'Không có bản ghi nào' }}</span>
          </div>
        </ng-template>
      }
      <ng-template pTemplate="removetokenicon">
        <i class="pi pi-times cmm-multiselect-chip-remove"></i>
      </ng-template>
    </p-multiselect>
    </ng-template>
    </div>
  `,
  styleUrl: './cmm-multiselect.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CmmMultiselectComponent),
      multi: true,
    },
  ],

})
export class CmmMultiselectComponent implements ControlValueAccessor {
  private readonly hostElement = inject(ElementRef<HTMLElement>);

  /**
   * When `floatLabel` is enabled the `label` is rendered as the floating label so the inline placeholder is suppressed.
   */
  getPlaceholder(): string {
    if (this.computedProps().floatLabel) {
      return '';
    }
    return this.computedProps().placeholder ?? '';
  }

  private getDefaultScrollHeight(p?: MultiselectProps): string {
    const maxVisibleSearchItems = p?.maxVisibleSearchItems ?? 5;
    const itemHeight = p?.virtualScrollItemSize ?? 40;
    const defaultPadding = 8;

    return `${maxVisibleSearchItems * itemHeight + defaultPadding}px`;
  }

  getEmptyStateHeight(): string {
    return this.computedProps().scrollHeight || this.getDefaultScrollHeight(this.props());
  }

  // Model
  value = model<any[]>([]);
  // Bỏ required tránh trường hợp form chưa render xong đã gọi viewChild -> crash
  // Write value chạy trước trong cycle nên this.multiselect sẽ không có instance khi init (vì khởi tạo afterView)
  multiselect = viewChild<MultiSelect>('multiselect');

  // Content children templates
  itemTemplate = contentChild<TemplateRef<any>>('item');
  selectedItemsTemplate = contentChild<TemplateRef<any>>('selectedItems');
  headerTemplate = contentChild<TemplateRef<any>>('header');
  footerTemplate = contentChild<TemplateRef<any>>('footer');
  emptyTemplate = contentChild<TemplateRef<any>>('empty');
  emptyFilterTemplate = contentChild<TemplateRef<any>>('emptyFilter');

  // Component props
  props = input<MultiselectProps>();

  cvaDisabled = signal(false);

  dropdownWrapper = viewChild.required<ElementRef>('dropdownWrapper');

  dropdownWidth = useElementWidth(
    this.dropdownWrapper
  )

  doesSelectionOverflow = signal(false);

  findOption(val: any): any {
    if (val == null) return null;
    const options = this.computedProps().options || [];
    const optionValueKey = this.computedProps().optionValue;
    const isValObject = typeof val === 'object' && val !== null;
    
    // First try strict lookup in options
    const option = options.find(opt => isValObject ? opt === val : opt[optionValueKey] === val);
    if (option) return option;

    // If val is an object and not found in options by reference, check structural keys
    if (isValObject) {
      const dataKey = this.computedProps().dataKey;
      if (dataKey && val[dataKey] !== undefined) {
        const found = options.find(opt => opt[dataKey] === val[dataKey]);
        if (found) return found;
      }
      if (optionValueKey && val[optionValueKey] !== undefined) {
        const found = options.find(opt => opt[optionValueKey] === val[optionValueKey]);
        if (found) return found;
      }
      
      // Fallback: treat the value object itself as the option
      return val;
    }
    return null;
  }

  getOptionLabel(option: any): string {
    if (!option) {
      return '';
    }
    const optionLabelKey = this.computedProps().optionLabel;
    return String(option[optionLabelKey] || '');
  }

  getSelectedItemsLabel(value: any[]): string {
    const count = value ? value.length : 0;
    const pattern = this.computedProps().selectedItemsLabel || 'Đã chọn {0} mục';
    return pattern.replace('{0}', String(count));
  }

  getCommaSeperatedLabels(value: any[]): string {
    if (!value || value.length === 0) return '';
    return value
      .map(val => this.getOptionLabel(this.findOption(val)))
      .filter(Boolean)
      .join(', ');
  }

  getChipValue(item: any): any {
    if (item == null) return null;
    const optionValueKey = this.computedProps().optionValue;
    if (typeof item === 'object' && optionValueKey && item[optionValueKey] !== undefined) {
      return item[optionValueKey];
    }
    return item;
  }

  removeChipItem(val: any): void {
    const currentValue = this.value() || [];
    const newValue = currentValue.filter(v => v !== val);
    this.value.set(newValue);
    this.onChangeFn(newValue);
    this.onTouchedFn();
    this.onRemove.emit({
      newValue: newValue,
      removed: val
    });
  }

  constructor() {
    effect(() => {
      const containerWidth = this.dropdownWidth();
      if (!containerWidth) {
        // console.log('--- cmm-multiselect: containerWidth is 0/undefined ---');
        return;
      }
      const reservedSpace = 80;
      const availableWidth = containerWidth - reservedSpace;
      const selectedValues = this.value() || [];
      // const options = this.computedProps().options || [];
      const optionLabelKey = this.computedProps().optionLabel;
      // const optionValueKey = this.computedProps().optionValue;
      const averageCharWidth = 8;
      const chipPaddingAndIconWidth = 34;
      // set infinitiy when ommited to prevent Math.min return NaN
      const maxChipWidth = this.computedProps().maxChipWidth ?? Infinity;
      const gap = 4;

      // console.log('--- cmm-multiselect overflow check start ---', {
      //   containerWidth,
      //   availableWidth,
      //   selectedValuesCount: selectedValues.length,
      //   optionsCount: options.length,
      //   optionLabelKey,
      //   optionValueKey
      // });

      let estimatedTotalWidth = 0;
      selectedValues.forEach((val, idx) => {
        const option = this.findOption(val);
        const labelText = option ? String(option[optionLabelKey] || '') : '';
        const estimatedChipWidth = Math.min(
          maxChipWidth,
          (labelText.length * averageCharWidth) + chipPaddingAndIconWidth
        );

        // console.log(`  [Chip ${idx}]`, {
        //   val,
        //   optionFound: !!option,
        //   labelText,
        //   estimatedChipWidth
        // });

        estimatedTotalWidth += estimatedChipWidth + gap;
      });

      if (selectedValues.length > 0) {
        estimatedTotalWidth -= gap;
      }

      const isCurrentlyOverflowed = untracked(this.doesSelectionOverflow);
      // Prevent loop flickering during zoom or layout changes with threshold
      const threshold = isCurrentlyOverflowed ? 30 : 0;
      const overflowed = estimatedTotalWidth > (availableWidth - threshold);

      // console.log('  [Calculation Summary]', {
      //   estimatedTotalWidth,
      //   availableWidthWithThreshold: availableWidth - threshold,
      //   overflowed,
      //   isCurrentlyOverflowed
      // });

      if (overflowed !== isCurrentlyOverflowed) {
        // console.log(`  => SWITCHING doesSelectionOverflow to: ${overflowed}`);
        this.doesSelectionOverflow.set(overflowed);
      }
    });
  }
  // Computed props with defaults
  computedProps = computed(() => {
    const p = this.props();
    return {
      ...p,
      options: p?.options ?? [],
      optionLabel: p?.optionLabel ?? MULTISELECT_DEFAULTS.OPTION_LABEL,
      optionValue: p?.optionValue ?? MULTISELECT_DEFAULTS.OPTION_VALUE,
      optionDisabled: p?.optionDisabled ?? MULTISELECT_DEFAULTS.OPTION_DISABLED,
      optionGroupLabel: p?.optionGroupLabel ?? MULTISELECT_DEFAULTS.OPTION_GROUP_LABEL,
      optionGroupChildren: p?.optionGroupChildren ?? MULTISELECT_DEFAULTS.OPTION_GROUP_CHILDREN,
      group: p?.group ?? false,
      disabled: (p?.disabled ?? MULTISELECT_DEFAULTS.DISABLED) || this.cvaDisabled(),
      filter: p?.filter ?? MULTISELECT_DEFAULTS.FILTER,
      filterMatchMode: p?.filterMatchMode ?? MULTISELECT_DEFAULTS.FILTER_MATCH_MODE,
      filterPlaceHolder: p?.filterPlaceHolder ?? undefined,
      filterLocale: p?.filterLocale ?? undefined,
      display: p?.display ?? MULTISELECT_DEFAULTS.DISPLAY,
      variant: p?.variant ?? MULTISELECT_DEFAULTS.VARIANT,
      size: p?.size ?? undefined,
      placeholder: p?.placeholder ?? undefined,
      floatLabel: p?.floatLabel ?? false,
      label: p?.label ?? '',
      inputId: p?.inputId ?? undefined,
      maxSelectedLabels: p?.maxSelectedLabels ?? MULTISELECT_DEFAULTS.MAX_SELECTED_LABELS,
      selectedItemsLabel: p?.selectedItemsLabel ?? undefined,
      showToggleAll: p?.showToggleAll ?? MULTISELECT_DEFAULTS.SHOW_TOGGLE_ALL,
      showClear: p?.showClear ?? MULTISELECT_DEFAULTS.SHOW_CLEAR,
      emptyMessage: p?.emptyMessage ?? undefined,
      emptyFilterMessage: p?.emptyFilterMessage ?? undefined,
      scrollHeight: p?.scrollHeight ?? this.getDefaultScrollHeight(p),
      lazy: p?.lazy ?? MULTISELECT_DEFAULTS.LAZY,
      virtualScroll: p?.virtualScroll ?? MULTISELECT_DEFAULTS.VIRTUAL_SCROLL,
      virtualScrollItemSize: p?.virtualScrollItemSize ?? undefined,
      virtualScrollOptions: p?.virtualScrollOptions ?? undefined,
      overlayVisible: p?.overlayVisible ?? MULTISELECT_DEFAULTS.OVERLAY_VISIBLE,
      appendTo: p?.appendTo ?? 'body',
      dataKey: p?.dataKey ?? undefined,
      autofocusFilter: p?.autofocusFilter ?? false,
      resetFilterOnHide: p?.resetFilterOnHide ?? MULTISELECT_DEFAULTS.RESET_FILTER_ON_HIDE,
      dropdownIcon: p?.dropdownIcon ?? MULTISELECT_DEFAULTS.DROP_DOWN_ICON,
      showHeader: p?.showHeader ?? MULTISELECT_DEFAULTS.SHOW_HEADER,
      autoZIndex: p?.autoZIndex ?? MULTISELECT_DEFAULTS.AUTO_Z_INDEX,
      baseZIndex: p?.baseZIndex ?? MULTISELECT_DEFAULTS.BASE_Z_INDEX,
      panelStyle: p?.panelStyle ?? undefined,
      panelStyleClass: p?.panelStyleClass ?? undefined,
      styleClass: p?.styleClass ?? undefined,
      style: p?.style ?? undefined,
      filterBy: p?.filterBy ?? undefined,
      selectionLimit: p?.selectionLimit ?? undefined,
      loading: p?.loading ?? false,
      loadingIcon: p?.loadingIcon ?? undefined,
      ariaLabel: p?.ariaLabel ?? undefined,
      ariaLabelledBy: p?.ariaLabelledBy ?? undefined,
      autofocus: p?.autofocus ?? false,
      maxWidth: p?.maxWidth ?? undefined,
      tabindex: p?.tabindex ?? 0,
      maxLength: p?.maxLength ?? undefined,
      maxChipWidth: p?.maxChipWidth ?? undefined,
    };
  });

  handlePanelShow(): void {
    this.onPanelShow.emit();
    const maxLength = this.computedProps().maxLength;
    if (maxLength == null) return;
    queueMicrotask(() => {
      const filterEl = this.multiselect()?.filterInputChild?.nativeElement;
      if (filterEl) {
        filterEl.setAttribute('maxlength', String(maxLength));
      }
    });
  }

  // Output events
  onChange = output<MultiSelectChangeEvent>();
  onFilter = output<MultiSelectFilterEvent>();
  onFocus = output<MultiSelectFocusEvent>();
  onBlur = output<MultiSelectBlurEvent>();
  onClick = output<Event>();
  onClear = output<void>();
  onPanelShow = output<void>();
  onPanelHide = output<void>();
  onLazyLoad = output<MultiSelectLazyLoadEvent>();
  onRemove = output<MultiSelectRemoveEvent>();
  onSelectAllChange = output<MultiSelectSelectAllChangeEvent>();
  handleClear() {
    this.onChangeFn([]);
    this.onTouchedFn()
    this.onClear.emit()
  }
  // ControlValueAccessor
  private onChangeFn: (value: any[]) => void = () => { };
  private onTouchedFn: () => void = () => { };

  writeValue(value: any[]): void {
    this.value.set(value || []);
    if (!value || value.length === 0) {
      // Write value chạy trước trong cycle nên this.multiselect sẽ không có instance khi init (vì khởi tạo afterView)
      this.multiselect()?.resetFilter();
    }
  }

  registerOnChange(fn: (value: any[]) => void): void {
    this.onChangeFn = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouchedFn = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.cvaDisabled.set(isDisabled);
  }

  handleChange(event: MultiSelectChangeEvent): void {
    this.onChange.emit(event);
    this.onChangeFn(event.value);
  }

  handleFilter(event: MultiSelectFilterEvent): void {
    this.onFilter.emit(event);
  }

  handleFocus(event: MultiSelectFocusEvent): void {
    this.onFocus.emit(event);
  }

  handleBlur(event: MultiSelectBlurEvent): void {
    this.onBlur.emit(event);
    if (!this.multiselect()?.overlayVisible) {
      this.onTouchedFn();
    }
  }

  /**
   * Commit the touched state when the overlay closes, mirroring PrimeNG
   * MultiSelect's onModelTouched() call in onOverlayAfterLeave(). This covers the
   * filter flow where the combobox input already blurred (while the panel was
   * open) when focus moved into the filter, so handleBlur is skipped on close.
   */
  handlePanelHide(): void {
    this.onPanelHide.emit();
    this.onTouchedFn();
  }

  /**
   * Handle document mouse down event
   * @param event Mouse event
   */
  @HostListener('document:mousedown', ['$event'])
  handleDocumentMouseDown(event: MouseEvent): void {
    const multiselect = this.multiselect();
    const triggerElement = this.hostElement.nativeElement;
    if (!multiselect) {
      return;
    }
    const overlayElement = multiselect.overlayViewChild?.overlayEl as HTMLElement | undefined;

    handleOutsideClick(
      event,
      [triggerElement, overlayElement],
      () => { multiselect.hide() },
      multiselect.overlayVisible // prevent execute when overlay not active
    )
  }

  protected readonly MULTISELECT_DEFAULTS = MULTISELECT_DEFAULTS;
}
