/**
 * Upload Facade - State Orchestration Layer
 * Following SOLID:
 * - Single Responsibility: Coordinate upload state & logic
 * - Open/Closed: Extensible via service injection
 * - Liskov Substitution: Implements IUploadFacade
 * - Interface Segregation: Minimal public API
 * - Dependency Inversion: Depends on abstractions (IFileValidator)
 *
 * OWNS ALL STATE
 * OWNS ALL EFFECTS
 * EXPOSES ONLY READONLY SIGNALS
 */

import { computed, effect, Injectable, signal } from '@angular/core';
import { FILEUPLOAD_DEFAULTS } from '../base/primeng/file-upload/file-upload.const';
import { FileValidationService } from './upload.service';
import { FileValidationError, IUploadFacade, UploadValidationConfig } from './upload.types';
import { addFiles, filterFilesByType, formatFileSize, limitFiles, removeFileAtIndex } from './upload.utils';

@Injectable()
export class UploadFacade implements IUploadFacade {
  // ========================================
  // PRIVATE STATE (Mutable)
  // ========================================
  private readonly filesState = signal<File[]>([]);
  private readonly errorsState = signal<FileValidationError[]>([]);
  private readonly uploadingState = signal<boolean>(false);
  private readonly dragOverState = signal<boolean>(false);
  private readonly dragInvalidState = signal<boolean>(false);
  private readonly dragErrorsState = signal<FileValidationError[]>([]);

  // Validation config (updated from component inputs)
  private readonly validationConfig = signal<UploadValidationConfig>({
    maxFileSize: FILEUPLOAD_DEFAULTS.MAX_FILE_SIZE,
    maxFiles: 10,
    minFiles: 0,
    accept: '.xls,.xlsx,.ods',
    invalidFileLimitMessageDetail: '',
    invalidFileLimitMessageSummary: '',
    invalidFileSizeMessageDetail: 'File quá lớn. Giới hạn tối đa 5MB.',
    invalidFileSizeMessageSummary: '',
    invalidFileTypeMessageDetail: '',
    invalidFileTypeMessageSummary: '',
  });

  private readonly multipleFlag = signal<boolean>(false);

  // ========================================
  // PUBLIC API - Readonly Signals 
  // ========================================
  readonly files = computed(() => {    
    return this.filesState();
  });
  readonly errors = computed(() => this.errorsState());
  readonly isUploading = computed(() => this.uploadingState());
  readonly isDragOver = computed(() => this.dragOverState());
  readonly isDragInvalid = computed(() => this.dragInvalidState());
  readonly dragErrors = computed(() => this.dragErrorsState());

  // Derived state
  readonly hasFiles = computed(() => this.filesState().length > 0);
  readonly fileCount = computed(() => this.filesState().length);

  readonly totalSize = computed(() => this.filesState().reduce((sum, file) => sum + file.size, 0));

  readonly isValid = computed(() => {
    const files = this.filesState();
    const errors = this.errorsState();
    const config = this.validationConfig();

    return files.length >= config.minFiles && files.length <= config.maxFiles && errors.length === 0;
  });

  readonly canSubmit = computed(() => this.hasFiles() && this.isValid());

  readonly totalSizeFormatted = computed(() => {
    const total = this.totalSize();
    return this.formatBytes(total);
  });

  // ========================================
  // CONSTRUCTOR & EFFECTS
  // ========================================
  constructor(private readonly validationService: FileValidationService) {
    // Auto-validate when files change
    effect(() => {
      const files = this.filesState();
      const config = this.validationConfig();
      this.validateCurrentFiles(files, config);
    });

    // Clear errors when all files removed
    effect(() => {
      if (this.filesState().length === 0) {
        this.errorsState.set([]);
      }
    });
  }

  // ========================================
  // CONFIGURATION
  // ========================================

  /**
   * Update validation configuration
   */
  updateConfig(config: Partial<UploadValidationConfig>): void {
    this.validationConfig.update((current) => ({ ...current, ...config }));
  }

  /**
   * Set multiple flag
   */
  setMultiple(multiple: boolean): void {
    this.multipleFlag.set(multiple);
  }

  // ========================================
  // FILE OPERATIONS
  // ========================================

  /**
   * Select files (from file input or initial set)
   */
  selectFiles(files: File[]): void {
    const config = this.validationConfig();
    const multiple = this.multipleFlag();
    const currentFiles = this.filesState();

    // Validate new files against existing files (including duplicate check)
    const newFileErrors = this.validationService.validateFiles(files, config, currentFiles);

    // Filter out files with errors (duplicates, invalid type, size)
    const filesWithErrors = newFileErrors.map((err) => err.file).filter(Boolean) as File[];
    const validFiles = files.filter((file) => !filesWithErrors.includes(file));

    // Filter by accepted types (additional check)
    const validTypeFiles = filterFilesByType(validFiles, config.accept);

    // Add files respecting multiple flag
    let newFiles = addFiles(currentFiles, validTypeFiles, multiple);

    // Limit to max files
    newFiles = limitFiles(newFiles, config.maxFiles);

    // Update state
    this.filesState.set(newFiles);

    // Set duplicate errors if any
    if (newFileErrors.length > 0) {
      const currentErrors = this.errorsState();
      this.errorsState.set([...currentErrors, ...newFileErrors]);
    }
  }

  /**
   * Remove file at specific index
   */
  removeFile(index: number): void {
    const currentFiles = this.filesState();
    const updatedFiles = removeFileAtIndex(currentFiles, index);    
    this.filesState.set(updatedFiles);
  }

  /**
   * Clear all files
   */
  clearFiles(): void {
    this.filesState.set([]);
    this.errorsState.set([]);
  }

  /**
   * Validate dragged files without adding them
   * Returns validation errors with type only (no message)
   * Parent component can handle error messages themselves
   */
  validateDraggedFiles(files: File[]): FileValidationError[] {
    const config = this.validationConfig();
    const validTypeFiles = filterFilesByType(files, config.accept);

    const errors: FileValidationError[] = [];

    // Check if all files were filtered out (invalid type)
    if (validTypeFiles.length === 0 && files.length > 0) {
      errors.push({
        type: 'type',
        message: config.invalidFileTypeMessageDetail ?? '',
      });
      this.dragErrorsState.set(errors);
      return errors;
    }

    // Check file size
    const oversizedFiles = validTypeFiles.filter((f) => f.size > config.maxFileSize);
    if (oversizedFiles.length > 0) {
      oversizedFiles.forEach((file) => {
        errors.push({
          type: 'size',
          message: config.invalidFileSizeMessageDetail ?? '',
          file,
        });
      });
    }

    // Check file limit
    const totalFiles = this.filesState().length + validTypeFiles.length;
    if (totalFiles > config.maxFiles) {
      errors.push({
        type: 'limit',
        message: config.invalidFileLimitMessageDetail ?? '',
      });
    }

    this.dragErrorsState.set(errors);
    return errors;
  }

  /**
   * Handle drag & drop
   */
  handleDrop(files: File[]): FileValidationError[] {
    const errors = this.validateDraggedFiles(files);

    if (errors.length === 0) {
      this.selectFiles(files);
    }

    this.setDragOver(false);
    this.setDragInvalid(false);

    return errors;
  }

  // ========================================
  // DRAG STATE
  // ========================================

  setDragOver(isDragOver: boolean): void {
    this.dragOverState.set(isDragOver);
    // Clear drag invalid state when not dragging
    if (!isDragOver) {
      this.setDragInvalid(false);
    }
  }

  setDragInvalid(isInvalid: boolean): void {
    this.dragInvalidState.set(isInvalid);
    if (!isInvalid) {
      this.dragErrorsState.set([]);
    }
  }

  /**
   * Validate files during drag without modifying state
   * Note: During dragover, we can only check MIME types, not full file validation
   */
  validateOnDragOver(dragEvent: DragEvent): void {
    const config = this.validationConfig();
    const items = dragEvent.dataTransfer?.items;

    if (!items || items.length === 0) {
      this.setDragInvalid(false);
      return;
    }

    const acceptTypes = config.accept.split(',').map((t) => t.trim());

    // Convert extension-based patterns to MIME types
    const acceptedMimeTypes = new Set<string>();
    const acceptedExtensions: string[] = [];

    acceptTypes.forEach((acceptType) => {
      if (acceptType.startsWith('.')) {
        // Store extension and get its MIME types
        acceptedExtensions.push(acceptType);
        const mimeTypes = this.extensionToMimeTypes(acceptType);
        mimeTypes.forEach((mime) => {
          acceptedMimeTypes.add(mime);
        });
      } else if (acceptType.endsWith('/*')) {
        // Wildcard MIME type pattern
        acceptedMimeTypes.add(acceptType);
      } else {
        // Exact MIME type
        acceptedMimeTypes.add(acceptType);
      }
    });

    let hasInvalidType = false;

    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      if (item.kind !== 'file') {
        continue;
      }

      const fileType = item.type;

      // If no MIME type provided, we can't validate
      if (!fileType) {
        continue;
      }

      // Check if MIME type is accepted
      let isAccepted = false;

      for (const acceptedType of acceptedMimeTypes) {
        if (acceptedType.endsWith('/*')) {
          const baseType = acceptedType.split('/')[0];
          if (fileType.startsWith(`${baseType}/`)) {
            isAccepted = true;
            break;
          }
        } else if (fileType === acceptedType) {
          isAccepted = true;
          break;
        }
      }

      if (!isAccepted) {
        hasInvalidType = true;
        break;
      }
    }

    this.setDragInvalid(hasInvalidType);
  }

  /**
   * Helper to convert extension to MIME types
   */
  private extensionToMimeTypes(extension: string): string[] {
    const ext = extension.toLowerCase().replace('.', '');

    const mimeMap: Record<string, string[]> = {
      xls: ['application/vnd.ms-excel'],
      xlsx: ['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'],
      ods: ['application/vnd.oasis.opendocument.spreadsheet'],
      doc: ['application/msword'],
      docx: ['application/vnd.openxmlformats-officedocument.wordprocessingml.document'],
      pdf: ['application/pdf'],
      jpg: ['image/jpeg'],
      jpeg: ['image/jpeg'],
      png: ['image/png'],
      gif: ['image/gif'],
      svg: ['image/svg+xml'],
      txt: ['text/plain'],
      csv: ['text/csv'],
    };

    return mimeMap[ext] || [];
  }

  // ========================================
  // UPLOAD STATE
  // ========================================

  setUploading(isUploading: boolean): void {
    this.uploadingState.set(isUploading);
  }

  // ========================================
  // VALIDATION
  // ========================================

  private validateCurrentFiles(files: File[], config: UploadValidationConfig): void {
    const errors = this.validationService.validateFiles(files, config);
    this.errorsState.set(errors);
  }

  /**
   * Manually trigger validation
   */
  validate(): FileValidationError[] {
    const files = this.filesState();
    const config = this.validationConfig();
    const errors = this.validationService.validateFiles(files, config);
    this.errorsState.set(errors);
    return errors;
  }

  // ========================================
  // PUBLIC GETTERS (for ControlValueAccessor)
  // ========================================

  getFiles(): File[] {
    return this.filesState();
  }

  getErrors(): FileValidationError[] {
    return this.errorsState();
  }

  /**
   * Format bytes to human-readable size
   * @private - Utility wrapper
   */
  private formatBytes(bytes: number): string {
    return formatFileSize(bytes);
  }

  /**
   * Set files directly (for ControlValueAccessor writeValue)
   */
  setFiles(files: File[] | null): void {
    this.filesState.set(files || []);
  }
}
