/**
 * ButtonGroup size options
 */
export const BUTTONGROUP_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type ButtonGroupSize = (typeof BUTTONGROUP_SIZES)[keyof typeof BUTTONGROUP_SIZES];

/**
 * ButtonGroup style variants
 */
export const BUTTONGROUP_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export type ButtonGroupVariant = (typeof BUTTONGROUP_VARIANTS)[keyof typeof BUTTONGROUP_VARIANTS];

/**
 * ButtonGroup orientation options
 */
export const BUTTONGROUP_ORIENTATIONS = {
  HORIZONTAL: 'horizontal',
  VERTICAL: 'vertical',
} as const;

export type ButtonGroupOrientation = (typeof BUTTONGROUP_ORIENTATIONS)[keyof typeof BUTTONGROUP_ORIENTATIONS];
