import { Component, computed } from '@angular/core';
import { IamBasIcon } from './base/base';

@Component({
  selector: 'span[closeIcon]',
  template: `
    @let data = computedProps();
    <svg
      xmlns="http://www.w3.org/2000/svg"
      [attr.width]="data.width"
      [attr.height]="data.height"
      viewBox="0 0 24 24"
      fill="none"
    >
      <path
        d="M7.75781 7.75781L16.2431 16.2431"
        [attr.stroke]="data.stroke"
        stroke-width="1.5"
        stroke-linecap="round"
        stroke-linejoin="round"
      />
      <path
        d="M7.75691 16.2431L16.2422 7.75781"
        [attr.stroke]="data.stroke"
        stroke-width="1.5"
        stroke-linecap="round"
        stroke-linejoin="round"
      />
    </svg>
  `,
})
export class IamCloseIcon extends IamBasIcon {
  computedProps = computed(() => {
    const p = this.props();
    return {
      ...p,
      width: p.width || '24',
      height: p.height || '24',
      stroke: p.stroke || '#0F1110',
    };
  });
}
