import { Component, input, contentChild, TemplateRef, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MeterGroupModule } from 'primeng/metergroup';
import {
  CmmMetergroupProps,
  MeterItem,
  MeterGroupOrientation,
  MeterGroupLabelPosition,
  MeterGroupLabelOrientation,
} from './cmm-metergroup.types';
import { METERGROUP_DEFAULTS } from './cmm-metergroup.constants';

/**
 * MeterGroup displays scalar measurements within a known range.
 * Wraps PrimeNG MeterGroup component.
 */
@Component({
  selector: 'cmm-metergroup',
  standalone: true,
  imports: [CommonModule, MeterGroupModule],
  templateUrl: './cmm-metergroup.component.html',
  styleUrl: './cmm-metergroup.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmMetergroupComponent {
  /**
   * Current value of the metergroup
   */
  value = input<MeterItem[]>();

  /**
   * Minimum boundary value
   */
  min = input<number>(METERGROUP_DEFAULTS.MIN);

  /**
   * Maximum boundary value
   */
  max = input<number>(METERGROUP_DEFAULTS.MAX);

  /**
   * Specifies the layout of the component
   */
  orientation = input<MeterGroupOrientation>(METERGROUP_DEFAULTS.ORIENTATION);

  /**
   * Specifies the label position of the component
   */
  labelPosition = input<MeterGroupLabelPosition>(METERGROUP_DEFAULTS.LABEL_POSITION);

  /**
   * Specifies the label orientation of the component
   */
  labelOrientation = input<MeterGroupLabelOrientation>(METERGROUP_DEFAULTS.LABEL_ORIENTATION);

  /**
   * Inline style of the element
   */
  style = input<Record<string, any>>();

  /**
   * Style class of the element
   */
  styleClass = input<string>();

  /**
   * Custom label template
   */
  labelTemplate = contentChild<TemplateRef<any>>('label');

  /**
   * Custom meter item template
   */
  meterTemplate = contentChild<TemplateRef<any>>('meter');

  /**
   * Custom start template
   */
  startTemplate = contentChild<TemplateRef<any>>('start');

  /**
   * Custom end template
   */
  endTemplate = contentChild<TemplateRef<any>>('end');

  /**
   * Custom icon template
   */
  iconTemplate = contentChild<TemplateRef<any>>('icon');
}
