import { ChangeDetectionStrategy, Component, contentChild, input, model, output, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { OrganizationChartModule } from 'primeng/organizationchart';
import { TreeNode } from 'primeng/api';
import {
  OrganizationChartNodeSelectEvent,
  OrganizationChartNodeUnSelectEvent,
  OrganizationChartNodeExpandEvent,
  OrganizationChartNodeCollapseEvent,
} from './cmm-organizationchart.types';
import { OrganizationChartSelectionMode } from './cmm-organizationchart.constants';

/**
 * CmmOrganizationChartComponent - Angular 19 wrapper for PrimeNG OrganizationChart
 *
 * A thin wrapper component that provides signal-based inputs and two-way binding
 * for PrimeNG's OrganizationChart component. OrganizationChart visualizes hierarchical
 * organization data in a tree structure.
 *
 * @example
 * ```html
 * <cmm-organization-chart
 *   [(value)]="orgData"
 *   [(selection)]="selectedNode"
 *   selectionMode="single">
 *   <ng-template pTemplate="person" let-node>
 *     <div>{{ node.label }}</div>
 *   </ng-template>
 * </cmm-organization-chart>
 * ```
 */
@Component({
  selector: 'cmm-organization-chart',
  standalone: true,
  imports: [CommonModule, OrganizationChartModule],
  templateUrl: './cmm-organizationchart.component.html',
  styleUrl: './cmm-organizationchart.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  exportAs: 'cmmorganizationchart',
})
export class CmmOrganizationChartComponent {
  // Template references
  readonly togglericonTemplate = contentChild<TemplateRef<any>>('togglericon');

  // Input properties
  /** Inline style of the component */
  readonly style = input<any>();
  /** Style class of the component */
  readonly styleClass = input<string>();
  /** Defines the selection mode */
  readonly selectionMode = input<OrganizationChartSelectionMode>();
  /** Whether the nodes can be expanded or toggled */
  readonly collapsible = input<boolean>(false);
  /** Whether the space allocated by a node is preserved when hidden */
  readonly preserveSpace = input<boolean>(true);

  // Two-way bindable properties
  /** An array of nested TreeNodes */
  readonly value = model<TreeNode[]>();
  /** A single treenode instance or an array to refer to the selections */
  readonly selection = model<any>();

  // Output events
  /** Callback to invoke when a node is selected */
  readonly onNodeSelect = output<OrganizationChartNodeSelectEvent>();
  /** Callback to invoke when a node is unselected */
  readonly onNodeUnselect = output<OrganizationChartNodeUnSelectEvent>();
  /** Callback to invoke when a node is expanded */
  readonly onNodeExpand = output<OrganizationChartNodeExpandEvent>();
  /** Callback to invoke when a node is collapsed */
  readonly onNodeCollapse = output<OrganizationChartNodeCollapseEvent>();
}
