import { Component, input, output, ChangeDetectionStrategy, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ToastModule } from 'primeng/toast';
import { ToastPosition } from './cmm-toast.types';
import { TOAST_DEFAULTS } from './cmm-toast.constants';

@Component({
  selector: 'cmm-toast',
  standalone: true,
  imports: [CommonModule, ToastModule],
  // providers: [MessageService],
  template: `
    <p-toast
      [key]="key()"
      [position]="position()"
      [life]="life()"
      [showTransitionOptions]="showTransitionOptions()"
      [hideTransitionOptions]="hideTransitionOptions()"
      [autoZIndex]="autoZIndex()"
      [baseZIndex]="baseZIndex()"
      [preventOpenDuplicates]="preventOpenDuplicates()"
      [preventDuplicates]="preventDuplicates()"
      [style]="style()"
      [styleClass]="styleClass()!"
      (onClose)="onClose.emit($event)"
      [breakpoints]="breakpoints()"
    >
      @if(messageTemplate()) {
        <ng-template #headless let-mess let-closeFn="closeFn">
          <ng-container *ngTemplateOutlet="messageTemplate()!; context: { $implicit: mess, closeFn: closeFn }" />
        </ng-template>
      }
      </p-toast>
  `,
  styleUrl: './cmm-toast.component.scss',
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmToastComponent {
  // Core props
  key = input<string>();
  position = input<ToastPosition>(TOAST_DEFAULTS.POSITION);
  life = input<number>(TOAST_DEFAULTS.LIFE);
  showTransitionOptions = input<string>(TOAST_DEFAULTS.SHOW_TRANSITION_OPTIONS);
  hideTransitionOptions = input<string>(TOAST_DEFAULTS.HIDE_TRANSITION_OPTIONS);
  autoZIndex = input<boolean>(TOAST_DEFAULTS.AUTO_Z_INDEX);
  baseZIndex = input<number>(TOAST_DEFAULTS.BASE_Z_INDEX);
  preventOpenDuplicates = input<boolean>(TOAST_DEFAULTS.PREVENT_OPEN_DUPLICATES);
  preventDuplicates = input<boolean>(TOAST_DEFAULTS.PREVENT_DUPLICATES);
  style = input<Record<string, any>>({zIndex: this.baseZIndex()});
  styleClass = input<string>();
  breakpoints = input<Record<string, unknown> | undefined>(undefined);

  messageTemplate = contentChild<TemplateRef<unknown>>('message', {descendants: true});

  // Output events
  onClose = output<any>();
}
