/**
 * this model for frontend usage
 */

export type Permission = {
  permissionId: string;
  permissionCode: string;
  permissionName: string;
  permissionDescription: string;
  endpoint: string;
  method: string;
  active?: boolean;
};
export type System = {
  systemId: string;
  systemCode: string;
  systemName: string;
  systemDescription: string;
  permissions: Permission[];
  active?: boolean;
};

export type Roles = {
  roleId: string;
  roleName: string;
  system: string;
  roleDescription: string;
  status: string;
  totalPermissions: number;
  systems: System[];
};

export type SCREEN_STATUS = 'EDITING' | 'VIEWONLY';
export const SCREEN_STATUS_ENUM = {
  EDITING: 'EDITING' as SCREEN_STATUS,
  VIEWONLY: 'VIEWONLY' as SCREEN_STATUS,
} as const;
