import { Component, input, output, viewChild, ChangeDetectionStrategy, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Popover, PopoverModule } from 'primeng/popover';
import { CmmPopoverProps } from './cmm-popover.types';
import { POPOVER_DEFAULTS } from './cmm-popover.constants';

/**
 * Popover is a container component that can overlay other components on page.
 * Wraps PrimeNG Popover component.
 */
@Component({
  selector: 'cmm-popover',
  standalone: true,
  imports: [CommonModule, PopoverModule],
  templateUrl: './cmm-popover.component.html',
  styleUrl: './cmm-popover.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmPopoverComponent {
  /**
   * Defines a string that labels the input for accessibility
   */
  ariaLabel = input<string>();

  /**
   * Establishes relationships between the component and label(s)
   */
  ariaLabelledBy = input<string>();

  /**
   * Enables to hide the overlay when outside is clicked
   */
  dismissable = input<boolean>(POPOVER_DEFAULTS.DISMISSABLE);

  /**
   * When enabled, displays a close icon at top right corner
   */
  showCloseIcon = input<boolean>(POPOVER_DEFAULTS.SHOW_CLOSE_ICON);

  /**
   * Inline style of the component
   */
  style = input<Record<string, any>>();

  /**
   * Style class of the component
   */
  styleClass = input<string>();

  /**
   * Target element to attach the panel
   */
  appendTo = input<any>(POPOVER_DEFAULTS.APPEND_TO);

  /**
   * Whether to automatically manage layering
   */
  autoZIndex = input<boolean>(POPOVER_DEFAULTS.AUTO_Z_INDEX);

  /**
   * Aria label of the close icon
   */
  ariaCloseLabel = input<string>();

  /**
   * Base zIndex value to use in layering
   */
  baseZIndex = input<number>(POPOVER_DEFAULTS.BASE_Z_INDEX);

  /**
   * When enabled, first button receives focus on show
   */
  focusOnShow = input<boolean>(POPOVER_DEFAULTS.FOCUS_ON_SHOW);

  /**
   * Transition options of the show animation
   */
  showTransitionOptions = input<string>(POPOVER_DEFAULTS.SHOW_TRANSITION);

  /**
   * Transition options of the hide animation
   */
  hideTransitionOptions = input<string>(POPOVER_DEFAULTS.HIDE_TRANSITION);

  /**
   * Callback to invoke when an overlay becomes visible
   */
  onShow = output<any>();

  /**
   * Callback to invoke when an overlay gets hidden
   */
  onHide = output<any>();

  /**
   * Custom content template
   */
  contentTemplate = contentChild<TemplateRef<any>>('content');

  /**
   * Custom close icon template
   */
  closeiconTemplate = contentChild<TemplateRef<any>>('closeicon');

  /**
   * Reference to the PrimeNG Popover component
   */
  popoverRef = viewChild<Popover>('popover');

  /**
   * Toggles the visibility of the panel
   */
  toggle(event: any, target?: any): void {
    this.popoverRef()?.toggle(event, target);
  }

  /**
   * Displays the panel
   */
  show(event: any, target?: any): void {
    this.popoverRef()?.show(event, target);
  }

  /**
   * Hides the panel
   */
  hide(): void {
    this.popoverRef()?.hide();
  }
}
