import {
  Component,
  input,
  output,
  model,
  contentChild,
  viewChild,
  TemplateRef,
  ChangeDetectionStrategy,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { Inplace, InplaceModule } from 'primeng/inplace';
import { INPLACE_DEFAULTS } from './cmm-inplace.constants';

@Component({
  selector: 'cmm-inplace',
  standalone: true,
  imports: [CommonModule, InplaceModule],
  template: `
    <p-inplace
      #inplace
      [active]="active()"
      [closable]="closable()"
      [disabled]="disabled()"
      [preventClick]="preventClick()"
      [style]="style() ?? undefined"
      [styleClass]="styleClass() ?? undefined"
      [closeIcon]="closeIcon() ?? undefined"
      [closeAriaLabel]="closeAriaLabel() ?? undefined"
      (onActivate)="onActivate.emit($event)"
      (onDeactivate)="onDeactivate.emit($event)">
      <ng-template pTemplate="display">
        @if (displayTemplate()) {
          <ng-container *ngTemplateOutlet="displayTemplate()!" />
        }
      </ng-template>
      <ng-template pTemplate="content">
        @if (contentTemplate()) {
          <ng-container *ngTemplateOutlet="contentTemplate()!" />
        }
      </ng-template>
      @if (closeIconTemplate()) {
        <ng-template pTemplate="closeicon">
          <ng-container *ngTemplateOutlet="closeIconTemplate()!" />
        </ng-template>
      }
    </p-inplace>
  `,
  styleUrl: './cmm-inplace.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmInplaceComponent {
  inplace = viewChild<Inplace>('inplace');

  // Core props
  active = model<boolean>(INPLACE_DEFAULTS.ACTIVE);
  closable = input<boolean>(INPLACE_DEFAULTS.CLOSABLE);
  disabled = input<boolean>(INPLACE_DEFAULTS.DISABLED);
  preventClick = input<boolean>(INPLACE_DEFAULTS.PREVENT_CLICK);
  closeIcon = input<string>();
  closeAriaLabel = input<string>();
  style = input<Record<string, any>>();
  styleClass = input<string>();

  // Templates
  displayTemplate = contentChild<TemplateRef<any>>('display');
  contentTemplate = contentChild<TemplateRef<any>>('content');
  closeIconTemplate = contentChild<TemplateRef<any>>('closeicon');

  // Events
  onActivate = output<Event>();
  onDeactivate = output<Event>();

  // Public methods
  activate(event: Event): void {
    this.inplace()?.activate(event);
  }

  deactivate(event: Event): void {
    this.inplace()?.deactivate(event);
  }
}
