import { Provider } from '@angular/core';
import { VALIDATION_MESSAGES_TOKEN, type ValidationMessages } from './validation-messages.token';
import { TranslateService } from '@ngx-translate/core';

/**
 * Provides reactive validation messages that automatically use the current language
 * from TranslateService. Messages are defined in public/translate/{lang}.json under VALIDATION key.
 * 
 * This is the recommended provider as it creates message functions that call
 * TranslateService.instant() on each use, making messages automatically reactive
 * to language changes.
 * 
 * @example
 * ```typescript
 * // app.config.ts
 * import { provideValidationMessages } from '@shared/validation';
 * 
 * export const appConfig: ApplicationConfig = {
 *   providers: [
 *     provideValidationMessages()  // ✅ Fully reactive to language changes!
 *   ]
 * };
 * ```
 * 
 * JSON structure required in vi.json / en.json:
 * ```json
 * {
 *   "VALIDATION": {
 *     "required": "{{0}} là bắt buộc",
 *     "email": "{{0}} không đúng định dạng email",
 *     "minLength": "{{0}} phải có ít nhất {{minLength}} ký tự"
 *   }
 * }
 * ```
 */
import { createValidationMessages } from './validation-messages'
export function provideValidationMessages(): Provider {
  return {
    provide: VALIDATION_MESSAGES_TOKEN,
    useFactory: (translate: any) => {
      return createValidationMessages(translate);
    },
    deps: [TranslateService]
  };
}

/**
 * Provides validation messages with custom overrides.
 * Custom messages can be strings or functions that return translated strings.
 * 
 * @param customMessages - Partial object with custom message overrides
 * 
 * @example
 * ```typescript
 * // app.config.ts
 * import { provideCustomValidationMessages } from '@shared/validation';
 * 
 * const customMessages = {
 *   required: (params) => `${params.fieldName} is mandatory!`,
 *   email: (params) => translateService.instant('CUSTOM.email', params)
 * };
 * 
 * export const appConfig: ApplicationConfig = {
 *   providers: [
 *     provideCustomValidationMessages(customMessages)
 *   ]
 * };
 * ```
 */
export function provideCustomValidationMessages(
  customMessages: Partial<ValidationMessages>
): Provider {
  return {
    provide: VALIDATION_MESSAGES_TOKEN,
    useFactory: (translate: any) => {
      
      const defaultMessages = createValidationMessages(translate);
      return { ...defaultMessages, ...customMessages };
    },
    deps: [TranslateService]
  };
}
