import { Directive, ElementRef, Renderer2, afterNextRender, Injector, inject } from '@angular/core';

/**
 * CmmHeaderDirective - Header section with dynamic height
 *
 * Header takes its natural content height and doesn't grow or shrink.
 * Must be used inside cmmLayout directive.
 *
 * @example
 * ```html
 * <div cmmLayout>
 *   <div cmmHeader>
 *     <h1>Page Title</h1>
 *     <nav>Navigation...</nav>
 *   </div>
 *   <div cmmContent>...</div>
 * </div>
 * ```
 */
@Directive({
  selector: '[cmmHeader]',
  standalone: true,
})
export class CmmHeaderDirective {
  private el = inject(ElementRef);
  private renderer = inject(Renderer2);
  private injector = inject(Injector);

  private static stylesInjected = false;
  private static readonly minifiedCss = '.cmm-header{box-sizing:border-box}';

  constructor() {
    afterNextRender(
      () => {
        this.injectStyles();
        this.applyStyles();
      },
      { injector: this.injector },
    );
  }

  private injectStyles(): void {
    if (!CmmHeaderDirective.stylesInjected && typeof document !== 'undefined') {
      const style = this.renderer.createElement('style');
      this.renderer.setAttribute(style, 'data-cmm-header', '');
      const text = this.renderer.createText(CmmHeaderDirective.minifiedCss);
      this.renderer.appendChild(style, text);
      this.renderer.appendChild(document.head, style);
      CmmHeaderDirective.stylesInjected = true;
    }
  }

  private applyStyles(): void {
    const element = this.el.nativeElement;

    // Header takes its natural height, doesn't grow or shrink
    this.renderer.addClass(element, 'cmm-header');
    this.renderer.setStyle(element, 'flex', '0 0 auto');
    this.renderer.setStyle(element, 'width', '100%');
  }
}
