/**
 * BlockUI size options
 */
export const BLOCK_UI_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type BlockUISize = (typeof BLOCK_UI_SIZES)[keyof typeof BLOCK_UI_SIZES];

/**
 * BlockUI style variants
 */
export const BLOCK_UI_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export type BlockUIVariant = (typeof BLOCK_UI_VARIANTS)[keyof typeof BLOCK_UI_VARIANTS];
