/**
 * FileUpload size options
 */
export const FILE_UPLOAD_SIZES = {
  SMALL: 'small',
  DEFAULT: 'default',
  LARGE: 'large',
} as const;

export type FileUploadSize = (typeof FILE_UPLOAD_SIZES)[keyof typeof FILE_UPLOAD_SIZES];

/**
 * FileUpload style variants
 */
export const FILE_UPLOAD_VARIANTS = {
  OUTLINED: 'outlined',
  FILLED: 'filled',
} as const;

export type FileUploadVariant = (typeof FILE_UPLOAD_VARIANTS)[keyof typeof FILE_UPLOAD_VARIANTS];

/**
 * FileUpload modes
 */
export const FILE_UPLOAD_MODES = {
  BASIC: 'basic',
  ADVANCED: 'advanced',
} as const;

export type FileUploadMode = (typeof FILE_UPLOAD_MODES)[keyof typeof FILE_UPLOAD_MODES];

/**
 * HTTP methods for file upload
 */
export const FILE_UPLOAD_METHODS = {
  POST: 'post',
  PUT: 'put',
} as const;

export type FileUploadMethod = (typeof FILE_UPLOAD_METHODS)[keyof typeof FILE_UPLOAD_METHODS];

