import { Component, ChangeDetectionStrategy, input, output, model, contentChild, TemplateRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Rating } from 'primeng/rating';

export interface RatingRateEvent {
  originalEvent: Event;
  value: number | undefined;
}

@Component({
  selector: 'cmm-rating',
  standalone: true,
  imports: [CommonModule, FormsModule, Rating],
  templateUrl: './cmm-rating.component.html',
  styleUrl: './cmm-rating.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmRatingComponent {
  disabled = input<boolean>(false);
  readonly = input<boolean>(false);
  stars = input<number>(5);
  iconOnClass = input<string>();
  iconOnStyle = input<Record<string, any>>();
  iconOffClass = input<string>();
  iconOffStyle = input<Record<string, any>>();
  autofocus = input<boolean>(false);

  value = model<number>();

  onRate = output<RatingRateEvent>();
  onCancel = output<Event>();
  onFocus = output<FocusEvent>();
  onBlur = output<FocusEvent>();

  onIconTemplate = contentChild<TemplateRef<any>>('onicon');
  offIconTemplate = contentChild<TemplateRef<any>>('officon');
  cancelIconTemplate = contentChild<TemplateRef<any>>('cancelicon');
}
