import { UBCK_TABLE_DEFAULTS } from "../table.const";
import { TableProps } from "../table.types";



export function computedTableProps(props:  TableProps) {
    const p = props;
    return {
        ...p,
        // Pagination
        paginator: p.paginator ?? UBCK_TABLE_DEFAULTS.PAGINATOR,
        rows: p.rows ?? UBCK_TABLE_DEFAULTS.ROWS,
        first: p.first ?? UBCK_TABLE_DEFAULTS.FIRST,
        totalRecords: p.totalRecords ?? 0,
        showCurrentPageReport: p.showCurrentPageReport ?? UBCK_TABLE_DEFAULTS.SHOW_CURRENT_PAGE_REPORT,
        currentPageReportTemplate: p.currentPageReportTemplate ?? UBCK_TABLE_DEFAULTS.CURRENT_PAGE_REPORT_TEMPLATE,
        paginatorPosition: p.paginatorPosition ?? UBCK_TABLE_DEFAULTS.PAGINATOR_POSITION,
        alwaysShowPaginator: p.alwaysShowPaginator ?? UBCK_TABLE_DEFAULTS.ALWAYS_SHOW_PAGINATOR,

        // Loading & Lazy
        lazy: p.lazy ?? UBCK_TABLE_DEFAULTS.LAZY,
        loading: p.loading ?? UBCK_TABLE_DEFAULTS.LOADING,

        // Data
        dataKey: p.dataKey ?? 'id',

        // Sorting
        sortField: p.sortField,
        sortOrder: p.sortOrder ?? 1,
        sortMode: p.sortMode ?? UBCK_TABLE_DEFAULTS.SORT_MODE,
        multiSortMeta: p.multiSortMeta,

        // Selection
        selectionMode: p.selectionMode,
        metaKeySelection: p.metaKeySelection,
        selectionPageOnly: p.selectionPageOnly,
        showIndeterminateCheckAll: p.showIndeterminateCheckAll ?? false,
        indeterminateCheckAllClass: p.indeterminateCheckAllClass,
        contextMenuSelection: p.contextMenuSelection,
        compareSelectionBy: p.compareSelectionBy ?? 'equals',
        rowTrackBy: p.rowTrackBy,
        contextMenu: p.contextMenu,

        // Row Grouping
        rowGroupMode: p.rowGroupMode,
        groupRowsBy: p.groupRowsBy,
        expandableRowGroups: p.expandableRowGroups,
        expandedRowKeys: p.expandedRowKeys,

        // Edit
        editMode: p.editMode,
        editingRowKeys: p.editingRowKeys,

        // Loading
        showLoader: p.showLoader,

        // Filtering
        globalFilterFields: p.globalFilterFields,
        filterDelay: p.filterDelay,

        // Responsive
        responsiveLayout: p.responsiveLayout ?? UBCK_TABLE_DEFAULTS.RESPONSIVE_LAYOUT,
        breakpoint: p.breakpoint,

        // Features
        rowHover: p.rowHover,
        reorderableColumns: p.reorderableColumns,
        resizableColumns: p.resizableColumns,
        columnResizeMode: p.columnResizeMode,

        // Scrolling
        scrollable: p.scrollable,
        scrollHeight: p.scrollHeight,
        virtualScroll: p.virtualScroll,
        virtualScrollItemSize: p.virtualScrollItemSize,

        // Frozen
        frozenValue: p.frozenValue,
        frozenColumns: p.frozenColumns,

        // Export
        exportFilename: p.exportFilename,

        // State
        stateStorage: p.stateStorage,
        stateKey: p.stateKey,

        // Styling
        size: p.size,
        style: p.style,
        styleClass: p.styleClass,
        tableStyle: p.tableStyle,
        tableStyleClass: p.tableStyleClass,

        // for custom

        colOrderName: p.colOrderName ?? "TT",
        emptyMessage: p.emptyMessage || 'Không có dữ liệu',
    };
}
