import { Directive, Input, TemplateRef } from '@angular/core';
import { Tooltip } from 'primeng/tooltip';

export type { TooltipOptions } from 'primeng/api';

@Directive({
  selector: '[cmmTooltip]',
  standalone: true,
  hostDirectives: [
    {
      directive: Tooltip,
      inputs: [
        'pTooltip:cmmTooltip',
        'tooltipPosition',
        'tooltipEvent',
        'appendTo',
        'positionStyle',
        'tooltipStyleClass',
        'tooltipZIndex',
        'escape',
        'showDelay',
        'hideDelay',
        'life',
        'positionTop',
        'positionLeft',
        'autoHide',
        'fitContent',
        'hideOnEscape',
        'tooltipOptions',
      ],
    },
  ],
})
export class CmmTooltipDirective {}
