import { Component, ChangeDetectionStrategy, input, computed } from '@angular/core';

import { Badge } from 'primeng/badge';

@Component({
  selector: 'cmm-badge',
  templateUrl: './cmm-badge.component.html',
  styleUrls: ['./cmm-badge.component.scss'],
  standalone: true,
  imports: [Badge],
  exportAs: 'cmmbadge',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmmBadgeComponent {
  // Signal inputs - Schema props
  style = input<{ [klass: string]: any } | null>(null); // Schema: inline style
  styleClass = input<string>(''); // Schema: class of the element
  badgeSize = input<'small' | 'large' | 'xlarge'>(); // Schema: size
  severity = input<'primary' | 'secondary' | 'success' | 'info' | 'warn' | 'danger' | 'contrast' | 'help'>(); // Schema: severity type (note: PrimeNG Badge supports subset)
  value = input<string | number>(''); // Schema: value to display
  disabled = input<boolean>(false); // Schema: disabled state

  // Custom enhancements
  variant = input<'outlined' | 'filled'>('filled');
  customSize = input<'small' | 'default' | 'large'>('default');

  // Computed style class
  computedStyleClass = computed(() => {
    const classes = ['cmm-badge', `cmm-badge--${this.variant()}`, `cmm-badge--${this.customSize()}`, this.styleClass()];
    return classes.filter(Boolean).join(' ');
  });

  // Helper to cast severity for PrimeNG Badge compatibility
  getSeverity(): any {
    return this.severity();
  }
}
